window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["ap"]={"id":"ap","num":6,"name":"Anatomy & Physiology","area":"Body systems","lessons":[{"n":1,"title":"The Human Body","kicker":"Lesson 1 of your course, built from Chapter 1 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–85 minutes","steps":[{"id":"ap1-1","chapter":"Anatomy, physiology and pathology","title":"Anatomy, physiology and pathology","teach":["Anatomy is the study of the body’s structure: what the parts are and how they’re organized. Physiology is the study of what those parts do and how they do it. Pathology is the study of the body’s diseases.","Anatomy and physiology are hard to separate. Your mouth is a good example: teeth break food down mechanically (structure doing a job), the tongue tastes and moves food, and saliva contains enzymes that start breaking complex carbohydrates into simple sugars.","People have studied the body for a long time. Leonardo da Vinci was the first to draw the whole skeleton correctly, Andreas Vesalius wrote a book on the human body, and William Harvey worked out how blood circulates."],"keyPoints":["Anatomy = structure","Physiology = function","Pathology = disease"],"mnemonic":{"cue":"Anatomy is what it IS, physiology is what it DOES","explanation":"Ask \"what is it made of and where is it?\" for anatomy, and \"what does it do?\" for physiology."},"act":{"type":"sort","prompt":"Sort each statement into the right field of study.","categories":["Anatomy","Physiology","Pathology"],"items":[{"label":"The heart has four chambers","category":0,"feedback":"That describes structure, so it’s anatomy."},{"label":"The heart pumps blood to the lungs and body","category":1,"feedback":"That describes what the heart does, so it’s physiology."},{"label":"How a heart attack damages heart muscle","category":2,"feedback":"That’s about disease, so it’s pathology."},{"label":"The femur is the longest bone in the body","category":0,"feedback":"Size and shape are structure: anatomy."},{"label":"Saliva enzymes break starch into sugars","category":1,"feedback":"That’s a process, so it’s physiology."},{"label":"What happens to bones in osteoporosis","category":2,"feedback":"That’s a disease, so it’s pathology."}]}},{"id":"ap1-2","chapter":"Anatomic position","title":"Anatomic position","teach":["To keep everyone using the same language, scientists use four reference systems: directions, planes, cavities and structural units.","All of them assume the body is in anatomic position: standing upright and facing forward, arms at the sides, palms and feet facing forward. Even if a patient is lying down, you describe locations as if they were standing this way."],"goodToKnow":"\"Left\" and \"right\" always mean the patient’s left and right, not yours.","act":{"type":"choice","prompt":"Which describes anatomic position?","options":[{"label":"Standing upright, facing forward, arms at the sides, palms facing forward","correct":true,"feedback":"Right. Palms forward is the detail people often miss."},{"label":"Standing upright, arms at the sides, palms facing the thighs","correct":false,"feedback":"Close, but in anatomic position the palms face forward."},{"label":"Lying on the back, arms by the sides","correct":false,"feedback":"That’s lying down. Anatomic position is standing and facing forward."}]}},{"id":"ap1-3","chapter":"Directional terms, part 1","title":"Directional terms, part 1","teach":["Superior means above (the head is superior to the neck). Inferior means below (the foot is inferior to the ankle).","Anterior means toward the front; ventral, the belly side, means the same thing. Posterior means toward the back; dorsal, the back side, means the same thing. The esophagus is posterior to the trachea.","Cephalad or cranial means toward the head, so it’s another word for superior. Caudal means toward the tail, and is sometimes used for inferior. Humans only have a tail as embryos."],"visual":{"kind":"hub","title":"Pairs of opposites","items":[{"label":"Superior / inferior","detail":"Above / below"},{"label":"Anterior / posterior","detail":"Front / back (ventral / dorsal)"},{"label":"Cephalad / caudal","detail":"Toward the head / toward the tail"},{"label":"Medial / lateral","detail":"Toward the midline / toward the side"},{"label":"Proximal / distal","detail":"Near / far from the point of attachment"}]},"act":{"type":"choice","prompt":"The vertebral column is ______ to the digestive tract.","options":[{"label":"Posterior (dorsal)","correct":true,"feedback":"Right. The spine sits behind the gut."},{"label":"Anterior (ventral)","correct":false,"feedback":"Anterior means in front. The spine is behind the gut."},{"label":"Superior","correct":false,"feedback":"Superior means above. Here the spine is behind, not above."}]}},{"id":"ap1-4","chapter":"Directional terms, part 2","title":"Directional terms, part 2","teach":["Medial means closer to the midline of the body: the nose is medial on the face, and the ulna is on the medial side of the forearm. Lateral means toward the side: the ears are lateral, and the radius is lateral to the ulna.","Proximal means near the point of attachment or origin. Distal means away from it. These are used mostly for limbs: the elbow is proximal to the wrist, and the wrist is distal to the elbow."],"mnemonic":{"cue":"Proximal = proximity, distal = distance","explanation":"Proximal parts are close to where the limb joins the trunk; distal parts are a long distance from it."},"act":{"type":"sort","prompt":"Pick the right term for each statement.","categories":["Proximal","Distal","Medial","Lateral"],"items":[{"label":"The knee, compared with the ankle","category":0,"feedback":"The knee is closer to the hip, where the leg attaches."},{"label":"The fingers, compared with the wrist","category":1,"feedback":"Fingers are farther from the shoulder attachment."},{"label":"The nose on the face","category":2,"feedback":"The nose sits on the midline."},{"label":"The radius, compared with the ulna","category":3,"feedback":"The radius is on the thumb side, away from the midline."},{"label":"The ears on the face","category":3,"feedback":"The ears are toward the sides."},{"label":"The wrist, compared with the elbow","category":1,"feedback":"The wrist is farther from the attachment, so it’s distal."}]}},{"id":"ap1-5","chapter":"Body planes","title":"Body planes","teach":["Planes are imaginary flat surfaces passing through the body. They’re most useful when describing dissections or scans.","A midsagittal (median) plane divides the body down the middle into equal left and right halves. Any sagittal plane runs parallel to it and divides the body into unequal left and right parts.","A horizontal or transverse plane divides the body into superior and inferior portions. A frontal or coronal plane divides it into anterior and posterior portions, at right angles to the sagittal plane.","When an organ is cut, a cut along its long axis is a longitudinal section, and a cut across it is a transverse or cross section."],"visual":{"kind":"flow","title":"Three planes","items":[{"label":"Sagittal (midsagittal)","detail":"Left and right parts. Midsagittal gives equal halves."},{"label":"Frontal (coronal)","detail":"Front (anterior) and back (posterior) parts."},{"label":"Transverse (horizontal)","detail":"Upper (superior) and lower (inferior) parts."}]},"act":{"type":"choice","prompt":"A CT scan slice that separates the chest from the abdomen is cut along which plane?","options":[{"label":"Transverse (horizontal)","correct":true,"feedback":"Right. It splits the body into upper and lower parts."},{"label":"Frontal (coronal)","correct":false,"feedback":"A frontal plane splits front from back."},{"label":"Midsagittal","correct":false,"feedback":"A midsagittal plane splits left from right."}]}},{"id":"ap1-6","chapter":"The dorsal cavity","title":"The dorsal cavity","teach":["The body has two major cavities, the dorsal cavity and the ventral cavity. The organs inside any cavity are called the viscera.","The dorsal cavity holds the nervous system organs that coordinate the body. It has two parts: the cranial cavity, which holds the brain, and the spinal cavity, which holds the spinal cord."],"act":{"type":"choice","prompt":"The spinal cord sits in the:","options":[{"label":"Spinal cavity, part of the dorsal cavity","correct":true,"feedback":"Right. The dorsal cavity is the cranial cavity plus the spinal cavity."},{"label":"Thoracic cavity, part of the ventral cavity","correct":false,"feedback":"The thoracic cavity holds the heart and lungs."},{"label":"Abdominopelvic cavity","correct":false,"feedback":"That holds digestive, urinary and reproductive organs."}]}},{"id":"ap1-7","chapter":"The ventral cavity","title":"The ventral cavity","teach":["The ventral cavity holds organs that keep the internal environment steady (homeostasis). Its first part is the thoracic cavity, surrounded by the rib cage.","Inside the thoracic cavity, the heart sits in the pericardial sac (the pericardial cavity) and each lung is covered by a pleural membrane (the pleural cavities). Between the two pleural cavities is the mediastinum, which holds the heart, thymus, lymph and blood vessels, trachea, esophagus and nerves.","The diaphragm separates the thoracic cavity from the abdominopelvic cavity. That second part holds the kidneys, stomach, liver and gallbladder, small and large intestines, spleen, pancreas, and in women the ovaries and uterus.","Parietal refers to the wall of a cavity (the parietal peritoneum lines the abdominal wall). Visceral refers to the covering of an organ (the visceral peritoneum covers the abdominal organs)."],"visual":{"kind":"flow","title":"Cavities of the body","items":[{"label":"Dorsal cavity","detail":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"label":"Thoracic cavity","detail":"Pericardial cavity (heart), pleural cavities (lungs), mediastinum."},{"label":"Diaphragm","detail":"The muscle that separates the chest from the abdomen."},{"label":"Abdominopelvic cavity","detail":"Stomach, liver, intestines, kidneys, spleen, pancreas, and in women the ovaries and uterus."}]},"mnemonic":{"cue":"Parietal = partition wall, visceral = viscera","explanation":"The parietal layer lines the wall; the visceral layer hugs the organ (the viscera)."},"act":{"type":"sort","prompt":"Put each organ in its cavity.","categories":["Cranial","Thoracic","Abdominopelvic"],"items":[{"label":"Brain","category":0,"feedback":"The brain is in the cranial cavity."},{"label":"Heart","category":1,"feedback":"The heart is in the pericardial cavity, inside the thoracic cavity."},{"label":"Lungs","category":1,"feedback":"Each lung is in a pleural cavity in the thorax."},{"label":"Esophagus (in the chest)","category":1,"feedback":"It runs through the mediastinum."},{"label":"Liver","category":2,"feedback":"The liver is below the diaphragm."},{"label":"Kidneys","category":2,"feedback":"The textbook lists the kidneys in the abdominopelvic cavity."},{"label":"Uterus","category":2,"feedback":"The uterus is in the pelvic part."}]}},{"id":"ap1-8","chapter":"Levels of organization","title":"Levels of organization","teach":["All living material is made of cells, the smallest units of life. Cells form tissues, tissues form organs, organs form systems, and all the systems together make the organism.","Below the cell are atoms (like carbon, hydrogen and oxygen) and molecules (like water, sugars and amino acids), but these aren’t alive. The cell is the smallest living unit and the basic unit of biologic organization.","The fluid part of a cell is protoplasm. It’s surrounded by the cell (plasma) membrane, which controls what enters and leaves, and it contains organelles such as mitochondria, ribosomes and lysosomes."],"act":{"type":"order","prompt":"Put the levels of organization in order, smallest first.","items":[{"label":"Atoms","detail":"Smallest units of elements"},{"label":"Molecules","detail":"Atoms joined by chemical bonds"},{"label":"Cells","detail":"Smallest living units"},{"label":"Tissues","detail":"Similar cells doing similar jobs"},{"label":"Organs","detail":"Different tissues working together"},{"label":"Systems","detail":"Groups of organs"},{"label":"Organism","detail":"All systems together"}]}},{"id":"ap1-9","chapter":"The four tissue types","title":"The four tissue types","teach":["Every tissue in the body fits one of four groups.","Epithelial tissue covers and protects surfaces (outside, like skin, and inside, like the intestine lining), forms glands and lines cavities. Its cells sit close together with almost no material between them.","Connective tissue binds and supports other tissues. Its cells make fibers (collagen and elastin) set in a nonliving matrix. Blood, bone and lymphatic tissue are specialized connective tissues.","Muscle tissue has long cells (muscle fibers) that generate movement by contracting forcefully. There are three types: skeletal (voluntary, pulls on bones), smooth (involuntary, in the intestines and blood vessels) and cardiac (involuntary, only in the heart).","Nervous tissue is made of nerve cells that link the sensory and motor structures of the body into one coordinating system."],"keyPoints":["4 tissue types: epithelial, connective, muscle, nervous","3 muscle types: skeletal, smooth, cardiac"],"act":{"type":"sort","prompt":"Match each description to its tissue.","categories":["Epithelial","Connective","Muscle","Nervous"],"items":[{"label":"Lines the intestine and forms glands","category":0,"feedback":"Covering, lining and glands are epithelial jobs."},{"label":"Bone and blood","category":1,"feedback":"Both are specialized connective tissues."},{"label":"Contracts forcefully to create movement","category":2,"feedback":"That’s muscle."},{"label":"Pushes food along the digestive tract","category":2,"feedback":"Smooth muscle does this."},{"label":"Carries signals between sensory and motor structures","category":3,"feedback":"That’s nervous tissue."},{"label":"Cells make collagen and elastin fibers in a matrix","category":1,"feedback":"Fibers in a matrix is the mark of connective tissue."}]}},{"id":"ap1-10","chapter":"Body systems: covering, support and movement","title":"Body systems: covering, support and movement","teach":["The integumentary system is the skin (epidermis and dermis) plus hair, nails, sebaceous glands and sweat glands. It insulates and protects the body, helps control temperature and water, and has receptors for temperature and pressure.","The skeletal system is bones, cartilage and the membranes around bones. It protects and supports, acts as levers for movement, makes blood cells in red marrow, stores fat in yellow marrow, and stores minerals like calcium and phosphorus.","The muscular system is muscles, fasciae, tendon sheaths and bursae. Skeletal muscle moves bones, smooth muscle moves food and blood, and cardiac muscle makes the heart contract."],"act":{"type":"choice","prompt":"Red bone marrow making blood cells is a job of which system?","options":[{"label":"Skeletal","correct":true,"feedback":"Right. Bones make blood cells and store fat and minerals."},{"label":"Cardiovascular","correct":false,"feedback":"The cardiovascular system moves blood, but bones make the cells."},{"label":"Lymphatic","correct":false,"feedback":"Not in this textbook’s list. Blood cells come from red bone marrow."}]}},{"id":"ap1-11","chapter":"Body systems: control and transport","title":"Body systems: control and transport","teach":["The nervous system (brain, spinal cord, cranial and peripheral nerves) controls and coordinates the other systems, interprets stimuli and handles the special senses.","The endocrine system is the ductless glands. The pituitary, the \"master gland\", controls the thyroid, adrenals, ovaries and testes. Hormones regulate the body chemically, and the hypothalamus links this system with the nervous system.","The cardiovascular system (heart, arteries, veins, capillaries) pumps blood carrying oxygen, nutrients and wastes.","The lymphatic (immune) system (lymph nodes, thymus, spleen, lymph vessels) drains extra fluid from tissues, carries absorbed fats from the intestine to the blood, and protects against disease."],"act":{"type":"sort","prompt":"Which system does each job?","categories":["Nervous","Endocrine","Cardiovascular","Lymphatic"],"items":[{"label":"Interprets sight, hearing, taste and smell","category":0,"feedback":"The special senses are nervous system work."},{"label":"Regulates the body with hormones","category":1,"feedback":"Hormones come from endocrine glands."},{"label":"Pumps blood through arteries, veins and capillaries","category":2,"feedback":"That’s the cardiovascular system."},{"label":"Carries absorbed fats from the intestine","category":3,"feedback":"Lymph vessels pick up fats."},{"label":"Drains extra fluid from tissue spaces","category":3,"feedback":"That’s a lymphatic job."},{"label":"Pituitary controls other glands","category":1,"feedback":"The pituitary is the endocrine master gland."}]}},{"id":"ap1-12","chapter":"Body systems: exchange, processing and reproduction","title":"Body systems: exchange, processing and reproduction","teach":["The respiratory system (nasal cavities, pharynx, larynx, trachea, bronchi, lungs) brings oxygen into the blood and removes carbon dioxide.","The digestive system is the alimentary canal (mouth to anus) plus the salivary glands, liver and pancreas. It breaks food into simpler substances that cells can absorb and gets rid of what can’t be digested.","The urinary system (two kidneys, two ureters, bladder, urethra) chemically regulates the blood, makes and removes urine, and helps maintain homeostasis.","The reproductive system is the ovaries, uterine tubes, uterus and vagina in women, and the testes, vas deferens, seminal vesicles, prostate, penis and urethra in men. It maintains sexual characteristics and continues the species."],"act":{"type":"sort","prompt":"Which system does each organ belong to?","categories":["Respiratory","Digestive","Urinary","Reproductive"],"items":[{"label":"Larynx","category":0,"feedback":"The larynx is part of the airway."},{"label":"Pancreas","category":1,"feedback":"It’s an associated gland of the digestive system."},{"label":"Ureters","category":2,"feedback":"They carry urine from the kidneys to the bladder."},{"label":"Prostate gland","category":3,"feedback":"It’s part of the male reproductive system."},{"label":"Bronchi","category":0,"feedback":"They lead into the lungs."},{"label":"Liver","category":1,"feedback":"The textbook lists it as a digestive gland."}]}},{"id":"ap1-13","chapter":"Homeostasis","title":"Homeostasis","teach":["Homeostasis is keeping the body’s internal environment within narrow limits. Claude Bernard was one of the first scientists to explain why it matters. Blood sugar, body temperature, heart rate and the fluid around cells are all kept in range.","Blood sugar: after a carbohydrate meal, blood glucose rises. The pancreas releases insulin, which moves extra glucose into the liver to be stored as glycogen. Between meals, when glucose drops, the pancreas releases glucagon, which breaks glycogen back down into glucose.","Temperature: when you overheat, the hypothalamus makes you sweat and widens blood vessels near the skin to lose heat. When you’re cold, it makes you shiver and narrows those vessels to hold heat in.","If homeostasis isn’t maintained, the body becomes diseased and eventually dies."],"visual":{"kind":"cycle","title":"Blood sugar balance","items":[{"label":"Meal raises glucose","detail":"Carbohydrates are broken down into glucose."},{"label":"Insulin released","detail":"The pancreas sends extra glucose to the liver."},{"label":"Stored as glycogen","detail":"The liver stores it for later."},{"label":"Glucose drops between meals","detail":"Cells keep using glucose."},{"label":"Glucagon released","detail":"Glycogen is broken back into glucose."}]},"act":{"type":"choice","prompt":"Between meals, blood glucose falls. What does the pancreas release?","options":[{"label":"Glucagon, which turns stored glycogen back into glucose","correct":true,"feedback":"Right. Glucagon raises blood glucose."},{"label":"Insulin, which moves glucose into the liver","correct":false,"feedback":"Insulin lowers blood glucose. That’s the response after a meal."},{"label":"Sweat, to cool the body","correct":false,"feedback":"Sweating is for temperature, not blood sugar."}]}},{"id":"ap1-14","chapter":"Negative and positive feedback","title":"Negative and positive feedback","teach":["The body keeps checking itself and correcting changes using negative feedback: a change triggers a response that reverses it. A home thermostat works the same way: when it gets cold, the furnace turns on; when it’s warm enough, it turns off. Body temperature control is negative feedback.","Positive feedback is the opposite: a stimulus leads to more of the same response. In labour, after the first contraction, the uterus keeps contracting harder and more often."],"mnemonic":{"cue":"Negative = \"no more\", positive = \"more, more\"","explanation":"Negative feedback shuts the change down. Positive feedback builds it up until an end point (like birth)."},"act":{"type":"sort","prompt":"Negative or positive feedback?","categories":["Negative feedback","Positive feedback"],"items":[{"label":"Sweating when body temperature rises","category":0,"feedback":"It brings temperature back down."},{"label":"Contractions growing stronger during labour","category":1,"feedback":"Each contraction leads to a stronger one."},{"label":"Insulin release after a meal","category":0,"feedback":"It brings blood glucose back down."},{"label":"Shivering in the cold","category":0,"feedback":"It brings temperature back up to normal."},{"label":"A furnace switching off when the room is warm","category":0,"feedback":"That’s the thermostat example of negative feedback."}]}}],"flashcards":[{"front":"Anatomy","back":"The study of the body’s structure and how its parts are organized."},{"front":"Physiology","back":"The study of what body parts do and how they do it."},{"front":"Pathology","back":"The study of the diseases of the body."},{"front":"Anatomic position","back":"Standing upright, facing forward, arms at the sides, palms and feet facing forward."},{"front":"Superior / inferior","back":"Above / below."},{"front":"Anterior (ventral) / posterior (dorsal)","back":"Toward the front / toward the back."},{"front":"Cephalad (cranial) / caudal","back":"Toward the head / toward the tail."},{"front":"Medial / lateral","back":"Toward the midline / toward the side."},{"front":"Proximal / distal","back":"Near / away from the point of attachment or origin."},{"front":"Midsagittal plane","back":"Divides the body into equal left and right halves (also called the median plane)."},{"front":"Transverse (horizontal) plane","back":"Divides the body into superior and inferior portions."},{"front":"Frontal (coronal) plane","back":"Divides the body into anterior and posterior portions."},{"front":"Viscera","back":"The organs inside any body cavity."},{"front":"Dorsal cavity","back":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"front":"Thoracic cavity","back":"Holds the heart in the pericardial cavity and the lungs in the pleural cavities, with the mediastinum between them."},{"front":"Mediastinum","back":"Space between the pleural cavities holding the heart, thymus, trachea, esophagus, vessels and nerves."},{"front":"Parietal / visceral","back":"Lining the wall of a cavity / covering an organ."},{"front":"Protoplasm","back":"The fluid part of a cell."},{"front":"Four tissue types","back":"Epithelial, connective, muscle and nervous."},{"front":"Three muscle types","back":"Skeletal (voluntary), smooth (involuntary, gut and vessels), cardiac (heart only)."},{"front":"Homeostasis","back":"Keeping the internal environment within narrow limits."},{"front":"Negative feedback","back":"A response that reverses a change, like temperature control."},{"front":"Positive feedback","back":"A response that increases the change, like labour contractions."}],"quiz":[{"q":"The organs of any cavity are referred to as the viscera.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the organs of any cavity are called the viscera. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"A __________________ is any plane that divides the body into superior and inferior portions.","o":["frontal","mid-sagittal","coronal","transverse"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says a horizontal or transverse plane divides the body into superior and inferior portions. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The heart is located within the _______________ cavity.","o":["pleural","pericardial","abdominal","cranial"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 says the heart sits in the pericardial sac, called the pericardial cavity, inside the thoracic cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The wrist is _____________________ to the elbow.","o":["proximal","superior","distal","superficial"],"a":2,"e":"Checked answer, not from an official key. Distal means away from the point of attachment. The textbook’s own example is \"the wrist is distal to the elbow\". Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What are the smallest living units of biologic organization?","o":["Atoms","Cells","Organelles","Systems"],"a":1,"e":"Checked answer, not from an official key. Table 1-1 says cells are the smallest living units of biologic organization. Atoms and molecules are smaller but not alive. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Skin, hair, and nails belong to the ________________________ system.","o":["integumentary","muscular","digestive","endocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the integumentary system includes the skin, hair, nails, sebaceous glands and sweat glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What term is used for the maintenance (within varying narrow limits) of the internal environment of the body?","o":["physiology","homeostasis","pathology","epithelium"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 defines homeostasis as the maintenance, within varying narrow limits, of the internal environment of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of muscle is found along the digestive tract?","o":["smooth","cardiac","skeletal","vascular"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says smooth (involuntary) muscle is found in the intestines, where it pushes food along the digestive tract. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Body temperature control is an example of, _______________________ a process by which the body responds to a stimulus by correcting the change and bringing the body back to the original setting.","o":["positive feedback","endocrinology","negative feedback","pathology"],"a":2,"e":"Checked answer, not from an official key. Chapter 1 uses body temperature control as its example of negative feedback, which corrects a change and brings the body back to normal. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The first contraction during labor results in stronger and stronger contractions of the uterus. This process is an example of _____________________________.","o":["negative feedback","endocrinology","pathology","positive feedback"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 gives labour as the example: after the first contraction, the uterus keeps contracting with more strength and frequency. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The study of the diseases of the body is called ___________________.","o":["anatomy","physiology","endocrinology","pathology"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says pathology is the study of the diseases of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of tissue generates movement by contracting in a forcible manner?","o":["muscle","nervous","connective","epithelial"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says muscle tissue generates movement by shortening or contracting in a forcible manner. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Anatomy is the study of diseases in the body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Anatomy is the study of structure. The study of disease is pathology. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"There are four types of muscle in the human body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. There are three types of muscle tissue: skeletal, smooth and cardiac. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The prostate gland, penis, and urethra belong to the male reproductive system.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 lists the prostate gland, penis and urethra as part of the male reproductive system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."}],"caseStudy":{"title":"From a warm room to a whole-body response","scenario":"During a classroom demonstration, a learner becomes warm and begins sweating. They say the skin alone is “fixing” temperature.","prompts":["Which structures detect and coordinate the change?","Which tissue and organ-system responses help release heat?","Why is this an example of negative feedback rather than a single-organ action?"],"takeaway":"Thermoregulation illustrates the course’s central idea: structure, signalling, circulation and effectors cooperate to keep a variable within a workable range."},"perStepChapter":true},{"n":2,"title":"The Chemistry of Life","kicker":"Describe atomic structure and distinguish elements, isotopes, ions, molecules and compounds.","duration":"80–95 minutes","steps":[{"id":"l2-m1","chapter":"Build matter from particles","chapterSummary":"Start with atoms, elements, ions, isotopes and compounds.","title":"Atomic structure determines chemical behaviour","highYield":"Protons identify the element, neutrons change its isotope, and electrons drive most chemical interactions.","teach":["An atom is the smallest particle that retains the properties of an element. Its compact nucleus contains positively charged protons and uncharged neutrons. Negatively charged electrons occupy regions around the nucleus. In a neutral atom, the numbers of protons and electrons are equal, so their charges balance.","The atomic number equals the number of protons and therefore identifies the element. Electron arrangement is especially important because chemical reactions involve gaining, losing or sharing electrons. An atom that gains electrons becomes negatively charged; one that loses electrons becomes positively charged. Charged atoms are called ions."],"keyPoints":["Protons have positive charge; neutrons have no charge.","Electrons have negative charge and participate in bonding.","Changing electron number creates an ion, not a new element."],"visual":{"title":"A simplified atom","kind":"layers","items":[{"label":"Nucleus","detail":"Protons and neutrons concentrated at the centre."},{"label":"Electron region","detail":"Electrons occupy energy levels around the nucleus."},{"label":"Net charge","detail":"Depends on the balance between protons and electrons."}]},"mnemonic":{"title":"Keep the particles straight","cue":"PEN","explanation":"Protons are Positive, Electrons are negative, Neutrons are neutral."},"goodToKnow":"An atomic diagram is a model. Electrons do not travel around the nucleus on fixed planetary tracks.","act":{"type":"choice","prompt":"An atom gains one electron without changing its nucleus. What changes?","options":[{"label":"It becomes a negatively charged ion.","correct":true,"feedback":"An extra electron creates a net negative charge."},{"label":"It becomes a different element.","correct":false,"feedback":"The element is determined by proton number."},{"label":"It becomes a new isotope.","correct":false,"feedback":"Isotopes differ in neutron number."}]}},{"id":"l2-m2","chapter":null,"chapterSummary":null,"title":"Elements, isotopes and compounds are related but distinct","highYield":"An element is defined by proton number; an isotope differs in neutrons; a compound joins atoms of different elements.","teach":["All atoms of one element have the same number of protons. Carbon is central to living matter because its electron arrangement allows it to form stable covalent frameworks with many other atoms. Hydrogen, oxygen, nitrogen, phosphorus and several mineral elements also contribute to body structure and function.","Isotopes are forms of the same element with different numbers of neutrons. Their chemical behaviour is often similar, although their mass and nuclear stability may differ. A molecule contains atoms held together by chemical bonds. When those atoms represent more than one element, the molecule is also a compound, as in water or carbon dioxide."],"keyPoints":["Element identity comes from proton number.","Isotopes differ in neutron number.","Every compound contains more than one element."],"visual":{"title":"Classify the particle","kind":"comparison","items":[{"label":"Element","detail":"One kind of atom defined by proton number."},{"label":"Isotope","detail":"Same element, different neutron number."},{"label":"Molecule","detail":"Two or more atoms chemically joined."},{"label":"Compound","detail":"Joined atoms from at least two elements."}]},"mnemonic":{"title":"Identity versus variation","cue":"P identifies; N varies","explanation":"Protons identify the element, while neutrons create isotopic variation."},"goodToKnow":"The word chemical does not mean artificial or harmful. Water, oxygen, glucose and DNA are chemicals.","act":{"type":"choice","prompt":"Which statement correctly describes an isotope?","options":[{"label":"It has a different number of protons and is a new element.","correct":false,"feedback":"Changing protons changes element identity."},{"label":"It has the same proton number but a different neutron number.","correct":true,"feedback":"That is the defining relationship among isotopes."},{"label":"It has identical particles but a different name.","correct":false,"feedback":"Isotopes have a real neutron and mass difference."}]}},{"id":"matter-match","title":"Match it: A simplified atom","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Protons and neutrons concentrated at the centre.","Electrons occupy energy levels around the nucleus.","Depends on the balance between protons and electrons."],"items":[{"label":"Nucleus","category":0,"feedback":"Nucleus: Protons and neutrons concentrated at the centre."},{"label":"Electron region","category":1,"feedback":"Electron region: Electrons occupy energy levels around the nucleus."},{"label":"Net charge","category":2,"feedback":"Net charge: Depends on the balance between protons and electrons."}]}},{"id":"l2-m3","chapter":"Connect bonds, water and energy","chapterSummary":"See how electron behaviour creates stable molecules and useful interactions.","title":"Bonds organize atoms into biological molecules","highYield":"Ionic bonding follows electron transfer, covalent bonding shares electrons, and hydrogen bonding is a weaker attraction between partial charges.","teach":["An ionic interaction begins when one atom loses electron density and another gains it, creating oppositely charged ions that attract. Many mineral salts separate into ions in water. Covalent bonds form when atoms share electron pairs. The carbon skeletons and many oxygen, hydrogen and nitrogen connections in biological molecules are covalent.","Because electrons may be shared unequally, a covalent molecule can have partially charged regions. Those partial charges allow weaker hydrogen bonds to form between molecules or between different parts of a large molecule. Individually weak interactions become powerful when many act together, helping stabilize water, proteins and nucleic acids."],"keyPoints":["Ionic interactions involve charged particles.","Covalent bonds involve shared electrons.","Hydrogen bonds help stabilize molecular shape and water behaviour."],"visual":{"title":"Three bonding patterns","kind":"comparison","items":[{"label":"Ionic","detail":"Electron transfer creates attraction between ions."},{"label":"Covalent","detail":"Atoms share electron pairs."},{"label":"Hydrogen","detail":"Partial charges form a weaker bridge."}]},"mnemonic":{"title":"Remember the electron action","cue":"I transfer · CO-share · H attracts","explanation":"Ionic transfer, covalent sharing and hydrogen attraction describe the core difference."},"goodToKnow":"Ionic bonds in a dry crystal and separated ions in water are different physical arrangements of the same chemical components.","act":{"type":"choice","prompt":"Which bond directly joins amino acids within a protein chain?","options":[{"label":"A covalent peptide bond","correct":true,"feedback":"Peptide bonds are covalent links between amino acids."},{"label":"Only a hydrogen bond","correct":false,"feedback":"Hydrogen bonds help shape proteins but do not form the primary amino-acid chain."},{"label":"A free-electron cloud with no bond","correct":false,"feedback":"A stable protein backbone requires covalent connections."}]}},{"id":"l2-m4","chapter":null,"chapterSummary":null,"title":"Water is a polar working environment","highYield":"Water’s polarity explains much of its solvent power, cohesion, heat buffering and transport role.","teach":["In water, oxygen attracts shared electrons more strongly than hydrogen, producing a partial negative region near oxygen and partial positive regions near hydrogen. This polarity allows water molecules to interact through hydrogen bonds and surround many ions and polar compounds. Substances that mix readily with water are hydrophilic; many nonpolar substances are hydrophobic.","Water participates in reactions, carries dissolved materials, lubricates surfaces and helps distribute heat. Its capacity to absorb substantial heat with a relatively modest temperature change supports thermal stability. No single property makes water important; its polarity, bonding and abundance combine to create the medium in which most cellular chemistry occurs."],"keyPoints":["Water has partial charges even though the molecule is neutral overall.","Polarity helps dissolve ions and polar molecules.","Hydrogen bonding contributes to cohesion and heat behaviour."],"visual":{"title":"Water as a molecular tool","kind":"hub","items":[{"label":"Solvent","detail":"Surrounds many ions and polar solutes."},{"label":"Transport","detail":"Provides the fluid medium for movement."},{"label":"Temperature","detail":"Absorbs and releases heat gradually."},{"label":"Reaction partner","detail":"Participates in many chemical reactions."}]},"mnemonic":{"title":"Water’s four jobs","cue":"STAR","explanation":"Solvent, Transport, temperature Absorption and Reactions."},"goodToKnow":"Hydrophobic does not mean harmful. Lipids are relatively nonpolar and are essential components of membranes.","act":{"type":"choice","prompt":"Why can water help dissolve sodium chloride?","options":[{"label":"Its polar regions interact with the charged sodium and chloride ions.","correct":true,"feedback":"Partial charges orient around and stabilize separated ions."},{"label":"It converts sodium and chloride into carbon.","correct":false,"feedback":"Dissolving does not change the elements."},{"label":"It has no electrical pattern at all.","correct":false,"feedback":"Water is neutral overall but polar within the molecule."}]}},{"id":"bonds-match","title":"Match it: Three bonding patterns","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Electron transfer creates attraction between ions.","Atoms share electron pairs.","Partial charges form a weaker bridge."],"items":[{"label":"Ionic","category":0,"feedback":"Ionic: Electron transfer creates attraction between ions."},{"label":"Covalent","category":1,"feedback":"Covalent: Atoms share electron pairs."},{"label":"Hydrogen","category":2,"feedback":"Hydrogen: Partial charges form a weaker bridge."}]}},{"id":"l2-m5","chapter":"Recognize the molecules of life","chapterSummary":"Connect common chemical families to cellular structure and energy transfer.","title":"Carbohydrates and lipids store and build in different ways","highYield":"Carbohydrates commonly provide readily accessible fuel and structural sugars; lipids store concentrated energy and form membranes.","teach":["Carbohydrates contain carbon, hydrogen and oxygen. Simple sugars such as glucose can be linked into larger storage molecules such as glycogen. Five-carbon sugars are structural components of nucleic acids. Cells use carbohydrate chemistry for both energy transfer and molecular construction, so carbohydrate is not synonymous with sweetness.","Lipids are relatively insoluble in water. Triacylglycerols combine glycerol with fatty acids and are an efficient energy store. Phospholipids contain both water-compatible and water-avoiding regions, allowing them to assemble into cell membranes. Saturated and unsaturated describe aspects of carbon bonding in fatty-acid chains, not a complete judgment about a food or person’s health."],"keyPoints":["Glucose is a six-carbon sugar used in cellular energy pathways.","Glycogen is a storage carbohydrate in animals.","Phospholipids self-organize into membrane bilayers.","Triacylglycerols store substantial chemical energy."],"visual":{"title":"Two molecular families","kind":"split","items":[{"label":"Carbohydrate","detail":"Sugars, storage polymers and structural components."},{"label":"Triacylglycerol","detail":"Glycerol plus three fatty acids."},{"label":"Phospholipid","detail":"Polar head with nonpolar tails for membranes."}]},"mnemonic":{"title":"Match structure to role","cue":"Sugar stores; phospholipid separates","explanation":"Carbohydrates often support fuel/storage, while phospholipids create boundaries."},"goodToKnow":"A nutrient’s molecular family does not determine the quality of an entire food or dietary pattern.","act":{"type":"choice","prompt":"Which molecule is especially suited to forming a cell boundary in water?","options":[{"label":"A phospholipid with a polar head and nonpolar tails","correct":true,"feedback":"Its two-region structure drives bilayer formation."},{"label":"A free neutron","correct":false,"feedback":"A neutron is a subatomic particle, not a membrane-forming molecule."},{"label":"Only a strand of glycogen","correct":false,"feedback":"Glycogen stores carbohydrate rather than forming the basic membrane bilayer."}]}},{"id":"l2-m6","chapter":null,"chapterSummary":null,"title":"Proteins, nucleic acids and ATP perform information-rich work","highYield":"Amino-acid sequence shapes protein function; nucleotide sequence stores information; ATP transfers usable energy between reactions.","teach":["Proteins are chains of amino acids linked by peptide bonds. The amino-acid sequence is the primary structure, and interactions along the chain produce increasingly complex folding. Shape matters: enzymes, receptors, transport proteins and structural proteins work because particular surfaces interact with particular molecules. Heat, pH and other conditions can alter folding and function.","DNA and RNA are nucleic acids built from nucleotides. Their base sequences carry and use biological information. ATP is also a nucleotide-related molecule, but its immediate role is energy transfer. When a reaction releases usable energy, cells can capture part of it in ATP; ATP can then support work such as transport, synthesis and movement."],"keyPoints":["Amino acids are the building blocks of proteins.","DNA and RNA are polymers of nucleotides.","ATP couples energy-releasing processes to cellular work."],"visual":{"title":"Build, instruct, power","kind":"triad","items":[{"label":"Protein","detail":"Amino-acid chain folded into a functional shape."},{"label":"Nucleic acid","detail":"Nucleotide sequence that stores or uses information."},{"label":"ATP","detail":"A transferable packet of chemical energy."}]},"mnemonic":{"title":"Three molecular jobs","cue":"PNA","explanation":"Proteins Perform, Nucleic acids encode, ATP Activates work."},"goodToKnow":"ATP is not a long-term energy warehouse; cells continually make and use it.","act":{"type":"choice","prompt":"What most directly determines a protein’s primary structure?","options":[{"label":"The order of its amino acids","correct":true,"feedback":"Primary structure is the amino-acid sequence."},{"label":"The number of neutrons in water","correct":false,"feedback":"That does not specify a protein chain."},{"label":"The pH scale alone","correct":false,"feedback":"pH can affect folding, but it does not encode the sequence."}]}},{"id":"molecules-match","title":"Match it: Two molecular families","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sugars, storage polymers and structural components.","Glycerol plus three fatty acids.","Polar head with nonpolar tails for membranes."],"items":[{"label":"Carbohydrate","category":0,"feedback":"Carbohydrate: Sugars, storage polymers and structural components."},{"label":"Triacylglycerol","category":1,"feedback":"Triacylglycerol: Glycerol plus three fatty acids."},{"label":"Phospholipid","category":2,"feedback":"Phospholipid: Polar head with nonpolar tails for membranes."}]}},{"id":"l2-m7","chapter":"Move matter and stabilize chemistry","chapterSummary":"Distinguish passive and active transport, then interpret pH.","title":"Diffusion follows a concentration gradient","highYield":"Net diffusion moves particles from higher to lower concentration through random molecular motion.","teach":["Particles in fluids are always moving. When more particles occupy one region than another, random motion produces a net movement down the concentration gradient until the distribution becomes more even. Temperature, distance, particle size and available surface can influence the rate. Equilibrium does not mean molecular motion stops; it means there is no net directional change.","Simple diffusion can occur through a membrane when the substance and membrane permit it. Facilitated diffusion also moves down a gradient but uses a membrane protein. Neither process directly consumes ATP to push the transported substance uphill. The distinction between direction and mechanism is essential."],"keyPoints":["Diffusion is driven by a concentration difference.","Equilibrium still includes molecular motion.","Facilitated diffusion uses a protein but remains passive."],"visual":{"title":"Gradient to equilibrium","kind":"sequence","items":[{"label":"High concentration","detail":"Many particles begin in one region."},{"label":"Net movement","detail":"Random movement favours spread toward the lower concentration."},{"label":"Dynamic equilibrium","detail":"Movement continues without a net shift."}]},"mnemonic":{"title":"Direction of diffusion","cue":"HIGH → LOW","explanation":"Passive net movement travels down the concentration gradient."},"goodToKnow":"Faster diffusion at a higher temperature does not mean temperature is the only control on transport in a living cell.","act":{"type":"choice","prompt":"Which process is passive but requires a membrane carrier or channel?","options":[{"label":"Facilitated diffusion","correct":true,"feedback":"The protein assists movement down a gradient without directly using ATP."},{"label":"Primary active transport","correct":false,"feedback":"Primary active transport uses energy to move against a gradient."},{"label":"Covalent bonding","correct":false,"feedback":"Bond formation is not a membrane-transport mechanism."}]}},{"id":"l2-m8","chapter":null,"chapterSummary":null,"title":"Osmosis tracks water across a selective barrier","highYield":"Water moves toward the side with the greater effective concentration of nonpenetrating solute.","teach":["Osmosis is the net movement of water through a selectively permeable membrane. Tonicity describes how a surrounding solution changes cell volume. In an isotonic environment, there is no sustained net water shift. A hypotonic environment favours water entry and swelling; a hypertonic environment favours water loss and shrinking.","The words hypo and hyper describe the solution relative to the cell, not the cell itself. Real biological fluids contain several solutes, and whether a solute can cross the membrane affects its osmotic impact. The classroom model is powerful, but it is still a model of a more complex system."],"keyPoints":["Osmosis concerns water movement.","Isotonic solutions do not drive a lasting volume change.","Hypotonic swells; hypertonic shrinks."],"visual":{"title":"Cell volume and tonicity","kind":"comparison","items":[{"label":"Hypotonic outside","detail":"Water tends to enter; cell volume rises."},{"label":"Isotonic outside","detail":"Water exchanges without a net volume shift."},{"label":"Hypertonic outside","detail":"Water tends to leave; cell volume falls."}]},"mnemonic":{"title":"Predict cell volume","cue":"HYPO = hippo-sized; HYPER = shrivel","explanation":"A simple visual cue: hypotonic surroundings swell a cell, hypertonic surroundings shrink it."},"goodToKnow":"Tonicity depends mainly on solutes that do not freely cross the membrane during the time being considered.","act":{"type":"choice","prompt":"A red blood cell loses water and shrinks. The surrounding solution is most likely:","options":[{"label":"Hypertonic relative to the cell","correct":true,"feedback":"Higher effective external solute draws water outward."},{"label":"Hypotonic relative to the cell","correct":false,"feedback":"A hypotonic environment favours water entry and swelling."},{"label":"Purely isotonic","correct":false,"feedback":"An isotonic environment should not drive a sustained volume loss."}]}},{"id":"l2-m9","chapter":null,"chapterSummary":null,"title":"Active transport and buffers protect useful gradients","highYield":"Active transport uses cellular energy to move substances against a gradient; buffers limit abrupt pH change by accepting or releasing hydrogen ions.","teach":["Cells maintain unequal ion distributions across membranes. Moving a substance from lower to higher concentration requires energy and a transport protein. Primary active transport uses energy directly, often from ATP. Vesicular processes can move larger packages into or out of cells. These mechanisms create gradients that later support electrical signals and coupled transport.","pH expresses hydrogen-ion concentration on a logarithmic scale. Values below 7 are acidic, 7 is neutral and values above 7 are basic in the standard classroom frame. Because each pH unit represents a tenfold change, a shift from 7 to 6 is substantial. Buffers reduce sudden pH swings by reversibly binding or releasing hydrogen ions; they do not make pH irrelevant or permanently fixed."],"keyPoints":["Active transport can move against a gradient.","ATP commonly supplies transport energy.","Lower pH means greater hydrogen-ion concentration.","Buffers resist rather than eliminate pH change."],"visual":{"title":"Maintaining chemical conditions","kind":"split","items":[{"label":"Transport pump","detail":"Uses energy to maintain unequal concentrations."},{"label":"Acid","detail":"Contributes hydrogen ions in solution."},{"label":"Base","detail":"Accepts hydrogen ions or reduces their concentration."},{"label":"Buffer","detail":"Temporarily absorbs added acid or base."}]},"mnemonic":{"title":"Two stabilizers","cue":"PUMPS place; BUFFERS brace","explanation":"Pumps place ions across membranes; buffers brace against rapid pH change."},"goodToKnow":"The pH scale is logarithmic, so equal numeric steps do not represent equal absolute changes in hydrogen ions.","act":{"type":"choice","prompt":"Which statement is accurate?","options":[{"label":"Active transport can use ATP to move a solute against its gradient.","correct":true,"feedback":"Energy allows the transporter to maintain an unequal distribution."},{"label":"A buffer prevents any possible change in pH.","correct":false,"feedback":"Buffers reduce the size or speed of change but have limits."},{"label":"pH 6 contains less hydrogen ion than pH 7.","correct":false,"feedback":"A lower pH represents a greater hydrogen-ion concentration."}]}},{"id":"movement-order","title":"Put it in order: Gradient to equilibrium","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"High concentration","detail":"Many particles begin in one region."},{"label":"Net movement","detail":"Random movement favours spread toward the lower concentration."},{"label":"Dynamic equilibrium","detail":"Movement continues without a net shift."}]}},{"id":"movement-match","title":"Match it: Cell volume and tonicity","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Water tends to enter; cell volume rises.","Water exchanges without a net volume shift.","Water tends to leave; cell volume falls."],"items":[{"label":"Hypotonic outside","category":0,"feedback":"Hypotonic outside: Water tends to enter; cell volume rises."},{"label":"Isotonic outside","category":1,"feedback":"Isotonic outside: Water exchanges without a net volume shift."},{"label":"Hypertonic outside","category":2,"feedback":"Hypertonic outside: Water tends to leave; cell volume falls."}]}}],"flashcards":[{"front":"Atomic number","back":"The number of protons in an atom’s nucleus."},{"front":"Isotope","back":"An atom of the same element with a different number of neutrons."},{"front":"Ion","back":"An atom or molecule with a net charge from gaining or losing electrons."},{"front":"Ionic interaction","back":"Attraction between oppositely charged ions created through electron transfer."},{"front":"Covalent bond","back":"A bond in which atoms share electron pairs."},{"front":"Hydrogen bond","back":"A relatively weak attraction involving partial charges, important in water and biomolecular shape."},{"front":"Amino acid","back":"A building block joined by peptide bonds to form proteins."},{"front":"Nucleotide","back":"A building block of nucleic acids, consisting of a sugar, phosphate and nitrogenous base."},{"front":"ATP","back":"A molecule that transfers chemical energy to many forms of cellular work."},{"front":"Diffusion","back":"Net movement down a concentration gradient."},{"front":"Osmosis","back":"Net movement of water through a selectively permeable membrane."},{"front":"Active transport","back":"Energy-dependent movement, often against a concentration gradient."},{"front":"Buffer","back":"A chemical system that resists abrupt pH change by accepting or releasing hydrogen ions."}],"quiz":[],"caseStudy":{"title":"A cell placed in a new solution","scenario":"A teaching model shows identical cells placed into three unlabeled solutions. One swells, one retains its volume and one shrinks.","prompts":["Classify each surrounding solution as hypotonic, isotonic or hypertonic.","Explain the direction of net water movement without saying that solute itself must cross.","Identify one reason a real cell may respond differently from a simplified model."],"takeaway":"Predicting transport requires the gradient, membrane permeability and the identity of the moving substance—not a memorized arrow alone."}},{"n":3,"title":"Cell Structure","kicker":"Use modern cell theory to explain why cells are the basic units of living structure and function.","duration":"75–95 minutes","steps":[{"id":"cell-theory","chapter":"Build the cellular map","chapterSummary":"Start with the shared rules of cells, then use compartments to organize a eukaryotic cell.","title":"Cell theory gives biology its smallest living unit","highYield":"Every human structure is built from cells, and every new cell comes from an existing cell.","teach":["Modern cell theory organizes three connected ideas: living organisms consist of cells, the cell is the basic unit of living structure and function, and cells arise through division of pre-existing cells. Human tissues may look continuous, but each is an organized population of cells plus surrounding material.","The theory also links continuity to heredity. When a cell divides, genetic information must be copied and distributed so daughter cells can maintain the functions appropriate to their tissue. A mature red blood cell and a neuron look very different because specialization changes cellular structure, not because either stops being a cell."],"keyPoints":["Cells are the smallest units that carry out the coordinated activities of life.","New cells arise from existing cells rather than appearing spontaneously.","Cell structure varies with function while core cellular principles remain shared.","Genetic information connects one cell generation to the next."],"visual":{"title":"From organism to cell","kind":"nested-scale","items":[{"label":"Organism","detail":"A coordinated human body."},{"label":"System","detail":"Organs cooperating toward a broad function."},{"label":"Organ","detail":"Multiple tissue types arranged together."},{"label":"Tissue","detail":"Related cells and extracellular material."},{"label":"Cell","detail":"The basic living unit at the center of the sequence."}]},"mnemonic":{"title":"Three C rules","cue":"Composition · Core unit · Continuity","explanation":"Organisms are composed of cells; cells are the core living units; cellular life continues from prior cells."},"goodToKnow":"The historical contributors refined cell theory over time as microscopes improved; the enduring value is the set of principles, not a single discovery date.","act":{"type":"choice","prompt":"A healing cut produces new epidermal cells. Which observation most directly illustrates cell theory?","options":[{"label":"Existing epidermal cells divide to make new cells.","correct":true,"feedback":"Correct. New cells arising from existing cells is a central principle of cell theory."},{"label":"The tissue contains extracellular proteins.","correct":false,"feedback":"Extracellular proteins matter, but they do not demonstrate the origin of new cells."},{"label":"The cut changes local blood flow.","correct":false,"feedback":"That is a tissue response, not the cell-theory principle being tested."}]}},{"id":"cell-types","chapter":null,"chapterSummary":null,"title":"Eukaryotic cells use internal compartments","highYield":"Human cells are eukaryotic: DNA is enclosed in a nucleus and many jobs occur in membrane-bound organelles.","teach":["A eukaryotic cell separates tasks into specialized compartments. The nucleus houses most DNA, mitochondria organize aerobic energy pathways, and the endomembrane system builds and routes many proteins and lipids. Compartmentalization lets different reactions occur under suitable conditions at the same time.","Prokaryotic cells, such as bacteria, lack a membrane-bound nucleus and the same suite of membrane-bound organelles. They are still complete living cells. Protoplasm is an older broad term for living cellular material; in practical study, it is more useful to distinguish cytoplasm from the nucleus and to name the structures within each region."],"keyPoints":["Eukaryotic DNA is mainly enclosed by a nuclear envelope.","Organelles divide cellular work into coordinated compartments.","Prokaryotes lack membrane-bound nuclei but are not empty or nonliving.","Cytoplasm includes cytosol, organelles, and inclusions outside the nucleus."],"visual":{"title":"Two cellular plans","kind":"comparison","items":[{"label":"Human eukaryotic cell","detail":"Nucleus plus membrane-bound organelles; generally larger and highly compartmentalized."},{"label":"Prokaryotic cell","detail":"DNA is not enclosed by a nuclear envelope; no classic membrane-bound organelles."},{"label":"Shared foundation","detail":"Plasma membrane, genetic material, ribosomes, and metabolic chemistry."}]},"mnemonic":{"title":"Eu keeps DNA enclosed","cue":"EU = enclosed units","explanation":"Use enclosed units to remember that eukaryotes package many jobs inside membrane-bound compartments."},"goodToKnow":"Ribosomes are present in both prokaryotic and eukaryotic cells even though ribosomes are not membrane-bound organelles.","act":{"type":"choice","prompt":"Which feature most clearly identifies a typical human cell as eukaryotic?","options":[{"label":"Its DNA is enclosed within a nucleus.","correct":true,"feedback":"Correct. A membrane-bound nucleus is a defining eukaryotic feature."},{"label":"It contains water.","correct":false,"feedback":"Water is common to both prokaryotic and eukaryotic cells."},{"label":"It has ribosomes.","correct":false,"feedback":"Both major cell types use ribosomes."}]}},{"id":"cell-foundations-match","title":"Match it: From organism to cell","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["A coordinated human body.","Organs cooperating toward a broad function.","Multiple tissue types arranged together.","Related cells and extracellular material.","The basic living unit at the center of the sequence."],"items":[{"label":"System","category":1,"feedback":"System: Organs cooperating toward a broad function."},{"label":"Cell","category":4,"feedback":"Cell: The basic living unit at the center of the sequence."},{"label":"Organ","category":2,"feedback":"Organ: Multiple tissue types arranged together."},{"label":"Organism","category":0,"feedback":"Organism: A coordinated human body."},{"label":"Tissue","category":3,"feedback":"Tissue: Related cells and extracellular material."}]}},{"id":"fluid-mosaic","chapter":"Control the boundary","chapterSummary":"Read the plasma membrane as a dynamic selective interface rather than a static wall.","title":"The plasma membrane is a fluid mosaic","highYield":"A phospholipid bilayer forms the barrier; membrane proteins provide much of its selectivity, signaling, adhesion, and transport.","teach":["Each phospholipid has a water-attracting polar head and water-avoiding nonpolar tails. In an aqueous environment, heads face the fluid on both sides while tails turn inward. This bilayer creates a flexible boundary whose hydrophobic center limits the free passage of many charged or water-soluble substances.","Proteins embedded in or attached to the bilayer act as channels, carriers, receptors, enzymes, anchors, and identity markers. Lipids and many proteins can move laterally, which is why the model is described as fluid. Mosaic refers to the varied components arranged across this moving surface."],"keyPoints":["Polar heads contact water; nonpolar tails form the membrane interior.","The bilayer is selectively permeable rather than completely sealed.","Channels and carriers support regulated movement across the membrane.","Receptors translate external signals into cellular responses."],"visual":{"title":"Membrane cross-section","kind":"layer-model","items":[{"label":"Extracellular fluid","detail":"Water-based environment outside the cell."},{"label":"Polar heads","detail":"Face the aqueous environments on both surfaces."},{"label":"Nonpolar core","detail":"Paired fatty-acid tails restrict many polar solutes."},{"label":"Transmembrane protein","detail":"Spans the bilayer as a channel, carrier, or receptor."},{"label":"Cytoplasm","detail":"Water-based internal environment."}]},"mnemonic":{"title":"Heads hug water","cue":"Heads out, tails in","explanation":"The phrase fixes the orientation of phospholipids in the bilayer."},"goodToKnow":"The membrane is only a few nanometres thick, yet its molecular arrangement maintains very different conditions inside and outside the cell.","act":{"type":"choice","prompt":"Why does an ion usually need a membrane protein to enter a cell?","options":[{"label":"Its charge is unfavorable in the nonpolar bilayer core.","correct":true,"feedback":"Correct. The hydrophobic interior resists charged particles, so a channel or carrier is usually needed."},{"label":"The polar heads destroy every ion.","correct":false,"feedback":"Polar heads do not destroy ions; the nonpolar interior is the main barrier."},{"label":"Ions are always larger than cells.","correct":false,"feedback":"Ions are tiny, but charge rather than overall size is the key obstacle here."}]}},{"id":"cytoplasm-cytoskeleton","chapter":null,"chapterSummary":null,"title":"Cytoplasm is organized, not shapeless","highYield":"Cytosol suspends organelles, while the cytoskeleton supports shape, internal transport, movement, and division.","teach":["The cytosol is the intracellular fluid in which dissolved substances and suspended macromolecules interact. Together with organelles and stored inclusions, it forms the cytoplasm outside the nucleus. Many metabolic reactions occur here, including the first stage of glucose breakdown.","Protein filaments organize the interior. Microtubules act as structural supports and tracks, help form the mitotic spindle, and contribute to cilia and flagella. Other filaments resist tension, position organelles, and help cells change shape. The result is a dynamic internal framework rather than a bag of floating parts."],"keyPoints":["Cytosol is the fluid portion; cytoplasm includes cytosol plus internal structures outside the nucleus.","The cytoskeleton maintains shape and positions cellular components.","Microtubules support transport, motility structures, and chromosome movement.","Cellular organization depends on continual remodeling."],"visual":{"title":"A cell as a working room","kind":"analogy-map","items":[{"label":"Cytosol","detail":"The fluid workspace where many reactions occur."},{"label":"Cytoskeleton","detail":"Beams and tracks that organize the room."},{"label":"Motor proteins","detail":"Molecular movers that carry cargo along selected tracks."},{"label":"Organelles","detail":"Specialized workstations placed within the network."}]},"mnemonic":{"title":"Skeleton does more than support","cue":"Shape · Ship · Split","explanation":"The cytoskeleton shapes the cell, helps ship cargo, and participates when cells split."},"goodToKnow":"Cilia usually occur in large numbers and move material over a cell surface; a flagellum is longer and propels a cell, as in a sperm cell.","act":{"type":"choice","prompt":"A vesicle moves from the cell center toward the membrane. Which structure most directly provides an intracellular track?","options":[{"label":"A cytoskeletal microtubule","correct":true,"feedback":"Correct. Microtubules commonly serve as tracks for motor-driven vesicle transport."},{"label":"A chromosome","correct":false,"feedback":"Chromosomes carry genetic information rather than serving as routine cargo tracks."},{"label":"The nucleolus","correct":false,"feedback":"The nucleolus helps assemble ribosomal components inside the nucleus."}]}},{"id":"cell-boundary-match","title":"Match it: Membrane cross-section","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Water-based environment outside the cell.","Face the aqueous environments on both surfaces.","Paired fatty-acid tails restrict many polar solutes.","Spans the bilayer as a channel, carrier, or receptor.","Water-based internal environment."],"items":[{"label":"Polar heads","category":1,"feedback":"Polar heads: Face the aqueous environments on both surfaces."},{"label":"Cytoplasm","category":4,"feedback":"Cytoplasm: Water-based internal environment."},{"label":"Nonpolar core","category":2,"feedback":"Nonpolar core: Paired fatty-acid tails restrict many polar solutes."},{"label":"Extracellular fluid","category":0,"feedback":"Extracellular fluid: Water-based environment outside the cell."},{"label":"Transmembrane protein","category":3,"feedback":"Transmembrane protein: Spans the bilayer as a channel, carrier, or receptor."}]}},{"id":"nucleus-mitochondria","chapter":"Coordinate the organelle network","chapterSummary":"Group organelles by information, energy, manufacture, shipping, cleanup, and movement.","title":"The nucleus stores instructions; mitochondria release usable energy","highYield":"The nucleus protects and manages most genetic information, while mitochondria convert fuel energy into ATP through aerobic pathways.","teach":["A double nuclear envelope separates nucleoplasm from cytoplasm, and nuclear pores regulate exchange. DNA associated with proteins forms chromatin, which condenses into visible chromosomes during division. The nucleolus is a dense region where ribosomal RNA is produced and early ribosome assembly begins.","Mitochondria also have two membranes. Folds of the inner membrane, called cristae, expand the surface available for electron transport and ATP production. Cells with high energy demand generally contain many mitochondria, showing the recurring structure–function principle."],"keyPoints":["Nuclear pores permit controlled traffic between nucleus and cytoplasm.","Chromatin contains DNA and associated proteins.","The nucleolus contributes components used to assemble ribosomes.","Cristae increase inner-membrane area for ATP-producing machinery."],"visual":{"title":"Two double-membrane organelles","kind":"paired-diagram","items":[{"label":"Nucleus","detail":"Envelope, pores, chromatin, and nucleolus organize genetic control."},{"label":"Mitochondrion","detail":"Outer membrane, inner membrane, cristae, and matrix organize aerobic metabolism."},{"label":"Functional link","detail":"Nuclear genes encode many proteins needed for mitochondrial work."}]},"mnemonic":{"title":"Nucleus knows; mitochondria mobilize","cue":"Know and mobilize","explanation":"The nucleus manages information, while mitochondria mobilize energy into ATP."},"goodToKnow":"Mitochondria contain a small amount of their own DNA, but most proteins they use are encoded by nuclear genes.","act":{"type":"choice","prompt":"Which structural feature most directly expands the surface for mitochondrial electron transport?","options":[{"label":"Cristae","correct":true,"feedback":"Correct. Cristae are folds of the inner mitochondrial membrane."},{"label":"Nuclear pores","correct":false,"feedback":"Nuclear pores control exchange across the nuclear envelope."},{"label":"Lysosomal vesicles","correct":false,"feedback":"Lysosomes digest selected cellular material."}]}},{"id":"endomembrane-system","chapter":null,"chapterSummary":null,"title":"ER, Golgi, and vesicles form a production line","highYield":"Rough ER begins production of many exported and membrane proteins; Golgi compartments modify, sort, and package them.","teach":["Rough endoplasmic reticulum has ribosomes attached to its cytosolic surface. Proteins destined for secretion, membranes, or certain organelles enter this system as they are made, then fold and receive early modifications. Smooth ER lacks attached ribosomes and contributes to lipid synthesis, detoxification, and calcium handling in specialized cells.","Transport vesicles carry cargo from ER to the Golgi apparatus. Flattened Golgi cisternae receive, modify, label, and sort products into new vesicles. Destinations can include the plasma membrane, secretion outside the cell, or a digestive compartment. Directional trafficking prevents cellular products from being delivered at random."],"keyPoints":["Rough ER is associated with ribosomes and many proteins entering the endomembrane pathway.","Smooth ER emphasizes lipid-related and specialized chemical tasks.","Golgi cisternae modify and sort incoming cargo.","Vesicles connect compartments and deliver products to selected destinations."],"visual":{"title":"Protein shipping route","kind":"process-flow","items":[{"label":"Ribosome on rough ER","detail":"Builds a protein into the ER pathway."},{"label":"Transport vesicle","detail":"Buds from ER carrying newly made cargo."},{"label":"Golgi apparatus","detail":"Modifies, labels, and sorts cargo."},{"label":"Delivery vesicle","detail":"Moves cargo to the membrane, secretion, or another compartment."}]},"mnemonic":{"title":"Build, fold, finish, forward","cue":"Ribosome → ER → Golgi → vesicle","explanation":"Use the four verbs to rehearse the secretory pathway in order."},"goodToKnow":"Free ribosomes and rough-ER-bound ribosomes are structurally similar; the destination signal on a growing protein helps determine where synthesis continues.","act":{"type":"choice","prompt":"A newly made digestive enzyme is ready to leave the rough ER. What is the next major destination?","options":[{"label":"A transport vesicle heading to the Golgi apparatus","correct":true,"feedback":"Correct. Vesicles transfer secretory-pathway cargo from ER to Golgi."},{"label":"Directly into the nucleus","correct":false,"feedback":"Secreted proteins do not normally return to the nucleus after entering rough ER."},{"label":"Directly into chromatin","correct":false,"feedback":"Chromatin is DNA-protein material, not a protein shipping destination."}]}},{"id":"cleanup-movement","chapter":null,"chapterSummary":null,"title":"Lysosomes recycle; centrioles and surface structures organize movement","highYield":"Cells survive by removing damaged material and by organizing controlled movement inside or at the surface.","teach":["Lysosomes are enzyme-containing vesicles that break down selected macromolecules, worn organelles, and material brought into the cell. Their membrane isolates digestive enzymes from most cytoplasm. Recovered building blocks can be reused. Extensive enzyme release can contribute to autolysis, while apoptosis is a regulated program of cell dismantling.","Near the nucleus, the centrosome organizes microtubules and contains a pair of centrioles in many animal cells. Microtubules contribute to the spindle during division and form the internal scaffold of cilia and flagella. These structures show how one molecular system can support transport, division, and movement."],"keyPoints":["Lysosomal enzymes digest selected cellular and imported material.","Recycling returns usable components to the cytoplasm.","The centrosome is a major microtubule-organizing site.","Cilia move material across a surface; a flagellum propels a cell."],"visual":{"title":"Maintain and move","kind":"two-pathway","items":[{"label":"Maintenance pathway","detail":"Damaged material → lysosome → breakdown → reusable components."},{"label":"Division pathway","detail":"Centrosome → spindle microtubules → chromosome movement."},{"label":"Surface pathway","detail":"Microtubule bundles → cilia or flagellum → directed movement."}]},"mnemonic":{"title":"Lysosomes lyse and recycle","cue":"Digest, recover, reuse","explanation":"The sequence emphasizes controlled intracellular digestion rather than indiscriminate destruction."},"goodToKnow":"Apoptosis is organized cell death used in development and tissue maintenance; it is conceptually different from uncontrolled injury-related cell breakdown.","act":{"type":"choice","prompt":"Which organelle most directly digests a worn-out cellular component?","options":[{"label":"Lysosome","correct":true,"feedback":"Correct. Lysosomal enzymes break down selected material for disposal or reuse."},{"label":"Nucleolus","correct":false,"feedback":"The nucleolus participates in ribosome production."},{"label":"Centriole","correct":false,"feedback":"Centrioles are associated with microtubule organization, not digestion."}]}},{"id":"organelle-network-order","title":"Put it in order: Protein shipping route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ribosome on rough ER","detail":"Builds a protein into the ER pathway."},{"label":"Transport vesicle","detail":"Buds from ER carrying newly made cargo."},{"label":"Golgi apparatus","detail":"Modifies, labels, and sorts cargo."},{"label":"Delivery vesicle","detail":"Moves cargo to the membrane, secretion, or another compartment."}]}},{"id":"organelle-network-match","title":"Match it: Two double-membrane organelles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Envelope, pores, chromatin, and nucleolus organize genetic control.","Outer membrane, inner membrane, cristae, and matrix organize aerobic metabolism.","Nuclear genes encode many proteins needed for mitochondrial work."],"items":[{"label":"Nucleus","category":0,"feedback":"Nucleus: Envelope, pores, chromatin, and nucleolus organize genetic control."},{"label":"Mitochondrion","category":1,"feedback":"Mitochondrion: Outer membrane, inner membrane, cristae, and matrix organize aerobic metabolism."},{"label":"Functional link","category":2,"feedback":"Functional link: Nuclear genes encode many proteins needed for mitochondrial work."}]}},{"id":"protein-synthesis","chapter":"Turn information into protein","chapterSummary":"Follow the logic from DNA to RNA to an amino-acid sequence, then compare the plant-cell plan.","title":"Transcription and translation connect genes to proteins","highYield":"Transcription makes an RNA copy from DNA; translation reads messenger RNA to assemble an amino-acid chain.","teach":["During transcription, a selected DNA region serves as a template for messenger RNA. The RNA copy can leave the nucleus through a pore while the original DNA remains protected. This separates information storage from the cytoplasmic machinery that uses the message.","At a ribosome, translation reads messenger RNA in three-base codons. Transfer RNA molecules use complementary anticodons to deliver the appropriate amino acids. Ribosomal RNA helps form the ribosome and supports peptide-bond formation. The amino-acid sequence then folds and may be processed further to become a functional protein."],"keyPoints":["DNA is the long-term information store; messenger RNA is a working copy.","Transcription occurs in the nucleus of a typical human cell.","Translation occurs at ribosomes in the cytoplasm or on rough ER.","Transfer RNA pairs anticodons with codons and carries amino acids.","Protein function depends on sequence, folding, and often later modification."],"visual":{"title":"Information relay","kind":"sequence","items":[{"label":"DNA gene","detail":"Stores the nucleotide sequence in the nucleus."},{"label":"Transcription","detail":"Produces a complementary messenger RNA copy."},{"label":"mRNA at ribosome","detail":"Presents codons in sequence."},{"label":"tRNA delivery","detail":"Matches anticodons and brings amino acids."},{"label":"Polypeptide","detail":"Folds and may be modified into a working protein."}]},"mnemonic":{"title":"Message, transfer, ribosome","cue":"mRNA = message · tRNA = transfer · rRNA = ribosome","explanation":"The initials cue the distinct roles of the three major RNA types in protein synthesis."},"goodToKnow":"A gene is not converted into a protein molecule directly; information is transcribed and translated through intermediates.","act":{"type":"choice","prompt":"Which molecule carries an amino acid to a ribosome and pairs with an mRNA codon?","options":[{"label":"Transfer RNA","correct":true,"feedback":"Correct. tRNA carries an amino acid and uses its anticodon to recognize an mRNA codon."},{"label":"DNA polymerase","correct":false,"feedback":"DNA polymerase participates in DNA replication, not amino-acid delivery."},{"label":"A phospholipid","correct":false,"feedback":"Phospholipids are major membrane components, not translation adaptors."}]}},{"id":"plant-comparison","chapter":null,"chapterSummary":null,"title":"Plant cells add structures for support and photosynthesis","highYield":"Plant and animal cells share the eukaryotic core, but plant cells also have a cellulose wall, plastids, and a prominent vacuole.","teach":["Plant cells contain nuclei, mitochondria, ER, ribosomes, Golgi apparatus, and plasma membranes just as animal cells do. A rigid cellulose cell wall lies outside the plasma membrane and supports cell shape. A large central vacuole helps store material and contributes to internal pressure.","Chloroplasts are plastids that capture light energy for photosynthesis. Their thylakoid membranes stack into grana, linked by lamellae. Other plastids store materials or pigments. Human cells have no cell wall or chloroplasts, so plant-specific structures should not be assigned to a typical anatomy diagram of a human cell."],"keyPoints":["Both plant and animal cells are eukaryotic.","The plant cell wall is outside the plasma membrane and contains cellulose.","Chloroplast thylakoids are organized into grana.","A large central vacuole is characteristic of many mature plant cells.","Human cells lack chloroplasts and cellulose walls."],"visual":{"title":"Shared core and plant additions","kind":"venn-model","items":[{"label":"Shared","detail":"Nucleus, mitochondria, ER, Golgi, ribosomes, plasma membrane."},{"label":"Plant emphasis","detail":"Cellulose wall, chloroplasts and other plastids, large central vacuole."},{"label":"Animal emphasis","detail":"Flexible outer boundary and centrioles in many cells; no chloroplasts."}]},"mnemonic":{"title":"Plants have the three Cs","cue":"Cell wall · Chloroplast · Central vacuole","explanation":"The three Cs quickly identify the most familiar plant-cell additions."},"goodToKnow":"Carotene and xanthophyll are pigments found in certain plant plastids; they are not human cellular organelles even though humans obtain related compounds from foods.","act":{"type":"choice","prompt":"A diagram shows a nucleus, mitochondria, a cellulose wall, and chloroplasts. What is the best identification?","options":[{"label":"A plant eukaryotic cell","correct":true,"feedback":"Correct. The nucleus confirms a eukaryote, while the cellulose wall and chloroplasts identify a plant cell."},{"label":"A typical human epithelial cell","correct":false,"feedback":"Human cells do not have cellulose walls or chloroplasts."},{"label":"A prokaryotic bacterial cell","correct":false,"feedback":"A membrane-bound nucleus and chloroplasts rule out a prokaryote."}]}},{"id":"information-flow-order","title":"Put it in order: Information relay","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"DNA gene","detail":"Stores the nucleotide sequence in the nucleus."},{"label":"Transcription","detail":"Produces a complementary messenger RNA copy."},{"label":"mRNA at ribosome","detail":"Presents codons in sequence."},{"label":"tRNA delivery","detail":"Matches anticodons and brings amino acids."},{"label":"Polypeptide","detail":"Folds and may be modified into a working protein."}]}},{"id":"information-flow-match","title":"Match it: Shared core and plant additions","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Nucleus, mitochondria, ER, Golgi, ribosomes, plasma membrane.","Cellulose wall, chloroplasts and other plastids, large central vacuole.","Flexible outer boundary and centrioles in many cells; no chloroplasts."],"items":[{"label":"Shared","category":0,"feedback":"Shared: Nucleus, mitochondria, ER, Golgi, ribosomes, plasma membrane."},{"label":"Plant emphasis","category":1,"feedback":"Plant emphasis: Cellulose wall, chloroplasts and other plastids, large central vacuole."},{"label":"Animal emphasis","category":2,"feedback":"Animal emphasis: Flexible outer boundary and centrioles in many cells; no chloroplasts."}]}}],"flashcards":[{"front":"What are the three central principles of modern cell theory?","back":"Organisms are composed of cells; the cell is the basic unit of living structure and function; new cells arise from existing cells."},{"front":"What makes a cell eukaryotic?","back":"Its DNA is enclosed in a nucleus and it uses membrane-bound organelles to compartmentalize many functions."},{"front":"What is the difference between cytosol and cytoplasm?","back":"Cytosol is the intracellular fluid; cytoplasm includes cytosol and structures outside the nucleus."},{"front":"How are phospholipids oriented in a membrane?","back":"Polar heads face water on both sides, and nonpolar tails face inward toward one another."},{"front":"Name four jobs of membrane proteins.","back":"Transport, receptor signaling, enzymatic activity, adhesion/anchoring, or identity marking; any four."},{"front":"What is the nucleolus?","back":"A nuclear region that produces ribosomal RNA and begins assembly of ribosomal subunits."},{"front":"Why do mitochondrial cristae matter?","back":"They expand the inner-membrane surface available for electron transport and ATP production."},{"front":"Contrast rough and smooth ER.","back":"Rough ER bears ribosomes and processes many proteins; smooth ER emphasizes lipid synthesis and specialized chemical tasks."},{"front":"What does the Golgi apparatus do?","back":"It modifies, sorts, and packages cellular products for selected destinations."},{"front":"What is a lysosome?","back":"An enzyme-containing compartment that digests selected macromolecules and worn cellular material."},{"front":"What are the roles of mRNA and tRNA?","back":"mRNA carries the coded message; tRNA matches codons through its anticodon and delivers amino acids."},{"front":"What are three characteristic plant-cell structures?","back":"A cellulose cell wall, chloroplasts or other plastids, and a large central vacuole."}],"quiz":[],"caseStudy":{"title":"Follow a secreted enzyme","scenario":"A glandular cell has been stimulated to release a protein enzyme. The gene is active, the cell has abundant rough ER and Golgi cisternae, and secretory vesicles are moving toward its plasma membrane.","prompts":["Trace the enzyme from DNA information to a finished product outside the cell.","Explain why this cell contains abundant rough ER, Golgi apparatus, and mitochondria.","Predict what would happen to delivery if vesicles could no longer move along cytoskeletal tracks.","Identify the membrane event that releases vesicle contents while preserving the cell boundary."],"takeaway":"A cellular product is the result of coordinated information flow, organelle processing, energy transfer, cytoskeletal transport, and membrane trafficking—not the action of one isolated structure."}},{"n":4,"title":"Cellular Metabolism and Reproduction","kicker":"Distinguish catabolic and anabolic pathways and explain why ATP couples energy release to cellular work.","duration":"95–120 minutes","steps":[{"id":"metabolism-atp","chapter":"Think in energy pathways","chapterSummary":"Learn the language of metabolism before following glucose through the cell.","title":"Metabolism links breakdown, building, and cellular work","highYield":"Catabolism releases usable energy from larger molecules; anabolism uses energy to build larger molecules; ATP transfers energy between them.","teach":["Metabolism is the complete network of chemical reactions occurring in a cell. Catabolic pathways dismantle molecules and can capture some released energy. Anabolic pathways assemble molecules required for growth, repair, storage, and function. The two sets are coordinated rather than operating as independent switches.","ATP is a short-term energy carrier. Energy released by favorable reactions can be captured when ATP is formed, and ATP hydrolysis can then help drive transport, movement, synthesis, and signaling. ATP is not a nutrient stored in large quantities; cells continually regenerate it from ADP and phosphate."],"keyPoints":["Catabolism breaks down; anabolism builds up.","ATP couples energy-releasing reactions to energy-requiring work.","Cells continually recycle ATP rather than stockpiling a lifetime supply.","Enzymes and cellular conditions regulate pathway rate and direction."],"visual":{"title":"The ATP coupling cycle","kind":"cycle","items":[{"label":"Fuel breakdown","detail":"Catabolic reactions release chemical energy."},{"label":"ATP regeneration","detail":"Part of that energy is captured as ATP from ADP plus phosphate."},{"label":"Cellular work","detail":"ATP hydrolysis supports transport, movement, and synthesis."},{"label":"ADP return","detail":"ADP and phosphate re-enter the cycle."}]},"mnemonic":{"title":"CAT cuts; ANA assembles","cue":"Catabolism cuts · Anabolism assembles","explanation":"The verbs distinguish the two complementary directions of metabolism."},"goodToKnow":"A food calorie measures energy content; ATP is the molecular transfer currency cells use to apply captured energy to work. The terms are related but not interchangeable.","act":{"type":"choice","prompt":"Which process is anabolic?","options":[{"label":"Linking amino acids to build a cellular protein","correct":true,"feedback":"Correct. Building a larger molecule from smaller units is anabolic."},{"label":"Splitting glucose during glycolysis","correct":false,"feedback":"Glycolysis is a catabolic breakdown pathway."},{"label":"Digesting a worn organelle","correct":false,"feedback":"Breakdown and recycling are catabolic processes."}]}},{"id":"glycolysis","chapter":null,"chapterSummary":null,"title":"Glycolysis starts glucose breakdown in the cytosol","highYield":"One six-carbon glucose becomes two three-carbon pyruvate molecules, with a small net ATP gain and reduced electron carriers.","teach":["Glycolysis is a sequence of enzyme-controlled reactions in the cytosol. An early investment phase uses ATP to activate glucose. Later reactions split and rearrange the carbon skeleton, producing two pyruvate and capturing energy in ATP and NADH. The pathway does not directly require oxygen.","Because glycolysis occurs outside mitochondria, it can provide ATP quickly and can continue under limited oxygen if NADH is reoxidized. Its direct ATP yield is modest compared with the complete aerobic pathway, so glycolysis is the opening stage rather than the whole story of cellular respiration."],"keyPoints":["Location: cytosol.","Carbon result: one glucose becomes two pyruvate.","Energy result: a small net amount of ATP plus NADH.","Oxygen is not a direct reactant in glycolysis.","The fate of pyruvate depends on cellular conditions."],"visual":{"title":"Glycolysis carbon ledger","kind":"process-flow","items":[{"label":"Glucose","detail":"One six-carbon starting molecule."},{"label":"Investment","detail":"ATP is used to prepare the molecule for splitting."},{"label":"Two three-carbon pathways","detail":"The reactions proceed twice after the split."},{"label":"Pyruvate","detail":"Two three-carbon end products remain."},{"label":"Captured energy","detail":"A small net ATP gain and NADH are produced."}]},"mnemonic":{"title":"Split, harvest, decide","cue":"Glucose splits · energy is harvested · pyruvate fate is decided","explanation":"The three-part cue captures the logic without memorizing every intermediate first."},"goodToKnow":"Glycolysis makes four ATP but uses two earlier in the pathway, so its direct net gain is two ATP per glucose.","act":{"type":"choice","prompt":"Which statement about glycolysis is accurate?","options":[{"label":"It occurs in the cytosol and produces two pyruvate per glucose.","correct":true,"feedback":"Correct. That location and carbon outcome define the pathway."},{"label":"It occurs only inside the nucleus.","correct":false,"feedback":"Glycolysis is a cytosolic pathway."},{"label":"It directly uses oxygen to split water.","correct":false,"feedback":"Oxygen is not a direct glycolysis reactant."}]}},{"id":"metabolic-logic-order","title":"Put it in order: Glycolysis carbon ledger","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Glucose","detail":"One six-carbon starting molecule."},{"label":"Investment","detail":"ATP is used to prepare the molecule for splitting."},{"label":"Two three-carbon pathways","detail":"The reactions proceed twice after the split."},{"label":"Pyruvate","detail":"Two three-carbon end products remain."},{"label":"Captured energy","detail":"A small net ATP gain and NADH are produced."}]}},{"id":"metabolic-logic-match","title":"Match it: The ATP coupling cycle","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Catabolic reactions release chemical energy.","Part of that energy is captured as ATP from ADP plus phosphate.","ATP hydrolysis supports transport, movement, and synthesis.","ADP and phosphate re-enter the cycle."],"items":[{"label":"ADP return","category":3,"feedback":"ADP return: ADP and phosphate re-enter the cycle."},{"label":"Cellular work","category":2,"feedback":"Cellular work: ATP hydrolysis supports transport, movement, and synthesis."},{"label":"ATP regeneration","category":1,"feedback":"ATP regeneration: Part of that energy is captured as ATP from ADP plus phosphate."},{"label":"Fuel breakdown","category":0,"feedback":"Fuel breakdown: Catabolic reactions release chemical energy."}]}},{"id":"citric-cycle","chapter":"Complete aerobic respiration","chapterSummary":"Move pyruvate into mitochondria, harvest electrons, and use oxygen at the end of the chain.","title":"Pyruvate links glycolysis to the citric acid cycle","highYield":"Pyruvate is converted to acetyl-CoA; the citric acid cycle releases carbon dioxide and loads electron carriers.","teach":["Under aerobic conditions, pyruvate enters a mitochondrion and is converted to acetyl-CoA, producing carbon dioxide and NADH. Acetyl-CoA then joins a four-carbon acceptor in the citric acid cycle, also called the Krebs cycle. The cycle regenerates its starting acceptor so another acetyl group can enter.","For each turn, carbon leaves as carbon dioxide, a small amount of ATP or an equivalent is formed, and much of the available energy is transferred to NADH and FADH2. The cycle is therefore best viewed as an electron-carrier loading system rather than the main direct source of ATP."],"keyPoints":["Pyruvate oxidation produces acetyl-CoA before the cycle begins.","The citric acid cycle operates in the mitochondrial matrix.","Carbon dioxide is released during pyruvate oxidation and the cycle.","NADH and FADH2 carry high-energy electrons onward.","Only a small portion of ATP is made directly in the cycle."],"visual":{"title":"Mitochondrial carbon route","kind":"cycle-and-entry","items":[{"label":"Pyruvate entry","detail":"The three-carbon product of glycolysis enters the mitochondrion."},{"label":"Acetyl-CoA","detail":"A two-carbon acetyl group is linked to coenzyme A."},{"label":"Cycle entry","detail":"The acetyl group joins a regenerated four-carbon acceptor."},{"label":"Carbon exit","detail":"Carbon dioxide leaves during oxidation steps."},{"label":"Carrier loading","detail":"NADH and FADH2 collect electrons for the next stage."}]},"mnemonic":{"title":"Acetyl enters; carriers exit loaded","cue":"A in, CO2 out, NADH/FADH2 loaded","explanation":"The cue tracks the main inputs and outputs without treating the cycle as a simple ATP factory."},"goodToKnow":"The cycle name refers to regeneration of the starting acceptor; acetyl carbon enters each turn while oxidized carbon eventually exits as carbon dioxide.","act":{"type":"choice","prompt":"What is the main energy-related output of the citric acid cycle?","options":[{"label":"Reduced electron carriers such as NADH and FADH2","correct":true,"feedback":"Correct. The cycle primarily loads carriers that feed electron transport."},{"label":"A large stockpile of glucose","correct":false,"feedback":"The pathway oxidizes carbon fuel rather than storing glucose."},{"label":"Messenger RNA","correct":false,"feedback":"mRNA is produced by transcription, not the citric acid cycle."}]}},{"id":"electron-transport","chapter":null,"chapterSummary":null,"title":"Electron transport creates the gradient that drives most ATP formation","highYield":"Electrons move through inner-membrane carriers; their energy pumps protons, and oxygen accepts electrons at the end.","teach":["NADH and FADH2 donate electrons to a chain of carriers in the inner mitochondrial membrane. As electrons move toward lower-energy states, selected complexes use released energy to pump hydrogen ions across the membrane. This creates an electrochemical gradient, storing potential energy.","Hydrogen ions flow back through ATP synthase, which couples that flow to ATP formation. Oxygen is the terminal electron acceptor and combines with electrons and hydrogen ions to form water. If oxygen is unavailable, the chain backs up and oxidative ATP production cannot continue normally."],"keyPoints":["The electron transport chain is embedded in the inner mitochondrial membrane.","Electron energy pumps protons and builds a gradient.","ATP synthase uses proton flow to phosphorylate ADP.","Oxygen accepts electrons at the end and contributes to water formation.","Most ATP from complete aerobic glucose oxidation is formed here."],"visual":{"title":"Electron-to-ATP converter","kind":"membrane-gradient","items":[{"label":"NADH/FADH2","detail":"Deliver high-energy electrons."},{"label":"Carrier chain","detail":"Transfers electrons and powers proton pumping."},{"label":"Proton gradient","detail":"Stores energy across the inner membrane."},{"label":"ATP synthase","detail":"Uses proton return to make ATP."},{"label":"Oxygen","detail":"Receives electrons at the chain end and supports water formation."}]},"mnemonic":{"title":"Electrons pump; protons power","cue":"e− move → H+ gradient → ATP","explanation":"Electron movement builds the gradient, and proton flow through ATP synthase powers ATP production."},"goodToKnow":"Older textbook accounting often gives one fixed ATP total per glucose. Modern estimates vary with cell type, shuttle systems, and coupling efficiency, so pathway logic is more dependable than a universal number.","act":{"type":"choice","prompt":"What directly powers ATP synthase during oxidative phosphorylation?","options":[{"label":"Hydrogen ions flowing down their electrochemical gradient","correct":true,"feedback":"Correct. Proton flow through ATP synthase is coupled to ATP formation."},{"label":"DNA moving out of the nucleus","correct":false,"feedback":"DNA remains the genetic template and does not power ATP synthase."},{"label":"Carbon dioxide binding to glucose","correct":false,"feedback":"Carbon dioxide is an oxidation product, not the immediate energy source for ATP synthase."}]}},{"id":"aerobic-respiration-match","title":"Match it: Mitochondrial carbon route","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["The three-carbon product of glycolysis enters the mitochondrion.","A two-carbon acetyl group is linked to coenzyme A.","The acetyl group joins a regenerated four-carbon acceptor.","Carbon dioxide leaves during oxidation steps.","NADH and FADH2 collect electrons for the next stage."],"items":[{"label":"Acetyl-CoA","category":1,"feedback":"Acetyl-CoA: A two-carbon acetyl group is linked to coenzyme A."},{"label":"Carrier loading","category":4,"feedback":"Carrier loading: NADH and FADH2 collect electrons for the next stage."},{"label":"Cycle entry","category":2,"feedback":"Cycle entry: The acetyl group joins a regenerated four-carbon acceptor."},{"label":"Pyruvate entry","category":0,"feedback":"Pyruvate entry: The three-carbon product of glycolysis enters the mitochondrion."},{"label":"Carbon exit","category":3,"feedback":"Carbon exit: Carbon dioxide leaves during oxidation steps."}]}},{"id":"anaerobic-pathways","chapter":"Adapt when oxygen or fuel changes","chapterSummary":"Compare fermentation routes and see where fat and protein can enter shared metabolic pathways.","title":"Fermentation regenerates NAD+ so glycolysis can continue","highYield":"When electron transport cannot reoxidize NADH fast enough, cells can transfer electrons to an organic molecule and preserve glycolytic ATP production.","teach":["In human cells under limited oxygen availability or very high demand, pyruvate can accept electrons from NADH and become lactate. This regenerates NAD+, which glycolysis needs. The process does not add extra ATP beyond the ATP already made by glycolysis, but it allows that small supply to continue temporarily.","Some microorganisms use alcoholic fermentation, converting pyruvate through acetaldehyde to ethanol and carbon dioxide while regenerating NAD+. Human muscle does not make ethanol as its normal anaerobic route. Fermentation should therefore be described by organism and end product rather than treated as one universal reaction."],"keyPoints":["The immediate purpose of fermentation is NAD+ regeneration.","Lactate formation is the relevant human pathway discussed here.","Alcoholic fermentation produces ethanol and carbon dioxide in organisms such as yeast.","Fermentation relies on glycolysis for its ATP.","Anaerobic output is limited compared with complete aerobic oxidation."],"visual":{"title":"Two pyruvate branches","kind":"branching-path","items":[{"label":"Shared start","detail":"Glycolysis produces pyruvate, NADH, and a small ATP gain."},{"label":"Human lactate branch","detail":"Pyruvate accepts electrons and NAD+ is regenerated."},{"label":"Yeast alcohol branch","detail":"Acetaldehyde becomes ethanol; carbon dioxide is released."},{"label":"Aerobic branch","detail":"Pyruvate enters mitochondrial oxidation when conditions support it."}]},"mnemonic":{"title":"Fermentation frees NAD+","cue":"NAD+ back, glycolysis on","explanation":"The key result is carrier recycling, not a large extra ATP reward."},"goodToKnow":"Lactate is not simply metabolic waste; it can be transported and used in other metabolic pathways. This lesson focuses on pathway logic rather than exercise prescriptions.","act":{"type":"choice","prompt":"Why does lactate formation help glycolysis continue?","options":[{"label":"It regenerates NAD+ from NADH.","correct":true,"feedback":"Correct. Glycolysis needs oxidized NAD+ to accept more electrons."},{"label":"It creates oxygen inside the cell.","correct":false,"feedback":"The pathway does not manufacture oxygen."},{"label":"It produces a large amount of mitochondrial ATP.","correct":false,"feedback":"The ATP comes from glycolysis and remains limited."}]}},{"id":"other-fuels","chapter":null,"chapterSummary":null,"title":"Fat and protein feed the same metabolic network at different entry points","highYield":"Glycerol, fatty acids, and amino-acid carbon skeletons can enter glycolysis, acetyl-CoA formation, or the citric acid cycle after appropriate processing.","teach":["Triglycerides are separated into glycerol and fatty acids. Glycerol can be converted to a glycolytic intermediate, while fatty acids are shortened through beta oxidation to produce acetyl-CoA and reduced carriers. This explains why fat is energy-dense and why its complete oxidation depends on mitochondrial pathways.","Amino acids can contribute to energy metabolism after removal or transfer of their nitrogen-containing amino group. The remaining carbon skeleton enters at different points depending on the amino acid. Nitrogen requires separate handling, so protein use is not identical to carbohydrate or fat oxidation."],"keyPoints":["Glycerol can enter near the glycolytic pathway.","Beta oxidation converts fatty acids into acetyl-CoA units and electron carriers.","Amino acids require nitrogen handling before carbon skeletons enter energy pathways.","Multiple fuels converge on shared mitochondrial reactions.","Fuel use depends on cellular state and regulation, not one nutrient in isolation."],"visual":{"title":"Fuel convergence map","kind":"converging-flow","items":[{"label":"Carbohydrate","detail":"Glucose enters glycolysis and forms pyruvate."},{"label":"Fat","detail":"Glycerol approaches glycolysis; fatty acids form acetyl-CoA."},{"label":"Protein","detail":"Amino-acid carbon skeletons enter at several metabolic points."},{"label":"Shared hub","detail":"Acetyl-CoA, citric acid cycle, and electron transport integrate fuel oxidation."}]},"mnemonic":{"title":"Glycerol joins, fatty acids fragment, amino acids adapt","cue":"Join · Fragment · Adapt","explanation":"The three verbs distinguish the main routes without suggesting all fuels enter at the same point."},"goodToKnow":"Metabolic flexibility means several fuels can contribute, but tissue type, hormonal state, oxygen supply, and recent intake influence which pathways are most active.","act":{"type":"choice","prompt":"Which product of fatty-acid beta oxidation enters the citric acid cycle pathway?","options":[{"label":"Acetyl-CoA","correct":true,"feedback":"Correct. Fatty acids are shortened into acetyl-CoA units."},{"label":"Messenger RNA","correct":false,"feedback":"mRNA carries genetic information and is not a fuel intermediate."},{"label":"Lactic acid as the only product","correct":false,"feedback":"Fatty-acid oxidation does not require conversion to lactate as its sole route."}]}},{"id":"alternative-fates-order","title":"Put it in order: Two pyruvate branches","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Shared start","detail":"Glycolysis produces pyruvate, NADH, and a small ATP gain."},{"label":"Human lactate branch","detail":"Pyruvate accepts electrons and NAD+ is regenerated."},{"label":"Yeast alcohol branch","detail":"Acetaldehyde becomes ethanol; carbon dioxide is released."},{"label":"Aerobic branch","detail":"Pyruvate enters mitochondrial oxidation when conditions support it."}]}},{"id":"dna-replication","chapter":"Copy information and divide a somatic cell","chapterSummary":"Connect complementary DNA structure to replication, then place mitosis inside the full cell cycle.","title":"Complementary DNA strands make accurate copying possible","highYield":"A pairs with T and C pairs with G; each original strand can guide synthesis of a complementary new strand.","teach":["DNA consists of two antiparallel nucleotide strands twisted into a double helix. Each nucleotide contains deoxyribose, phosphate, and one nitrogenous base. Adenine pairs with thymine through hydrogen bonds, while cytosine pairs with guanine. The base sequence carries genetic information.","Before division, the strands separate and each acts as a template for a new complementary strand. The result is two DNA molecules, each containing one old strand and one newly synthesized strand. Proofreading and repair improve accuracy, although replication errors can still occur."],"keyPoints":["A DNA nucleotide contains sugar, phosphate, and a base.","Complementary base pairing is A–T and C–G.","Base sequence stores information.","Replication is semiconservative: each product contains one original strand.","DNA must be copied before a cell can distribute chromosomes."],"visual":{"title":"Copy by complement","kind":"molecular-sequence","items":[{"label":"Parental helix","detail":"Two complementary DNA strands are paired."},{"label":"Strand separation","detail":"Hydrogen-bonded base pairs separate."},{"label":"Template reading","detail":"Each exposed base directs a complementary nucleotide."},{"label":"Two helices","detail":"Each contains one original and one new strand."}]},"mnemonic":{"title":"Apples in Trees; Cars in Garages","cue":"A–T · C–G","explanation":"The paired images cue the two complementary DNA base pairs."},"goodToKnow":"Watson and Crick proposed the double-helix model using crucial evidence that included Rosalind Franklin and Maurice Wilkins, along with base-pair findings from Erwin Chargaff.","act":{"type":"choice","prompt":"If one DNA strand reads A-C-G-T, what is the complementary sequence?","options":[{"label":"T-G-C-A","correct":true,"feedback":"Correct. A pairs with T, and C pairs with G."},{"label":"A-C-G-T","correct":false,"feedback":"The complementary strand uses paired bases rather than repeating the same sequence."},{"label":"U-G-C-A","correct":false,"feedback":"Uracil belongs to RNA; DNA uses thymine."}]}},{"id":"cell-cycle-mitosis","chapter":null,"chapterSummary":null,"title":"Mitosis distributes duplicated chromosomes to two nuclei","highYield":"Interphase prepares and copies DNA; mitosis separates duplicated chromosomes; cytokinesis divides the cell.","teach":["The cell cycle includes interphase and a division phase. During interphase, a cell grows, performs normal functions, duplicates DNA, and prepares division machinery. Interphase is active preparation, not a resting pause. After replication, each chromosome consists of sister chromatids joined at a centromere.","In prophase chromosomes condense and the spindle forms; in metaphase chromosomes align; in anaphase sister chromatids separate; in telophase new nuclear regions form. Cytokinesis partitions the cytoplasm. The resulting daughter cells normally receive equivalent chromosome sets for growth, replacement, and repair."],"keyPoints":["DNA replication occurs before mitosis, during interphase.","Prophase condenses, metaphase aligns, anaphase separates, telophase re-forms nuclei.","Sister chromatids separate during anaphase.","Cytokinesis divides cytoplasm after or alongside nuclear division.","Cell-cycle checkpoints help prevent damaged or incomplete cells from progressing."],"visual":{"title":"Mitosis chromosome choreography","kind":"timeline","items":[{"label":"Interphase","detail":"Grow, function, replicate DNA, prepare."},{"label":"Prophase","detail":"Condense chromosomes and assemble spindle."},{"label":"Metaphase","detail":"Align duplicated chromosomes at the middle."},{"label":"Anaphase","detail":"Separate sister chromatids toward opposite poles."},{"label":"Telophase + cytokinesis","detail":"Re-form nuclei and partition the cell."}]},"mnemonic":{"title":"Prepare, Meet, Apart, Two","cue":"Prophase · Metaphase · Anaphase · Telophase","explanation":"The action words cue the PMAT order and the main chromosome event in each stage."},"goodToKnow":"Cancer involves loss of normal controls on cell growth and division. Carcinogens can increase risk by damaging DNA, but cancer biology is multi-step and cannot be inferred from one exposure alone.","act":{"type":"choice","prompt":"During which mitotic stage do sister chromatids move toward opposite poles?","options":[{"label":"Anaphase","correct":true,"feedback":"Correct. Anaphase separates sister chromatids."},{"label":"Metaphase","correct":false,"feedback":"Metaphase aligns duplicated chromosomes before separation."},{"label":"Interphase","correct":false,"feedback":"Interphase includes growth and DNA replication, not chromatid separation."}]}},{"id":"dna-cell-cycle-order","title":"Put it in order: Copy by complement","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Parental helix","detail":"Two complementary DNA strands are paired."},{"label":"Strand separation","detail":"Hydrogen-bonded base pairs separate."},{"label":"Template reading","detail":"Each exposed base directs a complementary nucleotide."},{"label":"Two helices","detail":"Each contains one original and one new strand."}]}},{"id":"meiosis-logic","chapter":"Reduce chromosome number and create variation","chapterSummary":"Contrast one somatic-cell division with the two divisions that produce haploid gametes.","title":"Meiosis changes one diploid cell into haploid products","highYield":"DNA replicates once, but homologous chromosomes and then sister chromatids separate across two divisions.","teach":["A diploid human cell has homologous chromosome pairs, one member of each pair inherited from each parent. Meiosis begins after one round of DNA replication. In meiosis I, homologous chromosomes pair and then separate, reducing chromosome number. In meiosis II, sister chromatids separate in a mitosis-like division.","Crossing-over between homologous chromosomes and independent assortment of pairs create new allele combinations. The products are haploid, so fertilization can unite two gametes and restore the diploid number without chromosome number doubling in every generation."],"keyPoints":["Diploid means two chromosome sets; haploid means one set.","Homologous chromosomes separate in meiosis I.","Sister chromatids separate in meiosis II.","Crossing-over and independent assortment increase variation.","Fertilization restores the diploid chromosome number."],"visual":{"title":"One copy, two divisions","kind":"division-tree","items":[{"label":"Diploid parent cell","detail":"Contains homologous chromosome pairs."},{"label":"DNA replication","detail":"Each chromosome becomes two sister chromatids."},{"label":"Meiosis I","detail":"Homologous pairs separate; chromosome number is reduced."},{"label":"Meiosis II","detail":"Sister chromatids separate."},{"label":"Haploid products","detail":"Each receives one chromosome from every homologous pair."}]},"mnemonic":{"title":"Pairs first, sisters second","cue":"I = homologs · II = chromatids","explanation":"The sentence distinguishes the defining separation event in each meiotic division."},"goodToKnow":"Nondisjunction is a failure of chromosomes to separate normally and can change chromosome number in a gamete. The outcome depends on which chromosome and division are involved.","act":{"type":"choice","prompt":"What separates during anaphase I of meiosis?","options":[{"label":"Homologous chromosomes","correct":true,"feedback":"Correct. Meiosis I separates homologous members of each pair."},{"label":"Amino acids","correct":false,"feedback":"Amino acids are unrelated to chromosome separation."},{"label":"Sister chromatids in every case","correct":false,"feedback":"Sister chromatids normally remain together until meiosis II."}]}},{"id":"gametogenesis","chapter":null,"chapterSummary":null,"title":"Spermatogenesis and oogenesis apply meiosis differently","highYield":"Both produce haploid cells, but the timing and division of cytoplasm differ.","teach":["Spermatogenesis begins from germ cells in the testes and ordinarily produces four functional sperm from one primary meiotic cell, with cytoplasm divided relatively evenly. Continuous production after puberty creates many small, motile gametes.","Oogenesis begins before birth, includes long pauses, and divides cytoplasm unevenly so one cell retains most cellular resources. One primary meiotic cell ordinarily yields one large ovum and smaller polar bodies. The distinct patterns support different reproductive roles while using the same chromosome-reduction logic."],"keyPoints":["Both pathways reduce diploid germ cells to haploid gametes.","Spermatogenesis usually yields four functional sperm per primary meiotic cell.","Oogenesis usually concentrates cytoplasm into one functional ovum.","Meiotic timing differs substantially between the two pathways.","Fertilization unites haploid nuclei to form a diploid zygote."],"visual":{"title":"Two gamete-production patterns","kind":"comparison","items":[{"label":"Spermatogenesis","detail":"Relatively equal cytokinesis; four small functional gametes are typical."},{"label":"Oogenesis","detail":"Unequal cytokinesis; one large functional gamete and polar bodies are typical."},{"label":"Shared meiotic goal","detail":"Reduce chromosome number and create genetically varied haploid cells."}]},"mnemonic":{"title":"Sperm shares; ovum owns","cue":"Equal split versus concentrated cytoplasm","explanation":"The cue highlights the different pattern of cytoplasmic division, not the value of either gamete."},"goodToKnow":"Chromosome conditions such as trisomy 21 or XXY can result from nondisjunction, but diagnosis and counseling require appropriate clinical testing and expertise.","act":{"type":"choice","prompt":"Which comparison is most accurate?","options":[{"label":"Oogenesis usually retains most cytoplasm in one functional ovum, while spermatogenesis divides it more evenly.","correct":true,"feedback":"Correct. The different cytokinesis patterns produce different gamete forms."},{"label":"Only spermatogenesis uses meiosis.","correct":false,"feedback":"Both spermatogenesis and oogenesis use meiosis."},{"label":"Both pathways always produce four equally sized functional gametes.","correct":false,"feedback":"That does not describe oogenesis."}]}},{"id":"meiosis-match","title":"Match it: One copy, two divisions","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Contains homologous chromosome pairs.","Each chromosome becomes two sister chromatids.","Homologous pairs separate; chromosome number is reduced.","Sister chromatids separate.","Each receives one chromosome from every homologous pair."],"items":[{"label":"DNA replication","category":1,"feedback":"DNA replication: Each chromosome becomes two sister chromatids."},{"label":"Haploid products","category":4,"feedback":"Haploid products: Each receives one chromosome from every homologous pair."},{"label":"Meiosis I","category":2,"feedback":"Meiosis I: Homologous pairs separate; chromosome number is reduced."},{"label":"Diploid parent cell","category":0,"feedback":"Diploid parent cell: Contains homologous chromosome pairs."},{"label":"Meiosis II","category":3,"feedback":"Meiosis II: Sister chromatids separate."}]}}],"flashcards":[{"front":"What is metabolism?","back":"The complete network of chemical reactions in a cell or organism."},{"front":"Contrast catabolism and anabolism.","back":"Catabolism breaks molecules down and can release energy; anabolism builds molecules and requires energy."},{"front":"Where does glycolysis occur and what carbon products result?","back":"In the cytosol; one glucose becomes two pyruvate."},{"front":"What is the main role of the citric acid cycle in energy capture?","back":"It transfers electrons to NADH and FADH2 while releasing carbon dioxide and making a small direct energy yield."},{"front":"What does oxygen do in electron transport?","back":"It accepts electrons at the end of the chain and contributes to water formation."},{"front":"Why is fermentation useful?","back":"It regenerates NAD+ so glycolysis can continue producing a small amount of ATP."},{"front":"How do fatty acids enter central energy metabolism?","back":"Beta oxidation converts them into acetyl-CoA units and reduced electron carriers."},{"front":"What are the DNA base pairs?","back":"Adenine pairs with thymine; cytosine pairs with guanine."},{"front":"What is semiconservative replication?","back":"Each new DNA molecule contains one original strand and one newly synthesized strand."},{"front":"What is the order of mitosis?","back":"Prophase, metaphase, anaphase, telophase; cytokinesis partitions the cytoplasm."},{"front":"What separates in meiosis I versus meiosis II?","back":"Homologous chromosomes separate in meiosis I; sister chromatids separate in meiosis II."},{"front":"Why does meiosis matter?","back":"It produces genetically varied haploid gametes so fertilization can restore the diploid number."},{"front":"Contrast typical products of spermatogenesis and oogenesis.","back":"One primary cell typically yields four functional sperm, but one large ovum plus polar bodies."}],"quiz":[],"caseStudy":{"title":"From breakfast glucose to tissue renewal","scenario":"A tissue cell receives glucose and oxygen, uses ATP for active transport, duplicates its DNA, and later divides to replace a worn cell. During a brief period of high demand, glycolysis outpaces mitochondrial oxidation and lactate formation increases.","prompts":["Trace the major carbon and electron path from glucose through aerobic respiration.","Explain why lactate formation can support continued glycolysis but cannot match aerobic ATP output.","Place DNA replication, mitosis, and cytokinesis in the correct cell-cycle order.","Explain why this somatic-cell division is mitosis rather than meiosis."],"takeaway":"Cellular energy pathways and cell reproduction are linked by ATP demand, molecular regulation, and accurate information transfer; neither process is a single isolated reaction."}},{"n":5,"title":"Tissues","kicker":"Identify the four primary tissue classes and connect microscopic organization to function.","duration":"85–105 minutes","steps":[{"id":"four-families","chapter":"Read tissues as organized communities","chapterSummary":"Use histology and the four tissue families to move from isolated cells to organs.","title":"Four primary tissues divide the body’s work","highYield":"Epithelium covers and lines, connective tissue supports and links, muscle contracts, and nervous tissue communicates.","teach":["A tissue is a coordinated group of cells plus any extracellular material they produce. Histology studies these microscopic arrangements. Tissue identity depends not only on the cells present but also on their shape, spacing, polarity, fibers, and surrounding matrix.","The four primary tissue classes are epithelial, connective, muscle, and nervous. Most organs combine all four in different proportions. The stomach, for example, needs an epithelial lining, connective support, smooth muscle for movement, and nervous tissue for control."],"keyPoints":["Histology links microscopic structure with tissue function.","Epithelial cells form boundaries, surfaces, and glands.","Connective tissues contain cells dispersed within extracellular matrix.","Muscle produces force; nervous tissue carries and processes signals.","Organs usually contain multiple tissue classes."],"visual":{"title":"Four-tissue compass","kind":"quadrant","items":[{"label":"Epithelium","detail":"Cover, line, absorb, protect, and secrete."},{"label":"Connective","detail":"Bind, support, store, protect, and transport."},{"label":"Muscle","detail":"Shorten or develop tension to create movement."},{"label":"Nervous","detail":"Detect, integrate, and transmit information."}]},"mnemonic":{"title":"Every Connection Moves News","cue":"E · C · M · N","explanation":"The first letters cue epithelial, connective, muscle, and nervous tissue."},"goodToKnow":"A tissue sample is a two-dimensional slice through a three-dimensional structure, so orientation can change the shapes seen under a microscope.","act":{"type":"choice","prompt":"A sample contains cells packed into a continuous sheet with little extracellular matrix. Which class is most likely?","options":[{"label":"Epithelial tissue","correct":true,"feedback":"Correct. Closely packed cells forming a sheet are characteristic of epithelium."},{"label":"Connective tissue","correct":false,"feedback":"Connective tissue usually has more obvious extracellular matrix between cells."},{"label":"Nervous tissue only because it is thin","correct":false,"feedback":"Thickness alone does not identify nervous tissue."}]}},{"id":"structure-function","chapter":null,"chapterSummary":null,"title":"Arrangement predicts function","highYield":"Thin tissues favor exchange; layered tissues favor protection; fiber-rich matrices favor mechanical support.","teach":["Tissue design reflects the job. A single layer of flat cells creates a short diffusion path, useful in lung air sacs and vessel lining. Many cell layers withstand friction at the skin or mouth. Tall absorptive cells provide room for transport machinery, while cilia move surface material.","Connective tissues solve different problems through extracellular matrix. A loose matrix permits cushioning and diffusion, parallel collagen resists pull in one direction, cartilage provides resilient support, and mineralized bone resists compression. Structure–function reasoning is more durable than memorizing unrelated locations."],"keyPoints":["Cell layers affect protection versus exchange.","Cell shape provides clues to surface function.","Fiber type and orientation affect mechanical strength.","Matrix consistency ranges from fluid blood to rigid bone.","Location should confirm, not replace, structural identification."],"visual":{"title":"Design-to-job matches","kind":"matching-map","items":[{"label":"Thin single layer","detail":"Rapid exchange or smooth low-friction lining."},{"label":"Many layers","detail":"Protection from abrasion."},{"label":"Parallel collagen","detail":"Tensile strength along one main axis."},{"label":"Mineralized matrix","detail":"Rigid load-bearing support."},{"label":"Fluid matrix","detail":"Transport of cells and dissolved substances."}]},"mnemonic":{"title":"Shape serves the site","cue":"Structure → job → location","explanation":"Identify the structural clue, infer the job, then verify with a plausible location."},"goodToKnow":"A tissue can remodel when workload changes, but remodeling capacity differs among tissues and depends partly on blood supply and cell turnover.","act":{"type":"choice","prompt":"Which design best supports rapid diffusion?","options":[{"label":"A single layer of flattened cells","correct":true,"feedback":"Correct. A thin barrier shortens diffusion distance."},{"label":"Many layers of keratinized cells","correct":false,"feedback":"That arrangement emphasizes protection, not rapid exchange."},{"label":"A thick mineralized matrix","correct":false,"feedback":"Mineralized matrix provides support and creates a much longer diffusion path."}]}},{"id":"tissue-map-match","title":"Match it: Four-tissue compass","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Cover, line, absorb, protect, and secrete.","Bind, support, store, protect, and transport.","Shorten or develop tension to create movement.","Detect, integrate, and transmit information."],"items":[{"label":"Nervous","category":3,"feedback":"Nervous: Detect, integrate, and transmit information."},{"label":"Muscle","category":2,"feedback":"Muscle: Shorten or develop tension to create movement."},{"label":"Connective","category":1,"feedback":"Connective: Bind, support, store, protect, and transport."},{"label":"Epithelium","category":0,"feedback":"Epithelium: Cover, line, absorb, protect, and secrete."}]}},{"id":"epithelial-classification","chapter":"Classify coverings, linings, and glands","chapterSummary":"Name epithelia systematically, then distinguish secretions that use ducts from hormones entering tissue fluid and blood.","title":"Layer number and surface-cell shape name an epithelium","highYield":"Simple versus stratified describes layers; squamous, cuboidal, and columnar describe the cells at the free surface.","teach":["Epithelial tissue has an apical free surface and a basal surface attached to a basement membrane. It contains closely packed cells, has little extracellular matrix, and is avascular, receiving nutrients by diffusion from underlying connective tissue. Cell junctions help maintain a continuous boundary.","Simple epithelium is one cell layer thick; stratified epithelium has multiple layers. Squamous cells are flat, cuboidal cells are roughly as tall as wide, and columnar cells are taller than wide. Pseudostratified epithelium appears layered because nuclei sit at different heights, but all cells contact the basement membrane. Transitional epithelium changes shape as a urinary organ stretches."],"keyPoints":["The free surface is apical; the attached surface is basal.","Epithelium rests on a basement membrane and lacks its own blood vessels.","Simple means one layer; stratified means multiple layers.","Use the shape of apical cells to name stratified epithelium.","Pseudostratified and transitional are special arrangements, not exceptions to structure–function logic."],"visual":{"title":"Epithelial naming grid","kind":"classification-grid","items":[{"label":"Simple squamous","detail":"One thin layer; exchange and smooth lining."},{"label":"Simple cuboidal","detail":"One cube-shaped layer; secretion and absorption."},{"label":"Simple columnar","detail":"One tall-cell layer; absorption and secretion."},{"label":"Stratified squamous","detail":"Many layers; protection from abrasion."},{"label":"Pseudostratified","detail":"One layer that looks multilayered; often ciliated."},{"label":"Transitional","detail":"Layered tissue whose surface cells change shape during stretch."}]},"mnemonic":{"title":"Layers first, shape second","cue":"Simple/stratified + squamous/cuboidal/columnar","explanation":"The naming order prevents mixing cell shape with layer count."},"goodToKnow":"Endothelium is simple squamous epithelium lining blood and lymphatic vessels; mesothelium is simple squamous epithelium forming serous membranes.","act":{"type":"choice","prompt":"A lining has one layer of tall cells with nuclei near the base. How should it be classified?","options":[{"label":"Simple columnar epithelium","correct":true,"feedback":"Correct. One layer is simple and tall cells are columnar."},{"label":"Stratified squamous epithelium","correct":false,"feedback":"That would have multiple layers and flattened apical cells."},{"label":"Dense regular connective tissue","correct":false,"feedback":"Connective tissue is classified by cells and matrix, not epithelial layers."}]}},{"id":"glands","chapter":null,"chapterSummary":null,"title":"Glands specialize epithelial secretion","highYield":"Exocrine glands deliver through ducts to a surface; endocrine glands release hormones into interstitial fluid for distribution by blood.","teach":["Glandular epithelium produces and releases substances. Exocrine glands retain a connection to an epithelial surface through a duct. Their products include sweat, sebum, saliva, mucus, and digestive secretions. A unicellular goblet cell is a simple exocrine example, while multicellular glands may have branched ducts and secretory units.","Endocrine glands are ductless. They release hormones into surrounding fluid, and the hormones enter blood to reach responsive targets. The route, not merely the chemical name, distinguishes the two categories. Some organs contain both exocrine and endocrine components."],"keyPoints":["Exocrine products travel through ducts to an epithelial surface.","Endocrine hormones enter tissue fluid and then circulation.","Goblet cells are unicellular mucus-secreting exocrine glands.","Gland shape can be simple or compound and tubular or acinar.","One organ may perform both gland types."],"visual":{"title":"Two secretion routes","kind":"split-path","items":[{"label":"Exocrine cell","detail":"Product enters a duct."},{"label":"Duct route","detail":"Duct opens onto a body surface or lumen."},{"label":"Endocrine cell","detail":"Hormone enters nearby tissue fluid."},{"label":"Blood route","detail":"Capillaries distribute hormone to target cells."}]},"mnemonic":{"title":"EXits by a duct; ENters blood","cue":"EXocrine exits · ENdocrine enters","explanation":"The route words separate surface delivery from hormonal circulation."},"goodToKnow":"The pancreas illustrates a mixed organ: digestive enzymes use ducts, whereas pancreatic hormones enter the circulation.","act":{"type":"choice","prompt":"A gland releases a product into a tube that opens into the small intestine. What type is it?","options":[{"label":"Exocrine","correct":true,"feedback":"Correct. Delivery through a duct to a lumen defines an exocrine route."},{"label":"Endocrine","correct":false,"feedback":"Endocrine secretions are ductless and enter tissue fluid and blood."},{"label":"Nervous","correct":false,"feedback":"Nervous tissue communicates by electrical and chemical signals but is not this gland category."}]}},{"id":"epithelium-order","title":"Put it in order: Two secretion routes","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Exocrine cell","detail":"Product enters a duct."},{"label":"Duct route","detail":"Duct opens onto a body surface or lumen."},{"label":"Endocrine cell","detail":"Hormone enters nearby tissue fluid."},{"label":"Blood route","detail":"Capillaries distribute hormone to target cells."}]}},{"id":"loose-dense","chapter":"Build with cells, fibers, and matrix","chapterSummary":"Read connective tissue by the composition and organization of its extracellular matrix.","title":"Connective tissue proper ranges from loose packing to strong fiber bundles","highYield":"Fibroblasts make matrix; collagen provides tensile strength, elastin permits recoil, and reticular fibers form delicate support networks.","teach":["Unlike epithelium, connective tissue usually has cells separated by extracellular matrix. Fibroblasts are major matrix-producing cells. The matrix includes ground substance plus fibers. Other resident or visiting cells can store fat, defend tissue, release mediators, or clear debris.","Loose areolar tissue has open space, varied fibers, and fluid ground substance, making it useful beneath epithelia and around vessels. Adipose emphasizes lipid-storing cells, while reticular tissue forms soft scaffolds. Dense regular tissue aligns collagen in one direction, as in tendons and many ligaments; dense irregular tissue interweaves fibers to resist stress from several directions."],"keyPoints":["Connective-tissue identity depends heavily on extracellular matrix.","Fibroblasts produce fibers and ground-substance components.","Collagen resists tension; elastin supports stretch and recoil.","Loose tissue permits cushioning and exchange around other structures.","Dense regular tissue is strong mainly along the direction of its parallel fibers."],"visual":{"title":"Fiber architecture","kind":"texture-comparison","items":[{"label":"Areolar","detail":"Loose mesh with space for fluid, vessels, and migrating cells."},{"label":"Adipose","detail":"Large lipid-filled cells with storage, cushioning, and signaling roles."},{"label":"Reticular","detail":"Fine branching scaffold supporting many free cells."},{"label":"Dense regular","detail":"Parallel collagen bundles for one-direction pull."},{"label":"Dense irregular","detail":"Interwoven collagen for multi-direction stress."}]},"mnemonic":{"title":"Regular runs one way","cue":"Parallel = predictable pull","explanation":"Dense regular fibers align with the dominant direction of force."},"goodToKnow":"Adipose tissue is metabolically active and communicates through signaling molecules; it is more than inert padding or stored fuel.","act":{"type":"choice","prompt":"A tendon must resist strong pull along one main axis. Which tissue arrangement best fits?","options":[{"label":"Dense regular connective tissue with parallel collagen","correct":true,"feedback":"Correct. Parallel collagen is suited to tensile force in one direction."},{"label":"Simple squamous epithelium","correct":false,"feedback":"That thin epithelium supports exchange rather than strong tension."},{"label":"Reticular tissue only","correct":false,"feedback":"Reticular fibers form a delicate scaffold, not a tendon-like cable."}]}},{"id":"cartilage-bone-blood","chapter":null,"chapterSummary":null,"title":"Supportive and fluid connective tissues modify the matrix","highYield":"Cartilage uses a resilient gel, bone uses mineralized matrix, and blood uses plasma as a fluid matrix.","teach":["Cartilage cells called chondrocytes occupy spaces called lacunae. Hyaline cartilage provides smooth resilient support, elastic cartilage bends and recoils, and fibrocartilage combines thick collagen with resistance to compression. Cartilage has limited direct blood supply, which helps explain its relatively slow repair.","Bone has a collagen framework reinforced with mineral, producing rigid support and protection. Compact bone forms dense outer regions, while cancellous bone forms a lighter internal lattice. Blood is also connective tissue: formed elements such as red cells, white cells, and platelets are suspended in fluid plasma, allowing rapid transport."],"keyPoints":["Chondrocytes sit in lacunae within cartilage matrix.","Hyaline, elastic, and fibrocartilage differ in fiber emphasis and mechanical behavior.","Bone matrix combines organic collagen with inorganic mineral.","Compact and cancellous bone organize the same basic material differently.","Blood has a fluid extracellular matrix called plasma."],"visual":{"title":"Matrix consistency spectrum","kind":"continuum","items":[{"label":"Blood","detail":"Fluid plasma permits rapid transport."},{"label":"Cartilage","detail":"Firm, resilient matrix permits support with some flexibility."},{"label":"Bone","detail":"Mineralized matrix provides rigid strength."},{"label":"Shared principle","detail":"Cells are embedded or suspended within extracellular material."}]},"mnemonic":{"title":"Hyaline smooth, elastic springs, fibro fights pressure","cue":"Smooth · spring · compression","explanation":"The cue separates the three cartilage types by their dominant mechanical role."},"goodToKnow":"A lacuna is a space in matrix. Chondrocytes occupy cartilage lacunae and osteocytes occupy bone lacunae, so the surrounding matrix identifies the tissue.","act":{"type":"choice","prompt":"Which observation best identifies blood as connective tissue?","options":[{"label":"Cells and cell fragments are suspended in an extracellular plasma matrix.","correct":true,"feedback":"Correct. Blood follows the connective-tissue plan with a fluid matrix."},{"label":"Its cells form a continuous apical sheet.","correct":false,"feedback":"That describes epithelium rather than blood."},{"label":"It contains only neurons.","correct":false,"feedback":"Blood contains formed elements, not a population of neurons."}]}},{"id":"connective-tissue-match","title":"Match it: Fiber architecture","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Loose mesh with space for fluid, vessels, and migrating cells.","Large lipid-filled cells with storage, cushioning, and signaling roles.","Fine branching scaffold supporting many free cells.","Parallel collagen bundles for one-direction pull.","Interwoven collagen for multi-direction stress."],"items":[{"label":"Adipose","category":1,"feedback":"Adipose: Large lipid-filled cells with storage, cushioning, and signaling roles."},{"label":"Dense irregular","category":4,"feedback":"Dense irregular: Interwoven collagen for multi-direction stress."},{"label":"Reticular","category":2,"feedback":"Reticular: Fine branching scaffold supporting many free cells."},{"label":"Areolar","category":0,"feedback":"Areolar: Loose mesh with space for fluid, vessels, and migrating cells."},{"label":"Dense regular","category":3,"feedback":"Dense regular: Parallel collagen bundles for one-direction pull."}]}},{"id":"body-membranes","chapter":"Line and lubricate body spaces","chapterSummary":"Distinguish membranes by the epithelium, connective tissue, and body space involved.","title":"Mucous, serous, and synovial membranes occupy different spaces","highYield":"Mucous membranes line passages open to the exterior, serous membranes line closed ventral cavities, and synovial membranes line movable joint cavities.","teach":["A mucous membrane combines an epithelium with underlying connective tissue and lines a tract that communicates with the exterior, such as digestive, respiratory, urinary, or reproductive passages. Its mucus or other surface secretions protect, lubricate, or trap material according to location.","A serous membrane has a parietal layer lining a cavity wall and a visceral layer covering an organ. A thin serous fluid reduces friction in spaces such as pleura, pericardium, and peritoneum. Synovial membranes are connective-tissue membranes without a true epithelial layer; they line freely movable joint cavities and produce lubricating synovial fluid."],"keyPoints":["Mucous membranes line passages connected to the outside.","Serous membranes have parietal and visceral layers in closed ventral cavities.","Pleura, pericardium, and peritoneum are major serous membranes.","Synovial membranes line joint cavities and are not classic epithelial membranes.","Fluid reduces friction where surfaces move."],"visual":{"title":"Membrane location map","kind":"three-column","items":[{"label":"Mucous","detail":"Open tract; epithelium plus lamina propria; secretion varies by site."},{"label":"Serous","detail":"Closed cavity; parietal wall layer and visceral organ layer."},{"label":"Synovial","detail":"Movable joint cavity; connective lining and lubricating fluid."}]},"mnemonic":{"title":"Mucous meets outside; serous surrounds organs; synovial serves joints","cue":"Open · closed · joint","explanation":"The location cue distinguishes membranes more reliably than secretion alone."},"goodToKnow":"Serous layers are continuous, like a fist pushed into a partly inflated balloon; the fist represents the organ and the double balloon wall represents visceral and parietal layers.","act":{"type":"choice","prompt":"Which membrane directly covers a lung surface?","options":[{"label":"Visceral pleura","correct":true,"feedback":"Correct. The visceral serous layer adheres to the organ surface."},{"label":"Parietal peritoneum","correct":false,"feedback":"The peritoneum is associated with the abdominopelvic cavity, not the lung."},{"label":"Synovial membrane","correct":false,"feedback":"Synovial membranes line movable joints."}]}},{"id":"membranes-match","title":"Match it: Membrane location map","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Open tract; epithelium plus lamina propria; secretion varies by site.","Closed cavity; parietal wall layer and visceral organ layer.","Movable joint cavity; connective lining and lubricating fluid."],"items":[{"label":"Mucous","category":0,"feedback":"Mucous: Open tract; epithelium plus lamina propria; secretion varies by site."},{"label":"Serous","category":1,"feedback":"Serous: Closed cavity; parietal wall layer and visceral organ layer."},{"label":"Synovial","category":2,"feedback":"Synovial: Movable joint cavity; connective lining and lubricating fluid."}]}},{"id":"muscle-types","chapter":"Create movement and communication","chapterSummary":"Compare the three muscle tissues and trace information through a neuron with supporting glial cells.","title":"Three muscle tissues produce force in different settings","highYield":"Skeletal muscle is striated and usually voluntary; cardiac muscle is striated, branching, and involuntary; smooth muscle is nonstriated and involuntary.","teach":["Skeletal muscle fibers are long, cylindrical, multinucleated, and visibly striated. They attach directly or indirectly to the skeleton and generate voluntary movement, posture, and heat. Neural control can be conscious, although many postural adjustments are automatic.","Cardiac muscle forms the heart wall. Its striated branching cells connect through intercalated discs that support coordinated activity. Smooth muscle lacks visible striations and forms sheets around hollow organs and vessels, where slow sustained contractions move contents or change diameter."],"keyPoints":["Skeletal: long, striated, multinucleated fibers; usually voluntary.","Cardiac: branching striated cells with intercalated discs; involuntary.","Smooth: spindle-shaped nonstriated cells; involuntary.","All muscle tissue develops tension through interactions of contractile proteins.","Location and cell architecture help distinguish the three types."],"visual":{"title":"Muscle identity cards","kind":"comparison","items":[{"label":"Skeletal","detail":"Parallel striated fibers; multiple nuclei; moves the skeleton."},{"label":"Cardiac","detail":"Branching striated cells; intercalated discs; pumps blood."},{"label":"Smooth","detail":"Spindle-shaped nonstriated cells; moves contents and regulates tubes."}]},"mnemonic":{"title":"Skeleton stripes; heart branches; hollow organs smooth","cue":"Stripes · branches · smooth","explanation":"The visual cue connects each muscle type with its most recognizable appearance and location."},"goodToKnow":"Peristalsis is a coordinated wave of smooth-muscle contraction that propels material through a hollow organ such as the digestive tract.","act":{"type":"choice","prompt":"A tissue has branching striated cells joined by intercalated discs. What is it?","options":[{"label":"Cardiac muscle","correct":true,"feedback":"Correct. Branching striated cells and intercalated discs identify cardiac tissue."},{"label":"Smooth muscle","correct":false,"feedback":"Smooth muscle is nonstriated and spindle-shaped."},{"label":"Dense regular connective tissue","correct":false,"feedback":"Dense regular tissue has parallel collagen bundles, not contractile striations."}]}},{"id":"nervous-tissue","chapter":null,"chapterSummary":null,"title":"Neurons signal; glial cells sustain the signaling environment","highYield":"Dendrites usually receive, the cell body integrates, and the axon carries a signal toward its endings.","teach":["A neuron has a cell body containing the nucleus and most biosynthetic machinery, dendrites that commonly receive input, and one axon that conducts an electrical signal toward axon endings. At a synapse, the neuron communicates with another neuron, muscle cell, gland cell, or sensory partner.","Neuroglia are diverse supporting cells. Depending on location and type, they regulate the chemical environment, form insulating myelin, support immune defense, nourish neurons, or contribute to barriers. Nervous tissue function therefore depends on neuron–glia cooperation rather than neurons acting alone."],"keyPoints":["The neuronal cell body contains the nucleus and integrates inputs.","Dendrites generally receive information toward the cell body.","The axon conducts a signal away from the cell body to endings.","Synapses transfer information to another cell.","Glia support, protect, insulate, and regulate the neuronal environment."],"visual":{"title":"Neuron information path","kind":"directional-flow","items":[{"label":"Dendrites","detail":"Receive many incoming signals."},{"label":"Cell body","detail":"Integrates inputs and maintains the cell."},{"label":"Axon","detail":"Conducts the action signal over distance."},{"label":"Axon endings","detail":"Communicate with the next target at synapses."},{"label":"Glia","detail":"Maintain conditions that make reliable signaling possible."}]},"mnemonic":{"title":"Dendrites detect; axons announce","cue":"D in · A out","explanation":"The phrase captures the usual direction of information relative to the cell body."},"goodToKnow":"Neurons vary widely in shape and function. The basic dendrite–body–axon map is a powerful model, but specialized sensory neurons may not fit the simplest drawing perfectly.","act":{"type":"choice","prompt":"Which neuronal structure carries a signal toward axon endings?","options":[{"label":"Axon","correct":true,"feedback":"Correct. The axon conducts signals away from the cell body toward its endings."},{"label":"Basement membrane","correct":false,"feedback":"A basement membrane supports epithelium and is not part of a neuron."},{"label":"Collagen bundle","correct":false,"feedback":"Collagen provides connective-tissue strength rather than neuronal conduction."}]}},{"id":"muscle-nervous-order","title":"Put it in order: Neuron information path","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Dendrites","detail":"Receive many incoming signals."},{"label":"Cell body","detail":"Integrates inputs and maintains the cell."},{"label":"Axon","detail":"Conducts the action signal over distance."},{"label":"Axon endings","detail":"Communicate with the next target at synapses."},{"label":"Glia","detail":"Maintain conditions that make reliable signaling possible."}]}},{"id":"muscle-nervous-match","title":"Match it: Muscle identity cards","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Parallel striated fibers; multiple nuclei; moves the skeleton.","Branching striated cells; intercalated discs; pumps blood.","Spindle-shaped nonstriated cells; moves contents and regulates tubes."],"items":[{"label":"Skeletal","category":0,"feedback":"Skeletal: Parallel striated fibers; multiple nuclei; moves the skeleton."},{"label":"Cardiac","category":1,"feedback":"Cardiac: Branching striated cells; intercalated discs; pumps blood."},{"label":"Smooth","category":2,"feedback":"Smooth: Spindle-shaped nonstriated cells; moves contents and regulates tubes."}]}}],"flashcards":[{"front":"Name the four primary tissue classes.","back":"Epithelial, connective, muscle, and nervous."},{"front":"How is an epithelium named?","back":"By number of cell layers and the shape of cells at its free surface."},{"front":"Why is epithelium called avascular?","back":"It contains no blood vessels and receives nutrients by diffusion from underlying connective tissue."},{"front":"What is pseudostratified epithelium?","back":"A single layer in which nuclei appear at different heights, making it look multilayered."},{"front":"Contrast exocrine and endocrine glands.","back":"Exocrine glands use ducts to a surface or lumen; endocrine glands release hormones into tissue fluid and blood."},{"front":"What is extracellular matrix?","back":"Ground substance and fibers surrounding connective-tissue cells."},{"front":"Contrast dense regular and dense irregular connective tissue.","back":"Regular has mainly parallel collagen for one-direction pull; irregular has interwoven collagen for stress from several directions."},{"front":"Name the three cartilage types.","back":"Hyaline, elastic, and fibrocartilage."},{"front":"Why is blood connective tissue?","back":"Its cells and cell fragments are suspended in an extracellular fluid matrix called plasma."},{"front":"What do parietal and visceral mean in a serous membrane?","back":"Parietal lines the cavity wall; visceral covers the organ."},{"front":"Distinguish the three muscle tissues.","back":"Skeletal is striated and usually voluntary; cardiac is branching, striated, and involuntary; smooth is nonstriated and involuntary."},{"front":"State the usual direction through a neuron.","back":"Dendrites receive toward the cell body; the axon conducts toward axon endings."}],"quiz":[],"caseStudy":{"title":"Map the wall of the small intestine","scenario":"A cross-section of small intestine shows a tall absorptive lining with goblet cells, loose connective tissue containing capillaries, bands of smooth muscle, and nerve fibers coordinating movement and secretion.","prompts":["Classify the epithelial lining and explain why its structure suits absorption.","Identify the tissue beneath the epithelium and explain how it supports nutrient transfer.","Explain the distinct roles of goblet cells, smooth muscle, and nervous tissue.","Trace an absorbed water-soluble nutrient from the epithelial surface toward a blood vessel without treating tissues as isolated layers."],"takeaway":"An organ works because multiple tissue classes form an integrated route: boundary and absorption, support and transport, movement, and regulation."}},{"n":6,"title":"The Integumentary System","kicker":"Map the epidermis, dermis, and hypodermis and relate each region to its functions.","duration":"90–110 minutes","steps":[{"id":"system-overview","chapter":"Map the body covering","chapterSummary":"See skin as a layered organ system with appendages, blood supply, nerves, and glands.","title":"Skin is an active interface, not passive wrapping","highYield":"The integumentary system includes skin plus hair, nails, sebaceous, ceruminous, and sweat glands.","teach":["Skin covers the external body surface and forms a flexible, repairable boundary between internal tissues and the environment. Its appendages are modifications of the same organ system. Together they resist water loss, block many physical and chemical threats, contribute to sensation, and participate in temperature control.","Skin also supports immune surveillance, stores some lipid in deeper tissue, excretes small amounts of material in sweat, and begins vitamin D synthesis when ultraviolet radiation acts on a precursor. These functions depend on cooperation among epithelial, connective, nervous, vascular, muscular, and glandular components."],"keyPoints":["Skin and its appendages form the integumentary system.","The barrier limits water loss and entry of many hazards.","Sensory receptors and nerves sample the external environment.","Vessels and sweat glands contribute to thermoregulation.","Skin functions emerge from multiple tissue types working together."],"visual":{"title":"Integumentary function wheel","kind":"radial-map","items":[{"label":"Barrier","detail":"Limits water loss, friction injury, and entry of many substances."},{"label":"Sensation","detail":"Receptors detect touch, pressure, temperature, and pain."},{"label":"Temperature","detail":"Blood-flow changes and sweating alter heat exchange."},{"label":"Metabolic","detail":"Participates in vitamin D precursor conversion."},{"label":"Appendages","detail":"Hair, nails, and glands extend skin functions."}]},"mnemonic":{"title":"Cover, cue, cool, create","cue":"Barrier · sensation · temperature · vitamin D","explanation":"The four verbs organize major skin functions before adding appendage details."},"goodToKnow":"Skin blocks many substances but is not perfectly impermeable. Absorption varies with molecule properties, skin condition, location, and formulation.","act":{"type":"choice","prompt":"Which statement best represents the integumentary system?","options":[{"label":"It is a multi-tissue organ system that forms a selective protective interface.","correct":true,"feedback":"Correct. Skin is active, layered, innervated, vascularized in the dermis, and associated with appendages."},{"label":"It is only a dead waterproof sheet.","correct":false,"feedback":"Only the outermost cells are dead; deeper layers and appendages are living and active."},{"label":"It performs temperature regulation without blood vessels or glands.","correct":false,"feedback":"Dermal vessels and sweat glands are central to heat exchange."}]}},{"id":"three-regions","chapter":null,"chapterSummary":null,"title":"Epidermis, dermis, and hypodermis have distinct construction","highYield":"The epidermis is avascular epithelium, the dermis is vascular connective tissue, and the hypodermis is a deeper connective layer rich in adipose.","teach":["The epidermis is keratinized stratified squamous epithelium. It has no blood vessels, so living epidermal cells receive nutrients by diffusion from dermal vessels. The dermis underneath contains collagen, elastic fibers, vessels, nerves, receptors, hair follicles, and glands.","The hypodermis, or subcutaneous layer, lies below the skin proper. Loose connective and adipose tissues anchor skin to deeper structures, cushion mechanical forces, insulate, and provide an energy store. Its thickness varies by body region and individual biology."],"keyPoints":["Epidermis: avascular keratinized epithelium.","Dermis: vascular connective support with appendages and receptors.","Hypodermis: subcutaneous connective and adipose tissue below skin proper.","Diffusion from dermal vessels supports living epidermal cells.","Layer boundaries explain where structures can and cannot be found."],"visual":{"title":"Skin depth map","kind":"stacked-layers","items":[{"label":"Epidermis","detail":"Surface epithelium; keratinocytes and melanocytes; no vessels."},{"label":"Papillary dermis","detail":"Superficial connective tissue interlocking with epidermis."},{"label":"Reticular dermis","detail":"Deeper dense irregular connective tissue with appendages."},{"label":"Hypodermis","detail":"Loose and adipose tissue connecting skin to deeper structures."}]},"mnemonic":{"title":"Epi over derma over hypo","cue":"Surface · support · subcutaneous","explanation":"The location words fix the vertical order and a primary role for each region."},"goodToKnow":"The hypodermis is closely associated with skin but is commonly described as lying beneath the skin rather than being one of its two main layers.","act":{"type":"choice","prompt":"Where would you expect to find a blood vessel supplying the skin?","options":[{"label":"In the dermis","correct":true,"feedback":"Correct. The dermis is vascular; the epidermis is supplied by diffusion."},{"label":"Inside the stratum corneum","correct":false,"feedback":"The stratum corneum contains dead keratinized cells and no vessels."},{"label":"Only inside a hair shaft","correct":false,"feedback":"A hair shaft above the surface is composed of dead keratinized cells."}]}},{"id":"skin-map-match","title":"Match it: Integumentary function wheel","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Limits water loss, friction injury, and entry of many substances.","Receptors detect touch, pressure, temperature, and pain.","Blood-flow changes and sweating alter heat exchange.","Participates in vitamin D precursor conversion.","Hair, nails, and glands extend skin functions."],"items":[{"label":"Sensation","category":1,"feedback":"Sensation: Receptors detect touch, pressure, temperature, and pain."},{"label":"Appendages","category":4,"feedback":"Appendages: Hair, nails, and glands extend skin functions."},{"label":"Temperature","category":2,"feedback":"Temperature: Blood-flow changes and sweating alter heat exchange."},{"label":"Barrier","category":0,"feedback":"Barrier: Limits water loss, friction injury, and entry of many substances."},{"label":"Metabolic","category":3,"feedback":"Metabolic: Participates in vitamin D precursor conversion."}]}},{"id":"strata-keratinization","chapter":"Build the epidermal barrier","chapterSummary":"Follow keratinocytes from a dividing basal layer to a protective outer layer, then add pigment biology.","title":"Keratinization moves cells from renewal to barrier","highYield":"Keratinocytes originate deep, accumulate keratin as they move outward, flatten, die, and become part of the stratum corneum.","teach":["From deep to superficial, the major strata are basale, spinosum, granulosum, and corneum; thick skin of palms and soles also includes stratum lucidum between granulosum and corneum. Basal cells divide, and their descendants are displaced upward as newer cells form below.","During keratinization, cells make keratin and barrier lipids, flatten, lose nuclei and organelles, and eventually join the tough outer layer. Corneocytes are continually shed and replaced. Desmosomes help cells resist mechanical stress while they progress through the living layers."],"keyPoints":["Deep-to-superficial order: basale, spinosum, granulosum, lucidum when present, corneum.","Mitosis is concentrated in the deepest epidermal region.","Keratinization includes protein accumulation, flattening, and loss of living organelles.","The stratum corneum limits water loss and physical entry.","Thick skin has a prominent lucidum and no hair follicles."],"visual":{"title":"Epidermal escalator","kind":"vertical-process","items":[{"label":"Basale","detail":"Dividing cells and melanocytes near the basement membrane."},{"label":"Spinosum","detail":"Strong cell junctions help resist stress."},{"label":"Granulosum","detail":"Barrier proteins and lipids accumulate as cells flatten."},{"label":"Lucidum","detail":"Clear layer present in thick skin."},{"label":"Corneum","detail":"Dead keratinized cells form the outer barrier and are shed."}]},"mnemonic":{"title":"Before Signing, Get Legal Counsel","cue":"Basale · Spinosum · Granulosum · Lucidum · Corneum","explanation":"The sentence cues the deep-to-superficial order, with lucidum included for thick skin."},"goodToKnow":"A callus is localized thickening of the stratum corneum in response to repeated friction or pressure; a corn is a more focused thickened area, often over a pressure point.","act":{"type":"choice","prompt":"Which epidermal layer is found only in thick skin such as palms and soles?","options":[{"label":"Stratum lucidum","correct":true,"feedback":"Correct. Lucidum is the additional clear layer of thick skin."},{"label":"Stratum basale","correct":false,"feedback":"Basale is present in both thin and thick skin."},{"label":"Papillary dermis","correct":false,"feedback":"The papillary dermis is connective tissue beneath the epidermis, not an epidermal stratum."}]}},{"id":"pigmentation","chapter":null,"chapterSummary":null,"title":"Pigmentation reflects melanin biology, blood, and other pigments","highYield":"Melanocytes produce melanin and transfer pigment packages to keratinocytes; visible color is influenced by pigment amount, type, distribution, blood, and carotenoids.","teach":["Melanocytes in the basal epidermis synthesize melanin and package it into melanosomes, which are transferred to neighboring keratinocytes. Melanin helps absorb and disperse ultraviolet energy. Human variation in skin color relates more to melanin production, type, packaging, and persistence than to a simple difference in melanocyte presence.","Hemoglobin and dermal blood flow also influence color, as can carotene deposited in tissues. Color changes such as pallor, redness, yellowing, or bluish appearance are observations with many possible causes. They are not diagnoses by themselves and must be interpreted with context."],"keyPoints":["Melanocytes synthesize melanin in melanosomes.","Melanosomes are transferred to keratinocytes.","Pigmentation varies through melanin type, amount, packaging, and distribution.","Blood flow, hemoglobin state, and carotene also affect visible color.","Melanin provides partial protection but does not eliminate ultraviolet injury risk."],"visual":{"title":"Sources of visible skin color","kind":"layered-influences","items":[{"label":"Melanin","detail":"Brown-black and red-yellow pigments made by melanocytes."},{"label":"Melanosome transfer","detail":"Pigment packages distribute through keratinocytes."},{"label":"Hemoglobin","detail":"Blood volume, flow, and oxygenation influence undertone."},{"label":"Carotene","detail":"Diet-derived pigment can accumulate in the stratum corneum and subcutaneous fat."}]},"mnemonic":{"title":"Make, package, pass, protect","cue":"Melanocyte → melanosome → keratinocyte","explanation":"The sequence tracks pigment from production to its protective location in epidermal cells."},"goodToKnow":"Albinism describes inherited conditions with reduced or absent melanin production. It does not mean melanocytes or all skin structure are absent.","act":{"type":"choice","prompt":"Which statement about typical human skin-color variation is most accurate?","options":[{"label":"Variation largely reflects melanin production, type, packaging, and distribution.","correct":true,"feedback":"Correct. Melanocyte activity and melanosome biology matter more than a simple present-versus-absent model."},{"label":"Darker skin has an entirely different epidermal layer plan.","correct":false,"feedback":"The same fundamental epidermal strata occur across human skin tones."},{"label":"Melanin completely prevents ultraviolet damage.","correct":false,"feedback":"Melanin offers partial protection, not immunity from injury."}]}},{"id":"epidermis-order","title":"Put it in order: Epidermal escalator","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Basale","detail":"Dividing cells and melanocytes near the basement membrane."},{"label":"Spinosum","detail":"Strong cell junctions help resist stress."},{"label":"Granulosum","detail":"Barrier proteins and lipids accumulate as cells flatten."},{"label":"Lucidum","detail":"Clear layer present in thick skin."},{"label":"Corneum","detail":"Dead keratinized cells form the outer barrier and are shed."}]}},{"id":"epidermis-match","title":"Match it: Sources of visible skin color","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Brown-black and red-yellow pigments made by melanocytes.","Pigment packages distribute through keratinocytes.","Blood volume, flow, and oxygenation influence undertone.","Diet-derived pigment can accumulate in the stratum corneum and subcutaneous fat."],"items":[{"label":"Carotene","category":3,"feedback":"Carotene: Diet-derived pigment can accumulate in the stratum corneum and subcutaneous fat."},{"label":"Hemoglobin","category":2,"feedback":"Hemoglobin: Blood volume, flow, and oxygenation influence undertone."},{"label":"Melanosome transfer","category":1,"feedback":"Melanosome transfer: Pigment packages distribute through keratinocytes."},{"label":"Melanin","category":0,"feedback":"Melanin: Brown-black and red-yellow pigments made by melanocytes."}]}},{"id":"dermis","chapter":"Support skin and grow appendages","chapterSummary":"Move into the connective dermis, then trace hair and nail growth from living matrices to keratinized structures.","title":"The dermis provides strength, elasticity, circulation, and sensation","highYield":"Papillary dermis interlocks with epidermis; reticular dermis provides deeper dense irregular support.","teach":["The superficial papillary dermis is loose areolar connective tissue shaped into dermal papillae. These projections increase contact with the epidermis and carry capillary loops and sensory endings close to the surface. In thick skin, papillae contribute to friction ridges that form fingerprints.","The deeper reticular dermis contains thick interwoven collagen and elastic fibers. It houses larger vessels, nerves, hair follicles, smooth arrector pili muscles, and glands. Fiber orientation gives skin strength in multiple directions and helps explain tension lines relevant to wound opening."],"keyPoints":["Papillary dermis is superficial and contains loose connective tissue.","Dermal papillae strengthen attachment and support capillary and sensory access.","Reticular dermis is thicker dense irregular connective tissue.","Dermal vessels nourish both dermis and nearby epidermis.","Collagen resists tension; elastic fibers support recoil."],"visual":{"title":"Dermal support system","kind":"two-layer-map","items":[{"label":"Papillary","detail":"Loose, superficial, interlocking, capillary-rich."},{"label":"Reticular","detail":"Dense, deeper, fiber-rich, appendage-bearing."},{"label":"Vessels","detail":"Deliver nutrients and alter heat transfer."},{"label":"Receptors","detail":"Detect touch, pressure, vibration, pain, and temperature."}]},"mnemonic":{"title":"Papillary peaks; reticular ropes","cue":"Papillae up · fiber bundles deep","explanation":"The image separates superficial projections from deep interwoven connective fibers."},"goodToKnow":"Stretch marks reflect dermal connective-tissue changes during rapid stretching; their presence does not reveal a single cause or nutritional diagnosis.","act":{"type":"choice","prompt":"Which skin region contains hair follicles, glands, vessels, and dense irregular connective tissue?","options":[{"label":"Reticular dermis","correct":true,"feedback":"Correct. The reticular dermis is the deeper appendage-rich connective layer."},{"label":"Stratum corneum","correct":false,"feedback":"The corneum is the outer keratinized epidermal layer and has no vessels."},{"label":"Nail plate only","correct":false,"feedback":"A nail plate is a keratinized appendage, not the connective skin layer described."}]}},{"id":"hair-nails","chapter":null,"chapterSummary":null,"title":"Hair and nails grow from hidden matrices","highYield":"Hair and nail matrices contain dividing cells; their visible shafts and plates are keratinized structures pushed away from those growth zones.","teach":["A hair follicle is an epidermal tube extending into the dermis. At its expanded bulb, matrix cells divide around a vascular dermal papilla. As cells move upward, they keratinize and die, forming the hair root and then the visible shaft.","A hair commonly has an inner medulla, a cortex containing most pigment and structure, and an outer cuticle. An arrector pili smooth muscle attaches to the follicle. Hair cycles through growth, transition, and rest rather than growing continuously forever.","The visible nail plate lies over a nail bed and continues proximally as a hidden root. Matrix cells under the proximal fold divide, keratinize, and push the plate distally. The pale lunula marks part of this growth region in some nails; the free edge itself does not make new nail."],"keyPoints":["Follicle surrounds the root within skin; shaft projects above the surface.","The matrix near the bulb contains dividing growth cells.","The dermal papilla supplies the active hair-growth region.","Cuticle, cortex, and often medulla form the hair shaft.","The nail matrix makes the plate, which slides distally over the nail bed."],"visual":{"title":"Appendage growth maps","kind":"paired-process","items":[{"label":"Dermal papilla","detail":"Vascular connective tissue supports the growth zone."},{"label":"Matrix","detail":"Dividing cells generate the hair."},{"label":"Bulb and root","detail":"Cells keratinize while still within the follicle."},{"label":"Hair shaft","detail":"Dead keratinized structure extends above skin."},{"label":"Nail matrix","detail":"Proximal dividing cells generate the nail plate."},{"label":"Nail plate","detail":"Hard keratinized structure moves distally over the bed."}]},"mnemonic":{"title":"Matrix makes; keratin moves","cue":"Hair bulb and nail root make what appears farther away","explanation":"The cue separates living growth zones from the dead visible shaft and plate."},"goodToKnow":"Hair shedding is normal because follicles cycle asynchronously, and nails grow slowly from their bases. Changes in either appendage are nonspecific and require context.","act":{"type":"choice","prompt":"Where are the actively dividing cells that produce a hair?","options":[{"label":"In the matrix of the hair bulb","correct":true,"feedback":"Correct. Matrix cells divide near the dermal papilla."},{"label":"At the free end of the shaft","correct":false,"feedback":"The shaft is made of dead keratinized cells and does not grow from its tip."},{"label":"Inside a sweat duct","correct":false,"feedback":"Sweat ducts conduct glandular secretion and do not produce hair."}]}},{"id":"dermis-appendages-order","title":"Put it in order: Appendage growth maps","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Dermal papilla","detail":"Vascular connective tissue supports the growth zone."},{"label":"Matrix","detail":"Dividing cells generate the hair."},{"label":"Bulb and root","detail":"Cells keratinize while still within the follicle."},{"label":"Hair shaft","detail":"Dead keratinized structure extends above skin."},{"label":"Nail matrix","detail":"Proximal dividing cells generate the nail plate."},{"label":"Nail plate","detail":"Hard keratinized structure moves distally over the bed."}]}},{"id":"dermis-appendages-match","title":"Match it: Dermal support system","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Loose, superficial, interlocking, capillary-rich.","Dense, deeper, fiber-rich, appendage-bearing.","Deliver nutrients and alter heat transfer.","Detect touch, pressure, vibration, pain, and temperature."],"items":[{"label":"Receptors","category":3,"feedback":"Receptors: Detect touch, pressure, vibration, pain, and temperature."},{"label":"Vessels","category":2,"feedback":"Vessels: Deliver nutrients and alter heat transfer."},{"label":"Reticular","category":1,"feedback":"Reticular: Dense, deeper, fiber-rich, appendage-bearing."},{"label":"Papillary","category":0,"feedback":"Papillary: Loose, superficial, interlocking, capillary-rich."}]}},{"id":"skin-glands","chapter":"Secrete, cool, and regulate heat","chapterSummary":"Compare skin glands, then connect sweat and dermal blood flow to a homeostatic feedback loop.","title":"Skin glands differ by product, duct, and site","highYield":"Sebaceous glands release sebum; eccrine sweat glands emphasize cooling; apocrine glands empty into follicles; ceruminous glands contribute earwax.","teach":["Sebaceous glands usually empty oily sebum into hair follicles. Sebum lubricates skin and hair and contributes to the surface barrier. Eccrine, or merocrine, sweat glands are widely distributed and open directly to the skin surface. Their watery secretion is most important for evaporative cooling.","Apocrine sweat glands occur mainly in axillary and anogenital regions and typically empty into hair follicles. They become active around puberty, and bacterial action on their secretion contributes to odor. Modified glands include ceruminous glands of the ear canal, whose secretion combines with sebum and shed cells to form cerumen."],"keyPoints":["Sebaceous gland → sebum → usually a hair follicle.","Eccrine gland → watery sweat → skin surface.","Apocrine gland → thicker secretion → usually a hair follicle in selected regions.","Ceruminous glands contribute to protective earwax.","Duct destination is a useful classification clue."],"visual":{"title":"Gland route cards","kind":"comparison","items":[{"label":"Sebaceous","detail":"Branched gland beside follicle; oily sebum lubricates."},{"label":"Eccrine","detail":"Coiled tubular gland; duct opens at skin surface; cooling."},{"label":"Apocrine","detail":"Larger coiled gland; duct opens into follicle; regional secretion."},{"label":"Ceruminous","detail":"Modified gland in ear canal; contributes to cerumen."}]},"mnemonic":{"title":"Eccrine exits; apocrine approaches a follicle","cue":"Surface versus follicle","explanation":"The route cue distinguishes the two sweat-gland patterns emphasized in basic anatomy."},"goodToKnow":"Sweat itself is not the main source of body odor; bacterial metabolism of skin secretions produces many odor compounds.","act":{"type":"choice","prompt":"Which gland is most directly responsible for widespread evaporative cooling?","options":[{"label":"Eccrine sweat gland","correct":true,"feedback":"Correct. Eccrine glands are widely distributed and produce watery surface sweat."},{"label":"Sebaceous gland","correct":false,"feedback":"Sebaceous glands produce oily sebum rather than cooling sweat."},{"label":"Ceruminous gland","correct":false,"feedback":"Ceruminous glands contribute to earwax in the auditory canal."}]}},{"id":"thermoregulation","chapter":null,"chapterSummary":null,"title":"Skin changes heat transfer through blood flow and evaporation","highYield":"When core temperature rises, dermal vasodilation and sweating increase heat loss; cooling favors reduced skin blood flow and heat conservation.","teach":["Temperature sensors and hypothalamic control centers participate in a negative-feedback loop. In heat, dermal vessels widen so more warm blood reaches the surface, and eccrine sweat secretion increases. Evaporation removes heat as liquid water becomes vapor; sweat that drips without evaporating provides less cooling.","In cold conditions, reduced skin blood flow limits heat transfer from the core. Arrector pili contraction has little insulating value in humans because body hair is sparse, but it creates goose bumps. Heat balance also depends on metabolism, clothing, air movement, humidity, and behavior, so skin is one part of the response."],"keyPoints":["Vasodilation increases skin blood flow and heat transfer.","Vasoconstriction reduces skin blood flow and conserves core heat.","Sweat cools mainly when it evaporates.","High humidity reduces the evaporation gradient.","Thermoregulation is a negative-feedback system involving more than skin alone."],"visual":{"title":"Warm and cool responses","kind":"feedback-compare","items":[{"label":"Temperature rises","detail":"Sensors and control centers detect departure from the set range."},{"label":"Heat-loss response","detail":"Skin vessels dilate and eccrine sweating increases."},{"label":"Evaporation","detail":"Heat leaves with water vapor when environmental conditions permit."},{"label":"Temperature falls","detail":"Skin vessels constrict and heat loss decreases."},{"label":"Return toward range","detail":"The response diminishes as the disturbance is corrected."}]},"mnemonic":{"title":"Dilate to dissipate; constrict to conserve","cue":"Warm = wide · cold = narrow","explanation":"Vessel diameter changes how much warm blood reaches the skin surface."},"goodToKnow":"Sweat can be present without effective cooling if it cannot evaporate, which is why humidity changes thermal strain.","act":{"type":"choice","prompt":"Why is sweating less effective for cooling in very humid air?","options":[{"label":"The reduced vapor gradient slows evaporation from skin.","correct":true,"feedback":"Correct. Cooling requires liquid sweat to evaporate."},{"label":"Humidity removes every sweat gland.","correct":false,"feedback":"Glands remain present; the physical evaporation step is less effective."},{"label":"Blood stops circulating through the dermis.","correct":false,"feedback":"Dermal circulation continues and may increase in heat."}]}},{"id":"glands-temperature-match","title":"Match it: Gland route cards","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Branched gland beside follicle; oily sebum lubricates.","Coiled tubular gland; duct opens at skin surface; cooling.","Larger coiled gland; duct opens into follicle; regional secretion.","Modified gland in ear canal; contributes to cerumen."],"items":[{"label":"Ceruminous","category":3,"feedback":"Ceruminous: Modified gland in ear canal; contributes to cerumen."},{"label":"Apocrine","category":2,"feedback":"Apocrine: Larger coiled gland; duct opens into follicle; regional secretion."},{"label":"Eccrine","category":1,"feedback":"Eccrine: Coiled tubular gland; duct opens at skin surface; cooling."},{"label":"Sebaceous","category":0,"feedback":"Sebaceous: Branched gland beside follicle; oily sebum lubricates."}]}},{"id":"burns","chapter":"Observe injury without overreaching","chapterSummary":"Use depth, extent, morphology, and change over time as descriptive frameworks—not self-diagnosis shortcuts.","title":"Burn depth predicts which skin structures remain","highYield":"Superficial burns involve epidermis; partial-thickness burns extend into dermis; full-thickness burns destroy epidermis and dermis through their full depth.","teach":["A superficial burn affects the epidermis and is often red and painful. A partial-thickness burn extends into part of the dermis and may blister because epidermis separates from deeper tissue. Some dermal appendages can remain and contribute cells during repair, depending on depth.","A full-thickness burn destroys the epidermis and dermis across the affected area and may extend deeper. Nerve endings within the center can be damaged even while surrounding tissue is painful. Depth, body-surface extent, location, age, inhalation exposure, and health status all influence urgency and outcome."],"keyPoints":["Superficial: epidermis only.","Partial-thickness: epidermis plus part of dermis; blistering can occur.","Full-thickness: entire epidermis and dermis destroyed in the area.","Pain intensity alone does not determine burn depth.","Extent and location matter in addition to depth."],"visual":{"title":"Burn depth ladder","kind":"depth-model","items":[{"label":"Superficial","detail":"Damage remains within epidermis."},{"label":"Partial-thickness","detail":"Damage crosses epidermis into a portion of dermis."},{"label":"Full-thickness","detail":"Damage spans epidermis and dermis and may extend deeper."},{"label":"Assessment context","detail":"Extent, location, mechanism, and systemic signs change risk."}]},"mnemonic":{"title":"Surface, part, full","cue":"Epidermis · some dermis · all skin depth","explanation":"The three words cue the progressively deeper tissue involvement."},"goodToKnow":"The older first-, second-, and third-degree terms are still encountered, but superficial, partial-thickness, and full-thickness descriptions communicate depth more directly.","act":{"type":"choice","prompt":"A burn has destroyed epidermis and extends into but not through the entire dermis. Which category fits best?","options":[{"label":"Partial-thickness","correct":true,"feedback":"Correct. Part of the dermis is involved but some dermal tissue remains."},{"label":"Superficial only","correct":false,"feedback":"A superficial burn remains within the epidermis."},{"label":"Automatically full-thickness","correct":false,"feedback":"Full-thickness requires destruction through the full dermal depth."}]}},{"id":"lesions-screening","chapter":null,"chapterSummary":null,"title":"Describe what is present before naming a disorder","highYield":"Morphology, color, border, size, location, symptoms, and change over time are observations; diagnosis requires clinical context.","teach":["Skin vocabulary improves communication. A macule is a flat color change, a papule is a small raised solid lesion, and a pustule contains purulent material. Calluses and corns reflect localized keratin thickening. Descriptions should note distribution, symmetry, border, surface, and evolution rather than jumping from appearance to cause.","Common skin disorders include inflammatory, infectious, pigmentary, and neoplastic conditions. Basal cell carcinoma, squamous cell carcinoma, and melanoma arise from different cell populations and have different patterns. A changing, bleeding, painful, or otherwise concerning lesion warrants appropriate professional evaluation rather than diagnosis from a study guide."],"keyPoints":["Macule is flat; papule is raised and solid; pustule contains purulent material.","Describe size, shape, color, border, surface, distribution, and change.","A lesion name describes form but may not identify cause.","Skin cancers arise from different cells and cannot be distinguished reliably from one feature alone.","Concerning or changing findings need appropriate clinical evaluation."],"visual":{"title":"Observe in layers","kind":"observation-checklist","items":[{"label":"Form","detail":"Flat, raised, fluid-filled, solid, crusted, or ulcerated."},{"label":"Pattern","detail":"Single, grouped, symmetric, linear, or widespread."},{"label":"Surface and border","detail":"Smooth, scaly, regular, irregular, sharply or poorly defined."},{"label":"Time","detail":"New, stable, recurring, expanding, or changing."},{"label":"Context","detail":"Symptoms, exposures, medications, and health history."}]},"mnemonic":{"title":"Look, locate, listen, longitudinal","cue":"Appearance · distribution · symptoms · change","explanation":"The four-step cue keeps observation systematic and resists premature diagnosis."},"goodToKnow":"The ABCDE framework can support melanoma awareness, but it is a screening aid rather than a rule-out test; lesions outside the pattern can still require assessment.","act":{"type":"choice","prompt":"Which note is the most useful objective description?","options":[{"label":"A 4 mm raised, solid, round papule with a smooth surface on the forearm, unchanged for two months.","correct":true,"feedback":"Correct. It records morphology, size, site, surface, and time without assigning an unsupported cause."},{"label":"This is definitely a vitamin deficiency.","correct":false,"feedback":"That is a causal diagnosis without sufficient evidence."},{"label":"The skin looks bad.","correct":false,"feedback":"The wording is subjective and lacks reproducible features."}]}},{"id":"observe-protect-match","title":"Match it: Burn depth ladder","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Damage remains within epidermis.","Damage crosses epidermis into a portion of dermis.","Damage spans epidermis and dermis and may extend deeper.","Extent, location, mechanism, and systemic signs change risk."],"items":[{"label":"Assessment context","category":3,"feedback":"Assessment context: Extent, location, mechanism, and systemic signs change risk."},{"label":"Full-thickness","category":2,"feedback":"Full-thickness: Damage spans epidermis and dermis and may extend deeper."},{"label":"Partial-thickness","category":1,"feedback":"Partial-thickness: Damage crosses epidermis into a portion of dermis."},{"label":"Superficial","category":0,"feedback":"Superficial: Damage remains within epidermis."}]}}],"flashcards":[{"front":"What structures make up the integumentary system?","back":"Skin plus hair, nails, sebaceous glands, ceruminous glands, and sweat glands."},{"front":"Contrast epidermis, dermis, and hypodermis.","back":"Epidermis is avascular epithelium; dermis is vascular connective tissue; hypodermis is deeper loose and adipose tissue."},{"front":"List epidermal strata from deep to superficial.","back":"Basale, spinosum, granulosum, lucidum in thick skin, and corneum."},{"front":"What is keratinization?","back":"The process in which keratinocytes move outward, accumulate barrier material, flatten, die, and join the stratum corneum."},{"front":"What do melanocytes do?","back":"They synthesize melanin in melanosomes and transfer the pigment packages to keratinocytes."},{"front":"Contrast papillary and reticular dermis.","back":"Papillary dermis is superficial loose tissue with papillae; reticular dermis is deeper dense irregular tissue with larger appendages and vessels."},{"front":"Where does hair grow?","back":"From dividing matrix cells in the hair bulb around a vascular dermal papilla."},{"front":"Where does a nail grow?","back":"From the nail matrix under the proximal nail fold."},{"front":"Contrast eccrine and apocrine sweat glands.","back":"Eccrine glands open to the surface and emphasize cooling; apocrine glands usually open to follicles in selected regions."},{"front":"What does a sebaceous gland secrete?","back":"Sebum, an oily secretion that lubricates skin and hair and supports the surface barrier."},{"front":"How does skin respond to heat?","back":"Dermal vasodilation increases surface blood flow and eccrine sweating supports evaporative cooling."},{"front":"Distinguish superficial, partial-thickness, and full-thickness burns.","back":"They involve epidermis only, epidermis plus part of dermis, or destruction through epidermis and dermis, respectively."},{"front":"Contrast a macule and papule.","back":"A macule is flat color change; a papule is a small raised solid lesion."}],"quiz":[],"caseStudy":{"title":"A hot, humid shift","scenario":"During several hours of work in warm humid conditions, a person’s skin becomes flushed and wet. Sweat drips from the surface, but cooling feels limited. A small friction callus is also visible on the palm.","prompts":["Trace the negative-feedback responses involving dermal vessels and eccrine glands.","Explain why high humidity limits cooling even when sweat production is high.","Identify the epidermal process responsible for the callus and explain its protective tradeoff.","List contextual factors needed before offering individualized fluid or electrolyte guidance."],"takeaway":"Skin observations become meaningful when layer anatomy, gland routes, environmental physics, and whole-body context are combined—without turning a visible sign into a diagnosis."}},{"n":7,"title":"The Skeletal System","kicker":"Explain how the skeleton supports movement, protection, blood-cell formation and mineral storage.","duration":"70–90 minutes","steps":[{"id":"l7-m1","chapter":"Bone is living tissue","chapterSummary":"Begin with function, formation and continual remodeling.","title":"Five jobs of the skeleton","highYield":"The skeleton is not a passive frame: it supports, protects, moves, forms blood cells and stores minerals and fat.","teach":["Bones create a firm framework that supports softer tissues and shields organs such as the brain, spinal cord, heart and lungs. At joints, bones also act as levers. Skeletal muscles pull on those levers to create movement and help expand the thorax during breathing.","Red marrow forms blood cells through hematopoiesis. Bone also stores calcium and phosphorus, while yellow marrow stores fat. These roles explain why skeletal health is linked to movement, circulation and mineral homeostasis rather than being an isolated topic."],"keyPoints":["Support and protection are structural roles.","Bones and muscles work as lever-and-force partners.","Red marrow forms blood cells.","Bone is a regulated mineral reservoir."],"visual":{"title":"Function map","kind":"hub","items":[{"label":"Framework","detail":"Supports tissues and posture"},{"label":"Shield","detail":"Protects vital organs"},{"label":"Lever","detail":"Transmits muscular force"},{"label":"Marrow","detail":"Forms blood cells or stores fat"},{"label":"Reservoir","detail":"Stores calcium and phosphorus"}]},"mnemonic":{"title":"SPLeMB","cue":"Support · Protect · Levers · Marrow · Bank","explanation":"Think of bone as the body’s support-and-storage bank."},"goodToKnow":"The mineral matrix makes bone hard, but living cells, vessels and nerves make it dynamic.","act":{"type":"choice","prompt":"Which skeletal role most directly connects bone to blood-cell production?","options":[{"label":"Hematopoiesis in red marrow","correct":true,"feedback":"Correct. Red marrow is a major site of blood-cell formation."},{"label":"Fat storage in yellow marrow","correct":false,"feedback":"Yellow marrow stores fat; it is not the primary answer for blood-cell formation."},{"label":"Articulation at a joint","correct":false,"feedback":"Joints enable movement but do not describe hematopoiesis."}]}},{"id":"l7-m2","chapter":null,"chapterSummary":null,"title":"Build, maintain, resorb","highYield":"Osteoblasts deposit bone, osteocytes maintain it, and osteoclasts resorb it during remodeling.","teach":["Bone formation begins with osteoblasts. As the surrounding matrix matures, many become osteocytes housed in small spaces called lacunae. Osteoclasts remove bone, which is essential for shaping, repair and mineral regulation rather than simply being destructive.","Intramembranous ossification builds bone within connective membranes, especially in the skull. Endochondral ossification replaces a cartilage model and forms most other bones. Remodeling continues after growth has ended and responds to mechanical load and hormonal signals."],"keyPoints":["Osteoblast = deposition.","Osteocyte = mature maintenance cell.","Osteoclast = resorption.","Intramembranous and endochondral ossification start from different templates."],"visual":{"title":"Remodeling cycle","kind":"sequence","items":[{"label":"Deposit","detail":"Osteoblast lays matrix"},{"label":"Maintain","detail":"Osteocyte monitors local tissue"},{"label":"Resorb","detail":"Osteoclast removes matrix"},{"label":"Renew","detail":"New matrix replaces remodeled area"}]},"mnemonic":{"title":"BLC","cue":"Builders · Lodgers · Clean-up","explanation":"Blasts build, cytes live in the matrix, clasts clear bone."},"goodToKnow":"Parathyroid hormone and calcitonin participate in blood-calcium regulation; bone is one part of that larger system.","act":{"type":"choice","prompt":"Which pairing is accurate?","options":[{"label":"Osteoclast — bone resorption","correct":true,"feedback":"Correct. Osteoclasts remove mineralized matrix during remodeling."},{"label":"Osteocyte — first cartilage model","correct":false,"feedback":"A cartilage model belongs to endochondral ossification; osteocytes are mature bone cells."},{"label":"Osteoblast — mature cell in a lacuna","correct":false,"feedback":"A mature bone cell in a lacuna is an osteocyte."}]}},{"id":"living-bone-order","title":"Put it in order: Remodeling cycle","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Deposit","detail":"Osteoblast lays matrix"},{"label":"Maintain","detail":"Osteocyte monitors local tissue"},{"label":"Resorb","detail":"Osteoclast removes matrix"},{"label":"Renew","detail":"New matrix replaces remodeled area"}]}},{"id":"living-bone-match","title":"Match it: Function map","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Supports tissues and posture","Protects vital organs","Transmits muscular force","Forms blood cells or stores fat","Stores calcium and phosphorus"],"items":[{"label":"Shield","category":1,"feedback":"Shield: Protects vital organs"},{"label":"Reservoir","category":4,"feedback":"Reservoir: Stores calcium and phosphorus"},{"label":"Lever","category":2,"feedback":"Lever: Transmits muscular force"},{"label":"Framework","category":0,"feedback":"Framework: Supports tissues and posture"},{"label":"Marrow","category":3,"feedback":"Marrow: Forms blood cells or stores fat"}]}},{"id":"l7-m3","chapter":"Read bone architecture","chapterSummary":"Move from the osteon to whole-bone shape and marrow.","title":"Compact and spongy bone","highYield":"Compact bone is organized into osteons; spongy bone forms trabeculae around marrow spaces.","teach":["An osteon is the repeating structural unit of compact bone. A central canal carries vessels, concentric lamellae form rings, osteocytes occupy lacunae, and canaliculi create tiny communication routes through the hard matrix.","Spongy or cancellous bone is arranged as a lattice of trabeculae. Its spaces contain marrow, and its architecture places material along lines of stress without making the bone solid throughout. Compact and spongy tissue therefore solve different mechanical problems."],"keyPoints":["Central canal carries vessels.","Lamellae are concentric layers.","Lacunae house osteocytes.","Canaliculi connect spaces.","Trabeculae form the spongy lattice."],"visual":{"title":"From center outward","kind":"rings","items":[{"label":"Central canal","detail":"Vessels and nerves"},{"label":"Lamellae","detail":"Concentric matrix rings"},{"label":"Lacunae","detail":"Osteocyte spaces"},{"label":"Canaliculi","detail":"Microscopic connecting channels"}]},"mnemonic":{"title":"CLLC","cue":"Canal · Lamellae · Lacunae · Canaliculi","explanation":"Walk outward from an osteon’s center."},"goodToKnow":"Bone looks solid macroscopically, yet microscopic channels keep living cells supplied.","act":{"type":"choice","prompt":"Where would you expect to find an osteocyte?","options":[{"label":"Inside a lacuna","correct":true,"feedback":"Correct. Osteocytes occupy lacunae in mineralized bone."},{"label":"Inside the central canal","correct":false,"feedback":"The central canal primarily contains vessels and nerves."},{"label":"Only in yellow marrow","correct":false,"feedback":"Yellow marrow stores fat; it is not the location of osteocytes."}]}},{"id":"l7-m4","chapter":null,"chapterSummary":null,"title":"Long bones and shape classes","highYield":"A long bone has a shaft, ends, coverings and a marrow cavity; “long” describes shape, not absolute size.","teach":["The diaphysis is the shaft of a long bone, the epiphyses are its ends, and the metaphyses are transition regions. Periosteum covers the outer surface except at articular cartilage, while endosteum lines internal surfaces. The medullary cavity occupies the shaft.","Bones are also classified as long, short, flat, irregular or sesamoid. Flat bones provide broad protection or muscle attachment; irregular bones have complex shapes; sesamoid bones develop within tendons. Classification helps predict form and function."],"keyPoints":["Diaphysis = shaft.","Epiphysis = end.","Periosteum is external; endosteum is internal.","Patella is a sesamoid bone."],"visual":{"title":"Long-bone route","kind":"label-strip","items":[{"label":"Epiphysis","detail":"Expanded end"},{"label":"Metaphysis","detail":"Transition/growth region"},{"label":"Diaphysis","detail":"Shaft and medullary cavity"},{"label":"Periosteum","detail":"Fibrovascular outer covering"}]},"mnemonic":{"title":"DME","cue":"Diaphysis = Drive shaft; Metaphysis = Middle transition; Epiphysis = End","explanation":"Use position to retrieve each name."},"goodToKnow":"The femur is long, but tiny phalanges are also classified as long bones because of their proportions.","act":{"type":"choice","prompt":"Which structure is the shaft of a long bone?","options":[{"label":"Diaphysis","correct":true,"feedback":"Correct. The diaphysis is the elongated shaft."},{"label":"Epiphysis","correct":false,"feedback":"The epiphysis is an end of the bone."},{"label":"Lacuna","correct":false,"feedback":"A lacuna is a microscopic space housing an osteocyte."}]}},{"id":"bone-architecture-match","title":"Match it: From center outward","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Vessels and nerves","Concentric matrix rings","Osteocyte spaces","Microscopic connecting channels"],"items":[{"label":"Canaliculi","category":3,"feedback":"Canaliculi: Microscopic connecting channels"},{"label":"Lacunae","category":2,"feedback":"Lacunae: Osteocyte spaces"},{"label":"Lamellae","category":1,"feedback":"Lamellae: Concentric matrix rings"},{"label":"Central canal","category":0,"feedback":"Central canal: Vessels and nerves"}]}},{"id":"l7-m5","chapter":"Map the axial skeleton","chapterSummary":"Organize skull, vertebral column and thorax around protection.","title":"Cranium, face and openings","highYield":"Cranial bones protect the brain; facial bones shape the face and support the air and food passages.","teach":["The axial skeleton begins with the skull. Cranial bones include the frontal, parietal, temporal, occipital, sphenoid and ethmoid bones. The sphenoid spans the cranial floor and helps bind several cranial bones together. Facial bones include the maxillae, zygomatic bones and mandible.","Openings and processes reveal function. The foramen magnum in the occipital bone transmits the spinal cord, while condyles articulate with the first cervical vertebra. Sutures are fibrous joints that unite skull bones."],"keyPoints":["Cranial and facial bones have different organizing roles.","Mandible forms the lower jaw.","Sphenoid anchors across the cranial floor.","Foramen magnum connects cranial and vertebral spaces."],"visual":{"title":"Skull landmarks","kind":"map","items":[{"label":"Frontal","detail":"Forehead and anterior cranial roof"},{"label":"Occipital","detail":"Posterior skull and foramen magnum"},{"label":"Sphenoid","detail":"Central cranial-floor anchor"},{"label":"Mandible","detail":"Movable lower jaw"}]},"mnemonic":{"title":"FOSTEP","cue":"Frontal · Occipital · Sphenoid · Temporal · Ethmoid · Parietal","explanation":"A compact cue for the main cranial-bone set."},"goodToKnow":"The hyoid is part of the axial skeleton but does not articulate directly with another bone.","act":{"type":"choice","prompt":"Which opening carries the spinal cord through the skull?","options":[{"label":"Foramen magnum","correct":true,"feedback":"Correct. It is the large opening in the occipital bone."},{"label":"Medullary cavity","correct":false,"feedback":"That is an internal cavity of a long bone."},{"label":"Acetabulum","correct":false,"feedback":"The acetabulum is the hip socket."}]}},{"id":"l7-m6","chapter":null,"chapterSummary":null,"title":"Vertebral column and thorax","highYield":"The vertebral column protects the spinal cord; ribs and sternum protect thoracic organs and support breathing.","teach":["The vertebral column is organized into cervical, thoracic, lumbar, sacral and coccygeal regions. The atlas supports the skull and the axis permits rotation. Normal curves distribute load; exaggerated or lateral curves are described with specific terms such as kyphosis, lordosis and scoliosis.","The thoracic cage includes thoracic vertebrae, ribs and sternum. True ribs attach directly to the sternum through costal cartilage, false ribs attach indirectly, and floating ribs lack anterior attachment. The sternum includes the manubrium, body and xiphoid process."],"keyPoints":["Seven cervical, twelve thoracic and five lumbar vertebrae precede the fused regions.","Atlas and axis have specialized roles.","True ribs attach directly; floating ribs do not attach anteriorly.","The sternum is the breastbone."],"visual":{"title":"Axial stack","kind":"vertical","items":[{"label":"Cervical","detail":"Neck; C1–C7"},{"label":"Thoracic","detail":"Rib-bearing; T1–T12"},{"label":"Lumbar","detail":"Lower back; L1–L5"},{"label":"Sacrum/coccyx","detail":"Fused terminal regions"}]},"mnemonic":{"title":"Breakfast schedule","cue":"7 · 12 · 5","explanation":"Seven cervical, twelve thoracic and five lumbar—breakfast at 7, lunch at 12, dinner at 5."},"goodToKnow":"“True” and “false” describe rib attachment patterns, not whether a rib is complete or functional.","act":{"type":"choice","prompt":"Which region articulates with ribs?","options":[{"label":"Thoracic vertebrae","correct":true,"feedback":"Correct. Ribs articulate with thoracic vertebrae."},{"label":"Cervical vertebrae","correct":false,"feedback":"Cervical vertebrae form the neck."},{"label":"Coccygeal vertebrae","correct":false,"feedback":"The coccyx is the terminal fused region."}]}},{"id":"axial-order","title":"Put it in order: Axial stack","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Cervical","detail":"Neck; C1–C7"},{"label":"Thoracic","detail":"Rib-bearing; T1–T12"},{"label":"Lumbar","detail":"Lower back; L1–L5"},{"label":"Sacrum/coccyx","detail":"Fused terminal regions"}]}},{"id":"axial-match","title":"Match it: Skull landmarks","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Forehead and anterior cranial roof","Posterior skull and foramen magnum","Central cranial-floor anchor","Movable lower jaw"],"items":[{"label":"Mandible","category":3,"feedback":"Mandible: Movable lower jaw"},{"label":"Sphenoid","category":2,"feedback":"Sphenoid: Central cranial-floor anchor"},{"label":"Occipital","category":1,"feedback":"Occipital: Posterior skull and foramen magnum"},{"label":"Frontal","category":0,"feedback":"Frontal: Forehead and anterior cranial roof"}]}},{"id":"l7-m7","chapter":"Use the appendicular skeleton","chapterSummary":"Connect girdles and limbs to movement, load and practical bone health.","title":"Girdles and limbs","highYield":"The pectoral and pelvic girdles attach the upper and lower limbs to the axial skeleton.","teach":["The pectoral girdle consists of clavicles and scapulae. It prioritizes mobility, giving the upper limb a wide range of movement. The upper limb continues through humerus, radius and ulna to carpals, metacarpals and phalanges.","The pelvic girdle forms a stronger weight-bearing ring. Each hip bone is formed by the ilium, ischium and pubis; the acetabulum receives the femoral head. The lower limb continues through femur, patella, tibia and fibula to tarsals, metatarsals and phalanges."],"keyPoints":["Pectoral girdle favors mobility.","Pelvic girdle favors stability and weight transfer.","Radius/ulna are forearm bones.","Tibia/fibula are leg bones.","Carpals are wrist; tarsals are ankle/foot."],"visual":{"title":"Paired pathways","kind":"compare","items":[{"label":"Upper limb","detail":"Scapula → humerus → radius/ulna → carpals"},{"label":"Lower limb","detail":"Hip → femur → tibia/fibula → tarsals"}]},"mnemonic":{"title":"Car before tar","cue":"Carpals = hands; tarsals = feet","explanation":"A car is handled with the hands; tar is under the feet."},"goodToKnow":"The patella is the largest sesamoid bone and develops within the quadriceps tendon.","act":{"type":"choice","prompt":"Which structure receives the head of the femur?","options":[{"label":"Acetabulum","correct":true,"feedback":"Correct. It is the socket on the hip bone."},{"label":"Glenoid fossa","correct":false,"feedback":"The glenoid fossa receives the humeral head at the shoulder."},{"label":"Foramen magnum","correct":false,"feedback":"That opening is in the occipital bone."}]}},{"id":"l7-m8","chapter":null,"chapterSummary":null,"title":"Bone health is a system question","highYield":"Bone strength reflects matrix, cells, hormones, nutrients, load and time—not one nutrient in isolation.","teach":["Calcium and phosphorus contribute to mineralized matrix, while vitamin D supports calcium absorption. Protein supplies matrix components. Hormones help regulate deposition and release, and mechanical load influences remodeling. Adequacy across these factors matters more than a single “bone food.”","Disorders illustrate different mechanisms: rickets and osteomalacia involve impaired mineralization, osteoporosis involves reduced bone mass and altered structure, and Paget disease involves disordered remodeling. A fracture is a break in bone or associated cartilage and requires clinical care."],"keyPoints":["Mineralization and remodeling are different processes.","Vitamin D supports calcium handling.","Osteoporosis is not simply “low calcium.”","Fracture, rickets and Paget disease describe different problems."],"visual":{"title":"Bone maintenance web","kind":"network","items":[{"label":"Matrix","detail":"Collagen-rich framework plus mineral"},{"label":"Cells","detail":"Deposit, maintain and resorb"},{"label":"Signals","detail":"Hormonal regulation"},{"label":"Inputs","detail":"Nutrients and mechanical load"},{"label":"Time","detail":"Growth, aging and repair"}]},"mnemonic":{"title":"MINDS","cue":"Matrix · Inputs · load · endocrine signals · time","explanation":"Bone health emerges from interacting influences."},"goodToKnow":"An adult can have adequate current intake yet still require assessment for bone-density or fracture concerns.","act":{"type":"choice","prompt":"Which statement best reflects bone maintenance?","options":[{"label":"It depends on interacting cellular, nutritional, hormonal and mechanical factors.","correct":true,"feedback":"Correct. Bone is maintained by an integrated system."},{"label":"It is determined by calcium intake alone.","correct":false,"feedback":"Calcium matters, but bone maintenance is not a one-nutrient process."},{"label":"It stops when height growth ends.","correct":false,"feedback":"Remodeling continues throughout life."}]}},{"id":"appendicular-match","title":"Match it: Bone maintenance web","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Collagen-rich framework plus mineral","Deposit, maintain and resorb","Hormonal regulation","Nutrients and mechanical load","Growth, aging and repair"],"items":[{"label":"Cells","category":1,"feedback":"Cells: Deposit, maintain and resorb"},{"label":"Time","category":4,"feedback":"Time: Growth, aging and repair"},{"label":"Signals","category":2,"feedback":"Signals: Hormonal regulation"},{"label":"Matrix","category":0,"feedback":"Matrix: Collagen-rich framework plus mineral"},{"label":"Inputs","category":3,"feedback":"Inputs: Nutrients and mechanical load"}]}}],"flashcards":[{"front":"Osteoblast","back":"Bone-forming cell that deposits matrix."},{"front":"Osteoclast","back":"Large cell that resorbs bone during remodeling."},{"front":"Osteocyte","back":"Mature bone cell located in a lacuna."},{"front":"Osteon","back":"Central canal plus concentric lamellae of compact bone."},{"front":"Canaliculi","back":"Tiny channels connecting lacunae with each other and the central canal."},{"front":"Diaphysis","back":"Shaft of a long bone."},{"front":"Epiphysis","back":"Expanded end of a long bone."},{"front":"Axial skeleton","back":"Skull, vertebral column and thoracic cage."},{"front":"Appendicular skeleton","back":"Girdles and limbs."},{"front":"Foramen magnum","back":"Large occipital opening for the spinal cord."},{"front":"Acetabulum","back":"Hip socket that receives the femoral head."},{"front":"Hematopoiesis","back":"Formation of blood cells, largely in red marrow."}],"quiz":[],"caseStudy":{"title":"From a fall to a systems explanation","scenario":"An older adult reports a recent fall and asks whether drinking more milk alone will “rebuild” every weak bone.","prompts":["Name the skeletal functions relevant to the fall.","Explain remodeling using osteoblasts and osteoclasts.","Identify the limits of a one-food explanation.","State which concerns require clinical assessment rather than nutrition education alone."],"takeaway":"Use anatomy to explain the system, support adequate nutrition without promises, and keep fracture and bone-density assessment within clinical care."}},{"n":8,"title":"The Articular System","kicker":"Classify joints by structure and degree of movement.","duration":"60–80 minutes","steps":[{"id":"l8-m1","chapter":"A map of every joint","chapterSummary":"Start with the two classification questions: what connects the bones, and how much can they move?","title":"Structural and functional classifications","highYield":"Structure and movement are two different naming systems.","teach":["A joint, or articulation, is where two or more skeletal elements meet. Structural classification asks what material joins the bones: fibrous tissue, cartilage, or a fluid-filled synovial cavity.","Functional classification asks how much movement is possible. A synarthrosis is essentially immovable, an amphiarthrosis allows limited movement, and a diarthrosis moves freely. Most limb joints are diarthroses and structurally synovial."],"keyPoints":["Fibrous, cartilaginous and synovial are structural groups.","Synarthroses do not move.","Amphiarthroses move slightly.","Diarthroses move freely."],"visual":{"title":"Two lenses","kind":"concept-map","items":[{"label":"Structure","detail":"What physically joins the bones?"},{"label":"Function","detail":"How much movement occurs?"},{"label":"Key pairing","detail":"Synovial joints are usually diarthroses"}]},"mnemonic":{"title":"SAD movement scale","cue":"Synarthrosis · Amphiarthrosis · Diarthrosis","explanation":"Think still, a little, dynamic."},"goodToKnow":"The two systems overlap, but their terms are not interchangeable.","act":{"type":"choice","prompt":"Which functional class describes a freely movable shoulder joint?","options":[{"label":"Diarthrosis","correct":true,"feedback":"Correct. A freely movable joint is a diarthrosis."},{"label":"Amphiarthrosis","correct":false,"feedback":"That class permits only slight movement."},{"label":"Synarthrosis","correct":false,"feedback":"That class is essentially immovable."}]}},{"id":"l8-m2","chapter":null,"chapterSummary":null,"title":"Fibrous and cartilaginous joints","highYield":"Less motion generally brings more stability.","teach":["Fibrous joints are united by dense connective tissue. Skull sutures are nearly immovable; a syndesmosis uses a ligament or membrane between bones; a gomphosis anchors a tooth in its socket.","Cartilaginous joints join bones with cartilage. A synchondrosis uses hyaline cartilage, as in an epiphyseal plate before it closes. A symphysis uses fibrocartilage and allows limited movement, as at the pubic symphysis or between vertebral bodies."],"keyPoints":["Suture and gomphosis are fibrous.","Syndesmosis uses fibrous tissue.","Synchondrosis uses hyaline cartilage.","Symphysis uses fibrocartilage."],"visual":{"title":"Low-motion joints","kind":"concept-map","items":[{"label":"Suture","detail":"Interlocking skull bones"},{"label":"Gomphosis","detail":"Tooth in socket"},{"label":"Synchondrosis","detail":"Hyaline cartilage bridge"},{"label":"Symphysis","detail":"Fibrocartilage pad"}]},"mnemonic":{"title":"CH = cartilage","cue":"SynCHondrosis uses hyaline Cartilage","explanation":"The shared sound helps separate it from a symphysis."},"goodToKnow":"The former growth plate between a diaphysis and epiphysis is a classic synchondrosis.","act":{"type":"choice","prompt":"Which joint is united by fibrocartilage and allows slight movement?","options":[{"label":"Symphysis","correct":true,"feedback":"Correct. Symphyses are cartilaginous amphiarthroses."},{"label":"Suture","correct":false,"feedback":"A suture is fibrous and generally immovable."},{"label":"Ball-and-socket","correct":false,"feedback":"That is a freely movable synovial form."}]}},{"id":"joint-language-match","title":"Match it: Two lenses","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["What physically joins the bones?","How much movement occurs?","Synovial joints are usually diarthroses"],"items":[{"label":"Structure","category":0,"feedback":"Structure: What physically joins the bones?"},{"label":"Function","category":1,"feedback":"Function: How much movement occurs?"},{"label":"Key pairing","category":2,"feedback":"Key pairing: Synovial joints are usually diarthroses"}]}},{"id":"l8-m3","chapter":"The synovial-joint toolkit","chapterSummary":"A cavity, cartilage, capsule and lubricant create controlled, low-friction motion.","title":"Inside a synovial joint","highYield":"Articular cartilage reduces friction; fluid lubricates; ligaments guide and restrain.","teach":["At a synovial joint, the bone ends are capped by smooth articular cartilage and separated by a cavity. A capsule encloses the joint; its fibrous outer layer stabilizes while its inner synovial membrane produces synovial fluid.","Ligaments connect bone to bone. Bursae are small fluid-filled sacs positioned where skin, tendon, ligament, or bone might rub. Menisci or discs in some joints improve fit and distribute load."],"keyPoints":["Articular cartilage covers opposing bone ends.","Synovial fluid lubricates and nourishes cartilage.","Ligaments connect bone to bone.","Bursae reduce friction at pressure points."],"visual":{"title":"Synovial layers","kind":"concept-map","items":[{"label":"Cartilage","detail":"Smooth bearing surface"},{"label":"Cavity + fluid","detail":"Low-friction space"},{"label":"Capsule","detail":"Enclosure and stability"},{"label":"Ligament","detail":"Bone-to-bone restraint"},{"label":"Bursa","detail":"Friction-reducing sac"}]},"mnemonic":{"title":"C-C-F-L-B","cue":"Cartilage · Capsule · Fluid · Ligament · Bursa","explanation":"Rebuild the joint from the surfaces outward."},"goodToKnow":"Subcutaneous bursae lie between skin and a bony prominence, such as around the knee or elbow.","act":{"type":"choice","prompt":"What directly provides lubrication inside a synovial cavity?","options":[{"label":"Synovial fluid","correct":true,"feedback":"Correct. It reduces friction between moving surfaces."},{"label":"Sebum","correct":false,"feedback":"Sebum lubricates skin and hair, not joints."},{"label":"A suture","correct":false,"feedback":"A suture is a fibrous joint."}]}},{"id":"l8-m4","chapter":null,"chapterSummary":null,"title":"Six joint shapes","highYield":"Shape predicts available axes of motion.","teach":["Plane joints glide; hinge joints mainly flex and extend; pivot joints rotate around one axis. Condyloid joints move in two planes, saddle joints allow broad biaxial movement, and ball-and-socket joints move around multiple axes.","Use anchor examples: intercarpal plane, elbow hinge, proximal radioulnar pivot, knuckle condyloid, thumb saddle, and shoulder or hip ball-and-socket. Ball-and-socket mobility is broad, but stability still depends on socket depth, capsule, ligaments and muscles."],"keyPoints":["Hinge and pivot are uniaxial.","Condyloid and saddle are biaxial.","Ball-and-socket is multiaxial.","The thumb carpometacarpal joint is saddle shaped."],"visual":{"title":"Shape-to-motion ladder","kind":"concept-map","items":[{"label":"Plane","detail":"Glide"},{"label":"Hinge","detail":"Door-like arc"},{"label":"Pivot","detail":"Axial rotation"},{"label":"Condyloid","detail":"Two-plane oval"},{"label":"Saddle","detail":"Two-plane reciprocal curves"},{"label":"Ball-and-socket","detail":"Multiaxial sphere"}]},"mnemonic":{"title":"Please Help People Cook Soup Bowls","cue":"Plane · Hinge · Pivot · Condyloid · Saddle · Ball-and-socket","explanation":"Use the first letters to recall the six shapes."},"goodToKnow":"The hip and shoulder share a joint type but differ in stability because their surrounding anatomy differs.","act":{"type":"choice","prompt":"Which joint type is found at the base of the thumb?","options":[{"label":"Saddle","correct":true,"feedback":"Correct. The thumb carpometacarpal joint is the classic saddle joint."},{"label":"Hinge","correct":false,"feedback":"A hinge mainly flexes and extends."},{"label":"Pivot","correct":false,"feedback":"A pivot rotates around one axis."}]}},{"id":"synovial-design-match","title":"Match it: Synovial layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Smooth bearing surface","Low-friction space","Enclosure and stability","Bone-to-bone restraint","Friction-reducing sac"],"items":[{"label":"Cavity + fluid","category":1,"feedback":"Cavity + fluid: Low-friction space"},{"label":"Bursa","category":4,"feedback":"Bursa: Friction-reducing sac"},{"label":"Capsule","category":2,"feedback":"Capsule: Enclosure and stability"},{"label":"Cartilage","category":0,"feedback":"Cartilage: Smooth bearing surface"},{"label":"Ligament","category":3,"feedback":"Ligament: Bone-to-bone restraint"}]}},{"id":"l8-m5","chapter":"Decode movement words","chapterSummary":"Movement terms describe a direction, not a disease or level of ability.","title":"Angle and midline movements","highYield":"Flex/extend change an angle; abduct/adduct change distance from the midline.","teach":["Flexion decreases the angle between bones, while extension increases it. Hyperextension continues beyond the anatomical position. Abduction moves a part away from the midline; adduction returns it toward the midline.","Circumduction combines flexion, extension, abduction and adduction so the distal end traces a circle. Rotation turns a bone around its long axis."],"keyPoints":["Flexion decreases an angle.","Extension increases an angle.","Abduction moves away from the midline.","Adduction moves toward the midline."],"visual":{"title":"Direction compass","kind":"concept-map","items":[{"label":"Flexion","detail":"Close the angle"},{"label":"Extension","detail":"Open the angle"},{"label":"Abduction","detail":"Away from midline"},{"label":"Adduction","detail":"Add toward midline"},{"label":"Rotation","detail":"Turn around an axis"}]},"mnemonic":{"title":"ABduct = away","cue":"ABduction begins with the same sound as away","explanation":"Then adduction means add it back."},"goodToKnow":"Pronation is not movement of the jaw; in the forearm it turns the palm posteriorly/downward from anatomical position.","act":{"type":"choice","prompt":"A leg moves laterally away from the body midline. What movement occurred?","options":[{"label":"Abduction","correct":true,"feedback":"Correct. Abduction moves away from the midline."},{"label":"Adduction","correct":false,"feedback":"Adduction returns toward the midline."},{"label":"Flexion","correct":false,"feedback":"Flexion changes the joint angle."}]}},{"id":"l8-m6","chapter":null,"chapterSummary":null,"title":"Special movements","highYield":"Feet, forearms, jaw and shoulder girdles use specialized vocabulary.","teach":["Dorsiflexion brings the top of the foot toward the shin; plantar flexion points the foot. Inversion turns the sole inward and eversion turns it outward. Pronation and supination describe forearm rotation.","Elevation raises a body part and depression lowers it. Protraction moves a structure anteriorly, while retraction moves it posteriorly. Opposition brings the thumb across the palm to meet a fingertip."],"keyPoints":["Dorsiflexion lifts the foot.","Inversion and eversion apply to the foot.","Elevation and depression are opposites.","Opposition is central to thumb function."],"visual":{"title":"Special-movement pairs","kind":"concept-map","items":[{"label":"Dorsi / plantar","detail":"Foot up / point"},{"label":"Inversion / eversion","detail":"Sole in / out"},{"label":"Pronation / supination","detail":"Palm down / up"},{"label":"Elevation / depression","detail":"Raise / lower"},{"label":"Protraction / retraction","detail":"Forward / back"}]},"mnemonic":{"title":"SOUPination","cue":"Supination holds a bowl of soup","explanation":"Palm-up imagery separates it from pronation."},"goodToKnow":"Movement descriptions assume the anatomical position unless the context says otherwise.","act":{"type":"choice","prompt":"Which movement raises the foot at the ankle?","options":[{"label":"Dorsiflexion","correct":true,"feedback":"Correct. Dorsiflexion brings the dorsum toward the shin."},{"label":"Plantar flexion","correct":false,"feedback":"That points the foot downward."},{"label":"Eversion","correct":false,"feedback":"That turns the sole outward."}]}},{"id":"movement-match","title":"Match it: Direction compass","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Close the angle","Open the angle","Away from midline","Add toward midline","Turn around an axis"],"items":[{"label":"Extension","category":1,"feedback":"Extension: Open the angle"},{"label":"Rotation","category":4,"feedback":"Rotation: Turn around an axis"},{"label":"Abduction","category":2,"feedback":"Abduction: Away from midline"},{"label":"Flexion","category":0,"feedback":"Flexion: Close the angle"},{"label":"Adduction","category":3,"feedback":"Adduction: Add toward midline"}]}},{"id":"l8-m7","chapter":"Stress, injury and joint conditions","chapterSummary":"Separate the injured structure from the movement affected and from the condition’s cause.","title":"Sprain, strain and dislocation","highYield":"The words identify different structures and events.","teach":["A sprain injures a ligament; a strain injures muscle or tendon. A dislocation occurs when articulating bone surfaces are displaced, while subluxation is partial displacement. These require appropriate clinical assessment rather than self-classification.","Repetitive loading can irritate tendons or bursae and may contribute to compression syndromes such as carpal tunnel syndrome. A laminectomy is a surgical removal of part of a vertebral lamina to create space; it is not simply another word for dislocation."],"keyPoints":["Sprain involves a ligament.","Strain involves muscle or tendon.","Dislocation changes joint congruence.","Bursitis is inflammation of a bursa."],"visual":{"title":"Structure-first sorting","kind":"concept-map","items":[{"label":"Ligament","detail":"Sprain"},{"label":"Muscle/tendon","detail":"Strain"},{"label":"Joint alignment","detail":"Dislocation"},{"label":"Bursa","detail":"Bursitis"},{"label":"Joint overall","detail":"Arthritis"}]},"mnemonic":{"title":"SPRained Ligament","cue":"SPrain pairs with supporting ligament","explanation":"Contrast it with STRain of muscle/tendon."},"goodToKnow":"A temporarily displaced joint is still a safety concern even if it seems to move back into place.","act":{"type":"choice","prompt":"Which term best matches injury to a ligament?","options":[{"label":"Sprain","correct":true,"feedback":"Correct. Ligaments are the affected structure in a sprain."},{"label":"Strain","correct":false,"feedback":"A strain affects muscle or tendon."},{"label":"Arthritis","correct":false,"feedback":"Arthritis refers to joint inflammation/disease, not this injury category."}]}},{"id":"l8-m8","chapter":null,"chapterSummary":null,"title":"Arthritis patterns without shortcuts","highYield":"Arthritis is a broad category; several mechanisms can affect a joint.","teach":["Osteoarthritis involves degeneration of joint structures over time and load. Rheumatoid arthritis is a systemic autoimmune connective-tissue disorder that often inflames small joints. Gout follows deposition of urate crystals, commonly affecting the joint at the base of the large toe.","Shared symptoms such as pain, stiffness or swelling do not make the conditions equivalent. History, examination and testing guide diagnosis; anatomy study should help you understand the involved structures, not diagnose from a symptom list."],"keyPoints":["Arthritis means joint inflammation/disease as a broad label.","Osteoarthritis is degenerative.","Rheumatoid arthritis is autoimmune/systemic.","Gout involves urate crystals."],"visual":{"title":"Three mechanisms","kind":"concept-map","items":[{"label":"Wear/degeneration","detail":"Osteoarthritis"},{"label":"Autoimmune inflammation","detail":"Rheumatoid arthritis"},{"label":"Crystal deposition","detail":"Gout"}]},"mnemonic":{"title":"ORG","cue":"Osteoarthritis · Rheumatoid · Gout","explanation":"Name the mechanism after the label."},"goodToKnow":"Gout can involve other joints even though the first metatarsophalangeal joint is a classic site.","act":{"type":"choice","prompt":"Which condition is associated with urate-crystal deposition?","options":[{"label":"Gout","correct":true,"feedback":"Correct. Urate crystals can inflame affected joints."},{"label":"Rheumatoid arthritis","correct":false,"feedback":"That is an autoimmune disorder."},{"label":"Bursitis","correct":false,"feedback":"That affects a bursa rather than describing crystal deposition."}]}},{"id":"applied-joints-match","title":"Match it: Structure-first sorting","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sprain","Strain","Dislocation","Bursitis","Arthritis"],"items":[{"label":"Muscle/tendon","category":1,"feedback":"Muscle/tendon: Strain"},{"label":"Joint overall","category":4,"feedback":"Joint overall: Arthritis"},{"label":"Joint alignment","category":2,"feedback":"Joint alignment: Dislocation"},{"label":"Ligament","category":0,"feedback":"Ligament: Sprain"},{"label":"Bursa","category":3,"feedback":"Bursa: Bursitis"}]}}],"flashcards":[{"front":"Synarthrosis","back":"Functionally immovable joint."},{"front":"Amphiarthrosis","back":"Slightly movable joint."},{"front":"Diarthrosis","back":"Freely movable joint; most are synovial."},{"front":"Synchondrosis","back":"Cartilaginous joint united by hyaline cartilage."},{"front":"Symphysis","back":"Cartilaginous joint united by fibrocartilage."},{"front":"Bursa","back":"Small fluid-filled sac that reduces friction."},{"front":"Flexion","back":"Movement that decreases a joint angle."},{"front":"Abduction","back":"Movement away from the midline."},{"front":"Dorsiflexion","back":"Movement bringing the top of the foot toward the shin."},{"front":"Saddle joint","back":"Biaxial synovial joint; classic example is the thumb base."},{"front":"Sprain","back":"Ligament injury."},{"front":"Gout","back":"Inflammatory arthritis associated with urate crystals."}],"quiz":[],"caseStudy":{"title":"Name the motion, then the structure","scenario":"A client with a clinician-confirmed wrist condition says repetitive chopping is difficult and asks what “kind of joint problem” it is.","prompts":["Describe the task using movement terms.","List the synovial structures that reduce friction or add stability.","Explain why symptoms alone cannot distinguish tendon, ligament, bursa or nerve involvement.","Suggest an appropriate scope-safe next step for meal-planning support."],"takeaway":"Use joint language to understand function and adapt the task; leave diagnosis and rehabilitation to the appropriate clinician."}},{"n":9,"title":"The Muscular System","kicker":"Compare skeletal, cardiac and smooth muscle.","duration":"75–95 minutes","steps":[{"id":"l9-m1","chapter":"From whole muscle to filament","chapterSummary":"Muscle organization is nested: organ, fascicle, fiber, myofibril, sarcomere, filament.","title":"Three muscle tissues","highYield":"Control, striation, cell shape and location separate the three types.","teach":["Skeletal muscle is striated, usually voluntary, and moves the skeleton. Cardiac muscle is striated but involuntary and forms the heart wall. Smooth muscle lacks visible striations, is involuntary, and moves material through hollow organs and blood vessels.","All three convert chemical energy into force, yet their cell organization and control differ. Cardiac activity is influenced by the autonomic nervous system; this does not make cardiac tissue smooth muscle."],"keyPoints":["Skeletal: striated and voluntary.","Cardiac: striated and involuntary.","Smooth: nonstriated and involuntary.","Cardiac and smooth activity are autonomically influenced."],"visual":{"title":"Three-way comparison","kind":"concept-map","items":[{"label":"Skeletal","detail":"Bones; voluntary"},{"label":"Cardiac","detail":"Heart; involuntary"},{"label":"Smooth","detail":"Hollow organs; involuntary"}]},"mnemonic":{"title":"SCS","cue":"Skeletal · Cardiac · Smooth","explanation":"Move from body wall to heart to hollow organs."},"goodToKnow":"A tissue can be striated without being voluntarily controlled.","act":{"type":"choice","prompt":"Which striated muscle is involuntary?","options":[{"label":"Cardiac","correct":true,"feedback":"Correct. Cardiac muscle is striated and involuntary."},{"label":"Skeletal","correct":false,"feedback":"Skeletal muscle is usually voluntary."},{"label":"Smooth","correct":false,"feedback":"Smooth muscle is involuntary but not striated."}]}},{"id":"l9-m2","chapter":null,"chapterSummary":null,"title":"The nested organization","highYield":"Connective-tissue layers package force-producing cells.","teach":["Epimysium surrounds the whole muscle. Perimysium surrounds a fascicle, and endomysium surrounds each muscle fiber. A fiber contains many myofibrils, which are repeating chains of sarcomeres.","Within each sarcomere, thin actin and thick myosin filaments form the banding pattern. The light I band contains thin filaments; the dark A band spans thick filaments. Tendons transmit the combined pull to bone."],"keyPoints":["Epimysium: whole muscle.","Perimysium: fascicle.","Endomysium: fiber.","Myofibrils contain repeating sarcomeres.","Actin is thin; myosin is thick."],"visual":{"title":"Zoom sequence","kind":"concept-map","items":[{"label":"Muscle","detail":"Epimysium"},{"label":"Fascicle","detail":"Perimysium"},{"label":"Fiber","detail":"Endomysium"},{"label":"Myofibril","detail":"Sarcomere chain"},{"label":"Sarcomere","detail":"Actin + myosin"}]},"mnemonic":{"title":"EPE: entire, packet, each","cue":"Epimysium · Perimysium · Endomysium","explanation":"Move from the entire muscle to packets to each fiber."},"goodToKnow":"A fascicle is a bundle of muscle fibers, not one fiber or one myofibril.","act":{"type":"choice","prompt":"What surrounds a fascicle?","options":[{"label":"Perimysium","correct":true,"feedback":"Correct. Perimysium wraps each fascicle."},{"label":"Epimysium","correct":false,"feedback":"That surrounds the whole muscle."},{"label":"Endomysium","correct":false,"feedback":"That surrounds an individual fiber."}]}},{"id":"muscle-map-match","title":"Match it: Three-way comparison","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Bones; voluntary","Heart; involuntary","Hollow organs; involuntary"],"items":[{"label":"Skeletal","category":0,"feedback":"Skeletal: Bones; voluntary"},{"label":"Cardiac","category":1,"feedback":"Cardiac: Heart; involuntary"},{"label":"Smooth","category":2,"feedback":"Smooth: Hollow organs; involuntary"}]}},{"id":"l9-m3","chapter":"Turn a nerve signal into force","chapterSummary":"Electrical events release calcium; calcium permits actin–myosin cycling; ATP powers and resets it.","title":"Neuromuscular activation","highYield":"Acetylcholine starts a muscle-fiber action potential.","teach":["When a motor-neuron impulse reaches the neuromuscular junction, acetylcholine is released. It binds receptors on the sarcolemma, changing ion permeability; sodium entry helps depolarize the membrane and launch an action potential.","The signal travels along the sarcolemma and down T tubules. This triggers the sarcoplasmic reticulum to release calcium around the myofibrils. The electrical message has now become a chemical permission signal for contraction."],"keyPoints":["Acetylcholine is the neuromuscular transmitter.","Sodium is concentrated outside the resting fiber.","The action potential enters T tubules.","The sarcoplasmic reticulum releases calcium."],"visual":{"title":"Signal relay","kind":"concept-map","items":[{"label":"Motor neuron","detail":"Impulse arrives"},{"label":"ACh","detail":"Crosses junction"},{"label":"Sarcolemma/T tubule","detail":"Conducts signal"},{"label":"SR","detail":"Releases Ca²⁺"}]},"mnemonic":{"title":"A-T-C","cue":"Acetylcholine · T tubule · Calcium","explanation":"Recall the activation sequence."},"goodToKnow":"Calcium release here is intracellular signaling, not a claim that an acute calcium supplement directly causes a stronger contraction.","act":{"type":"choice","prompt":"What ion is released by the sarcoplasmic reticulum after T-tubule activation?","options":[{"label":"Calcium","correct":true,"feedback":"Correct. Calcium exposes actin sites through regulatory proteins."},{"label":"Sodium","correct":false,"feedback":"Sodium helps depolarize the membrane but is not the SR signal here."},{"label":"Chloride","correct":false,"feedback":"It is not the key coupling ion in this sequence."}]}},{"id":"l9-m4","chapter":null,"chapterSummary":null,"title":"Sliding filaments and ATP","highYield":"Filaments slide past one another; they do not become shorter.","teach":["Calcium binds the regulatory system associated with troponin and tropomyosin, exposing binding sites on actin. Energized myosin heads attach, pivot, and pull thin filaments toward the sarcomere center.","ATP binding releases myosin from actin; ATP breakdown re-cocks the head for another cycle. As cycling repeats, Z lines approach, the I band and H zone narrow, and the A band stays the same length."],"keyPoints":["Calcium exposes binding sites.","Myosin forms cross-bridges with actin.","ATP is needed for detachment and re-energizing.","The A band remains constant."],"visual":{"title":"Cross-bridge cycle","kind":"concept-map","items":[{"label":"Expose","detail":"Calcium shifts regulators"},{"label":"Attach","detail":"Myosin binds actin"},{"label":"Pull","detail":"Power stroke"},{"label":"Release","detail":"ATP binds"},{"label":"Reset","detail":"ATP is hydrolyzed"}]},"mnemonic":{"title":"CAPRR","cue":"Calcium · Attach · Pull · Release · Reset","explanation":"Use the cycle rather than memorizing isolated steps."},"goodToKnow":"Rigor after death reflects loss of ATP-dependent cross-bridge release, illustrating ATP’s role in relaxation.","act":{"type":"choice","prompt":"During contraction, which band remains the same length?","options":[{"label":"A band","correct":true,"feedback":"Correct. It reflects the length of thick filaments."},{"label":"I band","correct":false,"feedback":"The I band narrows as overlap increases."},{"label":"H zone","correct":false,"feedback":"The H zone narrows and may disappear."}]}},{"id":"contraction-match","title":"Match it: Signal relay","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Impulse arrives","Crosses junction","Conducts signal","Releases Ca²⁺"],"items":[{"label":"SR","category":3,"feedback":"SR: Releases Ca²⁺"},{"label":"Sarcolemma/T tubule","category":2,"feedback":"Sarcolemma/T tubule: Conducts signal"},{"label":"ACh","category":1,"feedback":"ACh: Crosses junction"},{"label":"Motor neuron","category":0,"feedback":"Motor neuron: Impulse arrives"}]}},{"id":"l9-m5","chapter":"Fuel, tension and adaptation","chapterSummary":"Muscles regenerate ATP through overlapping systems and express force in different ways.","title":"Three routes to ATP","highYield":"Stored ATP is small; phosphocreatine, glycolysis and aerobic metabolism replenish it.","teach":["Muscle stores only a brief supply of ATP. Phosphocreatine rapidly transfers a phosphate to ADP and is especially useful during short, intense work. Anaerobic glycolysis produces ATP quickly from glucose but yields lactate when pyruvate cannot be processed aerobically at the same rate.","Aerobic metabolism in mitochondria uses oxygen and fuel molecules to generate much more ATP, supporting longer-duration activity. All systems overlap; their relative contribution shifts with intensity, duration, training and recovery."],"keyPoints":["Phosphocreatine rapidly buffers ATP.","Glycolysis can proceed without oxygen.","Aerobic metabolism yields more ATP over time.","Lactate is associated with anaerobic processing in this text’s framework."],"visual":{"title":"Energy continuum","kind":"concept-map","items":[{"label":"Stored ATP","detail":"Seconds"},{"label":"Phosphocreatine","detail":"Rapid high power"},{"label":"Anaerobic glycolysis","detail":"Fast, limited yield"},{"label":"Aerobic metabolism","detail":"Slower, sustained yield"}]},"mnemonic":{"title":"PGA","cue":"Phosphocreatine · Glycolysis · Aerobic","explanation":"Order the major replenishment routes from rapid to sustained."},"goodToKnow":"Phosphocreatine is the phosphorylated molecule named in the source quiz, whereas creatine alone is not the immediate phosphate donor.","act":{"type":"choice","prompt":"What molecule rapidly donates phosphate to regenerate ATP in muscle?","options":[{"label":"Phosphocreatine","correct":true,"feedback":"Correct. It serves as a rapid high-energy phosphate reserve."},{"label":"Actin","correct":false,"feedback":"Actin is a contractile protein."},{"label":"Lactate","correct":false,"feedback":"Lactate is not the immediate phosphate donor."}]}},{"id":"l9-m6","chapter":null,"chapterSummary":null,"title":"Tone and contraction types","highYield":"Length change and tension are separate features.","teach":["Muscle tone is a low level of ongoing activation that helps posture and readiness. In an isotonic contraction, tension moves a load and muscle length changes: concentric action shortens; eccentric action lengthens under tension.","In an isometric contraction, tension rises but overall muscle length and the joint angle remain relatively constant. Repeated overload can promote hypertrophy; disuse can lead to atrophy."],"keyPoints":["Tone supports posture.","Concentric shortens under load.","Eccentric lengthens under load.","Isometric creates tension without visible shortening.","Disuse promotes atrophy."],"visual":{"title":"Tension map","kind":"concept-map","items":[{"label":"Concentric","detail":"Shorten"},{"label":"Eccentric","detail":"Lengthen under load"},{"label":"Isometric","detail":"Hold length"},{"label":"Tone","detail":"Baseline activation"}]},"mnemonic":{"title":"Metric means length","cue":"IsoMETRIC keeps the measurement similar","explanation":"Isotonic involves movement in the simplified textbook contrast."},"goodToKnow":"Holding a weight still is isometric; lifting it is typically concentric, not isometric.","act":{"type":"choice","prompt":"A person holds a grocery bag motionless with the elbow fixed. Which contraction dominates?","options":[{"label":"Isometric","correct":true,"feedback":"Correct. Tension is present without an obvious length change."},{"label":"Concentric","correct":false,"feedback":"That would shorten the active muscle to move the load."},{"label":"Atrophy","correct":false,"feedback":"Atrophy is loss of muscle bulk, not a contraction type."}]}},{"id":"energy-control-match","title":"Match it: Energy continuum","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Seconds","Rapid high power","Fast, limited yield","Slower, sustained yield"],"items":[{"label":"Aerobic metabolism","category":3,"feedback":"Aerobic metabolism: Slower, sustained yield"},{"label":"Anaerobic glycolysis","category":2,"feedback":"Anaerobic glycolysis: Fast, limited yield"},{"label":"Phosphocreatine","category":1,"feedback":"Phosphocreatine: Rapid high power"},{"label":"Stored ATP","category":0,"feedback":"Stored ATP: Seconds"}]}},{"id":"l9-m7","chapter":"Read muscle names and actions","chapterSummary":"Names often reveal location, shape, fiber direction, attachment or action.","title":"Origin, insertion and teamwork","highYield":"Movement emerges from groups, not one muscle acting alone.","teach":["The origin is usually the less movable attachment; the insertion is usually the more movable attachment where the effect is seen. During an action, the prime mover or agonist supplies the main force, an antagonist opposes or controls it, and synergists assist or stabilize.","Muscle names can encode clues: rectus means straight, oblique signals diagonal fibers, maximus indicates large size, and terms such as flexor, adductor or levator describe action."],"keyPoints":["Insertion is typically the movable attachment.","Agonist is the prime mover.","Antagonist opposes or controls.","Synergists assist.","Names often predict action or anatomy."],"visual":{"title":"Team roles","kind":"concept-map","items":[{"label":"Agonist","detail":"Main action"},{"label":"Antagonist","detail":"Opposes/controls"},{"label":"Synergist","detail":"Assists"},{"label":"Origin","detail":"Less movable"},{"label":"Insertion","detail":"More movable"}]},"mnemonic":{"title":"AIS","cue":"Agonist acts · antagonist inhibits/controls · synergist supports","explanation":"Use roles rather than memorizing pairs."},"goodToKnow":"The same muscle may be an agonist in one movement and an antagonist in another.","act":{"type":"choice","prompt":"What is the movable attachment called?","options":[{"label":"Insertion","correct":true,"feedback":"Correct. The effect of contraction is usually seen at the insertion."},{"label":"Origin","correct":false,"feedback":"The origin is usually less movable."},{"label":"Fascicle","correct":false,"feedback":"A fascicle is a bundle of fibers."}]}},{"id":"l9-m8","chapter":null,"chapterSummary":null,"title":"Anchor muscles by function","highYield":"Connect a familiar action to each name.","teach":["Frontalis raises the eyebrows; rectus abdominis flexes the trunk; the superior rectus elevates the eye. Flexor digitorum longus flexes the toes, while tibialis anterior contributes to dorsiflexion.","Action words generalize: abductors move away from the midline, adductors return toward it, levators raise, depressors lower, flexors decrease an angle and extensors increase it. Learn the rule first, then the regional example."],"keyPoints":["Frontalis raises eyebrows.","Rectus abdominis flexes trunk.","Flexor digitorum longus flexes toes.","Superior rectus raises the eye.","Tibialis anterior dorsiflexes."],"visual":{"title":"Name-to-action anchors","kind":"concept-map","items":[{"label":"Frontalis","detail":"Forehead/eyebrows"},{"label":"Rectus abdominis","detail":"Trunk flexion"},{"label":"Flexor digitorum longus","detail":"Toe flexion"},{"label":"Superior rectus","detail":"Eye elevation"},{"label":"Tibialis anterior","detail":"Dorsiflexion"}]},"mnemonic":{"title":"Name is a clue","cue":"Region + direction + action","explanation":"Decode the components before rote recall."},"goodToKnow":"Dorsiflexion appears in both the joint and muscle lessons because movement vocabulary bridges systems.","act":{"type":"choice","prompt":"Which muscle is emphasized in a traditional sit-up?","options":[{"label":"Rectus abdominis","correct":true,"feedback":"Correct. It is a major trunk flexor."},{"label":"Frontalis","correct":false,"feedback":"That raises the eyebrows."},{"label":"Superior rectus","correct":false,"feedback":"That moves the eye."}]}},{"id":"muscle-actions-match","title":"Match it: Team roles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Main action","Opposes/controls","Assists","Less movable","More movable"],"items":[{"label":"Antagonist","category":1,"feedback":"Antagonist: Opposes/controls"},{"label":"Insertion","category":4,"feedback":"Insertion: More movable"},{"label":"Synergist","category":2,"feedback":"Synergist: Assists"},{"label":"Agonist","category":0,"feedback":"Agonist: Main action"},{"label":"Origin","category":3,"feedback":"Origin: Less movable"}]}}],"flashcards":[{"front":"Fascicle","back":"Bundle of muscle fibers."},{"front":"Epimysium","back":"Connective tissue around a whole muscle."},{"front":"Perimysium","back":"Connective tissue around a fascicle."},{"front":"Sarcomere","back":"Repeating contractile unit of a myofibril."},{"front":"Actin","back":"Thin contractile filament."},{"front":"Myosin","back":"Thick motor filament."},{"front":"Acetylcholine","back":"Neurotransmitter released at the neuromuscular junction."},{"front":"Phosphocreatine","back":"Rapid high-energy phosphate reserve for ATP regeneration."},{"front":"Isometric","back":"Tension without appreciable muscle shortening."},{"front":"Atrophy","back":"Decrease in muscle bulk, often associated with disuse."},{"front":"Agonist","back":"Prime mover for an action."},{"front":"Insertion","back":"Usually the more movable muscle attachment."}],"quiz":[],"caseStudy":{"title":"Fuel is only one part of force","scenario":"A recreational athlete says fatigue during repeated lifts must mean one specific nutrient is missing.","prompts":["Trace the signal from motor neuron to calcium release.","Name the ATP systems that overlap during repeated work.","Distinguish concentric, eccentric and isometric phases.","Explain why fatigue cannot be diagnosed from the workout description alone."],"takeaway":"Connect neural activation, cross-bridge cycling, energy systems and task demands before considering nutrition within scope."}},{"n":10,"title":"The Nervous System: Introduction, Spinal Cord, and Spinal Nerves","kicker":"Organize the nervous system into central, peripheral, sensory and motor divisions.","duration":"75–95 minutes","steps":[{"id":"l10-m1","chapter":"Build the communication map","chapterSummary":"The nervous system receives information, integrates it and sends a response.","title":"CNS, PNS, sensory and motor","highYield":"Location and direction create the master map.","teach":["The central nervous system (CNS) is the brain and spinal cord. The peripheral nervous system (PNS) includes nerves and ganglia outside the CNS. Together they form a rapid control and communication network.","Sensory, or afferent, neurons carry information toward the CNS. Motor, or efferent, neurons carry commands from the CNS to muscles and glands. Interneurons inside the CNS connect and process these pathways."],"keyPoints":["CNS = brain + spinal cord.","PNS = nerves + ganglia.","Afferent arrives at the CNS.","Efferent exits the CNS.","Interneurons integrate."],"visual":{"title":"Information loop","kind":"concept-map","items":[{"label":"Receptor","detail":"Detects change"},{"label":"Afferent neuron","detail":"Toward CNS"},{"label":"Interneuron","detail":"Integrates"},{"label":"Efferent neuron","detail":"Away from CNS"},{"label":"Effector","detail":"Responds"}]},"mnemonic":{"title":"SAME direction","cue":"Sensory Afferent; Motor Efferent","explanation":"SAME pairs pathway role with directional term."},"goodToKnow":"A motor neuron is also called efferent; the first neuron from a receptor is sensory/afferent, not motor.","act":{"type":"choice","prompt":"Which neuron carries a command from spinal cord to skeletal muscle?","options":[{"label":"Motor/efferent","correct":true,"feedback":"Correct. Efferent pathways exit the CNS."},{"label":"Sensory/afferent","correct":false,"feedback":"Afferent pathways carry input toward the CNS."},{"label":"Bipolar receptor only","correct":false,"feedback":"Shape does not replace directional function."}]}},{"id":"l10-m2","chapter":null,"chapterSummary":null,"title":"Neuron shapes and parts","highYield":"Dendrites receive, the soma maintains, and the axon conducts away.","teach":["A neuron has a cell body, dendrites and usually one axon. Multipolar neurons have many dendrites and one axon and are common among motor neurons and interneurons. Most general sensory neurons are unipolar; bipolar neurons occur in special sensory pathways.","Neuron shape and pathway role are related but not identical labels. A neuron may be called sensory because of information direction and unipolar because of structure."],"keyPoints":["Dendrites receive input.","The axon carries signals away from the soma.","Multipolar neurons have many dendrites.","Most general sensory neurons are unipolar.","Bipolar neurons serve special senses."],"visual":{"title":"Neuron forms","kind":"concept-map","items":[{"label":"Multipolar","detail":"Many dendrites, one axon"},{"label":"Unipolar","detail":"Single process; common sensory form"},{"label":"Bipolar","detail":"Two processes; special senses"}]},"mnemonic":{"title":"MUB","cue":"Multipolar · Unipolar · Bipolar","explanation":"Picture many, one, and two processes."},"goodToKnow":"The soma is metabolically essential; a long axon depends on transport from its cell body.","act":{"type":"choice","prompt":"Which structural type describes most general sensory neurons?","options":[{"label":"Unipolar","correct":true,"feedback":"Correct. Most are unipolar in this textbook classification."},{"label":"Multipolar","correct":false,"feedback":"Most motor neurons and interneurons are multipolar."},{"label":"Acellular","correct":false,"feedback":"Neurons are cells."}]}},{"id":"organization-match","title":"Match it: Information loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Detects change","Toward CNS","Integrates","Away from CNS","Responds"],"items":[{"label":"Afferent neuron","category":1,"feedback":"Afferent neuron: Toward CNS"},{"label":"Effector","category":4,"feedback":"Effector: Responds"},{"label":"Interneuron","category":2,"feedback":"Interneuron: Integrates"},{"label":"Receptor","category":0,"feedback":"Receptor: Detects change"},{"label":"Efferent neuron","category":3,"feedback":"Efferent neuron: Away from CNS"}]}},{"id":"l10-m3","chapter":"Support and signal","chapterSummary":"Glia maintain the neural environment; neurons generate and transmit electrochemical signals.","title":"Neuroglia are active partners","highYield":"Different glia support, defend, insulate and circulate fluid.","teach":["Astrocytes form a supporting network and help regulate the CNS environment. Oligodendrocytes form myelin in the CNS; Schwann cells form myelin in the PNS. Microglia are phagocytic defenders, and ependymal cells line fluid-filled CNS spaces.","Satellite cells support neuron cell bodies in peripheral ganglia. Glia are more numerous than neurons in many regions; the claim that more than 60% of all brain cells are neurons is therefore not a safe generalization."],"keyPoints":["Astrocytes support and regulate.","Oligodendrocytes myelinate CNS axons.","Schwann cells myelinate PNS axons.","Microglia defend.","Ependymal cells line ventricles/central canal."],"visual":{"title":"Glial jobs","kind":"concept-map","items":[{"label":"Astrocyte","detail":"Support and environment"},{"label":"Oligodendrocyte","detail":"CNS myelin"},{"label":"Schwann cell","detail":"PNS myelin"},{"label":"Microglia","detail":"Defense"},{"label":"Ependymal","detail":"Fluid-space lining"}]},"mnemonic":{"title":"CNS O, PNS S","cue":"Oligodendrocyte in the CNS; Schwann in the PNS","explanation":"Anchor the myelin cells by location."},"goodToKnow":"A single oligodendrocyte can myelinate parts of several CNS axons; one Schwann cell wraps one PNS segment.","act":{"type":"choice","prompt":"Which cell forms myelin around a peripheral nerve fiber?","options":[{"label":"Schwann cell","correct":true,"feedback":"Correct. Schwann cells myelinate PNS axons."},{"label":"Astrocyte","correct":false,"feedback":"Astrocytes support the CNS environment."},{"label":"Microglia","correct":false,"feedback":"Microglia are immune-like CNS cells."}]}},{"id":"l10-m4","chapter":null,"chapterSummary":null,"title":"Action potentials and synapses","highYield":"Electrical conduction along an axon becomes chemical signaling at many synapses.","teach":["At rest, ion gradients create a membrane potential. A sufficient stimulus opens voltage-gated channels: sodium entry depolarizes the membrane, then potassium movement helps repolarize it. The refractory period supports one-way propagation from the trigger zone along the axon.","Myelin speeds conduction because current effectively jumps between nodes. At a chemical synapse, the action potential triggers neurotransmitter release; transmitter crosses the cleft, binds receptors and changes the next cell. Acetylcholine is a common transmitter, but the body uses many others."],"keyPoints":["Sodium entry drives depolarization.","Potassium movement supports repolarization.","Myelin increases conduction speed.","Neurotransmitters cross chemical synapses.","Refractory behavior supports one-way travel."],"visual":{"title":"Signal sequence","kind":"concept-map","items":[{"label":"Rest","detail":"Ion gradients"},{"label":"Depolarize","detail":"Na⁺ entry"},{"label":"Repolarize","detail":"K⁺ shift"},{"label":"Conduct","detail":"Along axon"},{"label":"Transmit","detail":"Neurotransmitter across cleft"}]},"mnemonic":{"title":"Na in, K reset","cue":"Sodium depolarizes; potassium helps restore","explanation":"Then transmitter carries the message across the gap."},"goodToKnow":"Unmyelinated fibers conduct along the full membrane and are generally slower than comparable myelinated fibers.","act":{"type":"choice","prompt":"What crosses the gap at a chemical synapse?","options":[{"label":"A neurotransmitter","correct":true,"feedback":"Correct. It binds receptors on the next cell."},{"label":"A sarcolemma","correct":false,"feedback":"That is a muscle-cell membrane."},{"label":"A tract","correct":false,"feedback":"A tract is a CNS bundle of axons."}]}},{"id":"cells-signals-match","title":"Match it: Glial jobs","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Support and environment","CNS myelin","PNS myelin","Defense","Fluid-space lining"],"items":[{"label":"Oligodendrocyte","category":1,"feedback":"Oligodendrocyte: CNS myelin"},{"label":"Ependymal","category":4,"feedback":"Ependymal: Fluid-space lining"},{"label":"Schwann cell","category":2,"feedback":"Schwann cell: PNS myelin"},{"label":"Astrocyte","category":0,"feedback":"Astrocyte: Support and environment"},{"label":"Microglia","category":3,"feedback":"Microglia: Defense"}]}},{"id":"l10-m5","chapter":"Read the spinal cord and nerves","chapterSummary":"Learn the location vocabulary before tracing a pathway.","title":"Gray, white, tract, nerve, nucleus, ganglion","highYield":"The same cellular material receives different names by location.","teach":["Gray matter contains many neuron cell bodies, dendrites and synapses; white matter contains many myelinated axons. In the spinal cord, gray matter forms an inner butterfly-like region surrounded by white columns.","A bundle of axons inside the CNS is a tract; outside it is a nerve. A cluster of neuron cell bodies inside the CNS is a nucleus; outside it is a ganglion. These paired terms are frequent test targets."],"keyPoints":["Gray matter emphasizes somas and dendrites.","White matter emphasizes myelinated axons.","CNS axon bundle = tract.","PNS axon bundle = nerve.","PNS cell-body cluster = ganglion."],"visual":{"title":"Location vocabulary","kind":"concept-map","items":[{"label":"CNS bundle","detail":"Tract"},{"label":"PNS bundle","detail":"Nerve"},{"label":"CNS somas","detail":"Nucleus"},{"label":"PNS somas","detail":"Ganglion"}]},"mnemonic":{"title":"TNNG map","cue":"Tract/Nucleus in CNS; Nerve/Ganglion in PNS","explanation":"Sort by axons versus somas, then by location."},"goodToKnow":"Ganglion and ganglia refer to the same PNS cell-body structure in singular and plural.","act":{"type":"choice","prompt":"What is a bundle of axons within the CNS called?","options":[{"label":"Tract","correct":true,"feedback":"Correct. A peripheral bundle would be a nerve."},{"label":"Ganglion","correct":false,"feedback":"A ganglion is a PNS cluster of cell bodies."},{"label":"Nucleus","correct":false,"feedback":"A nucleus is a CNS cluster of cell bodies."}]}},{"id":"l10-m6","chapter":null,"chapterSummary":null,"title":"Cord, roots and mixed spinal nerves","highYield":"Sensory and motor fibers separate at roots but combine in each spinal nerve.","teach":["The spinal cord continues from the medulla oblongata through the vertebral canal. Dorsal roots bring sensory information into the cord, and their dorsal-root ganglia contain sensory neuron cell bodies. Ventral roots carry motor output away.","A dorsal and ventral root unite to form a mixed spinal nerve, so every spinal nerve carries both sensory and motor fibers. The epidural space lies between the vertebral canal and the dura mater and contains cushioning tissue and vessels."],"keyPoints":["Cord continues from medulla oblongata.","Dorsal root is sensory.","Ventral root is motor.","All spinal nerves are mixed.","Epidural space lies outside the dura."],"visual":{"title":"Root-to-nerve","kind":"concept-map","items":[{"label":"Dorsal root","detail":"Sensory input"},{"label":"Dorsal-root ganglion","detail":"Sensory somas"},{"label":"Ventral root","detail":"Motor output"},{"label":"Spinal nerve","detail":"Mixed fibers"},{"label":"Epidural space","detail":"Outside dura"}]},"mnemonic":{"title":"DAVE","cue":"Dorsal Afferent; Ventral Efferent","explanation":"Then the roots unite into a mixed nerve."},"goodToKnow":"The adult spinal cord ends above the lowest vertebrae; lower roots descend before exiting.","act":{"type":"choice","prompt":"Why is a spinal nerve called mixed?","options":[{"label":"It contains both sensory and motor fibers.","correct":true,"feedback":"Correct. The two root streams combine."},{"label":"It belongs only to the autonomic system.","correct":false,"feedback":"Spinal nerves carry multiple functional fiber types."},{"label":"It contains gray and white matter.","correct":false,"feedback":"Those terms describe CNS tissue organization."}]}},{"id":"spinal-map-match","title":"Match it: Location vocabulary","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tract","Nerve","Nucleus","Ganglion"],"items":[{"label":"PNS somas","category":3,"feedback":"PNS somas: Ganglion"},{"label":"CNS somas","category":2,"feedback":"CNS somas: Nucleus"},{"label":"PNS bundle","category":1,"feedback":"PNS bundle: Nerve"},{"label":"CNS bundle","category":0,"feedback":"CNS bundle: Tract"}]}},{"id":"l10-m7","chapter":"Fast responses and autonomic balance","chapterSummary":"Reflex arcs protect and regulate; autonomic divisions shift organ activity with context.","title":"The reflex arc","highYield":"A reflex can produce a rapid response before conscious interpretation.","teach":["A basic somatic reflex arc includes receptor, sensory neuron, integration center, motor neuron and skeletal-muscle effector. Some reflexes are monosynaptic; many use interneurons and multiple synapses.","The brain can become aware of the event and modify later behavior, but the spinal circuitry does not need to wait for a conscious decision. Reflex testing therefore samples both sensory and motor pathway integrity."],"keyPoints":["Receptor detects the stimulus.","Afferent neuron enters the CNS.","Integration occurs in CNS gray matter.","Efferent neuron activates an effector."],"visual":{"title":"Reflex loop","kind":"concept-map","items":[{"label":"1 Receptor","detail":"Detect"},{"label":"2 Afferent","detail":"Carry in"},{"label":"3 Integration","detail":"Process"},{"label":"4 Efferent","detail":"Carry out"},{"label":"5 Effector","detail":"Respond"}]},"mnemonic":{"title":"RAIME","cue":"Receptor · Afferent · Integration · Motor · Effector","explanation":"Trace the five stations in order."},"goodToKnow":"A withdrawal reflex and the conscious perception of pain are related but not identical events.","act":{"type":"choice","prompt":"Which neuron directly brings a command to the responding muscle?","options":[{"label":"Motor/efferent neuron","correct":true,"feedback":"Correct. It is the output limb of the arc."},{"label":"Sensory/afferent neuron","correct":false,"feedback":"That carries information from the receptor."},{"label":"Dorsal-root ganglion","correct":false,"feedback":"That is a cluster of sensory cell bodies."}]}},{"id":"l10-m8","chapter":null,"chapterSummary":null,"title":"ANS bridge for this quiz bank","highYield":"Sympathetic mobilizes; parasympathetic supports routine restorative functions.","teach":["The autonomic nervous system is the involuntary motor branch serving smooth muscle, cardiac muscle and glands. Its sympathetic division generally mobilizes the body during challenge, increasing selected activities needed for action; its parasympathetic division predominates during many routine conditions and supports digestion, urination and defecation.","In the textbook framing, acetylcholine is released at parasympathetic nerve endings at target organs, while sympathetic end organs commonly receive norepinephrine. Both divisions use acetylcholine at their first ganglionic synapse. Lesson 11 expands this preview; it appears here because the supplied Lesson 10 quiz tests it directly."],"keyPoints":["ANS is involuntary motor output.","Sympathetic prepares for challenge.","Parasympathetic supports rest-and-digest functions.","ACh is used at parasympathetic target endings.","Both divisions use ACh before the ganglion."],"visual":{"title":"Autonomic balance","kind":"concept-map","items":[{"label":"Sympathetic","detail":"Mobilize"},{"label":"Parasympathetic","detail":"Restore and maintain"},{"label":"Shared first synapse","detail":"ACh"},{"label":"Parasympathetic target","detail":"ACh"},{"label":"Common sympathetic target","detail":"Norepinephrine"}]},"mnemonic":{"title":"S = stress; P = peace","cue":"Sympathetic mobilizes, parasympathetic maintains","explanation":"Use the pattern, not the idea that one division is always on alone."},"goodToKnow":"The two divisions often have opposing effects, yet both continuously contribute to organ regulation.","act":{"type":"choice","prompt":"Which transmitter does the parasympathetic division release at its target endings in this course?","options":[{"label":"Acetylcholine","correct":true,"feedback":"Correct. This is the quiz-bank wording and textbook pattern."},{"label":"Dopamine","correct":false,"feedback":"Dopamine has other CNS roles."},{"label":"Epinephrine only","correct":false,"feedback":"That is not the standard parasympathetic target transmitter."}]}},{"id":"responses-match","title":"Match it: Reflex loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Detect","Carry in","Process","Carry out","Respond"],"items":[{"label":"2 Afferent","category":1,"feedback":"2 Afferent: Carry in"},{"label":"5 Effector","category":4,"feedback":"5 Effector: Respond"},{"label":"3 Integration","category":2,"feedback":"3 Integration: Process"},{"label":"1 Receptor","category":0,"feedback":"1 Receptor: Detect"},{"label":"4 Efferent","category":3,"feedback":"4 Efferent: Carry out"}]}}],"flashcards":[{"front":"Afferent neuron","back":"Carries sensory information toward the CNS."},{"front":"Efferent neuron","back":"Carries motor output away from the CNS."},{"front":"Unipolar neuron","back":"Common structural type for general sensory neurons."},{"front":"Astrocyte","back":"Star-shaped CNS glial cell that supports and regulates the neural environment."},{"front":"Schwann cell","back":"Cell that forms PNS myelin."},{"front":"Neurotransmitter","back":"Chemical messenger released across a synapse."},{"front":"Tract","back":"Bundle of axons within the CNS."},{"front":"Ganglion","back":"Cluster of neuron cell bodies in the PNS."},{"front":"Gray matter","back":"Region rich in neuron somas, dendrites and synapses."},{"front":"Dorsal root","back":"Sensory/afferent root of a spinal nerve."},{"front":"Sympathetic","back":"Autonomic division that mobilizes body functions during challenge."},{"front":"Parasympathetic","back":"Autonomic division supporting routine restorative and digestive functions."},{"front":"Depressant","back":"Drug category that reduces aspects of CNS activity; Valium is the quiz example."},{"front":"Anabolic steroid","back":"Substance class with androgen-like effects; not a stimulant/depressant/hallucinogen category."}],"quiz":[],"caseStudy":{"title":"A hot surface and a fast response","scenario":"A person touches a hot tray, withdraws the hand, then notices pain and a racing heart.","prompts":["Trace the withdrawal reflex from receptor to effector.","Separate the spinal reflex from conscious perception.","Name the autonomic division that supports the challenge response.","Explain why this sequence does not identify the cause of persistent symptoms."],"takeaway":"Map sensory, integrative, motor and autonomic events as connected layers, while leaving diagnosis to clinical assessment."}},{"n":11,"title":"The Brain, Cranial Nerves, Autonomic Nervous System, and Special Senses","kicker":"Locate major brain regions and connect each with its broad function.","duration":"90–110 minutes","steps":[{"id":"l11-m1","chapter":"Brain regions as a working team","chapterSummary":"Avoid “one region, one behavior” oversimplification while learning each region’s anchor job.","title":"Cerebrum and lobes","highYield":"The cerebral cortex supports conscious sensation, movement and higher processing.","teach":["The longitudinal fissure separates right and left cerebral hemispheres, while the corpus callosum connects them. Gyri are raised folds and sulci are shallower grooves; folding expands cortical surface area.","The frontal lobe supports planning and voluntary motor control; parietal regions process somatic sensation; temporal regions contribute to hearing and memory; the occipital lobe receives and interprets visual input. These functions operate through networks rather than isolated boxes."],"keyPoints":["Longitudinal fissure separates hemispheres.","Corpus callosum connects hemispheres.","Gyri are folds.","Occipital lobe is the visual anchor.","Cortical functions are networked."],"visual":{"title":"Cortical anchors","kind":"concept-map","items":[{"label":"Frontal","detail":"Plan and move"},{"label":"Parietal","detail":"Body sensation"},{"label":"Temporal","detail":"Hear and remember"},{"label":"Occipital","detail":"See"}]},"mnemonic":{"title":"FPTO","cue":"Front · Parietal · Temporal · Occipital","explanation":"Move front-to-back around the cortex."},"goodToKnow":"The cerebral hemispheres are highly interconnected; “left brain/right brain personality” claims are oversimplified.","act":{"type":"choice","prompt":"Which lobe is the primary visual-processing anchor?","options":[{"label":"Occipital","correct":true,"feedback":"Correct. Visual input is received and interpreted there."},{"label":"Temporal","correct":false,"feedback":"Temporal regions are associated more strongly with hearing and memory."},{"label":"Frontal","correct":false,"feedback":"Frontal regions anchor planning and motor functions."}]}},{"id":"l11-m2","chapter":null,"chapterSummary":null,"title":"Diencephalon, brainstem and cerebellum","highYield":"Relay, homeostasis, vital pathways and movement coordination occupy different regions.","teach":["The thalamus relays much sensory information toward the cortex. The hypothalamus links neural and endocrine regulation and helps govern temperature, appetite, thirst and autonomic activity; the infundibulum connects it to the pituitary. The pineal gland secretes melatonin.","Midbrain, pons and medulla form the brainstem; ascending and descending tracts pass through it, and the medulla continues as the spinal cord. The reticular formation supports arousal. The cerebellum coordinates timing, balance and complex skeletal movement rather than intellectual processes or emotions."],"keyPoints":["Thalamus is a major relay.","Hypothalamus regulates homeostasis and pituitary control.","Infundibulum connects hypothalamus and pituitary.","Reticular formation supports arousal.","Cerebellum coordinates movement."],"visual":{"title":"Deep-brain map","kind":"concept-map","items":[{"label":"Thalamus","detail":"Relay"},{"label":"Hypothalamus","detail":"Homeostasis"},{"label":"Brainstem","detail":"Pathways/vital centers"},{"label":"Reticular formation","detail":"Arousal"},{"label":"Cerebellum","detail":"Coordination"}]},"mnemonic":{"title":"THReC","cue":"Thalamus · Hypothalamus · Reticular · Cerebellum","explanation":"Attach relay, homeostasis, arousal and coordination."},"goodToKnow":"The medulla contains pathways linking spinal cord and higher brain regions as well as important autonomic centers.","act":{"type":"choice","prompt":"Which region coordinates complex skeletal movements as a reflex center?","options":[{"label":"Cerebellum","correct":true,"feedback":"Correct. It refines timing, balance and coordination."},{"label":"Corpus callosum","correct":false,"feedback":"That connects the hemispheres."},{"label":"Occipital lobe","correct":false,"feedback":"That processes vision."}]}},{"id":"brain-regions-match","title":"Match it: Cortical anchors","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Plan and move","Body sensation","Hear and remember","See"],"items":[{"label":"Occipital","category":3,"feedback":"Occipital: See"},{"label":"Temporal","category":2,"feedback":"Temporal: Hear and remember"},{"label":"Parietal","category":1,"feedback":"Parietal: Body sensation"},{"label":"Frontal","category":0,"feedback":"Frontal: Plan and move"}]}},{"id":"l11-m3","chapter":"Protect and connect the brain","chapterSummary":"Membranes, fluid, vessels and cranial nerves interface the brain with the body.","title":"Meninges, CSF and circulation","highYield":"Three membranes and circulating fluid cushion vulnerable neural tissue.","teach":["From outside inward, the meninges are dura mater, arachnoid mater and pia mater. Cerebrospinal fluid (CSF) circulates through ventricles and the subarachnoid space, providing buoyancy, cushioning and chemical stability.","The brain requires continuous blood flow. An interrupted vessel can produce a cerebrovascular accident, or stroke; an aneurysm is a dilation of a vessel wall that may rupture. These are urgent medical concerns, not conditions to assess through nutrition symptoms alone."],"keyPoints":["Dura is outermost.","Arachnoid is middle.","Pia closely follows brain surface.","CSF cushions CNS.","Stroke and aneurysm are vascular terms."],"visual":{"title":"Protective layers","kind":"concept-map","items":[{"label":"Dura","detail":"Tough outer"},{"label":"Arachnoid","detail":"Web-like middle"},{"label":"Subarachnoid space","detail":"CSF"},{"label":"Pia","detail":"Delicate inner"}]},"mnemonic":{"title":"DAP","cue":"Dura · Arachnoid · Pia","explanation":"Recall meninges from outer to inner."},"goodToKnow":"Meningitis affects meninges; encephalitis affects brain tissue itself.","act":{"type":"choice","prompt":"What is the middle meningeal layer?","options":[{"label":"Arachnoid mater","correct":true,"feedback":"Correct. It lies between dura and pia."},{"label":"Pia mater","correct":false,"feedback":"Pia is the innermost layer."},{"label":"Dura mater","correct":false,"feedback":"Dura is the outermost layer."}]}},{"id":"l11-m4","chapter":null,"chapterSummary":null,"title":"Cranial-nerve anchors","highYield":"Learn tested functions before attempting all details at once.","teach":["Twelve pairs of cranial nerves arise from the brain. The trigeminal nerve is the largest and carries facial sensation plus chewing motor fibers. The hypoglossal nerve controls tongue movements; the vestibulocochlear nerve carries hearing and balance information.","The abducens nerve is motor and moves the eyeball laterally. The optic nerve carries visual information and exits the eye at the optic disc. Cranial nerves may be sensory, motor or mixed."],"keyPoints":["Trigeminal is the largest cranial nerve.","Hypoglossal moves tongue.","Vestibulocochlear serves hearing/balance.","Abducens moves the eye.","Optic carries vision."],"visual":{"title":"Five tested nerves","kind":"concept-map","items":[{"label":"V Trigeminal","detail":"Face and chewing"},{"label":"VI Abducens","detail":"Eye movement"},{"label":"VIII Vestibulocochlear","detail":"Hearing/balance"},{"label":"II Optic","detail":"Vision"},{"label":"XII Hypoglossal","detail":"Tongue"}]},"mnemonic":{"title":"TAVOH","cue":"Trigeminal · Abducens · Vestibulocochlear · Optic · Hypoglossal","explanation":"Use the tested anchors, then add the remaining nerves later."},"goodToKnow":"The lacrimal gland makes tears; it is a gland, not a cranial nerve.","act":{"type":"choice","prompt":"Which cranial nerve controls tongue movement?","options":[{"label":"Hypoglossal","correct":true,"feedback":"Correct. Cranial nerve XII is motor to the tongue."},{"label":"Trigeminal","correct":false,"feedback":"It is mainly facial sensation and chewing."},{"label":"Vestibulocochlear","correct":false,"feedback":"It serves hearing and balance."}]}},{"id":"protection-nerves-match","title":"Match it: Protective layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tough outer","Web-like middle","CSF","Delicate inner"],"items":[{"label":"Pia","category":3,"feedback":"Pia: Delicate inner"},{"label":"Subarachnoid space","category":2,"feedback":"Subarachnoid space: CSF"},{"label":"Arachnoid","category":1,"feedback":"Arachnoid: Web-like middle"},{"label":"Dura","category":0,"feedback":"Dura: Tough outer"}]}},{"id":"l11-m5","chapter":"Automatic control without a simple on/off switch","chapterSummary":"Somatic and autonomic systems serve different effectors; sympathetic and parasympathetic outputs rebalance organs.","title":"Somatic versus autonomic motor output","highYield":"The effector identifies the motor branch.","teach":["Somatic motor pathways control skeletal muscle. Autonomic pathways regulate smooth muscle, cardiac muscle and glands through a two-neuron chain with a peripheral ganglion.","Sympathetic output generally prepares the body for challenge; parasympathetic output supports routine, nonstressful functions such as digestion. Both divisions usually maintain some activity, so “fight or flight” and “rest and digest” are useful anchors rather than complete descriptions."],"keyPoints":["Somatic targets skeletal muscle.","Autonomic targets smooth/cardiac muscle and glands.","ANS uses a two-neuron chain.","Sympathetic mobilizes.","Parasympathetic maintains/restores."],"visual":{"title":"Motor branches","kind":"concept-map","items":[{"label":"Somatic","detail":"Skeletal muscle"},{"label":"Sympathetic","detail":"Mobilizing ANS"},{"label":"Parasympathetic","detail":"Restorative ANS"}]},"mnemonic":{"title":"Skeletal = somatic","cue":"Somatic starts with S, as does skeletal","explanation":"Autonomic covers organs and glands."},"goodToKnow":"The somatic system does not regulate internal organs; that function belongs mainly to autonomic motor pathways.","act":{"type":"choice","prompt":"Which division predominates during many normal nonstressful digestive activities?","options":[{"label":"Parasympathetic","correct":true,"feedback":"Correct. It supports many routine vegetative functions."},{"label":"Sympathetic","correct":false,"feedback":"It more often mobilizes resources during challenge."},{"label":"Somatic","correct":false,"feedback":"Somatic pathways target skeletal muscle."}]}},{"id":"l11-m6","chapter":null,"chapterSummary":null,"title":"Transmitters and organ effects","highYield":"Ganglionic and target synapses use different transmitter patterns.","teach":["Both autonomic divisions release acetylcholine from preganglionic neurons. Parasympathetic postganglionic neurons also typically release acetylcholine; most sympathetic postganglionic neurons release norepinephrine.","Effects depend on receptor type and target organ. Sympathetic activity can increase cardiac output and redirect resources, while parasympathetic activity can promote digestive motility and secretion. The divisions are coordinated, not moral opposites."],"keyPoints":["All preganglionic ANS neurons use ACh.","Parasympathetic target endings use ACh.","Most sympathetic target endings use norepinephrine.","Effect depends on receptor and organ."],"visual":{"title":"Two-neuron chain","kind":"concept-map","items":[{"label":"Preganglionic","detail":"ACh in both divisions"},{"label":"Autonomic ganglion","detail":"Second neuron begins"},{"label":"Parasympathetic target","detail":"Usually ACh"},{"label":"Sympathetic target","detail":"Usually norepinephrine"}]},"mnemonic":{"title":"A-A/N","cue":"ACh first; ACh parasympathetic, NE sympathetic at targets","explanation":"Track each synapse separately."},"goodToKnow":"Exceptions exist, so transmitter patterns should be learned as common organization rather than absolute rules.","act":{"type":"choice","prompt":"What transmitter do both ANS divisions use before the ganglion?","options":[{"label":"Acetylcholine","correct":true,"feedback":"Correct. Both preganglionic neuron types release ACh."},{"label":"Norepinephrine","correct":false,"feedback":"That is common at sympathetic target endings."},{"label":"Melatonin","correct":false,"feedback":"Melatonin is a pineal hormone."}]}},{"id":"autonomic-match","title":"Match it: Motor branches","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Skeletal muscle","Mobilizing ANS","Restorative ANS"],"items":[{"label":"Somatic","category":0,"feedback":"Somatic: Skeletal muscle"},{"label":"Sympathetic","category":1,"feedback":"Sympathetic: Mobilizing ANS"},{"label":"Parasympathetic","category":2,"feedback":"Parasympathetic: Restorative ANS"}]}},{"id":"l11-m7","chapter":"Vision: route light to neural signal","chapterSummary":"Follow light through transparent structures to photoreceptors, then out through the optic nerve.","title":"Layers and the light path","highYield":"The cornea and lens focus; the retina transduces.","teach":["The sclera is the tough outer coat; its transparent anterior portion is the cornea. The vascular middle layer includes choroid, ciliary body and iris. The iris controls pupil diameter and therefore light entry. The retina is the inner photosensitive layer.","Light passes through cornea, aqueous humor, pupil, lens and vitreous humor before reaching the retina. The lens changes shape for near or far focus. Neural signals leave at the optic disc, a region without photoreceptors."],"keyPoints":["Cornea is transparent outer layer.","Iris regulates pupil diameter.","Lens focuses light.","Retina contains photoreceptors.","Optic disc is the nerve exit."],"visual":{"title":"Light route","kind":"concept-map","items":[{"label":"Cornea","detail":"Initial refraction"},{"label":"Pupil/iris","detail":"Light amount"},{"label":"Lens","detail":"Focus"},{"label":"Vitreous","detail":"Transmits"},{"label":"Retina","detail":"Transduces"},{"label":"Optic nerve","detail":"Carries signal"}]},"mnemonic":{"title":"CPLRO","cue":"Cornea · Pupil · Lens · Retina · Optic nerve","explanation":"A simplified route to reconstruct under test pressure."},"goodToKnow":"The fovea centralis is specialized for high-acuity vision, whereas the optic disc creates a blind spot.","act":{"type":"choice","prompt":"Which layer contains the photosensitive cells?","options":[{"label":"Retina","correct":true,"feedback":"Correct. Rods and cones are retinal photoreceptors."},{"label":"Sclera","correct":false,"feedback":"The sclera is the tough outer coat."},{"label":"Iris","correct":false,"feedback":"The iris regulates pupil diameter."}]}},{"id":"l11-m8","chapter":null,"chapterSummary":null,"title":"Rods and cones","highYield":"Sensitivity and color discrimination trade off.","teach":["Rods are highly sensitive and support dim-light, noncolor vision. Cones require more light and support color vision and fine detail; they are densely concentrated in the fovea.","Photoreceptors pass signals through retinal circuits to ganglion-cell axons, which form the optic nerve. The brain then interprets the patterned activity; the eye does not produce a finished picture on its own."],"keyPoints":["Rods work well in dim light.","Rods do not provide color vision.","Cones support color and detail.","Cones need brighter light.","Optic nerve is formed by ganglion-cell axons."],"visual":{"title":"Photoreceptor contrast","kind":"concept-map","items":[{"label":"Rods","detail":"Dim, sensitive, no color"},{"label":"Cones","detail":"Bright, color, fine detail"},{"label":"Fovea","detail":"High cone density"}]},"mnemonic":{"title":"Rods roam at night","cue":"Rods = low light; cones = color","explanation":"Pair the functional contrasts."},"goodToKnow":"Vitamin A is involved in visual pigment physiology, but new night-vision problems should not be assumed to be dietary deficiency.","act":{"type":"choice","prompt":"Which photoreceptors produce color vision?","options":[{"label":"Cones","correct":true,"feedback":"Correct. Cones require more light and distinguish color."},{"label":"Rods","correct":false,"feedback":"Rods are sensitive in dim light but do not produce color vision."},{"label":"Ganglia","correct":false,"feedback":"Ganglion cells relay output rather than detect photons."}]}},{"id":"vision-match","title":"Match it: Photoreceptor contrast","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Dim, sensitive, no color","Bright, color, fine detail","High cone density"],"items":[{"label":"Rods","category":0,"feedback":"Rods: Dim, sensitive, no color"},{"label":"Cones","category":1,"feedback":"Cones: Bright, color, fine detail"},{"label":"Fovea","category":2,"feedback":"Fovea: High cone density"}]}},{"id":"l11-m9","chapter":"Hearing, balance and neurologic vocabulary","chapterSummary":"Mechanical vibration becomes neural activity; condition names point to different tissues and mechanisms.","title":"From sound wave to cochlea","highYield":"Outer ear collects, middle ear transfers, inner ear transduces.","teach":["Sound waves enter the auditory canal and vibrate the tympanic membrane. The malleus, incus and stapes transmit the vibration to the oval window, creating fluid waves in the cochlea that bend sensory hair cells.","Signals travel through the cochlear branch of the vestibulocochlear nerve. The semicircular ducts detect rotational movements, while vestibular structures respond to linear acceleration and head position."],"keyPoints":["Tympanic membrane vibrates first.","Ossicles transmit vibration.","Stapes contacts oval window.","Cochlear hair cells transduce sound.","Vestibular apparatus supports balance."],"visual":{"title":"Sound pathway","kind":"concept-map","items":[{"label":"Canal","detail":"Directs sound"},{"label":"Tympanic membrane","detail":"Vibrates"},{"label":"Ossicles","detail":"Amplify/transfer"},{"label":"Oval window","detail":"Starts inner-ear wave"},{"label":"Cochlea","detail":"Transduces"},{"label":"CN VIII","detail":"Carries signal"}]},"mnemonic":{"title":"TM-O-C","cue":"Tympanic membrane · Ossicles · Cochlea","explanation":"Use the three main stages, then add details."},"goodToKnow":"The auditory tube helps equalize middle-ear pressure; it is not the main sound receptor.","act":{"type":"choice","prompt":"What structure first vibrates when sound reaches the end of the ear canal?","options":[{"label":"Tympanic membrane","correct":true,"feedback":"Correct. It transfers sound energy to the ossicles."},{"label":"Oval window","correct":false,"feedback":"The stapes reaches it after the ossicles move."},{"label":"Retina","correct":false,"feedback":"That is part of the eye."}]}},{"id":"l11-m10","chapter":null,"chapterSummary":null,"title":"Keep neurologic terms distinct","highYield":"Tissue, mechanism and clinical course determine the label.","teach":["Meningitis is inflammation of the meninges; encephalitis is inflammation of brain tissue. Multiple sclerosis involves progressive demyelination in the CNS. Alzheimer disease produces progressive cognitive deterioration, while Parkinson disease is associated with movement-control circuitry.","A stroke results from interrupted or bleeding cerebral circulation; an aneurysm is an abnormal vessel-wall dilation. Epilepsy involves recurrent seizure tendency. These summaries support vocabulary only—diagnosis requires clinical evaluation."],"keyPoints":["Meningitis affects meninges.","Encephalitis affects brain tissue.","Multiple sclerosis involves CNS demyelination.","Stroke is a vascular brain event.","Aneurysm is vessel-wall dilation."],"visual":{"title":"Term sorter","kind":"concept-map","items":[{"label":"Membranes","detail":"Meningitis"},{"label":"Brain tissue inflammation","detail":"Encephalitis"},{"label":"Myelin","detail":"Multiple sclerosis"},{"label":"Blood flow","detail":"Stroke"},{"label":"Vessel wall","detail":"Aneurysm"}]},"mnemonic":{"title":"ME-MSA","cue":"Meningitis · Encephalitis · MS · Stroke · Aneurysm","explanation":"Attach each term to its primary tissue/mechanism."},"goodToKnow":"Similar symptoms can arise from very different processes, which is why pattern-matching is unsafe.","act":{"type":"choice","prompt":"Which term means inflammation of brain tissue?","options":[{"label":"Encephalitis","correct":true,"feedback":"Correct. Encephalo- refers to brain."},{"label":"Meningitis","correct":false,"feedback":"That affects the meninges."},{"label":"Aneurysm","correct":false,"feedback":"That is vessel-wall dilation."}]}},{"id":"hearing-balance-match","title":"Match it: Term sorter","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Meningitis","Encephalitis","Multiple sclerosis","Stroke","Aneurysm"],"items":[{"label":"Brain tissue inflammation","category":1,"feedback":"Brain tissue inflammation: Encephalitis"},{"label":"Vessel wall","category":4,"feedback":"Vessel wall: Aneurysm"},{"label":"Myelin","category":2,"feedback":"Myelin: Multiple sclerosis"},{"label":"Membranes","category":0,"feedback":"Membranes: Meningitis"},{"label":"Blood flow","category":3,"feedback":"Blood flow: Stroke"}]}}],"flashcards":[{"front":"Longitudinal fissure","back":"Deep groove separating the cerebral hemispheres."},{"front":"Gyri","back":"Raised folds of the cerebral cortex."},{"front":"Cerebellum","back":"Region coordinating balance and complex skeletal movement."},{"front":"Reticular formation","back":"Brainstem network involved in arousal and consciousness."},{"front":"Arachnoid mater","back":"Middle meningeal layer."},{"front":"Cerebrospinal fluid","back":"Fluid that cushions and supports the CNS."},{"front":"Trigeminal nerve","back":"Largest cranial nerve; facial sensation and chewing functions."},{"front":"Hypoglossal nerve","back":"Motor nerve controlling tongue movement."},{"front":"Retina","back":"Innermost eye layer containing photoreceptors."},{"front":"Cones","back":"Photoreceptors for color and fine detail in brighter light."},{"front":"Tympanic membrane","back":"Membrane vibrated by incoming sound waves."},{"front":"Encephalitis","back":"Inflammation of brain tissue."},{"front":"Stroke","back":"Brain injury from interrupted or bleeding cerebral circulation."},{"front":"Aneurysm","back":"Abnormal dilation of a blood-vessel wall."}],"quiz":[],"caseStudy":{"title":"One breakfast, many neural tasks","scenario":"An older adult after a clinician-diagnosed stroke has visual-field difficulty, reduced hand control and trouble following a fast conversation.","prompts":["Name the broad brain and sensory systems involved without localizing the lesion.","Identify accommodations that could make counselling accessible.","Explain the roles of cranial nerves and somatic motor pathways in eating.","List issues that require team-based assessment, such as swallowing safety."],"takeaway":"Anatomy helps anticipate functional demands and design access; it does not replace neurologic or swallowing assessment."}},{"n":12,"title":"The Endocrine System","kicker":"Distinguish endocrine from exocrine signaling and compare major hormone classes.","duration":"90–110 minutes","steps":[{"id":"l12-m1","chapter":"How hormones communicate","chapterSummary":"Hormones travel widely but act only where the right receptor and cellular machinery are present.","title":"Endocrine versus exocrine","highYield":"Ductless endocrine glands release to blood; exocrine glands use ducts.","teach":["Endocrine glands secrete hormones into interstitial fluid and then the bloodstream. Hormones circulate throughout the body, but only target cells with suitable receptors respond. Exocrine glands send products through ducts to a surface or lumen.","Neural and endocrine control interact: neural signals are typically rapid and targeted, whereas hormonal signals may begin more slowly and persist longer. The hypothalamus is a central bridge between the systems."],"keyPoints":["Endocrine glands are ductless.","Hormones enter circulation.","Receptors create target specificity.","Exocrine glands use ducts.","Hypothalamus links nervous and endocrine control."],"visual":{"title":"Signal comparison","kind":"concept-map","items":[{"label":"Endocrine","detail":"Blood-borne hormone"},{"label":"Target cell","detail":"Matching receptor"},{"label":"Exocrine","detail":"Duct to surface/lumen"},{"label":"Neural","detail":"Rapid directed signal"}]},"mnemonic":{"title":"ENDO enters blood","cue":"Endocrine goes inward to circulation; exocrine exits by duct","explanation":"Use route, not product name alone."},"goodToKnow":"The pancreas has both endocrine islets and exocrine digestive tissue.","act":{"type":"choice","prompt":"Which statement describes an endocrine gland?","options":[{"label":"It releases hormone into circulation without a duct.","correct":true,"feedback":"Correct. Endocrine glands are ductless."},{"label":"It always releases through a duct.","correct":false,"feedback":"That describes exocrine secretion."},{"label":"It acts on every cell equally.","correct":false,"feedback":"Only receptor-bearing target cells respond."}]}},{"id":"l12-m2","chapter":null,"chapterSummary":null,"title":"Hormone chemistry and receptors","highYield":"Protein, steroid and modified amino-acid hormones signal differently.","teach":["Protein and peptide hormones, including insulin and growth hormone, are water soluble and generally bind membrane receptors, activating internal second-messenger pathways. Steroid hormones, including cortisol and testosterone, are lipid soluble and bind intracellular receptors that influence gene expression.","Modified amino-acid hormones include epinephrine and thyroid hormones. Their behavior depends on structure: catecholamines use membrane receptors, while thyroid hormone acts more like a lipid-soluble signal."],"keyPoints":["Insulin and GH are protein hormones.","Cortisol and testosterone are steroids.","Epinephrine is a modified amino acid.","Water-soluble hormones use membrane receptors.","Steroids use intracellular receptors."],"visual":{"title":"Hormone classes","kind":"concept-map","items":[{"label":"Protein/peptide","detail":"Insulin, GH"},{"label":"Steroid","detail":"Cortisol, testosterone"},{"label":"Modified amino acid","detail":"Epinephrine, thyroid hormone"}]},"mnemonic":{"title":"PSA","cue":"Protein · Steroid · Amino-acid derivative","explanation":"Class first, then attach examples."},"goodToKnow":"A hormone’s chemistry helps predict receptor location, not whether it is “stronger.”","act":{"type":"choice","prompt":"Which pair contains steroid hormones?","options":[{"label":"Cortisol and testosterone","correct":true,"feedback":"Correct. Both derive from cholesterol."},{"label":"Insulin and growth hormone","correct":false,"feedback":"Those are protein hormones."},{"label":"Epinephrine and insulin","correct":false,"feedback":"They belong to different classes."}]}},{"id":"hormone-logic-match","title":"Match it: Signal comparison","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Blood-borne hormone","Matching receptor","Duct to surface/lumen","Rapid directed signal"],"items":[{"label":"Neural","category":3,"feedback":"Neural: Rapid directed signal"},{"label":"Exocrine","category":2,"feedback":"Exocrine: Duct to surface/lumen"},{"label":"Target cell","category":1,"feedback":"Target cell: Matching receptor"},{"label":"Endocrine","category":0,"feedback":"Endocrine: Blood-borne hormone"}]}},{"id":"l12-m3","chapter":"Feedback and the pituitary hub","chapterSummary":"Hormone axes are regulated loops, not one-way chains.","title":"Negative feedback","highYield":"The response reduces the original drive and stabilizes a variable.","teach":["In negative feedback, rising hormone or target-variable levels inhibit further secretion from upstream sources. For example, hypothalamic TRH stimulates pituitary TSH, which stimulates thyroid hormone; adequate thyroid hormone then reduces TRH and TSH drive.","Positive feedback amplifies a process for a limited event. Oxytocin-driven uterine contractions during childbirth are a classic example: contraction promotes additional oxytocin signaling until birth ends the loop."],"keyPoints":["Negative feedback opposes change.","Rising end hormone can inhibit upstream signals.","TRH → TSH → thyroid hormone.","Oxytocin can participate in positive feedback."],"visual":{"title":"Feedback loop","kind":"concept-map","items":[{"label":"Hypothalamus","detail":"Releasing hormone"},{"label":"Anterior pituitary","detail":"Tropic hormone"},{"label":"Target gland","detail":"End hormone"},{"label":"Feedback","detail":"End hormone reduces upstream drive"}]},"mnemonic":{"title":"TRH tells TSH","cue":"TRH from hypothalamus triggers pituitary TSH","explanation":"Then thyroid hormone feeds back."},"goodToKnow":"Feedback is dynamic; a single hormone measurement is interpreted with timing and related signals.","act":{"type":"choice","prompt":"What happens in endocrine negative feedback?","options":[{"label":"A rising output inhibits continued secretion upstream.","correct":true,"feedback":"Correct. The loop resists further change."},{"label":"Every hormone rises without limit.","correct":false,"feedback":"That would not stabilize the system."},{"label":"A duct carries hormone to the target.","correct":false,"feedback":"Endocrine hormones circulate without ducts."}]}},{"id":"l12-m4","chapter":null,"chapterSummary":null,"title":"Anterior and posterior pituitary","highYield":"One lobe synthesizes several hormones; the other stores and releases hypothalamic hormones.","teach":["The pituitary, or hypophysis, has two major lobes. The anterior pituitary produces growth hormone, TSH, ACTH, FSH, LH, prolactin and MSH. GH supports growth and metabolism; MSH can increase pigmentation; LH helps trigger ovulation; prolactin supports milk production after birth.","The posterior pituitary stores and releases oxytocin and antidiuretic hormone made in the hypothalamus. Oxytocin supports uterine contractions and milk ejection; ADH promotes water conservation by the kidneys."],"keyPoints":["Pituitary is also called hypophysis.","Anterior lobe makes GH, TSH, ACTH, FSH, LH, prolactin, MSH.","LH triggers ovulation.","Prolactin supports milk production.","Posterior lobe releases ADH and oxytocin."],"visual":{"title":"Pituitary split","kind":"concept-map","items":[{"label":"Anterior","detail":"Makes multiple tropic/direct hormones"},{"label":"Posterior","detail":"Stores/releases hypothalamic ADH + oxytocin"},{"label":"LH","detail":"Ovulation"},{"label":"Prolactin","detail":"Milk production"},{"label":"MSH","detail":"Pigmentation"}]},"mnemonic":{"title":"FLAT PiG + M","cue":"FSH · LH · ACTH · TSH · Prolactin · GH · MSH","explanation":"A common checklist for anterior-pituitary hormones."},"goodToKnow":"Milk production (prolactin) and milk ejection (oxytocin) are different processes.","act":{"type":"choice","prompt":"Which anterior-pituitary hormone triggers ovulation?","options":[{"label":"Luteinizing hormone","correct":true,"feedback":"Correct. The LH surge triggers ovulation."},{"label":"Oxytocin","correct":false,"feedback":"Oxytocin is released from the posterior pituitary."},{"label":"Aldosterone","correct":false,"feedback":"Aldosterone is an adrenal-cortex hormone."}]}},{"id":"feedback-pituitary-match","title":"Match it: Feedback loop","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Releasing hormone","Tropic hormone","End hormone","End hormone reduces upstream drive"],"items":[{"label":"Feedback","category":3,"feedback":"Feedback: End hormone reduces upstream drive"},{"label":"Target gland","category":2,"feedback":"Target gland: End hormone"},{"label":"Anterior pituitary","category":1,"feedback":"Anterior pituitary: Tropic hormone"},{"label":"Hypothalamus","category":0,"feedback":"Hypothalamus: Releasing hormone"}]}},{"id":"l12-m5","chapter":"Metabolic rate and calcium balance","chapterSummary":"The thyroid and parathyroids regulate different variables despite their close location.","title":"Thyroid hormones and iodine","highYield":"Thyroid hormone supports metabolic activity; calcitonin participates in calcium regulation.","teach":["TSH stimulates the thyroid to produce T3 and T4, hormones that increase metabolic activity in many tissues. Iodine is required to build these hormones. Inadequate iodine can contribute to thyroid enlargement, called goiter, though goiter has more than one possible cause.","Excess thyroid-hormone production is associated with hyperthyroid states such as Graves disease. Severe adult hypothyroid patterns were historically described with myxedema, including fluid accumulation in subcutaneous tissues; diagnosis depends on clinical and laboratory evaluation."],"keyPoints":["TSH stimulates thyroid.","T3/T4 require iodine.","Goiter means enlarged thyroid.","Graves disease is associated with excess thyroid activity.","Myxedema is a severe hypothyroid pattern."],"visual":{"title":"Thyroid chain","kind":"concept-map","items":[{"label":"TRH","detail":"Hypothalamus"},{"label":"TSH","detail":"Anterior pituitary"},{"label":"T3/T4","detail":"Thyroid"},{"label":"Iodine","detail":"Hormone substrate"},{"label":"Feedback","detail":"T3/T4 reduce upstream drive"}]},"mnemonic":{"title":"T3/T4 need I","cue":"Thyroid hormone requires iodine","explanation":"Adequacy matters; more is not automatically better."},"goodToKnow":"Excess iodine can also disrupt thyroid function; avoid treating an assumed deficiency without assessment.","act":{"type":"choice","prompt":"What dietary element is required to synthesize T3 and T4?","options":[{"label":"Iodine","correct":true,"feedback":"Correct. Iodine is built into thyroid hormones."},{"label":"Iron only","correct":false,"feedback":"Iron has many roles but is not the defining thyroid-hormone element."},{"label":"Calcium","correct":false,"feedback":"Calcium is regulated by other endocrine pathways."}]}},{"id":"l12-m6","chapter":null,"chapterSummary":null,"title":"Parathyroid hormone and calcitonin","highYield":"Low blood calcium activates PTH; calcitonin generally opposes that direction.","teach":["When blood calcium falls, parathyroid hormone (PTH) raises it by acting on bone and kidneys and by supporting vitamin-D activation, which increases intestinal calcium absorption. The net effect is to defend extracellular calcium needed for nerve and muscle function.","Calcitonin from thyroid C cells tends to lower blood calcium by discouraging bone resorption, although its role in adult moment-to-moment regulation is smaller than PTH’s. Excess PTH can demineralize and deform bone over time."],"keyPoints":["Parathyroids release PTH.","PTH responds to low blood calcium.","PTH supports renal retention and vitamin-D activation.","Calcitonin tends to lower blood calcium.","Chronic excess PTH can weaken bone."],"visual":{"title":"Calcium directions","kind":"concept-map","items":[{"label":"Low Ca²⁺","detail":"PTH rises"},{"label":"Kidney","detail":"Retain Ca²⁺/activate vitamin D"},{"label":"Intestine","detail":"Absorb more with active vitamin D"},{"label":"Bone","detail":"PTH can increase release"},{"label":"Calcitonin","detail":"Opposing direction"}]},"mnemonic":{"title":"PTH Pulls calcium To Higher blood levels","cue":"PTH raises extracellular calcium","explanation":"Attach the direction before the mechanisms."},"goodToKnow":"Blood calcium is tightly controlled, so a normal blood value does not by itself prove optimal skeletal calcium stores.","act":{"type":"choice","prompt":"Which gland responds when blood calcium is too low?","options":[{"label":"Parathyroid","correct":true,"feedback":"Correct. It releases PTH."},{"label":"Pineal","correct":false,"feedback":"The pineal releases melatonin."},{"label":"Pituitary only","correct":false,"feedback":"It is not the direct calcium-sensing gland in this pathway."}]}},{"id":"thyroid-calcium-match","title":"Match it: Thyroid chain","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hypothalamus","Anterior pituitary","Thyroid","Hormone substrate","T3/T4 reduce upstream drive"],"items":[{"label":"TSH","category":1,"feedback":"TSH: Anterior pituitary"},{"label":"Feedback","category":4,"feedback":"Feedback: T3/T4 reduce upstream drive"},{"label":"T3/T4","category":2,"feedback":"T3/T4: Thyroid"},{"label":"TRH","category":0,"feedback":"TRH: Hypothalamus"},{"label":"Iodine","category":3,"feedback":"Iodine: Hormone substrate"}]}},{"id":"l12-m7","chapter":"Adrenal layers and stress responses","chapterSummary":"Cortex and medulla have different origins, hormones and time courses.","title":"Adrenal cortex zones","highYield":"Mineral balance, glucose/stress and androgens map from outer to inner cortex.","teach":["The adrenal cortex produces steroid hormones. Its outer zona glomerulosa makes mineralocorticoids such as aldosterone, which promote sodium retention and potassium excretion. The middle zona fasciculata makes glucocorticoids such as cortisol, which influence metabolism and stress adaptation.","The inner zona reticularis produces adrenal androgens. Too little adrenal-cortex output is associated with Addison disease; chronic excess, especially cortisol, with Cushing syndrome. These are clinical diagnoses, not conclusions from body shape or fatigue alone."],"keyPoints":["Cortex makes steroids.","Outer cortex makes mineralocorticoids.","Cortisol is a glucocorticoid.","Inner cortex makes androgens.","Cushing = excess cortex hormones; Addison = deficiency."],"visual":{"title":"Cortex layers","kind":"concept-map","items":[{"label":"Glomerulosa","detail":"Salt/mineralocorticoids"},{"label":"Fasciculata","detail":"Sugar/glucocorticoids"},{"label":"Reticularis","detail":"Sex/androgens"}]},"mnemonic":{"title":"GFR: Salt, Sugar, Sex","cue":"Glomerulosa · Fasciculata · Reticularis","explanation":"Move outer to inner with the three S words."},"goodToKnow":"Cortisol has normal essential functions; “cortisol is bad” is biologically inaccurate.","act":{"type":"choice","prompt":"What does the outer adrenal cortex chiefly secrete?","options":[{"label":"Mineralocorticoids","correct":true,"feedback":"Correct. Aldosterone is the key example."},{"label":"Melatonin","correct":false,"feedback":"That comes from the pineal."},{"label":"Insulin","correct":false,"feedback":"That comes from pancreatic beta cells."}]}},{"id":"l12-m8","chapter":null,"chapterSummary":null,"title":"Adrenal medulla","highYield":"Epinephrine and norepinephrine rapidly support fight-or-flight physiology.","teach":["The adrenal medulla is functionally linked to the sympathetic nervous system. Its chromaffin cells release epinephrine and norepinephrine into blood, extending a rapid challenge response throughout the body.","These catecholamines can increase cardiac activity, redirect blood flow and help mobilize fuel. They are modified amino-acid hormones, unlike the steroid hormones produced by the cortex."],"keyPoints":["Medulla releases epinephrine and norepinephrine.","These are fight-or-flight hormones.","They are modified amino-acid derivatives.","Medulla is linked to sympathetic output.","Cortex hormones are steroids."],"visual":{"title":"One gland, two systems","kind":"concept-map","items":[{"label":"Cortex","detail":"Slower steroid signals"},{"label":"Medulla","detail":"Rapid catecholamines"},{"label":"Epinephrine/NE","detail":"Fight-or-flight"}]},"mnemonic":{"title":"Medulla = emergency middle","cue":"The inner medulla releases rapid challenge signals","explanation":"Contrast it with the steroid cortex."},"goodToKnow":"A short stress response is adaptive; chronic symptoms have many possible contributors.","act":{"type":"choice","prompt":"Which pair is released by the adrenal medulla?","options":[{"label":"Epinephrine and norepinephrine","correct":true,"feedback":"Correct. They are catecholamine fight-or-flight hormones."},{"label":"Insulin and glucagon","correct":false,"feedback":"Those are pancreatic hormones."},{"label":"T3 and T4","correct":false,"feedback":"Those are thyroid hormones."}]}},{"id":"adrenal-stress-match","title":"Match it: Cortex layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Salt/mineralocorticoids","Sugar/glucocorticoids","Sex/androgens"],"items":[{"label":"Glomerulosa","category":0,"feedback":"Glomerulosa: Salt/mineralocorticoids"},{"label":"Fasciculata","category":1,"feedback":"Fasciculata: Sugar/glucocorticoids"},{"label":"Reticularis","category":2,"feedback":"Reticularis: Sex/androgens"}]}},{"id":"l12-m9","chapter":"Fuel, reproduction and biological time","chapterSummary":"Pancreas, gonads and pineal gland regulate distinct but interacting variables.","title":"Insulin and glucagon","highYield":"Pancreatic islets defend blood glucose in opposite directions.","teach":["Beta cells release insulin when blood glucose rises. Insulin supports glucose uptake in responsive tissues and storage, so blood glucose falls. Alpha cells release glucagon when glucose is low; glucagon stimulates the liver to break down glycogen and produce/release glucose.","Diabetes mellitus involves inadequate insulin production, impaired insulin action, or both. Polydipsia means excessive thirst; polyuria is excessive urination; polyphagia is excessive hunger. These signs require assessment rather than self-diagnosis."],"keyPoints":["Beta cells make insulin.","Alpha cells make glucagon.","Insulin lowers circulating glucose.","Glucagon raises it through liver action.","Polydipsia means excessive thirst."],"visual":{"title":"Glucose seesaw","kind":"concept-map","items":[{"label":"High glucose","detail":"Insulin from beta cells"},{"label":"Storage/uptake","detail":"Glucose falls"},{"label":"Low glucose","detail":"Glucagon from alpha cells"},{"label":"Liver output","detail":"Glucose rises"}]},"mnemonic":{"title":"I lowers; G gives","cue":"Insulin lowers blood glucose; glucagon gives glucose back","explanation":"Use the directional contrast."},"goodToKnow":"Insulin and glucagon often act together across meals and fasting rather than as isolated switches.","act":{"type":"choice","prompt":"Which pancreatic cells secrete insulin?","options":[{"label":"Beta cells","correct":true,"feedback":"Correct. Beta cells are the insulin source."},{"label":"Alpha cells","correct":false,"feedback":"Alpha cells secrete glucagon."},{"label":"Oxyphil cells","correct":false,"feedback":"Those are found in parathyroid tissue."}]}},{"id":"l12-m10","chapter":null,"chapterSummary":null,"title":"Gonads, prolactin and melatonin","highYield":"Reproductive signals and circadian timing complete the endocrine map.","teach":["The ovaries produce estrogens and progesterone; testes produce testosterone. FSH and LH from the anterior pituitary regulate gonadal function, with LH triggering ovulation. Testosterone and related anabolic steroids have androgenic and anabolic effects; nonmedical use carries risks.","Prolactin supports milk production after childbirth. The pineal gland secretes melatonin, which helps regulate circadian rhythms. Seasonal changes in light can influence melatonin timing, but seasonal affective disorder is more complex than simply “too much melatonin.”"],"keyPoints":["FSH/LH regulate gonads.","LH triggers ovulation.","Prolactin supports milk production.","Pineal gland makes melatonin.","Melatonin helps set circadian rhythms."],"visual":{"title":"Reproduction and rhythm","kind":"concept-map","items":[{"label":"Gonads","detail":"Sex steroids"},{"label":"FSH/LH","detail":"Pituitary control"},{"label":"Prolactin","detail":"Milk production"},{"label":"Pineal","detail":"Melatonin"},{"label":"Melatonin","detail":"Circadian timing"}]},"mnemonic":{"title":"PLM","cue":"Prolactin · LH · Melatonin","explanation":"Milk production, ovulation, biological night."},"goodToKnow":"Anabolic steroids are variants related to testosterone; they are not the same category as stimulants or depressants.","act":{"type":"choice","prompt":"Which hormone helps regulate circadian rhythms?","options":[{"label":"Melatonin","correct":true,"feedback":"Correct. It is secreted by the pineal gland."},{"label":"Aldosterone","correct":false,"feedback":"That regulates sodium and potassium handling."},{"label":"Prolactin","correct":false,"feedback":"That supports milk production."}]}},{"id":"fuel-reproduction-rhythm-match","title":"Match it: Glucose seesaw","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Insulin from beta cells","Glucose falls","Glucagon from alpha cells","Glucose rises"],"items":[{"label":"Liver output","category":3,"feedback":"Liver output: Glucose rises"},{"label":"Low glucose","category":2,"feedback":"Low glucose: Glucagon from alpha cells"},{"label":"Storage/uptake","category":1,"feedback":"Storage/uptake: Glucose falls"},{"label":"High glucose","category":0,"feedback":"High glucose: Insulin from beta cells"}]}}],"flashcards":[{"front":"Endocrine gland","back":"Ductless gland that releases hormone into circulation."},{"front":"Protein hormone","back":"Water-soluble hormone such as insulin or growth hormone."},{"front":"Steroid hormone","back":"Cholesterol-derived hormone such as cortisol or testosterone."},{"front":"Negative feedback","back":"Rising output reduces continued upstream secretion."},{"front":"Hypophysis","back":"Another name for the pituitary gland."},{"front":"Luteinizing hormone","back":"Anterior-pituitary hormone whose surge triggers ovulation."},{"front":"Prolactin","back":"Hormone supporting milk production."},{"front":"Goiter","back":"Enlargement of the thyroid gland."},{"front":"Parathyroid hormone","back":"Hormone that raises blood calcium when it falls."},{"front":"Mineralocorticoid","back":"Adrenal-cortex hormone class regulating electrolytes; aldosterone is the example."},{"front":"Beta cell","back":"Pancreatic islet cell that releases insulin."},{"front":"Glucagon","back":"Pancreatic hormone that raises blood glucose through liver action."},{"front":"Polydipsia","back":"Excessive thirst."},{"front":"Melatonin","back":"Pineal hormone involved in circadian timing."}],"quiz":[],"caseStudy":{"title":"After a meal: a coordinated endocrine story","scenario":"A learner says one high-carbohydrate meal permanently “breaks hormones” and that every tired feeling must be high cortisol.","prompts":["Trace insulin and glucagon around a meal and between meals.","Explain negative feedback using one pituitary axis.","Contrast adrenal cortex and medulla signals.","Identify why symptoms alone cannot establish an endocrine diagnosis.","Offer scope-safe nutrition education without fear-based claims."],"takeaway":"Endocrine regulation is dynamic, receptor-specific and feedback controlled; nutrition matters within a larger physiologic and clinical context."}},{"n":13,"title":"The Blood","kicker":"Explain how plasma and formed elements support transport, regulation, and protection.","duration":"70–90 minutes","steps":[{"id":"l13-m1","chapter":"Build the blood map","chapterSummary":"Start with the liquid matrix, formed elements, and where blood cells come from.","title":"Blood is a moving connective tissue","highYield":"Blood transports materials, stabilizes the internal environment, and limits harm; it is more than a carrier for oxygen.","teach":["Blood is classified as connective tissue because living cells are suspended in an extracellular matrix called plasma. Its transport work includes respiratory gases, nutrients, hormones, heat, and wastes. Its regulatory work supports temperature, fluid balance, and acid–base conditions, while its protective work includes immune defence and hemostasis.","A useful first distinction is concentration versus total amount. A laboratory value reports what is present in a sample under specific conditions; hydration, timing, illness, altitude, and many other factors may influence interpretation. One result is evidence to place in context, not a stand-alone diagnosis."],"keyPoints":["Plasma is the liquid matrix.","Formed elements are erythrocytes, leukocytes, and platelets.","Transport, regulation, and protection overlap.","Concentration and total body amount are not identical."],"visual":{"title":"Three jobs of blood","kind":"map","items":[{"label":"Transport","detail":"Gases, nutrients, hormones, heat, and wastes"},{"label":"Regulate","detail":"Temperature, fluid distribution, and pH"},{"label":"Protect","detail":"Immune activity and control of blood loss"}]},"mnemonic":{"title":"TRP","cue":"Transport · Regulate · Protect","explanation":"Use TRP to recall the three broad functions before naming individual cells."},"goodToKnow":"Plasma volume can change more quickly than red-cell mass, so a concentration can shift even when the total number of cells has not changed by the same proportion.","act":{"type":"choice","prompt":"Which statement best describes blood as a tissue?","options":[{"label":"Cells suspended in a liquid extracellular matrix that supports transport, regulation, and protection","correct":true,"feedback":"Correct. Plasma is the matrix and the formed elements perform specialized work."},{"label":"A fluid made only of water and dissolved nutrients","correct":false,"feedback":"Plasma contains water and dissolved substances, but blood also contains cells and platelets."},{"label":"An organ whose only function is oxygen transport","correct":false,"feedback":"Oxygen transport matters, but blood also regulates and protects."}]}},{"id":"l13-m2","chapter":null,"chapterSummary":null,"title":"Plasma and formed elements tell different parts of the story","highYield":"Plasma carries dissolved materials; formed elements perform cell-based transport, defence, and hemostasis.","teach":["Plasma is mostly water, but its proteins and dissolved solutes make it physiologically active. Albumin contributes to fluid distribution, globulins include transport and immune proteins, and fibrinogen is a precursor used in clot formation. Electrolytes, nutrients, gases, hormones, and wastes travel within this medium.","The formed elements include erythrocytes, several leukocyte families, and platelets. A complete blood count separates these populations because a total blood volume cannot show which component has changed. Reading the compartments first prevents the common error of treating every abnormal blood result as the same problem."],"keyPoints":["Albumin influences oncotic pressure and transport.","Fibrinogen participates in clot formation.","Erythrocytes are the most numerous formed element.","Platelets are cell fragments, not complete cells."],"visual":{"title":"What is in blood?","kind":"layers","items":[{"label":"Plasma","detail":"Water, proteins, electrolytes, nutrients, hormones, gases, and wastes"},{"label":"Buffy coat","detail":"Leukocytes and platelets; a small fraction by volume"},{"label":"Erythrocytes","detail":"The dominant cellular fraction"}]},"mnemonic":{"title":"P-F-E","cue":"Plasma · Formed elements · Examine separately","explanation":"Separate the fluid and cellular compartments before interpreting change."},"goodToKnow":"Serum is the fluid remaining after clotting factors used in coagulation have been removed from plasma.","act":{"type":"choice","prompt":"Which plasma protein is directly converted into a fibrin mesh during coagulation?","options":[{"label":"Fibrinogen","correct":true,"feedback":"Correct. Coagulation converts soluble fibrinogen into insoluble fibrin strands."},{"label":"Hemoglobin","correct":false,"feedback":"Hemoglobin is inside erythrocytes and transports respiratory gases."},{"label":"Keratin","correct":false,"feedback":"Keratin is a structural protein of skin, hair, and nails."}]}},{"id":"composition-match","title":"Match it: Three jobs of blood","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Gases, nutrients, hormones, heat, and wastes","Temperature, fluid distribution, and pH","Immune activity and control of blood loss"],"items":[{"label":"Transport","category":0,"feedback":"Transport: Gases, nutrients, hormones, heat, and wastes"},{"label":"Regulate","category":1,"feedback":"Regulate: Temperature, fluid distribution, and pH"},{"label":"Protect","category":2,"feedback":"Protect: Immune activity and control of blood loss"}]}},{"id":"l13-m3","chapter":"Follow blood-cell life cycles","chapterSummary":"Connect hematopoiesis, erythrocyte design, and leukocyte specialization.","title":"Hematopoiesis is a regulated production system","highYield":"Blood cells arise from stem-cell lineages in red bone marrow and are produced in response to changing needs.","teach":["Hematopoiesis begins with multipotent stem cells in red bone marrow. Through branching lineages, these precursors become erythrocytes, leukocytes, or platelet-producing megakaryocytes. Growth factors and hormones regulate the rate and direction of production rather than all cell types being made equally at all times.","Reduced oxygen delivery stimulates the kidneys to increase erythropoietin signalling, which supports erythrocyte production in marrow. Production also requires raw materials such as amino acids, iron, folate, and vitamin B12. A nutrient is necessary for the pathway, but its necessity does not prove that every low blood count is caused by diet."],"keyPoints":["Red bone marrow is the main production site.","Stem cells branch into specialized lineages.","Kidney oxygen sensing influences erythropoietin.","Adequate substrates do not replace investigation of blood loss, inflammation, or marrow disease."],"visual":{"title":"Production pathway","kind":"flow","items":[{"label":"Stem cell","detail":"Self-renewing marrow precursor"},{"label":"Lineage signals","detail":"Direct development toward red cells, white cells, or platelets"},{"label":"Maturation","detail":"Cells acquire their specialized structure and function"},{"label":"Release","detail":"Mature elements enter circulation"}]},"mnemonic":{"title":"M-S-M-R","cue":"Marrow · Signal · Mature · Release","explanation":"Trace a blood cell from origin to circulation."},"goodToKnow":"Erythropoietin is a signal, not an iron source; marrow still needs appropriate substrates and functional tissue.","act":{"type":"choice","prompt":"Which sequence best represents regulated erythrocyte production?","options":[{"label":"Low oxygen signal → kidney erythropoietin → marrow response → mature erythrocytes","correct":true,"feedback":"Correct. The kidney signal and marrow response are distinct steps."},{"label":"Dietary iron → immediate conversion into circulating red cells","correct":false,"feedback":"Iron is a substrate, but erythrocyte production requires regulated marrow maturation over time."},{"label":"Platelets → leukocytes → erythrocytes","correct":false,"feedback":"These are separate differentiated products of precursor lineages."}]}},{"id":"l13-m4","chapter":null,"chapterSummary":null,"title":"Erythrocyte shape supports gas transport","highYield":"A biconcave, flexible, nucleus-free erythrocyte devotes space to hemoglobin and moves through tiny capillaries.","teach":["Mature erythrocytes are flexible biconcave discs. The shape increases surface area relative to volume and shortens diffusion distance. Loss of the nucleus and most organelles creates room for hemoglobin, but it also limits repair and protein synthesis, so erythrocytes have a finite life span.","Hemoglobin binds oxygen reversibly and participates in carbon-dioxide and acid–base transport. Old or damaged erythrocytes are removed mainly by macrophages in the spleen and liver; useful components such as iron can be recycled, while heme is processed into pigments excreted through bile."],"keyPoints":["Biconcave shape improves exchange area.","Flexibility supports capillary passage.","Hemoglobin carries oxygen reversibly.","Iron can be recycled after erythrocyte breakdown."],"visual":{"title":"Structure serves function","kind":"comparison","items":[{"label":"Biconcave disc","detail":"Large surface area and short diffusion path"},{"label":"Flexible membrane","detail":"Deforms through narrow capillaries"},{"label":"No nucleus","detail":"More space for hemoglobin but little repair capacity"},{"label":"Hemoglobin","detail":"Binds and releases oxygen according to local conditions"}]},"mnemonic":{"title":"SHAPE","cue":"Surface · Hemoglobin · Adaptable · Passage · Exchange","explanation":"SHAPE links erythrocyte anatomy to oxygen delivery."},"goodToKnow":"Hemoglobin concentration, erythrocyte number, and hematocrit are related measurements but are not interchangeable.","act":{"type":"choice","prompt":"Why does the mature erythrocyte lack a nucleus?","options":[{"label":"It allows more internal space for hemoglobin, while limiting the cell's ability to repair itself","correct":true,"feedback":"Correct. The adaptation improves carrying capacity but shortens functional life."},{"label":"It enables the cell to divide rapidly in the bloodstream","correct":false,"feedback":"Mature erythrocytes do not divide."},{"label":"It lets oxygen dissolve only in plasma","correct":false,"feedback":"Most oxygen is carried bound to hemoglobin inside erythrocytes."}]}},{"id":"cells-order","title":"Put it in order: Production pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Stem cell","detail":"Self-renewing marrow precursor"},{"label":"Lineage signals","detail":"Direct development toward red cells, white cells, or platelets"},{"label":"Maturation","detail":"Cells acquire their specialized structure and function"},{"label":"Release","detail":"Mature elements enter circulation"}]}},{"id":"cells-match","title":"Match it: Structure serves function","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Large surface area and short diffusion path","Deforms through narrow capillaries","More space for hemoglobin but little repair capacity","Binds and releases oxygen according to local conditions"],"items":[{"label":"Hemoglobin","category":3,"feedback":"Hemoglobin: Binds and releases oxygen according to local conditions"},{"label":"No nucleus","category":2,"feedback":"No nucleus: More space for hemoglobin but little repair capacity"},{"label":"Flexible membrane","category":1,"feedback":"Flexible membrane: Deforms through narrow capillaries"},{"label":"Biconcave disc","category":0,"feedback":"Biconcave disc: Large surface area and short diffusion path"}]}},{"id":"l13-m5","chapter":"Differentiate defence cells","chapterSummary":"Use cell roles—not colour or a single count—to distinguish leukocytes and platelets.","title":"Leukocytes divide defence work","highYield":"Leukocyte families specialize in rapid ingestion, inflammatory signalling, targeted immunity, and cleanup.","teach":["Neutrophils are rapid phagocytic responders, especially in many bacterial infections. Eosinophils participate in responses to parasites and allergic inflammation, while basophils release mediators such as histamine. Monocytes enter tissues and can mature into macrophages that ingest debris and coordinate responses.","Lymphocytes include B cells, T cells, and natural killer cells. Their roles differ, but together they support targeted recognition, antibody production, cellular regulation, and destruction of abnormal or infected cells. Counts vary with age and context, so a differential is interpreted as a pattern rather than a ranking of which cell is most important."],"keyPoints":["Neutrophils are rapid phagocytes.","Eosinophils and basophils contribute to distinct inflammatory patterns.","Monocytes can become tissue macrophages.","Lymphocytes support adaptive and cytotoxic responses."],"visual":{"title":"Leukocyte role map","kind":"map","items":[{"label":"Neutrophil","detail":"Rapid phagocytic response"},{"label":"Eosinophil","detail":"Parasite defence and allergic inflammation"},{"label":"Basophil","detail":"Inflammatory mediator release"},{"label":"Monocyte","detail":"Macrophage precursor and cleanup"},{"label":"Lymphocyte","detail":"Targeted recognition and immune memory"}]},"mnemonic":{"title":"Never Let Monkeys Eat Bananas","cue":"Neutrophils · Lymphocytes · Monocytes · Eosinophils · Basophils","explanation":"A familiar order aid; always pair the name with its actual function."},"goodToKnow":"A high or low leukocyte count describes a laboratory pattern; it does not by itself identify the cause.","act":{"type":"choice","prompt":"Which leukocyte can enter tissue and develop into a macrophage?","options":[{"label":"Monocyte","correct":true,"feedback":"Correct. Circulating monocytes can differentiate into tissue macrophages."},{"label":"Erythrocyte","correct":false,"feedback":"An erythrocyte transports gases and is not a leukocyte."},{"label":"Platelet","correct":false,"feedback":"A platelet is a cell fragment involved in hemostasis."}]}},{"id":"l13-m6","chapter":null,"chapterSummary":null,"title":"Platelets start repair but do not work alone","highYield":"Platelets adhere and aggregate at injury; coagulation then stabilizes the temporary plug with fibrin.","teach":["Platelets are fragments released from large marrow cells called megakaryocytes. When a vessel is injured, local signals expose surfaces that promote platelet adhesion. Activated platelets change shape, release chemical signals, and recruit additional platelets to form a temporary plug.","Platelet activity is only one part of hemostasis. Vascular constriction reduces flow, and the coagulation cascade generates fibrin that reinforces the plug. Later, repair and fibrinolysis remodel and remove the clot. The system must respond strongly at injury while remaining restrained in intact vessels."],"keyPoints":["Platelets derive from megakaryocytes.","Adhesion and aggregation form a temporary plug.","Fibrin stabilizes the plug.","Clot formation and clot removal are both regulated."],"visual":{"title":"From injury to repair","kind":"sequence","items":[{"label":"1 · Constrict","detail":"The damaged vessel narrows"},{"label":"2 · Plug","detail":"Platelets adhere, activate, and aggregate"},{"label":"3 · Reinforce","detail":"Coagulation creates fibrin"},{"label":"4 · Remodel","detail":"Repair proceeds and fibrinolysis limits the clot"}]},"mnemonic":{"title":"CPFR","cue":"Constrict · Plug · Fibrin · Remodel","explanation":"Use the sequence to avoid collapsing all hemostasis into 'clotting.'"},"goodToKnow":"Clotting factors circulate largely as inactive precursors so that coagulation can be amplified locally without continuously clotting the circulation.","act":{"type":"choice","prompt":"What most directly stabilizes the initial platelet plug?","options":[{"label":"A fibrin mesh produced through coagulation","correct":true,"feedback":"Correct. Fibrin reinforces the temporary platelet plug."},{"label":"Conversion of platelets into red blood cells","correct":false,"feedback":"Platelets and erythrocytes are distinct formed elements."},{"label":"Removal of all plasma proteins","correct":false,"feedback":"Plasma clotting proteins are required for coagulation."}]}},{"id":"defence-order","title":"Put it in order: From injury to repair","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"1 · Constrict","detail":"The damaged vessel narrows"},{"label":"2 · Plug","detail":"Platelets adhere, activate, and aggregate"},{"label":"3 · Reinforce","detail":"Coagulation creates fibrin"},{"label":"4 · Remodel","detail":"Repair proceeds and fibrinolysis limits the clot"}]}},{"id":"defence-match","title":"Match it: Leukocyte role map","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Rapid phagocytic response","Parasite defence and allergic inflammation","Inflammatory mediator release","Macrophage precursor and cleanup","Targeted recognition and immune memory"],"items":[{"label":"Eosinophil","category":1,"feedback":"Eosinophil: Parasite defence and allergic inflammation"},{"label":"Lymphocyte","category":4,"feedback":"Lymphocyte: Targeted recognition and immune memory"},{"label":"Basophil","category":2,"feedback":"Basophil: Inflammatory mediator release"},{"label":"Neutrophil","category":0,"feedback":"Neutrophil: Rapid phagocytic response"},{"label":"Monocyte","category":3,"feedback":"Monocyte: Macrophage precursor and cleanup"}]}},{"id":"l13-m7","chapter":"Reason through blood compatibility","chapterSummary":"Separate antigens, antibodies, compatibility testing, and the limits of simplified rules.","title":"ABO type is an antigen–antibody relationship","highYield":"ABO compatibility depends on antigens on erythrocytes and antibodies in plasma; mismatching can cause agglutination and hemolysis.","teach":["In the ABO system, erythrocytes may display A antigen, B antigen, both, or neither. Plasma contains predictable antibodies against the ABO antigen a person lacks. If donor erythrocytes carry an antigen targeted by the recipient's antibodies, cells can agglutinate and be destroyed.","The familiar universal-donor and universal-recipient shortcuts refer to specific components and circumstances, not every transfusion product. Modern transfusion practice uses typing, antibody screening, and crossmatching because ABO is not the only clinically relevant antigen system."],"keyPoints":["Type A cells carry A antigen.","Type B cells carry B antigen.","Type AB cells carry both; type O cells carry neither A nor B.","Compatibility depends on the component and recipient antibodies."],"visual":{"title":"ABO logic","kind":"comparison","items":[{"label":"A","detail":"A antigen; anti-B antibodies"},{"label":"B","detail":"B antigen; anti-A antibodies"},{"label":"AB","detail":"A and B antigens; neither anti-A nor anti-B"},{"label":"O","detail":"Neither A nor B antigen; both anti-A and anti-B"}]},"mnemonic":{"title":"Antigen on, antibody against","cue":"Name what is on the cell; then name what plasma targets","explanation":"This two-step logic is safer than memorizing arrows without understanding them."},"goodToKnow":"Plasma compatibility runs in the opposite conceptual direction from red-cell compatibility because the transfused component contains different antibodies and antigens.","act":{"type":"choice","prompt":"Why can incompatible red-cell transfusion be dangerous?","options":[{"label":"Recipient antibodies can bind donor-cell antigens, causing agglutination and hemolysis","correct":true,"feedback":"Correct. The antigen–antibody reaction can rapidly damage donor erythrocytes."},{"label":"Donor erythrocytes become platelets","correct":false,"feedback":"Cell types do not convert this way."},{"label":"The recipient immediately stops producing plasma","correct":false,"feedback":"The danger is the immune reaction against incompatible cells."}]}},{"id":"l13-m8","chapter":null,"chapterSummary":null,"title":"Rh status adds another compatibility layer","highYield":"Rh-positive means the D antigen is present; Rh-negative means it is absent, but antibody formation usually follows exposure.","teach":["The Rh system includes several antigens, with D being the main antigen used in routine Rh typing. A person who is Rh-negative does not normally have anti-D from birth. Exposure to Rh-positive erythrocytes through transfusion or pregnancy can stimulate antibody formation in some people.","In pregnancy, maternal antibodies formed after sensitization may cross the placenta in a later pregnancy and affect Rh-positive fetal erythrocytes. Prevention and monitoring are medical processes. For study, keep the sequence clear: antigen difference, exposure, sensitization, then possible antibody-mediated effects."],"keyPoints":["Rh status usually refers to D antigen.","Anti-D is generally acquired after exposure.","Sensitization and disease are not the same event.","ABO and Rh are separate classification systems."],"visual":{"title":"Rh sensitization sequence","kind":"flow","items":[{"label":"Antigen difference","detail":"Rh-negative person encounters Rh-positive cells"},{"label":"Exposure","detail":"Transfusion or fetomaternal blood contact"},{"label":"Sensitization","detail":"Immune system forms anti-D"},{"label":"Later exposure","detail":"Antibodies may respond more rapidly"}]},"mnemonic":{"title":"D-E-S-R","cue":"D antigen · Exposure · Sensitize · Respond","explanation":"Use the order to distinguish status from acquired antibody formation."},"goodToKnow":"An antibody screen provides information beyond the ABO/Rh label because other erythrocyte antigens can also matter.","act":{"type":"choice","prompt":"Which statement about an Rh-negative person is most accurate?","options":[{"label":"They lack the D antigen and may form anti-D after exposure to Rh-positive erythrocytes","correct":true,"feedback":"Correct. Rh status describes the antigen; sensitization describes an acquired immune response."},{"label":"They are born with large amounts of anti-D in every case","correct":false,"feedback":"Anti-D usually develops after exposure rather than being naturally present."},{"label":"They cannot have any other red-cell antigens","correct":false,"feedback":"Rh D is only one antigen among many blood-group systems."}]}},{"id":"compatibility-order","title":"Put it in order: Rh sensitization sequence","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Antigen difference","detail":"Rh-negative person encounters Rh-positive cells"},{"label":"Exposure","detail":"Transfusion or fetomaternal blood contact"},{"label":"Sensitization","detail":"Immune system forms anti-D"},{"label":"Later exposure","detail":"Antibodies may respond more rapidly"}]}},{"id":"compatibility-match","title":"Match it: ABO logic","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["A antigen; anti-B antibodies","B antigen; anti-A antibodies","A and B antigens; neither anti-A nor anti-B","Neither A nor B antigen; both anti-A and anti-B"],"items":[{"label":"O","category":3,"feedback":"O: Neither A nor B antigen; both anti-A and anti-B"},{"label":"AB","category":2,"feedback":"AB: A and B antigens; neither anti-A nor anti-B"},{"label":"B","category":1,"feedback":"B: B antigen; anti-A antibodies"},{"label":"A","category":0,"feedback":"A: A antigen; anti-B antibodies"}]}}],"flashcards":[{"front":"Plasma","back":"The liquid extracellular matrix of blood containing water, proteins, electrolytes, nutrients, hormones, gases, and wastes."},{"front":"Formed elements","back":"Erythrocytes, leukocytes, and platelets suspended in plasma."},{"front":"Hematopoiesis","back":"The regulated formation and maturation of blood cells, mainly in red bone marrow."},{"front":"Erythropoietin","back":"A kidney-derived signal that increases marrow erythrocyte production when oxygen delivery is reduced."},{"front":"Hemoglobin","back":"The erythrocyte protein that reversibly binds oxygen and contributes to gas and acid–base transport."},{"front":"Neutrophil","back":"A rapid phagocytic leukocyte important in many acute bacterial responses."},{"front":"Monocyte","back":"A circulating leukocyte that can enter tissue and differentiate into a macrophage."},{"front":"Platelet","back":"A megakaryocyte-derived cell fragment that adheres and aggregates at vessel injury."},{"front":"Fibrin","back":"An insoluble protein mesh that stabilizes a platelet plug during coagulation."},{"front":"ABO antigen","back":"An A or B surface marker on erythrocytes used in ABO blood typing."},{"front":"Agglutination","back":"Clumping that can occur when antibodies bind incompatible erythrocyte antigens."},{"front":"Rh sensitization","back":"Formation of anti-D after an Rh-negative person is exposed to Rh-positive erythrocytes."}],"quiz":[],"caseStudy":{"title":"Fatigue, a low hemoglobin result, and a tempting shortcut","scenario":"A client reports persistent fatigue and shows you a recent low hemoglobin result. They assume the answer is to buy the highest-dose iron supplement immediately. They also report heavy menstrual bleeding and have not discussed the result with their clinician.","prompts":["Which blood measurements and contextual questions would help separate anemia from its possible causes?","Why does iron's role in hemoglobin not prove iron deficiency from this information alone?","What food-intake information is useful within nutrition scope?","What follow-up is appropriate before high-dose supplementation?"],"takeaway":"Connect physiology to safe reasoning: low hemoglobin warrants cause-focused assessment. Nutrition history can support the picture, but blood loss, inflammation, absorption, inherited conditions, and other causes require appropriate clinical evaluation."}},{"n":14,"title":"The Cardiovascular Circulatory System","kicker":"Trace blood through the chambers, valves, lungs, and systemic circulation.","duration":"80–100 minutes","steps":[{"id":"l14-m1","chapter":"Build the heart as a pump","chapterSummary":"Learn the coverings, wall layers, chambers, valves, and great vessels as one connected design.","title":"The heart wall and its coverings have distinct jobs","highYield":"Pericardium contains and protects; myocardium contracts; endocardium lines the chambers and valves.","teach":["The heart sits within a pericardial sac that limits friction and helps contain the organ. The wall itself includes an outer epicardial surface, a thick myocardium, and a smooth endocardial lining. The myocardium is thickest where the pressure demand is greatest, especially in the left ventricle.","Layer names are easiest to learn by asking what touches what. The endocardium touches blood, myocardium produces force, and the outer surface meets the pericardial space. Inflammation or damage in one layer is not automatically equivalent to disease in another."],"keyPoints":["The pericardium surrounds the heart.","Myocardium is cardiac muscle.","Endocardium lines chambers and valves.","Left ventricular myocardium is especially thick."],"visual":{"title":"Heart from outside to inside","kind":"layers","items":[{"label":"Fibrous/serous pericardium","detail":"Protective sac and low-friction surfaces"},{"label":"Epicardium","detail":"Outer heart-wall layer"},{"label":"Myocardium","detail":"Contractile cardiac muscle"},{"label":"Endocardium","detail":"Smooth inner lining"}]},"mnemonic":{"title":"E-M-E","cue":"Epicardium · Myocardium · Endocardium","explanation":"Move from exterior to interior; myocardium in the middle makes the movement."},"goodToKnow":"The wall of the left ventricle is thicker because it must generate pressure for systemic circulation, not because it contains more blood.","act":{"type":"choice","prompt":"Which layer generates the force that ejects blood?","options":[{"label":"Myocardium","correct":true,"feedback":"Correct. Cardiac muscle in the myocardium contracts."},{"label":"Endocardium","correct":false,"feedback":"The endocardium is the inner lining."},{"label":"Parietal pericardium","correct":false,"feedback":"The pericardium surrounds the heart but does not pump blood."}]}},{"id":"l14-m2","chapter":null,"chapterSummary":null,"title":"Four chambers create two coordinated pumps","highYield":"The right side sends blood to the lungs; the left side sends blood to the body.","teach":["The atria receive blood and the ventricles eject it. The right atrium receives systemic venous blood, and the right ventricle sends it through the pulmonary trunk toward the lungs. Pulmonary veins return oxygenated blood to the left atrium, and the left ventricle ejects it into the aorta.","Septa separate the right and left sides, while valves support one-way movement. The tricuspid and mitral valves lie between atria and ventricles; the pulmonary and aortic semilunar valves guard ventricular outflow. Valves open and close because pressure gradients change, not because they actively pull themselves open."],"keyPoints":["Atria receive; ventricles eject.","Right heart supports pulmonary flow.","Left heart supports systemic flow.","Pressure differences operate the valves."],"visual":{"title":"Chambers and valves","kind":"flow","items":[{"label":"Right atrium","detail":"Receives vena-caval and coronary venous return"},{"label":"Tricuspid valve","detail":"Directs flow to right ventricle"},{"label":"Pulmonary valve","detail":"Directs flow to pulmonary trunk"},{"label":"Left atrium","detail":"Receives pulmonary venous return"},{"label":"Mitral and aortic valves","detail":"Direct flow through left ventricle into aorta"}]},"mnemonic":{"title":"A-V-E","cue":"Atrium receives · Ventricle pumps · Exit through semilunar valve","explanation":"Use AVE on both sides of the heart."},"goodToKnow":"Pulmonary arteries carry deoxygenated blood and pulmonary veins carry oxygenated blood; artery and vein are defined by direction relative to the heart.","act":{"type":"choice","prompt":"What directly causes a normal heart valve to open?","options":[{"label":"A pressure difference across the valve","correct":true,"feedback":"Correct. Flow follows the pressure gradient and moves the valve leaflets."},{"label":"A valve-specific nerve pulling it open","correct":false,"feedback":"Valves operate passively through pressure changes."},{"label":"The colour of the blood","correct":false,"feedback":"Diagram colours do not control physiology."}]}},{"id":"heart-structure-order","title":"Put it in order: Chambers and valves","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Right atrium","detail":"Receives vena-caval and coronary venous return"},{"label":"Tricuspid valve","detail":"Directs flow to right ventricle"},{"label":"Pulmonary valve","detail":"Directs flow to pulmonary trunk"},{"label":"Left atrium","detail":"Receives pulmonary venous return"},{"label":"Mitral and aortic valves","detail":"Direct flow through left ventricle into aorta"}]}},{"id":"heart-structure-match","title":"Match it: Heart from outside to inside","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Protective sac and low-friction surfaces","Outer heart-wall layer","Contractile cardiac muscle","Smooth inner lining"],"items":[{"label":"Endocardium","category":3,"feedback":"Endocardium: Smooth inner lining"},{"label":"Myocardium","category":2,"feedback":"Myocardium: Contractile cardiac muscle"},{"label":"Epicardium","category":1,"feedback":"Epicardium: Outer heart-wall layer"},{"label":"Fibrous/serous pericardium","category":0,"feedback":"Fibrous/serous pericardium: Protective sac and low-friction surfaces"}]}},{"id":"l14-m3","chapter":"Follow flow and electrical timing","chapterSummary":"Connect circulation order, conduction, and the mechanical cardiac cycle.","title":"Trace one complete circuit without skipping the lungs","highYield":"Systemic return → right heart → lungs → left heart → systemic arteries.","teach":["A complete trace begins with systemic veins entering the venae cavae, then passes through the right atrium, tricuspid valve, right ventricle, pulmonary valve, pulmonary trunk, and pulmonary arteries. Gas exchange occurs in lung capillaries before pulmonary veins return blood to the left atrium.","Blood then crosses the mitral valve into the left ventricle, passes the aortic valve, and enters the aorta. Coronary arteries branch near the aortic root to supply the heart itself. Remember that the two pumps work in series: sustained output from one side must be matched by the other."],"keyPoints":["Pulmonary circulation links right and left heart.","Systemic circulation begins at the aorta.","Coronary circulation supplies myocardium.","The two sides pump the same long-term volume."],"visual":{"title":"One red-cell journey","kind":"sequence","items":[{"label":"Systemic veins","detail":"Return blood to venae cavae"},{"label":"Right heart","detail":"Receives and sends blood to lungs"},{"label":"Lung capillaries","detail":"Exchange oxygen and carbon dioxide"},{"label":"Left heart","detail":"Receives and sends blood to aorta"},{"label":"Systemic capillaries","detail":"Exchange with tissues"}]},"mnemonic":{"title":"Body–Right–Lungs–Left–Body","cue":"BRLLB","explanation":"Say the five locations before adding chambers and valves."},"goodToKnow":"Oxygenation changes in capillary beds; it does not occur simply because blood enters an artery or vein.","act":{"type":"choice","prompt":"Which vessel returns oxygenated blood from the lungs?","options":[{"label":"Pulmonary veins","correct":true,"feedback":"Correct. They enter the left atrium."},{"label":"Pulmonary arteries","correct":false,"feedback":"Pulmonary arteries carry blood from the right ventricle toward the lungs."},{"label":"Superior vena cava","correct":false,"feedback":"It returns systemic venous blood to the right atrium."}]}},{"id":"l14-m4","chapter":null,"chapterSummary":null,"title":"Electrical conduction coordinates contraction","highYield":"SA node initiates, AV node delays, and the ventricular conduction network distributes the impulse.","teach":["Autorhythmic cells can generate electrical activity without a motor nerve initiating every beat. The sinoatrial node normally sets the rhythm across the atria. The atrioventricular node briefly delays conduction, allowing atrial emptying before the impulse travels into the atrioventricular bundle.","Bundle branches and Purkinje fibres distribute activation through ventricular myocardium so contraction proceeds efficiently. Electrical activity and mechanical contraction are linked but not identical; an electrocardiogram records surface electrical patterns, not the pumping force itself."],"keyPoints":["SA node is the usual pacemaker.","AV delay supports filling.","Bundle branches and Purkinje fibres activate ventricles.","ECG reflects electrical, not direct mechanical, activity."],"visual":{"title":"Conduction pathway","kind":"flow","items":[{"label":"SA node","detail":"Initiates atrial depolarization"},{"label":"AV node","detail":"Brief delay"},{"label":"AV bundle","detail":"Only normal electrical bridge through fibrous skeleton"},{"label":"Bundle branches","detail":"Travel through interventricular septum"},{"label":"Purkinje network","detail":"Distributes activation through ventricles"}]},"mnemonic":{"title":"Start–Await–Bundle–Branch–Purkinje","cue":"S-A-B-B-P","explanation":"The sequence mirrors the path from pacemaker to ventricular muscle."},"goodToKnow":"Autonomic nerves change heart rate and force, but the intrinsic conduction system organizes the beat.","act":{"type":"choice","prompt":"Why is the AV nodal delay useful?","options":[{"label":"It gives the atria time to complete emptying before ventricular contraction","correct":true,"feedback":"Correct. Timing supports efficient sequential pumping."},{"label":"It oxygenates blood inside the node","correct":false,"feedback":"Gas exchange occurs mainly in capillaries, not the AV node."},{"label":"It closes every blood vessel","correct":false,"feedback":"The AV node coordinates electrical timing, not vessel closure."}]}},{"id":"flow-rhythm-order","title":"Put it in order: One red-cell journey","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Systemic veins","detail":"Return blood to venae cavae"},{"label":"Right heart","detail":"Receives and sends blood to lungs"},{"label":"Lung capillaries","detail":"Exchange oxygen and carbon dioxide"},{"label":"Left heart","detail":"Receives and sends blood to aorta"},{"label":"Systemic capillaries","detail":"Exchange with tissues"}]}},{"id":"l14-m5","chapter":"Connect the cardiac cycle to vessels","chapterSummary":"Distinguish systole, diastole, vessel walls, and capillary exchange.","title":"Systole and diastole describe changing pressure phases","highYield":"Filling and ejection depend on pressure gradients created by relaxation and contraction.","teach":["During ventricular diastole, ventricular pressure falls and the atrioventricular valves open when atrial pressure is higher. Ventricular filling is mostly passive, with atrial contraction adding the final portion. During ventricular systole, pressure rises, atrioventricular valves close, and semilunar valves open once ventricular pressure exceeds arterial pressure.","Heart sounds are associated mainly with valve closure and surrounding vibration. Stroke volume is the amount ejected per beat, while cardiac output is heart rate multiplied by stroke volume. These values change with activity and physiological demand rather than remaining fixed at one ideal number."],"keyPoints":["Diastole supports filling.","Systole supports ejection.","Valves respond to pressure gradients.","Cardiac output = heart rate × stroke volume."],"visual":{"title":"Cycle logic","kind":"comparison","items":[{"label":"Diastole","detail":"Ventricular relaxation and filling"},{"label":"AV-valve closure","detail":"Beginning of ventricular systole"},{"label":"Ejection","detail":"Semilunar valves open when ventricular pressure is higher"},{"label":"Semilunar closure","detail":"Occurs as arterial pressure exceeds ventricular pressure"}]},"mnemonic":{"title":"D fills, S sends","cue":"Diastole fills · Systole sends","explanation":"A compact cue for the ventricular cycle."},"goodToKnow":"Blood pressure and cardiac output are related but not equivalent; pressure also depends strongly on vessel resistance and arterial properties.","act":{"type":"choice","prompt":"What is cardiac output?","options":[{"label":"Heart rate multiplied by stroke volume","correct":true,"feedback":"Correct. It estimates volume pumped per minute."},{"label":"Systolic pressure minus diastolic pressure","correct":false,"feedback":"That difference is pulse pressure."},{"label":"The amount of blood in the entire body","correct":false,"feedback":"Cardiac output is flow per unit time."}]}},{"id":"l14-m6","chapter":null,"chapterSummary":null,"title":"Vessel walls match pressure and exchange","highYield":"Arteries distribute under pressure, veins return with high capacitance, and capillaries optimize exchange.","teach":["Arteries have a prominent smooth-muscle and elastic middle layer that tolerates and adjusts to pulsatile pressure. Veins operate at lower pressure, have thinner walls and larger lumens, and often use valves plus skeletal-muscle and respiratory pumps to support return to the heart.","Capillary walls are primarily a single endothelial layer with a basement membrane, minimizing diffusion distance. Their enormous total cross-sectional area slows flow and supports exchange. Arterioles provide major resistance control; venules collect blood from capillary beds."],"keyPoints":["Arteries carry blood away from the heart.","Veins carry blood toward the heart.","Capillaries are exchange vessels.","Arterioles strongly influence local resistance."],"visual":{"title":"Vessel comparison","kind":"comparison","items":[{"label":"Artery","detail":"Thick, elastic, muscular wall; higher pressure"},{"label":"Vein","detail":"Larger lumen; lower pressure; valves in many regions"},{"label":"Capillary","detail":"One-cell-thick exchange surface"},{"label":"Arteriole","detail":"Adjustable resistance vessel"}]},"mnemonic":{"title":"Away–Return–Exchange","cue":"Artery away · Vein return · Capillary exchange","explanation":"Direction defines artery and vein; wall design supports the job."},"goodToKnow":"A vessel carrying oxygen-poor blood can still be an artery if it carries blood away from the heart.","act":{"type":"choice","prompt":"Which vessel is best designed for diffusion between blood and tissue?","options":[{"label":"Capillary","correct":true,"feedback":"Correct. Its thin wall and broad network support exchange."},{"label":"Aorta","correct":false,"feedback":"The aorta is designed for high-pressure distribution."},{"label":"Vena cava","correct":false,"feedback":"The vena cava is a large return vessel."}]}},{"id":"cycle-vessels-match","title":"Match it: Cycle logic","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Ventricular relaxation and filling","Beginning of ventricular systole","Semilunar valves open when ventricular pressure is higher","Occurs as arterial pressure exceeds ventricular pressure"],"items":[{"label":"Semilunar closure","category":3,"feedback":"Semilunar closure: Occurs as arterial pressure exceeds ventricular pressure"},{"label":"Ejection","category":2,"feedback":"Ejection: Semilunar valves open when ventricular pressure is higher"},{"label":"AV-valve closure","category":1,"feedback":"AV-valve closure: Beginning of ventricular systole"},{"label":"Diastole","category":0,"feedback":"Diastole: Ventricular relaxation and filling"}]}},{"id":"l14-m7","chapter":"Think in routes and regulation","chapterSummary":"Use circulation routes and homeostatic reasoning in applied scenarios.","title":"Not every circuit follows the same itinerary","highYield":"Pulmonary, coronary, systemic, and portal routes serve different exchange needs.","teach":["Pulmonary circulation moves blood between heart and lungs. Coronary circulation supplies the myocardium. Systemic circulation serves the rest of the body, while portal circulation sends blood through a second capillary bed before returning to the heart. The hepatic portal route carries nutrient-rich blood from digestive organs to the liver.","The liver can process, store, transform, or release absorbed substances before they enter the general circulation. This first-pass relationship is central to nutrient handling and many medicines. It does not mean all absorbed material is stored, nor that the liver 'detoxes' every exposure completely."],"keyPoints":["Coronary circulation feeds the heart muscle.","Pulmonary circulation supports gas exchange.","Hepatic portal blood reaches the liver before systemic return.","Routes reflect the exchange task."],"visual":{"title":"Four circulation routes","kind":"map","items":[{"label":"Pulmonary","detail":"Heart ↔ lungs"},{"label":"Coronary","detail":"Aorta → myocardium → coronary sinus/right atrium"},{"label":"Systemic","detail":"Left heart → body tissues → right heart"},{"label":"Hepatic portal","detail":"Digestive capillaries → portal vein → liver sinusoids"}]},"mnemonic":{"title":"PCSH","cue":"Pulmonary · Coronary · Systemic · Hepatic portal","explanation":"Name the destination and purpose for each route."},"goodToKnow":"Dietary lipids are initially routed largely through intestinal lymph rather than directly through the hepatic portal vein.","act":{"type":"choice","prompt":"Where does blood from most absorbed water-soluble nutrients travel first?","options":[{"label":"Through the hepatic portal vein to the liver","correct":true,"feedback":"Correct. The liver receives portal blood from digestive organs."},{"label":"Directly from the intestine into the left ventricle","correct":false,"feedback":"Venous return reaches the liver and then the right heart before systemic circulation."},{"label":"Only into the coronary arteries","correct":false,"feedback":"Coronary arteries supply the myocardium."}]}},{"id":"l14-m8","chapter":null,"chapterSummary":null,"title":"Perfusion depends on pump, pipes, and volume","highYield":"Tissue delivery reflects cardiac output, vessel resistance, circulating volume, and local control.","teach":["Cardiovascular homeostasis is a coordinated problem. The heart provides flow, arteries distribute pressure, arterioles adjust resistance, capillaries exchange, and veins return volume. Nervous, endocrine, renal, and local tissue signals continually alter this system to match changing demand.","Population-level dietary patterns can influence long-term cardiovascular risk, but a single nutrient cannot explain an individual's pressure, symptoms, or disease. Accurate practice separates risk-factor education from diagnosis and recognizes urgent symptoms that need immediate medical assessment."],"keyPoints":["Flow requires a pressure gradient.","Resistance changes strongly with vessel radius.","Kidneys influence long-term volume and pressure.","Risk education is not acute symptom assessment."],"visual":{"title":"Perfusion model","kind":"map","items":[{"label":"Pump","detail":"Heart rate and stroke volume"},{"label":"Pipes","detail":"Vessel radius and elasticity"},{"label":"Volume","detail":"Blood and extracellular-fluid regulation"},{"label":"Demand","detail":"Local metabolic control in tissues"}]},"mnemonic":{"title":"PPVD","cue":"Pump · Pipes · Volume · Demand","explanation":"Use all four before explaining tissue perfusion."},"goodToKnow":"Sodium affects extracellular-fluid regulation, but pressure response varies and cannot be inferred from one meal.","act":{"type":"choice","prompt":"Which change most directly raises resistance in a small artery?","options":[{"label":"A decrease in vessel radius","correct":true,"feedback":"Correct. Narrowing greatly increases resistance to flow."},{"label":"A larger capillary exchange area","correct":false,"feedback":"Exchange area affects velocity and diffusion, not arteriolar radius directly."},{"label":"Opening an atrioventricular valve","correct":false,"feedback":"That changes intracardiac flow, not small-artery resistance."}]}},{"id":"integration-match","title":"Match it: Four circulation routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Heart ↔ lungs","Aorta → myocardium → coronary sinus/right atrium","Left heart → body tissues → right heart","Digestive capillaries → portal vein → liver sinusoids"],"items":[{"label":"Hepatic portal","category":3,"feedback":"Hepatic portal: Digestive capillaries → portal vein → liver sinusoids"},{"label":"Systemic","category":2,"feedback":"Systemic: Left heart → body tissues → right heart"},{"label":"Coronary","category":1,"feedback":"Coronary: Aorta → myocardium → coronary sinus/right atrium"},{"label":"Pulmonary","category":0,"feedback":"Pulmonary: Heart ↔ lungs"}]}}],"flashcards":[{"front":"Myocardium","back":"The contractile cardiac-muscle layer of the heart wall."},{"front":"Endocardium","back":"The smooth inner lining of heart chambers and valves."},{"front":"Tricuspid valve","back":"The right atrioventricular valve between right atrium and ventricle."},{"front":"Mitral valve","back":"The left atrioventricular valve between left atrium and ventricle."},{"front":"SA node","back":"The usual pacemaker that initiates atrial depolarization."},{"front":"AV node","back":"The conduction site that briefly delays the impulse before ventricular activation."},{"front":"Stroke volume","back":"The amount of blood ejected by one ventricle per beat."},{"front":"Cardiac output","back":"Heart rate multiplied by stroke volume; flow per minute."},{"front":"Arteriole","back":"A small resistance vessel that regulates flow into capillary beds."},{"front":"Capillary","back":"A microscopic thin-walled vessel specialized for exchange."},{"front":"Hepatic portal circulation","back":"Route carrying blood from digestive capillaries to liver sinusoids before systemic return."},{"front":"Coronary circulation","back":"Blood supply serving the myocardium itself."}],"quiz":[],"caseStudy":{"title":"A number, a symptom, and two different priorities","scenario":"A client wants nutrition advice after a home blood-pressure reading. During the conversation they also mention new chest pressure while climbing stairs. They ask whether simply avoiding salt for a week will settle both concerns.","prompts":["Which information belongs to long-term cardiovascular risk education?","Why can one home reading not define the mechanism?","Which symptom changes the priority of the conversation?","How can you state the nutrition role without delaying appropriate assessment?"],"takeaway":"Nutrition can support long-term cardiovascular health, but new exertional chest pressure requires prompt medical assessment. Do not let risk-factor counselling become a substitute for symptom triage."}},{"n":15,"title":"The Lymphatic Circulatory System","kicker":"Explain how lymphatic vessels return interstitial fluid and absorbed lipids to circulation.","duration":"75–95 minutes","steps":[{"id":"l15-m1","chapter":"Follow fluid back to blood","chapterSummary":"Understand one-way lymph flow, vessel design, and intestinal lipid transport.","title":"Lymph begins as interstitial fluid","highYield":"The lymphatic system returns excess tissue fluid and proteins that blood capillaries do not directly recover.","teach":["Fluid filters from blood capillaries into the interstitial space, where it supports exchange with cells. Most returns locally to blood, while a portion enters blind-ended lymphatic capillaries. Once inside the lymphatic network, the fluid is called lymph.","Lymphatic capillaries have overlapping endothelial flaps that open when tissue pressure rises. Larger vessels contain valves and ultimately return lymph to large veins near the base of the neck. If filtration, return, or drainage becomes unbalanced, fluid can accumulate in tissues, but the cause cannot be identified from swelling alone."],"keyPoints":["Interstitial fluid becomes lymph after entering lymphatic capillaries.","Lymph flow is one-way toward the venous circulation.","Valves limit backflow.","Edema reflects a fluid-balance problem, not one single diagnosis."],"visual":{"title":"Fluid recovery loop","kind":"flow","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]},"mnemonic":{"title":"Filter–Feed–Fetch–Flow back","cue":"FFFF","explanation":"Blood filters, tissue fluid feeds cells, lymphatics fetch excess, and lymph flows back to veins."},"goodToKnow":"The lymphatic circulation has no single central pump equivalent to the heart.","act":{"type":"choice","prompt":"When does interstitial fluid become lymph?","options":[{"label":"After it enters a lymphatic capillary","correct":true,"feedback":"Correct. Location within the lymphatic vessel defines lymph."},{"label":"As soon as plasma leaves the heart","correct":false,"feedback":"Fluid becomes interstitial after capillary filtration and lymph only after lymphatic entry."},{"label":"Only after passing through the spleen","correct":false,"feedback":"Lymph is present throughout lymphatic vessels before any organ encounter."}]}},{"id":"l15-m2","chapter":null,"chapterSummary":null,"title":"Movement depends on valves and body motion","highYield":"Skeletal-muscle contraction, breathing, smooth muscle, and valves move lymph through a low-pressure system.","teach":["Lymphatic vessels resemble thin-walled veins but begin as capillaries in tissues. Contraction of surrounding skeletal muscle compresses them, pressure changes during breathing draw lymph toward the thorax, and smooth muscle in larger vessel walls contributes rhythmic propulsion.","Valves segment the pathway so each compression tends to move fluid centrally. The right lymphatic duct drains part of the upper body, while the thoracic duct drains most remaining regions. Both empty into venous circulation near the junctions of internal jugular and subclavian veins."],"keyPoints":["Lymph flow is low pressure.","Muscle and respiratory pumps assist movement.","The thoracic duct drains most of the body.","Ducts return lymph to venous blood."],"visual":{"title":"What moves lymph?","kind":"map","items":[{"label":"Skeletal-muscle pump","detail":"External compression of vessels"},{"label":"Respiratory pump","detail":"Thoracic pressure changes during breathing"},{"label":"Vessel smooth muscle","detail":"Intrinsic contraction in larger vessels"},{"label":"Valves","detail":"Limit reverse flow"}]},"mnemonic":{"title":"Move–Breathe–Valve","cue":"MBV","explanation":"Movement and breathing provide pressure; valves preserve direction."},"goodToKnow":"Being still does not stop all lymph flow, but ordinary movement contributes to its efficiency.","act":{"type":"choice","prompt":"Which feature most directly prevents lymph from moving backward after a vessel is compressed?","options":[{"label":"Valves","correct":true,"feedback":"Correct. Valves create one-way segments."},{"label":"Erythrocytes","correct":false,"feedback":"Lymph normally contains few or no erythrocytes."},{"label":"Gastric acid","correct":false,"feedback":"Gastric acid has no role in lymphatic valve function."}]}},{"id":"circulation-order","title":"Put it in order: Fluid recovery loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]}},{"id":"circulation-match","title":"Match it: What moves lymph?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["External compression of vessels","Thoracic pressure changes during breathing","Intrinsic contraction in larger vessels","Limit reverse flow"],"items":[{"label":"Valves","category":3,"feedback":"Valves: Limit reverse flow"},{"label":"Vessel smooth muscle","category":2,"feedback":"Vessel smooth muscle: Intrinsic contraction in larger vessels"},{"label":"Respiratory pump","category":1,"feedback":"Respiratory pump: Thoracic pressure changes during breathing"},{"label":"Skeletal-muscle pump","category":0,"feedback":"Skeletal-muscle pump: External compression of vessels"}]}},{"id":"l15-m3","chapter":"Map lymphatic organs","chapterSummary":"Separate filtration of lymph, filtration of blood, immune-cell maturation, and mucosal surveillance.","title":"Nodes filter lymph and organize responses","highYield":"Lymph nodes sample lymph, house immune cells, and slow flow so antigens and cells can interact.","teach":["A lymph node receives lymph through multiple afferent vessels and releases it through fewer efferent vessels at the hilum. Its capsule and internal sinuses channel flow through regions rich in macrophages, B cells, T cells, and antigen-presenting cells.","Nodes enlarge for many reasons, including immune-cell activation, increased traffic, infection, and malignancy. Tenderness, location, duration, and associated symptoms matter. A palpable node is an observation—not enough information to label the cause."],"keyPoints":["Afferent vessels enter; efferent vessels exit.","Nodes filter lymph, not blood.","Cortex and deeper regions organize immune cells.","Node enlargement has multiple possible causes."],"visual":{"title":"Through a lymph node","kind":"flow","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]},"mnemonic":{"title":"A arrives, E exits","cue":"Afferent arrives · Efferent exits","explanation":"Use the first letters to keep vessel direction straight."},"goodToKnow":"Cancer cells may travel through lymph and be found in nodes, but node enlargement is not synonymous with cancer.","act":{"type":"choice","prompt":"Which statement correctly distinguishes lymph nodes from the spleen?","options":[{"label":"Nodes filter lymph; the spleen filters blood","correct":true,"feedback":"Correct. Their fluid pathways differ."},{"label":"Nodes pump blood; the spleen produces bile","correct":false,"feedback":"Neither statement describes their primary roles."},{"label":"Nodes mature erythrocytes; the spleen filters air","correct":false,"feedback":"Erythrocytes mature in marrow and air is filtered in the respiratory tract."}]}},{"id":"l15-m4","chapter":null,"chapterSummary":null,"title":"Spleen, thymus, and tonsils occupy different checkpoints","highYield":"Spleen monitors blood, thymus supports T-cell maturation, and tonsils sample material at the pharyngeal entrance.","teach":["The spleen's white pulp supports immune surveillance of blood-borne antigens, while red pulp removes aged or damaged erythrocytes and stores some platelets. Unlike a lymph node, the spleen is connected directly to blood circulation rather than positioned in a chain of lymphatic vessels.","The thymus provides an environment for T-cell maturation and is most active earlier in life. Tonsils and other mucosa-associated lymphoid tissues sample material near respiratory and digestive entry points. Each structure contributes to defence from a different anatomical location."],"keyPoints":["Spleen filters blood and recycles erythrocyte components.","Thymus supports T-cell maturation.","Tonsils survey the pharyngeal region.","Lymphatic organs are not interchangeable."],"visual":{"title":"Organ checkpoints","kind":"comparison","items":[{"label":"Lymph node","detail":"Samples lymph from tissues"},{"label":"Spleen","detail":"Samples blood and removes old erythrocytes"},{"label":"Thymus","detail":"Supports T-cell maturation"},{"label":"Tonsils/MALT","detail":"Monitor mucosal entry sites"}]},"mnemonic":{"title":"Node–Blood–T–Throat","cue":"Node filters lymph · spleen filters blood · thymus trains T cells · tonsils watch throat","explanation":"The location hints at the job."},"goodToKnow":"The thymus becomes less prominent after puberty but does not simply vanish or make adult immunity impossible.","act":{"type":"choice","prompt":"Which organ removes many aged erythrocytes from blood?","options":[{"label":"Spleen","correct":true,"feedback":"Correct. Red pulp participates in erythrocyte removal and recycling."},{"label":"Thymus","correct":false,"feedback":"The thymus is primarily associated with T-cell maturation."},{"label":"Tonsil","correct":false,"feedback":"Tonsils are mucosal immune tissues near the pharynx."}]}},{"id":"organs-order","title":"Put it in order: Through a lymph node","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]}},{"id":"organs-match","title":"Match it: Organ checkpoints","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Samples lymph from tissues","Samples blood and removes old erythrocytes","Supports T-cell maturation","Monitor mucosal entry sites"],"items":[{"label":"Tonsils/MALT","category":3,"feedback":"Tonsils/MALT: Monitor mucosal entry sites"},{"label":"Thymus","category":2,"feedback":"Thymus: Supports T-cell maturation"},{"label":"Spleen","category":1,"feedback":"Spleen: Samples blood and removes old erythrocytes"},{"label":"Lymph node","category":0,"feedback":"Lymph node: Samples lymph from tissues"}]}},{"id":"l15-m5","chapter":"Layer innate and adaptive defence","chapterSummary":"Understand barriers, inflammation, antigen recognition, and lymphocyte specialization.","title":"Innate defence responds quickly to patterns","highYield":"Barriers, phagocytes, complement, inflammation, and fever act without needing prior exposure to one exact antigen.","teach":["Innate defence includes intact skin and mucosa, antimicrobial secretions, resident and recruited phagocytes, natural killer cells, complement proteins, and inflammatory signals. These components recognize broad features of damage or microbes and respond rapidly.","Inflammation increases local blood flow and vessel permeability while recruiting cells and proteins. This can support containment and repair, but excessive or misplaced inflammation can damage tissue. 'Inflammation' is therefore a process, not a universal diagnosis or a food morality label."],"keyPoints":["Barriers are first-line defences.","Innate recognition is pattern-based.","Inflammation recruits cells and proteins.","Fever and inflammation are regulated responses with possible costs."],"visual":{"title":"Innate defence layers","kind":"layers","items":[{"label":"Barrier","detail":"Skin, mucosa, secretions"},{"label":"Recognition","detail":"Cells detect common danger patterns"},{"label":"Response","detail":"Phagocytosis, complement, inflammation"},{"label":"Resolution","detail":"Signals limit response and support repair"}]},"mnemonic":{"title":"B-R-R-R","cue":"Barrier · Recognize · Respond · Resolve","explanation":"A healthy defence response must eventually resolve."},"goodToKnow":"A marker of inflammation can rise for many reasons and does not identify a specific food trigger by itself.","act":{"type":"choice","prompt":"Which is an innate defence?","options":[{"label":"A skin barrier and rapid phagocyte response","correct":true,"feedback":"Correct. These act broadly without requiring antigen-specific memory."},{"label":"A highly specific memory B-cell response after vaccination","correct":false,"feedback":"That is adaptive immunity."},{"label":"ABO compatibility testing","correct":false,"feedback":"That is a transfusion-safety process, not an innate defence."}]}},{"id":"l15-m6","chapter":null,"chapterSummary":null,"title":"Adaptive immunity adds specificity and memory","highYield":"B and T lymphocytes recognize specific antigens, expand selected clones, and can leave memory cells.","teach":["Adaptive responses begin when lymphocytes with matching receptors encounter antigen in the right signalling context. Clonal expansion creates many related cells. B cells can differentiate into plasma cells that secrete antibodies, while memory B cells support faster future responses.","T-cell populations perform different work: helper T cells coordinate responses, cytotoxic T cells kill selected infected or abnormal cells, and regulatory T cells help limit inappropriate activation. Antibodies act outside cells; cytotoxic T cells inspect cellular antigen presentation. Both arms cooperate with innate defence."],"keyPoints":["Adaptive recognition is antigen-specific.","B cells can produce antibody-secreting plasma cells.","T cells coordinate, kill, or regulate.","Memory changes a later response."],"visual":{"title":"Two adaptive arms","kind":"comparison","items":[{"label":"Humoral","detail":"B cells and antibodies act in extracellular spaces"},{"label":"Cell-mediated","detail":"T cells coordinate or act on selected cells"},{"label":"Memory","detail":"Long-lived cells support faster later response"},{"label":"Cooperation","detail":"Innate signals help activate and shape adaptive responses"}]},"mnemonic":{"title":"B = antibodies, T = tasks in tissues","cue":"B builds antibodies · T targets and tunes","explanation":"A study cue, not a complete catalogue of lymphocyte biology."},"goodToKnow":"Antibodies can neutralize, tag, or activate other defence mechanisms; they do not directly 'eat' microbes.","act":{"type":"choice","prompt":"Which cell directly secretes large amounts of antibody?","options":[{"label":"A plasma cell derived from a B lymphocyte","correct":true,"feedback":"Correct. Plasma cells are specialized antibody secretors."},{"label":"An erythrocyte","correct":false,"feedback":"Erythrocytes transport gases."},{"label":"A platelet","correct":false,"feedback":"Platelets function mainly in hemostasis and repair signalling."}]}},{"id":"immunity-match","title":"Match it: Innate defence layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Skin, mucosa, secretions","Cells detect common danger patterns","Phagocytosis, complement, inflammation","Signals limit response and support repair"],"items":[{"label":"Resolution","category":3,"feedback":"Resolution: Signals limit response and support repair"},{"label":"Response","category":2,"feedback":"Response: Phagocytosis, complement, inflammation"},{"label":"Recognition","category":1,"feedback":"Recognition: Cells detect common danger patterns"},{"label":"Barrier","category":0,"feedback":"Barrier: Skin, mucosa, secretions"}]}},{"id":"l15-m7","chapter":"Compare acquired protection","chapterSummary":"Distinguish active and passive immunity, antigen–antibody binding, and safe practice boundaries.","title":"Active and passive immunity differ in who makes the antibody","highYield":"Active immunity develops after your immune system responds; passive immunity transfers ready-made antibodies.","teach":["Active immunity follows infection or vaccination and requires the recipient's lymphocytes to respond. It takes time to develop but can create memory. Passive immunity provides antibodies made elsewhere, such as maternal antibodies transferred across the placenta or an administered antibody product.","Passive protection can act quickly but is temporary because the recipient did not create the memory response. Natural and artificial describe how exposure occurs, while active and passive describe who produced the protective antibodies. Keep these two classification axes separate."],"keyPoints":["Active immunity can form memory.","Passive immunity transfers antibody.","Passive protection is relatively immediate and temporary.","Natural/artificial and active/passive answer different questions."],"visual":{"title":"Four acquisition routes","kind":"comparison","items":[{"label":"Natural active","detail":"Immune response after infection"},{"label":"Artificial active","detail":"Immune response after vaccination"},{"label":"Natural passive","detail":"Maternal antibody transfer"},{"label":"Artificial passive","detail":"Administered antibody preparation"}]},"mnemonic":{"title":"Active acts; passive passes","cue":"Act to make · Pass ready-made","explanation":"Active means the recipient's immune system produces the response."},"goodToKnow":"Vaccination does not guarantee identical protection in every person, but it trains adaptive recognition without requiring the full disease experience.","act":{"type":"choice","prompt":"Which example is natural passive immunity?","options":[{"label":"Maternal IgG crossing the placenta","correct":true,"feedback":"Correct. Ready-made antibody is naturally transferred."},{"label":"Memory after recovering from infection","correct":false,"feedback":"That is natural active immunity."},{"label":"Antibody production after vaccination","correct":false,"feedback":"That is artificial active immunity."}]}},{"id":"l15-m8","chapter":null,"chapterSummary":null,"title":"Antigen–antibody binding is precise but not sufficient alone","highYield":"Antibodies bind particular molecular features and then recruit or block other processes.","teach":["An antigen contains molecular regions called epitopes. An antibody's binding site fits a particular epitope closely enough to bind. This specificity explains why one antibody does not recognize every pathogen and why cross-reactivity can occur when structures are similar.","Binding can neutralize a toxin or virus, mark a target for phagocytosis, clump particles, or activate complement. Outcome depends on the antibody class, location, target, and other immune components. A positive antibody result may reflect past exposure, vaccination, current response, or cross-reactivity; interpretation needs context."],"keyPoints":["Epitopes are recognized portions of antigens.","Antibody specificity is selective, not absolute.","Binding recruits additional mechanisms.","An antibody test is contextual evidence."],"visual":{"title":"What antibody binding can do","kind":"map","items":[{"label":"Neutralize","detail":"Block a target from attaching or acting"},{"label":"Opsonize","detail":"Tag a target for phagocytes"},{"label":"Agglutinate","detail":"Cross-link particles"},{"label":"Activate complement","detail":"Trigger a protein cascade"}]},"mnemonic":{"title":"NOAC","cue":"Neutralize · Opsonize · Agglutinate · Complement","explanation":"Four common consequences of antibody binding."},"goodToKnow":"Allergy is an immune response to a usually harmless substance; it is not evidence that the immune system is simply 'weak.'","act":{"type":"choice","prompt":"What is an epitope?","options":[{"label":"A specific region of an antigen recognized by an immune receptor or antibody","correct":true,"feedback":"Correct. Recognition occurs at particular molecular features."},{"label":"The fluid inside a lymphatic vessel","correct":false,"feedback":"That fluid is lymph."},{"label":"A valve in a vein","correct":false,"feedback":"A valve directs fluid flow and is unrelated to antigen recognition."}]}},{"id":"memory-match","title":"Match it: Four acquisition routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Immune response after infection","Immune response after vaccination","Maternal antibody transfer","Administered antibody preparation"],"items":[{"label":"Artificial passive","category":3,"feedback":"Artificial passive: Administered antibody preparation"},{"label":"Natural passive","category":2,"feedback":"Natural passive: Maternal antibody transfer"},{"label":"Artificial active","category":1,"feedback":"Artificial active: Immune response after vaccination"},{"label":"Natural active","category":0,"feedback":"Natural active: Immune response after infection"}]}}],"flashcards":[{"front":"Lymph","back":"Interstitial fluid after it enters lymphatic vessels."},{"front":"Thoracic duct","back":"The major lymphatic duct draining most of the body into venous circulation."},{"front":"Lacteal","back":"A lymphatic capillary in an intestinal villus that absorbs dietary lipids packaged as chylomicrons."},{"front":"Afferent lymphatic","back":"A vessel carrying lymph into a node."},{"front":"Efferent lymphatic","back":"A vessel carrying lymph away from a node."},{"front":"Spleen","back":"A lymphatic organ that filters blood and removes many aged erythrocytes."},{"front":"Thymus","back":"An organ supporting T-cell maturation, especially early in life."},{"front":"Innate immunity","back":"Rapid pattern-based defence including barriers, phagocytes, inflammation, and complement."},{"front":"Humoral immunity","back":"Adaptive defence mediated primarily by B cells and antibodies."},{"front":"Cell-mediated immunity","back":"Adaptive defence involving T-cell coordination and action on selected cells."},{"front":"Active immunity","back":"Protection generated by the recipient's own immune response, often with memory."},{"front":"Passive immunity","back":"Temporary protection from transferred ready-made antibodies."}],"quiz":[],"caseStudy":{"title":"A persistent neck lump and an 'immune-boosting' plan","scenario":"A client has noticed an enlarging neck lump for several weeks and asks which supplement will 'drain the lymph' and strengthen immunity. They have not sought medical assessment.","prompts":["What can and cannot be inferred from a palpable node?","Which duration and change details make follow-up important?","How would you explain the role of a lymph node without diagnosing the cause?","What supportive nutrition conversation can occur without delaying assessment?"],"takeaway":"Lymph nodes enlarge for multiple reasons. Explain the mechanism, avoid supplement promises, and encourage appropriate clinical assessment of a persistent or enlarging lump."}},{"n":16,"title":"Nutrition and the Digestive System","kicker":"Trace food through the alimentary canal and identify accessory-organ contributions.","duration":"90–110 minutes","steps":[{"id":"l16-m1","chapter":"Orient to the digestive tube","chapterSummary":"Build the wall layers, movement pattern, and oral phase before following individual nutrients.","title":"One continuous tube, four repeating wall layers","highYield":"Mucosa handles contact and absorption; submucosa supports; muscularis moves; serosa/adventitia anchors or reduces friction.","teach":["The alimentary canal runs from mouth to anus. Although each region is specialized, much of the tube follows a four-layer plan: mucosa, submucosa, muscularis externa, and an outer serosa or adventitia. The mucosa includes epithelium, connective tissue, and a thin muscle layer; its surface changes according to function.","The submucosa carries vessels, glands, and nerve networks. Circular and longitudinal smooth muscle in the muscularis mix and propel contents. Enteric nerve plexuses coordinate local activity while autonomic and hormonal signals modify it. Digestion is therefore mechanical, chemical, and regulatory at the same time."],"keyPoints":["Mucosa faces the lumen.","Submucosa supports vessels, glands, and nerves.","Muscularis mixes and propels.","Serosa reduces friction; adventitia anchors some regions."],"visual":{"title":"GI wall from lumen outward","kind":"layers","items":[{"label":"Mucosa","detail":"Secretion, protection, absorption"},{"label":"Submucosa","detail":"Vessels, glands, connective support, nerve plexus"},{"label":"Muscularis externa","detail":"Circular and longitudinal movement"},{"label":"Serosa/adventitia","detail":"Outer covering or attachment"}]},"mnemonic":{"title":"M-S-M-S","cue":"Mucosa · Submucosa · Muscularis · Serosa","explanation":"Move from the lumen outward; substitute adventitia where the organ is anchored."},"goodToKnow":"The enteric nervous system can coordinate local reflexes, but it still communicates with the central nervous and endocrine systems.","act":{"type":"choice","prompt":"Which layer directly contacts material in the intestinal lumen?","options":[{"label":"Mucosa","correct":true,"feedback":"Correct. Its epithelium forms the luminal surface."},{"label":"Muscularis externa","correct":false,"feedback":"The muscularis lies deeper and produces movement."},{"label":"Serosa","correct":false,"feedback":"The serosa is an outer covering."}]}},{"id":"l16-m2","chapter":null,"chapterSummary":null,"title":"The mouth begins both processing and decision-making","highYield":"Chewing, saliva, tongue movement, and swallowing prepare a manageable bolus; digestion does not begin in the stomach.","teach":["Teeth mechanically reduce food size, increasing surface area. The tongue positions food, contributes to taste, and forms a bolus. Saliva moistens and lubricates, buffers the oral environment, and contains enzymes that begin starch and some lipid processing, although most digestion occurs later.","Swallowing begins voluntarily and then becomes a coordinated reflex moving the bolus through pharynx and esophagus. Peristaltic waves propel it toward the stomach while sphincters help direct flow. Chewing time or saliva alone cannot determine nutrient absorption, but oral function can strongly affect what a person can comfortably eat."],"keyPoints":["Mastication increases surface area.","Saliva lubricates and begins chemical digestion.","The tongue forms and positions the bolus.","Swallowing changes from voluntary to reflex control."],"visual":{"title":"Oral-to-esophageal sequence","kind":"sequence","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]},"mnemonic":{"title":"CMFSP","cue":"Chew · Moisten · Form · Swallow · Propel","explanation":"A five-step oral and esophageal route."},"goodToKnow":"Salivary amylase starts starch digestion but is not responsible for completing carbohydrate digestion.","act":{"type":"choice","prompt":"What is the main immediate benefit of chewing for digestion?","options":[{"label":"It reduces particle size and increases surface area","correct":true,"feedback":"Correct. This improves contact with fluids and enzymes."},{"label":"It absorbs all nutrients through the teeth","correct":false,"feedback":"Teeth mechanically process food; they do not absorb nutrients."},{"label":"It converts protein directly into glucose","correct":false,"feedback":"Protein digestion requires enzymatic steps in the stomach and small intestine."}]}},{"id":"organization-order","title":"Put it in order: Oral-to-esophageal sequence","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]}},{"id":"organization-match","title":"Match it: GI wall from lumen outward","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Secretion, protection, absorption","Vessels, glands, connective support, nerve plexus","Circular and longitudinal movement","Outer covering or attachment"],"items":[{"label":"Serosa/adventitia","category":3,"feedback":"Serosa/adventitia: Outer covering or attachment"},{"label":"Muscularis externa","category":2,"feedback":"Muscularis externa: Circular and longitudinal movement"},{"label":"Submucosa","category":1,"feedback":"Submucosa: Vessels, glands, connective support, nerve plexus"},{"label":"Mucosa","category":0,"feedback":"Mucosa: Secretion, protection, absorption"}]}},{"id":"l16-m3","chapter":"Coordinate stomach and accessory organs","chapterSummary":"Separate storage, acid and enzymes, pancreatic secretion, bile, and liver processing.","title":"The stomach stores, mixes, acidifies, and meters","highYield":"The stomach begins substantial protein digestion and delivers chyme gradually; it is not the main nutrient-absorption site.","teach":["The stomach's folds allow expansion while muscular layers churn food into chyme. Parietal cells secrete hydrochloric acid and intrinsic factor, chief cells release pepsinogen, and mucous cells help protect the lining. Acid denatures proteins and activates pepsin, while intrinsic factor later supports vitamin B12 absorption in the ileum.","Pyloric control meters chyme into the duodenum. Emptying rate changes with meal composition, particle size, and regulatory signals. Fat and high energy density often slow emptying, but individual symptoms are not a direct readout of one nutrient or of stomach acid level."],"keyPoints":["Acid denatures protein and activates pepsin.","Intrinsic factor is required for normal B12 absorption.","Mucus and bicarbonate protect the stomach lining.","The pylorus regulates delivery to duodenum."],"visual":{"title":"Gastric cell roles","kind":"comparison","items":[{"label":"Parietal cell","detail":"Hydrochloric acid and intrinsic factor"},{"label":"Chief cell","detail":"Pepsinogen precursor"},{"label":"Mucous cell","detail":"Protective mucus and local buffering"},{"label":"Muscle layers","detail":"Mix chyme and support emptying"}]},"mnemonic":{"title":"A-I-P-M","cue":"Acid · Intrinsic factor · Pepsin · Mucus","explanation":"Four gastric products/functions to keep distinct."},"goodToKnow":"Very little macronutrient absorption occurs in the stomach; most absorption occurs in the small intestine.","act":{"type":"choice","prompt":"Which stomach product is essential for efficient vitamin B12 absorption later in the ileum?","options":[{"label":"Intrinsic factor","correct":true,"feedback":"Correct. B12 binds intrinsic factor before receptor-mediated absorption."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and aids lipid handling."},{"label":"Insulin","correct":false,"feedback":"Insulin is an endocrine pancreatic hormone, not a gastric product."}]}},{"id":"l16-m4","chapter":null,"chapterSummary":null,"title":"Pancreas, liver, and gallbladder deliver complementary support","highYield":"Pancreas supplies bicarbonate and enzymes; liver makes bile and processes portal blood; gallbladder stores and concentrates bile.","teach":["The exocrine pancreas delivers bicarbonate to neutralize acidic chyme and enzymes that digest carbohydrate, protein, fat, and nucleic acids. Its endocrine islets release hormones such as insulin and glucagon into blood. Exocrine and endocrine functions share an organ but use different ducts and destinations.","The liver produces bile, processes portal nutrients, stores selected fuels and vitamins, synthesizes many plasma proteins, and modifies wastes and chemicals. The gallbladder stores and concentrates bile, then releases it when signalled. Bile emulsifies fat into smaller droplets; it is not a digestive enzyme and does not chemically split triglycerides."],"keyPoints":["Pancreatic bicarbonate raises duodenal pH.","Pancreatic enzymes act on all major nutrient classes.","Liver produces bile; gallbladder stores it.","Bile emulsifies rather than hydrolyzes fat."],"visual":{"title":"Accessory-organ teamwork","kind":"map","items":[{"label":"Pancreas","detail":"Bicarbonate plus digestive enzymes"},{"label":"Liver","detail":"Bile production and portal processing"},{"label":"Gallbladder","detail":"Bile storage and concentration"},{"label":"Duodenum","detail":"Receives chyme, bile, and pancreatic secretion"}]},"mnemonic":{"title":"PBLG","cue":"Pancreas breaks · Bile bundles · Liver generates · Gallbladder holds","explanation":"A compact cue; remember enzymes break bonds while bile disperses fat."},"goodToKnow":"A person can live without a gallbladder because the liver still produces bile, though delivery becomes less concentrated and less meal-timed.","act":{"type":"choice","prompt":"Which statement about bile is accurate?","options":[{"label":"It emulsifies fat, increasing surface area for lipase","correct":true,"feedback":"Correct. Bile disperses fat droplets but does not hydrolyze triglycerides itself."},{"label":"It is a protease secreted by the stomach","correct":false,"feedback":"Bile is not an enzyme and is produced by the liver."},{"label":"It transports oxygen in red blood cells","correct":false,"feedback":"Hemoglobin performs that role."}]}},{"id":"upper-organs-match","title":"Match it: Gastric cell roles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hydrochloric acid and intrinsic factor","Pepsinogen precursor","Protective mucus and local buffering","Mix chyme and support emptying"],"items":[{"label":"Muscle layers","category":3,"feedback":"Muscle layers: Mix chyme and support emptying"},{"label":"Mucous cell","category":2,"feedback":"Mucous cell: Protective mucus and local buffering"},{"label":"Chief cell","category":1,"feedback":"Chief cell: Pepsinogen precursor"},{"label":"Parietal cell","category":0,"feedback":"Parietal cell: Hydrochloric acid and intrinsic factor"}]}},{"id":"l16-m5","chapter":"Digest and absorb","chapterSummary":"Use small-intestinal surface area and colon function to explain nutrient and fluid handling.","title":"The small intestine completes digestion and captures nutrients","highYield":"Folds, villi, and microvilli create a large absorptive surface supplied by blood capillaries and lacteals.","teach":["The duodenum receives chyme, bile, and pancreatic secretion; the jejunum is a major site of absorption; and the ileum completes absorption of selected substances, including the intrinsic-factor–B12 complex and recycled bile salts. Segmentation mixes contents while peristalsis advances them.","Circular folds, villi, and microvilli multiply surface area. Monosaccharides, amino acids, and many water-soluble products enter blood capillaries and travel through the hepatic portal vein. Long-chain lipids are rebuilt into triglycerides, packaged into chylomicrons, and enter lacteals before reaching blood."],"keyPoints":["Duodenum coordinates neutralization and digestion.","Villi and microvilli expand surface area.","Water-soluble nutrients generally enter portal blood.","Chylomicrons generally enter lymphatic lacteals."],"visual":{"title":"Two absorption routes","kind":"comparison","items":[{"label":"Blood capillary route","detail":"Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","detail":"Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","detail":"B12–intrinsic factor complex and bile-salt recovery"}]},"mnemonic":{"title":"Sugar and amino acids sail portal; fat floats lymph","cue":"Portal for soluble · lymph for chylomicrons","explanation":"A useful general pattern with exceptions for some shorter fatty acids."},"goodToKnow":"Absorption is selective and transporter-dependent; eating a nutrient does not guarantee identical absorption in every context.","act":{"type":"choice","prompt":"Where do most long-chain dietary lipids go immediately after absorption?","options":[{"label":"Into chylomicrons that enter intestinal lacteals","correct":true,"feedback":"Correct. They travel through lymph before venous blood."},{"label":"Directly into the aorta as free triglycerides","correct":false,"feedback":"They are packaged in enterocytes and enter lymph first."},{"label":"Into the urinary bladder","correct":false,"feedback":"The urinary tract is not an absorption route for dietary lipid."}]}},{"id":"l16-m6","chapter":null,"chapterSummary":null,"title":"The large intestine recovers fluid and forms stool","highYield":"The colon reabsorbs water and electrolytes, houses microbes, compacts contents, and coordinates elimination.","teach":["Material entering the large intestine contains water, electrolytes, undigested components, microbes, shed cells, and secretions. The colon absorbs much of the remaining water and electrolytes, secretes mucus, and moves contents through haustral mixing and mass movements toward the rectum.","Colonic microbes ferment selected carbohydrates and produce metabolites, including short-chain fatty acids, while also contributing to some vitamin production. Microbiome composition varies widely; one stool pattern cannot define a 'healthy microbiome,' and broad claims about cleansing or toxins are not supported by colon anatomy."],"keyPoints":["Colon recovers water and electrolytes.","Mucus supports passage.","Microbes ferment selected substrates.","Rectal filling participates in the defecation reflex."],"visual":{"title":"Colon functions","kind":"map","items":[{"label":"Recover","detail":"Water and electrolytes"},{"label":"Ferment","detail":"Microbial use of selected carbohydrates"},{"label":"Compact","detail":"Formation of fecal material"},{"label":"Propel","detail":"Movement toward rectum and elimination"}]},"mnemonic":{"title":"RFCP","cue":"Recover · Ferment · Compact · Propel","explanation":"Four colon functions without calling it a waste-storage tube only."},"goodToKnow":"Stool frequency varies; a change from a person's usual pattern plus symptoms is often more informative than one universal number.","act":{"type":"choice","prompt":"Which is a major function of the large intestine?","options":[{"label":"Recovery of water and electrolytes","correct":true,"feedback":"Correct. The colon helps conserve fluid while forming stool."},{"label":"Production of pancreatic enzymes","correct":false,"feedback":"Those enzymes come from the pancreas."},{"label":"Most amino-acid absorption","correct":false,"feedback":"Most nutrient absorption occurs in the small intestine."}]}},{"id":"intestinal-match","title":"Match it: Two absorption routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein","Chylomicrons containing long-chain dietary lipid → lymph → venous blood","B12–intrinsic factor complex and bile-salt recovery"],"items":[{"label":"Blood capillary route","category":0,"feedback":"Blood capillary route: Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","category":1,"feedback":"Lacteal route: Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","category":2,"feedback":"Ileal specialities: B12–intrinsic factor complex and bile-salt recovery"}]}},{"id":"l16-m7","chapter":"Connect foods to pathways","chapterSummary":"Follow macronutrient digestion and use a scoped, evidence-aware nutrition lens.","title":"Each macronutrient needs a different breakdown strategy","highYield":"Carbohydrate becomes absorbable monosaccharides, protein becomes amino acids and small peptides, and triglyceride becomes lipid products before repackaging.","teach":["Starch digestion begins with amylase and is completed by pancreatic and brush-border enzymes to monosaccharides. Protein is denatured in the stomach and hydrolyzed by gastric, pancreatic, and brush-border proteases into amino acids and small peptides. These products use specific transport systems to enter enterocytes and then portal blood.","Fat requires emulsification by bile and hydrolysis mainly by pancreatic lipase. Lipid products form micelles that approach the enterocyte membrane, then are absorbed, reassembled, and packaged into chylomicrons. The pathway explains why bile and pancreatic function matter without implying that dietary fat is inherently difficult or harmful."],"keyPoints":["Starch → monosaccharides.","Protein → amino acids and small peptides.","Triglycerides → fatty acids/monoglycerides → reassembly.","Transporters and packaging complete absorption."],"visual":{"title":"Macronutrient pathways","kind":"comparison","items":[{"label":"Carbohydrate","detail":"Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","detail":"Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","detail":"Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]},"mnemonic":{"title":"C-P-F: Cut, Process, Ferry","cue":"Cut bonds · Process at brush border · Ferry through blood or lymph","explanation":"Use the same logic while keeping each nutrient's products and route distinct."},"goodToKnow":"Fibre is not digested into glucose by human enzymes; fermentable fibre can be metabolized by colonic microbes.","act":{"type":"choice","prompt":"Which pairing is correct?","options":[{"label":"Bile emulsifies lipid; pancreatic lipase hydrolyzes triglyceride","correct":true,"feedback":"Correct. Physical dispersion and chemical digestion are different jobs."},{"label":"Pepsin digests starch into glucose","correct":false,"feedback":"Pepsin is a protease."},{"label":"Amylase converts protein into amino acids","correct":false,"feedback":"Amylase acts on starch."}]}},{"id":"l16-m8","chapter":null,"chapterSummary":null,"title":"Assessment separates intake, digestion, absorption, and use","highYield":"A nutrient problem can arise before eating, during digestion, at absorption, in transport, or during cellular use.","teach":["Nutritional status is not determined by intake alone. Food access and appetite affect intake; oral and GI function affect digestion; mucosal surface and transporters affect absorption; liver and circulation affect distribution; and cells must use or store what arrives. Losses and altered needs add further branches.","This pathway keeps counselling focused. Ask what the person eats, what happens after eating, how long the pattern has persisted, what medical evaluation exists, and which practical barriers matter. Avoid diagnosing malabsorption or prescribing restrictive diets from symptoms alone."],"keyPoints":["Availability precedes intake.","Digestion and absorption are distinct.","Transport and cellular use follow absorption.","Losses and needs change status."],"visual":{"title":"Nutrition status pathway","kind":"flow","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]},"mnemonic":{"title":"A-C-D-A-U","cue":"Available · Consumed · Digested · Absorbed · Used","explanation":"Locate the possible bottleneck before choosing an intervention."},"goodToKnow":"A normal-looking diet does not rule out impaired absorption, and GI symptoms do not prove malabsorption.","act":{"type":"choice","prompt":"A client eats adequate B12 but has impaired intrinsic-factor production. Which stage is most directly affected?","options":[{"label":"Absorption","correct":true,"feedback":"Correct. Intake may be adequate while ileal B12 uptake is impaired."},{"label":"Food availability","correct":false,"feedback":"The nutrient is available and consumed in this example."},{"label":"Chewing","correct":false,"feedback":"The mechanism described is not oral processing."}]}},{"id":"nutrient-integration-order","title":"Put it in order: Nutrition status pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]}},{"id":"nutrient-integration-match","title":"Match it: Macronutrient pathways","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Amylases and brush-border enzymes → monosaccharides → portal blood","Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood","Bile + lipase → micelles → enterocyte → chylomicron → lymph"],"items":[{"label":"Carbohydrate","category":0,"feedback":"Carbohydrate: Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","category":1,"feedback":"Protein: Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","category":2,"feedback":"Fat: Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]}}],"flashcards":[{"front":"Mucosa","back":"The innermost GI layer responsible for protection, secretion, and absorption."},{"front":"Peristalsis","back":"Coordinated wave-like contraction that propels contents along the digestive tract."},{"front":"Intrinsic factor","back":"A gastric protein required for efficient vitamin B12 absorption in the ileum."},{"front":"Pepsin","back":"A gastric protease activated in acidic conditions that begins protein digestion."},{"front":"Bile","back":"A liver secretion that emulsifies lipid and supports micelle formation; it is not an enzyme."},{"front":"Pancreatic bicarbonate","back":"An alkaline secretion that helps neutralize acidic chyme in the duodenum."},{"front":"Villus","back":"A projection of small-intestinal mucosa containing blood capillaries and a lacteal."},{"front":"Chylomicron","back":"A lipoprotein particle carrying absorbed long-chain dietary lipid from enterocyte into lymph."},{"front":"Hepatic portal vein","back":"Vessel delivering blood from digestive organs to the liver before systemic return."},{"front":"Segmentation","back":"Local intestinal mixing contractions that expose contents to enzymes and absorptive surfaces."},{"front":"Colon","back":"Large-intestinal region that recovers water/electrolytes, houses microbes, and compacts stool."},{"front":"Bioavailability","back":"The fraction of an ingested substance that becomes available for absorption and use, shaped by food and host factors."}],"quiz":[],"caseStudy":{"title":"A restrictive diet built from symptoms alone","scenario":"A client reports bloating, intermittent diarrhea, fatigue, and an unplanned weight change. They have removed gluten, dairy, legumes, fruit, and several vegetables after online advice, but symptoms continue. No diagnostic evaluation has occurred.","prompts":["Which stages of the nutrition-status pathway could contribute?","Which red flags or duration details should be clarified?","How might broad restriction create additional nutrition risk?","What can be documented and supported while medical assessment proceeds?"],"takeaway":"GI symptoms rarely identify one mechanism by themselves. Protect intake, document the pattern, avoid escalating unsupported restrictions, and coordinate appropriate assessment."}},{"n":17,"title":"The Respiratory System","kicker":"Trace air through conducting and respiratory zones.","duration":"75–95 minutes","steps":[{"id":"l17-m1","chapter":"Follow the conducting zone","chapterSummary":"Learn how the upper and lower airways condition air while protecting a delicate exchange surface.","title":"The upper airway warms, humidifies, filters, and senses","highYield":"The nose and pharynx prepare inspired air before it reaches the gas-exchange surface.","teach":["Air entering the nasal cavity encounters hairs, mucus, a vascular mucosa, and turbinates that create turbulence. These features trap particles and increase contact for warming and humidification. Olfactory receptors occupy a specialized superior region rather than the entire nasal lining.","The pharynx is shared by respiratory and digestive pathways. The nasopharynx carries air, while lower regions also conduct swallowed material. This shared architecture explains why coordination of swallowing, laryngeal closure, and breathing is essential for airway protection."],"keyPoints":["Nasal turbinates increase contact area.","Mucus traps particles.","Rich blood supply warms air.","The pharynx is a shared passage."],"visual":{"title":"Upper-airway tasks","kind":"map","items":[{"label":"Filter","detail":"Hair, mucus, and cilia trap material"},{"label":"Warm","detail":"Vascular mucosa transfers heat"},{"label":"Humidify","detail":"Moist surfaces add water"},{"label":"Sense","detail":"Olfactory epithelium detects odorants"}]},"mnemonic":{"title":"FWHS","cue":"Filter · Warm · Humidify · Sense","explanation":"Four functions before air reaches the larynx."},"goodToKnow":"Breathing through the mouth can bypass some nasal conditioning, but mouth breathing alone does not identify why nasal airflow is limited.","act":{"type":"choice","prompt":"What is a main function of the nasal turbinates?","options":[{"label":"Create airflow turbulence and increase mucosal contact","correct":true,"feedback":"Correct. This supports warming, humidifying, and filtering."},{"label":"Exchange oxygen directly with systemic blood","correct":false,"feedback":"Gas exchange occurs mainly in alveoli."},{"label":"Produce surfactant","correct":false,"feedback":"Alveolar type II cells produce pulmonary surfactant."}]}},{"id":"l17-m2","chapter":null,"chapterSummary":null,"title":"Larynx, trachea, and bronchi keep a route open","highYield":"Cartilage maintains airway patency while branching, smooth muscle, mucus, and cilia shape airflow and clearance.","teach":["The larynx protects the lower airway and houses the vocal folds. During swallowing, coordinated elevation and closure help direct material away from the trachea. The trachea is reinforced by C-shaped cartilage rings; its open posterior portion allows the esophagus room to expand.","The trachea branches into main bronchi, then smaller bronchi and bronchioles. Cartilage becomes less prominent with branching, while smooth muscle becomes important in controlling bronchiolar diameter. Ciliated epithelium and mucus form a clearance system that moves trapped material toward the pharynx."],"keyPoints":["Larynx supports voice and airway protection.","Tracheal cartilage limits collapse.","Bronchi branch into bronchioles.","Cilia move mucus toward the pharynx."],"visual":{"title":"Branching airway","kind":"flow","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]},"mnemonic":{"title":"L-T-B-B","cue":"Larynx · Trachea · Bronchi · Bronchioles","explanation":"Follow the branches before reaching respiratory bronchioles and alveoli."},"goodToKnow":"The right main bronchus is generally wider and more vertical, which helps explain why aspirated material often enters the right side.","act":{"type":"choice","prompt":"Why are tracheal cartilage rings C-shaped rather than complete circles?","options":[{"label":"They support the airway while allowing the esophagus behind it to expand","correct":true,"feedback":"Correct. The open posterior wall provides flexibility beside the esophagus."},{"label":"They allow blood to enter the airway","correct":false,"feedback":"Blood should remain within vessels."},{"label":"They create alveolar surfactant","correct":false,"feedback":"Surfactant is produced in alveoli, not tracheal cartilage."}]}},{"id":"airway-order","title":"Put it in order: Branching airway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]}},{"id":"airway-match","title":"Match it: Upper-airway tasks","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hair, mucus, and cilia trap material","Vascular mucosa transfers heat","Moist surfaces add water","Olfactory epithelium detects odorants"],"items":[{"label":"Sense","category":3,"feedback":"Sense: Olfactory epithelium detects odorants"},{"label":"Humidify","category":2,"feedback":"Humidify: Moist surfaces add water"},{"label":"Warm","category":1,"feedback":"Warm: Vascular mucosa transfers heat"},{"label":"Filter","category":0,"feedback":"Filter: Hair, mucus, and cilia trap material"}]}},{"id":"l17-m3","chapter":"Reach the alveolar interface","chapterSummary":"Connect lung architecture, pleura, alveoli, and diffusion.","title":"Lungs pair branching trees with pleural mechanics","highYield":"The visceral and parietal pleura create a low-friction, pressure-coupled interface between lung and thoracic wall.","teach":["Each lung contains lobes supplied by branching bronchi, vessels, and nerves. The visceral pleura adheres to the lung surface, while parietal pleura lines the thoracic cavity. A thin fluid layer reduces friction and helps couple lung movement to changes in the chest wall.","The pleural space normally has pressure below atmospheric pressure, helping keep lungs expanded against the thoracic wall. Loss of this pressure relationship can allow lung recoil and impaired expansion. Pleural mechanics are different from airflow through bronchi and from diffusion at alveoli."],"keyPoints":["Visceral pleura covers lung.","Parietal pleura lines thorax.","Pleural fluid reduces friction.","Pressure coupling helps lungs follow chest expansion."],"visual":{"title":"Pleural relationship","kind":"layers","items":[{"label":"Thoracic wall","detail":"Moves during breathing"},{"label":"Parietal pleura","detail":"Lines the cavity"},{"label":"Pleural fluid space","detail":"Low-friction pressure coupling"},{"label":"Visceral pleura","detail":"Covers lung surface"},{"label":"Lung","detail":"Elastic tissue containing airways and alveoli"}]},"mnemonic":{"title":"Parietal = perimeter","cue":"P lines the perimeter; visceral visits the organ","explanation":"A spatial cue for the two pleural layers."},"goodToKnow":"Pleural fluid is a thin lubricating layer, not a large normal reservoir around the lungs.","act":{"type":"choice","prompt":"Which pleural layer is directly attached to the lung surface?","options":[{"label":"Visceral pleura","correct":true,"feedback":"Correct. The visceral layer follows the lung surface."},{"label":"Parietal pleura","correct":false,"feedback":"The parietal layer lines the thoracic cavity."},{"label":"Pericardium","correct":false,"feedback":"The pericardium surrounds the heart."}]}},{"id":"l17-m4","chapter":null,"chapterSummary":null,"title":"Alveoli trade distance for area","highYield":"A very thin alveolar–capillary membrane and enormous surface area support rapid diffusion.","teach":["Respiratory bronchioles lead to alveolar ducts and sacs. Alveoli are lined mainly by thin type I cells, while type II cells produce surfactant. Closely applied capillary endothelium and shared thin barriers minimize diffusion distance between air and blood.","Oxygen diffuses down its partial-pressure gradient into blood, and carbon dioxide diffuses in the opposite direction. Surfactant reduces surface tension and helps prevent small alveoli from collapsing. Efficient exchange also requires ventilation, perfusion, adequate surface area, and a thin intact membrane."],"keyPoints":["Type I cells form much of the exchange surface.","Type II cells produce surfactant.","Diffusion follows partial-pressure gradients.","Ventilation and perfusion must be reasonably matched."],"visual":{"title":"Alveolar exchange unit","kind":"layers","items":[{"label":"Alveolar air","detail":"Source of inspired oxygen"},{"label":"Type I epithelium","detail":"Thin gas-exchange surface"},{"label":"Fused basement region","detail":"Minimal diffusion distance"},{"label":"Capillary endothelium","detail":"Thin vessel wall"},{"label":"Erythrocyte","detail":"Hemoglobin binds oxygen"}]},"mnemonic":{"title":"A-T-M","cue":"Area · Thinness · Match","explanation":"Exchange needs large area, a thin membrane, and ventilation–perfusion matching."},"goodToKnow":"More ventilation does not help an alveolus that has no blood flow, and more blood flow does not help an alveolus that receives no fresh air.","act":{"type":"choice","prompt":"What is surfactant's main mechanical contribution?","options":[{"label":"It lowers alveolar surface tension","correct":true,"feedback":"Correct. This supports alveolar stability and reduces work of inflation."},{"label":"It carries oxygen through plasma","correct":false,"feedback":"Hemoglobin performs most oxygen transport."},{"label":"It contracts the diaphragm","correct":false,"feedback":"The phrenic nerves activate the diaphragm."}]}},{"id":"exchange-match","title":"Match it: Pleural relationship","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Moves during breathing","Lines the cavity","Low-friction pressure coupling","Covers lung surface","Elastic tissue containing airways and alveoli"],"items":[{"label":"Parietal pleura","category":1,"feedback":"Parietal pleura: Lines the cavity"},{"label":"Lung","category":4,"feedback":"Lung: Elastic tissue containing airways and alveoli"},{"label":"Pleural fluid space","category":2,"feedback":"Pleural fluid space: Low-friction pressure coupling"},{"label":"Thoracic wall","category":0,"feedback":"Thoracic wall: Moves during breathing"},{"label":"Visceral pleura","category":3,"feedback":"Visceral pleura: Covers lung surface"}]}},{"id":"l17-m5","chapter":"Move air and gases","chapterSummary":"Separate ventilation mechanics from exchange and transport.","title":"Inspiration follows expansion and falling pressure","highYield":"Diaphragm contraction expands thoracic volume, lowers alveolar pressure, and draws air inward.","teach":["During quiet inspiration, the diaphragm contracts and descends while external intercostal activity expands the rib cage. Greater thoracic volume lowers pressure within the lungs below atmospheric pressure, so air flows inward. Air moves because of a pressure gradient, not because lungs actively pull individual oxygen molecules.","Quiet expiration is largely passive as inspiratory muscles relax and elastic tissues recoil, raising alveolar pressure above atmospheric pressure. Forced breathing recruits additional muscles. Airway resistance, tissue elasticity, and surface tension all influence the work required."],"keyPoints":["Volume and pressure change inversely.","Diaphragm is the principal quiet-inspiration muscle.","Quiet expiration uses elastic recoil.","Air flows down a pressure gradient."],"visual":{"title":"One quiet breath","kind":"comparison","items":[{"label":"Inspiration","detail":"Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","detail":"Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","detail":"Narrower airways require a larger pressure difference"}]},"mnemonic":{"title":"Expand–Drop–Enter","cue":"EDE","explanation":"Thorax expands, pressure drops, air enters."},"goodToKnow":"Deep breathing changes ventilation, but oxygen delivery also depends on alveolar exchange, blood flow, hemoglobin, and tissue demand.","act":{"type":"choice","prompt":"What immediately draws air into the lungs during quiet inspiration?","options":[{"label":"Alveolar pressure falls below atmospheric pressure","correct":true,"feedback":"Correct. Air moves down the resulting pressure gradient."},{"label":"Carbon dioxide stops being produced","correct":false,"feedback":"Metabolism continues; pressure change drives airflow."},{"label":"The pleural membranes open to outside air","correct":false,"feedback":"The pleural space normally remains closed."}]}},{"id":"l17-m6","chapter":null,"chapterSummary":null,"title":"Ventilation, respiration, and transport are separate steps","highYield":"Airflow, lung exchange, blood transport, and tissue exchange are linked but not interchangeable.","teach":["Ventilation is movement of air into and out of lungs. External respiration is gas exchange between alveoli and pulmonary capillary blood. Blood then transports gases, mostly with oxygen bound to hemoglobin and carbon dioxide carried mainly as bicarbonate.","Internal respiration is exchange between systemic capillary blood and tissues. Cells use oxygen in aerobic metabolism and produce carbon dioxide. A problem at any step can limit overall delivery, so a normal breathing rate alone does not prove normal tissue oxygenation."],"keyPoints":["Ventilation moves air.","External respiration exchanges gases at lungs.","Blood transports gases.","Internal respiration exchanges gases with tissues."],"visual":{"title":"Oxygen pathway","kind":"flow","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]},"mnemonic":{"title":"VETDU","cue":"Ventilate · Exchange · Transport · Deliver · Use","explanation":"Locate the step before explaining low oxygen delivery."},"goodToKnow":"Most carbon dioxide is transported as bicarbonate after reactions within erythrocytes, not simply dissolved as gas.","act":{"type":"choice","prompt":"What is external respiration?","options":[{"label":"Gas exchange between alveoli and pulmonary capillary blood","correct":true,"feedback":"Correct. It occurs across the respiratory membrane."},{"label":"Air moving through the nose","correct":false,"feedback":"That is ventilation through the conducting zone."},{"label":"Cellular ATP production","correct":false,"feedback":"That is cellular metabolism using delivered oxygen."}]}},{"id":"ventilation-order","title":"Put it in order: Oxygen pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]}},{"id":"ventilation-match","title":"Match it: One quiet breath","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Thorax expands → alveolar pressure falls → air enters","Elastic recoil reduces volume → alveolar pressure rises → air leaves","Narrower airways require a larger pressure difference"],"items":[{"label":"Inspiration","category":0,"feedback":"Inspiration: Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","category":1,"feedback":"Expiration: Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","category":2,"feedback":"Resistance: Narrower airways require a larger pressure difference"}]}},{"id":"l17-m7","chapter":"Measure and integrate","chapterSummary":"Use lung volumes as functional measurements and connect respiratory control to homeostasis.","title":"Volumes combine into capacities","highYield":"A volume is one measurable compartment; a capacity is the sum of two or more lung volumes.","teach":["Tidal volume is air moved during a quiet breath. Inspiratory and expiratory reserve volumes describe additional air that can be moved beyond a quiet breath. Residual volume remains after maximal expiration and cannot be measured by simple spirometry.","Vital capacity combines inspiratory reserve, tidal volume, and expiratory reserve. Total lung capacity also includes residual volume. Values vary with body size, age, sex-related anatomy, posture, effort, conditioning, and disease, so a measured result must be compared with appropriate reference values and test quality."],"keyPoints":["Tidal volume is a quiet breath.","Reserve volumes extend beyond tidal breathing.","Residual volume remains after maximal exhalation.","Capacities combine volumes."],"visual":{"title":"Stacked lung volumes","kind":"layers","items":[{"label":"Inspiratory reserve","detail":"Additional volume inhaled above tidal inspiration"},{"label":"Tidal volume","detail":"Quiet breath"},{"label":"Expiratory reserve","detail":"Additional volume exhaled below tidal expiration"},{"label":"Residual volume","detail":"Air remaining after maximal exhalation"}]},"mnemonic":{"title":"VC = IRV + TV + ERV","cue":"Vital uses the three movable volumes","explanation":"Residual volume is not part of vital capacity."},"goodToKnow":"Simple spirometry cannot directly measure residual volume, so it also cannot directly measure capacities that include it.","act":{"type":"choice","prompt":"Which volume remains after the strongest possible exhalation?","options":[{"label":"Residual volume","correct":true,"feedback":"Correct. It helps keep alveoli from emptying completely."},{"label":"Tidal volume","correct":false,"feedback":"Tidal volume is a quiet breath."},{"label":"Inspiratory reserve volume","correct":false,"feedback":"That is additional inhaled volume above a normal inspiration."}]}},{"id":"l17-m8","chapter":null,"chapterSummary":null,"title":"Respiratory control responds strongly to carbon dioxide","highYield":"Brainstem networks adjust ventilation using chemical and mechanical feedback; rising carbon dioxide is a major normal drive.","teach":["Respiratory rhythm is generated by interacting brainstem networks and modified by sensory input. Central chemoreceptors respond indirectly to carbon-dioxide–related changes in cerebrospinal-fluid pH, while peripheral chemoreceptors respond to arterial oxygen, carbon dioxide, and pH.","Exercise increases ventilation through feed-forward motor signals and feedback from working tissues. The respiratory, cardiovascular, renal, and nervous systems cooperate to regulate gases and acid–base conditions. Nutrition supports energy metabolism and respiratory muscle function, but does not replace evaluation of persistent cough or breathlessness."],"keyPoints":["Brainstem networks generate rhythm.","Carbon dioxide/pH strongly influence normal ventilation.","Peripheral chemoreceptors also sense low arterial oxygen.","Respiratory and renal systems coordinate acid–base balance."],"visual":{"title":"Control loop","kind":"flow","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]},"mnemonic":{"title":"Sense–Set–Send","cue":"Sensors report · brainstem sets · motor nerves send","explanation":"A short respiratory-control loop."},"goodToKnow":"In chronic respiratory disease, ventilatory control can be altered; simplified statements that oxygen 'turns off breathing' are unsafe.","act":{"type":"choice","prompt":"Which chemical change is a major normal stimulus for increased ventilation?","options":[{"label":"Rising carbon dioxide and associated fall in pH","correct":true,"feedback":"Correct. CO₂-related pH change strongly influences respiratory drive."},{"label":"A small rise in dietary fibre","correct":false,"feedback":"Fibre intake does not directly set the brainstem respiratory rhythm."},{"label":"Lower skin melanin","correct":false,"feedback":"Melanin does not regulate ventilation."}]}},{"id":"capacity-order","title":"Put it in order: Control loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]}},{"id":"capacity-match","title":"Match it: Stacked lung volumes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Additional volume inhaled above tidal inspiration","Quiet breath","Additional volume exhaled below tidal expiration","Air remaining after maximal exhalation"],"items":[{"label":"Residual volume","category":3,"feedback":"Residual volume: Air remaining after maximal exhalation"},{"label":"Expiratory reserve","category":2,"feedback":"Expiratory reserve: Additional volume exhaled below tidal expiration"},{"label":"Tidal volume","category":1,"feedback":"Tidal volume: Quiet breath"},{"label":"Inspiratory reserve","category":0,"feedback":"Inspiratory reserve: Additional volume inhaled above tidal inspiration"}]}}],"flashcards":[{"front":"Conducting zone","back":"Airways that move, warm, humidify, and filter air without direct gas exchange."},{"front":"Mucociliary escalator","back":"Cilia moving mucus and trapped material toward the pharynx."},{"front":"Visceral pleura","back":"Serous membrane covering the lung surface."},{"front":"Type I alveolar cell","back":"Thin epithelial cell forming most of the gas-exchange surface."},{"front":"Type II alveolar cell","back":"Cell that produces pulmonary surfactant."},{"front":"Surfactant","back":"Material that lowers alveolar surface tension and improves stability."},{"front":"Ventilation","back":"Movement of air into and out of lungs."},{"front":"External respiration","back":"Gas exchange between alveoli and pulmonary capillary blood."},{"front":"Internal respiration","back":"Gas exchange between systemic capillary blood and tissues."},{"front":"Tidal volume","back":"Air moved during a quiet breath."},{"front":"Residual volume","back":"Air remaining after maximal exhalation."},{"front":"Vital capacity","back":"Inspiratory reserve + tidal volume + expiratory reserve."}],"quiz":[],"caseStudy":{"title":"Breathlessness after 'just being out of shape'","scenario":"A client reports increasing shortness of breath during ordinary activity, a persistent cough, and new difficulty finishing meals because breathing feels hard. They ask for an energy supplement and assume deconditioning is the only cause.","prompts":["Which steps in VETDU could limit oxygen delivery?","Which symptoms and progression details change the urgency?","What nutrition risks can develop when breathing interferes with meals?","How can nutrition support occur without diagnosing or delaying respiratory assessment?"],"takeaway":"Breathlessness can arise at multiple respiratory, cardiovascular, hematologic, and metabolic steps. Progressive symptoms need clinical assessment; nutrition support can address intake barriers alongside, not instead of, that care."}},{"n":18,"title":"The Urinary System","kicker":"Identify the organs of the urinary system and explain how the kidneys maintain internal balance.","duration":"90–110 minutes","steps":[{"id":"l18-m1","chapter":"Orient to the kidneys","chapterSummary":"Start with the system's homeostatic jobs, then locate the external and internal structures that support them.","title":"The kidneys edit blood, not merely remove waste","highYield":"Kidneys continually adjust what stays in blood and what leaves in urine, supporting volume, composition, pH, endocrine signalling, and waste removal.","teach":["The urinary system includes two kidneys, two ureters, the urinary bladder, and the urethra. The kidneys receive a large blood supply and produce urine; the ureters transport it, the bladder stores it, and the urethra carries it outside. This sequence is simple, but urine formation is selective rather than a passive draining process.","By filtering plasma and then reclaiming or adding selected substances, kidneys regulate water, sodium, potassium, acid–base balance, and many dissolved wastes. They also release renin and erythropoietin and participate in vitamin D activation. The lungs, skin, liver, and intestines also remove particular wastes, yet they cannot replace the full range of kidney functions."],"keyPoints":["Kidneys form urine from filtered blood plasma.","Ureters transport; bladder stores; urethra eliminates.","Kidneys regulate fluid, electrolytes, and acid–base balance.","Renin, erythropoietin, and vitamin D activation are additional renal roles."],"visual":{"title":"Four organs, four main jobs","kind":"flow","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]},"mnemonic":{"title":"K-U-B-U","cue":"Kidneys edit · Ureters move · Bladder holds · Urethra exits","explanation":"Use the route to separate urine formation from transport and storage."},"goodToKnow":"Urine colour and volume change with hydration, diet, medicines, temperature, and other factors; neither alone diagnoses kidney function.","act":{"type":"choice","prompt":"Which urinary organ makes urine by selectively processing filtered blood?","options":[{"label":"Kidneys","correct":true,"feedback":"Correct. Nephrons within the kidneys form urine."},{"label":"Ureters","correct":false,"feedback":"Ureters transport urine but do not form it."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine until voiding."}]}},{"id":"l18-m2","chapter":null,"chapterSummary":null,"title":"Kidney regions create a collecting funnel","highYield":"Cortex and medulla contain nephron structures; pyramids drain through papillae and calyces into the renal pelvis.","teach":["The kidneys lie behind the peritoneal lining on the posterior abdominal wall, with the right usually slightly lower because of the liver. At the medial hilum, the renal artery, renal vein, nerves, lymphatics, and ureter enter or leave. A fibrous renal capsule, cushioning adipose tissue, and renal fascia protect and anchor each kidney.","Internally, the cortex forms the outer region and extends between medullary pyramids as renal columns. Each pyramid ends at a papilla, where collecting ducts empty into a minor calyx. Minor calyces join into major calyces, which feed the renal pelvis and then the ureter. This is the urine route after nephron processing is complete."],"keyPoints":["Kidneys are retroperitoneal.","The hilum is the gateway for vessels, nerves, lymphatics, and ureter.","Cortex surrounds medullary pyramids and extends as columns.","Papilla → minor calyx → major calyx → renal pelvis → ureter."],"visual":{"title":"From kidney tissue to ureter","kind":"sequence","items":[{"label":"Cortex/medulla","detail":"Nephrons and collecting ducts process filtrate"},{"label":"Papilla","detail":"Tip of a medullary pyramid"},{"label":"Minor calyx","detail":"Receives urine from one papillary region"},{"label":"Major calyx","detail":"Collects from minor calyces"},{"label":"Renal pelvis","detail":"Funnel leading to the ureter"}]},"mnemonic":{"title":"Please Make More Renal Urine","cue":"Papilla · Minor calyx · Major calyx · Renal pelvis · Ureter","explanation":"A route cue for urine after it leaves collecting ducts."},"goodToKnow":"The adrenal glands sit near the kidneys but are endocrine organs with distinct functions; their position does not make them part of the urinary tract.","act":{"type":"choice","prompt":"What structure receives urine immediately after a renal papilla?","options":[{"label":"Minor calyx","correct":true,"feedback":"Correct. Papillary ducts drain into a minor calyx."},{"label":"Renal artery","correct":false,"feedback":"The renal artery supplies blood, not urine."},{"label":"Urinary bladder","correct":false,"feedback":"Urine reaches the bladder only after the renal pelvis and ureter."}]}},{"id":"homeostasis-anatomy-order","title":"Put it in order: Four organs, four main jobs","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]}},{"id":"l18-m3","chapter":"Build the nephron map","chapterSummary":"Connect the renal corpuscle, tubule, collecting system, and two capillary beds before studying transport.","title":"A nephron begins with a filter and continues as a tubule","highYield":"The renal corpuscle filters; the renal tubule modifies; the collecting duct makes final water and solute adjustments.","teach":["A nephron's renal corpuscle consists of a capillary tuft called the glomerulus surrounded by the glomerular capsule. Blood enters through an afferent arteriole and leaves through an efferent arteriole. The filtration barrier separates blood cells and most large proteins from water and smaller dissolved substances that enter capsular space.","Filtrate then passes through the proximal convoluted tubule, descending and ascending limbs of the nephron loop, and distal convoluted tubule. The distal tubule empties into a collecting duct shared by several nephrons. Segment-specific permeability and transport let the kidney recover useful substances, remove additional wastes, and vary the final urine concentration."],"keyPoints":["Renal corpuscle = glomerulus plus glomerular capsule.","Afferent enters; efferent exits.","Tubule route: proximal → loop → distal.","Collecting ducts receive fluid from multiple nephrons."],"visual":{"title":"Nephron route","kind":"flow","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]},"mnemonic":{"title":"Filter, Proximal, Loop, Distal, Collect","cue":"F-P-L-D-C","explanation":"Follow filtrate through the nephron without confusing it with blood flow."},"goodToKnow":"The filtrate is not yet urine. Its composition changes substantially as it passes through the tubule and collecting duct.","act":{"type":"choice","prompt":"Which vessel carries blood away from the glomerulus?","options":[{"label":"Efferent arteriole","correct":true,"feedback":"Correct. Think E for exit."},{"label":"Afferent arteriole","correct":false,"feedback":"Afferent blood arrives at the glomerulus."},{"label":"Ureter","correct":false,"feedback":"The ureter carries urine, not blood."}]}},{"id":"l18-m4","chapter":null,"chapterSummary":null,"title":"One arteriole links two capillary networks","highYield":"Glomerular capillaries support filtration; peritubular capillaries and vasa recta support exchange with the tubule.","teach":["Renal blood travels from the renal artery through progressively smaller branches to afferent arterioles and glomerular capillaries. Instead of draining directly into a vein, the glomerulus drains through the efferent arteriole. That vessel then forms peritubular capillaries around cortical tubules and, for deeper nephrons, long vasa recta alongside the nephron loop.","This two-capillary arrangement serves two different tasks. Relatively high pressure in the glomerulus favours filtration, while vessels around the tubule receive reabsorbed water and solutes and deliver substances for secretion. Their proximity also helps preserve the medullary gradient needed to conserve water."],"keyPoints":["Renal artery branches ultimately supply afferent arterioles.","Glomerulus lies between afferent and efferent arterioles.","Peritubular capillaries exchange with cortical tubules.","Vasa recta support deep loops and medullary gradients."],"visual":{"title":"Blood–filtrate partnership","kind":"parallel","items":[{"label":"Blood path","detail":"Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","detail":"Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","detail":"Reabsorption moves toward blood; secretion moves toward tubule"}]},"mnemonic":{"title":"A-G-E-P","cue":"Afferent · Glomerulus · Efferent · Peritubular","explanation":"The core renal microcirculation sequence."},"goodToKnow":"Juxtamedullary nephrons have long loops extending deep into the medulla and are especially important for producing concentrated urine.","act":{"type":"choice","prompt":"Why is the efferent arteriole unusual in this circulation?","options":[{"label":"It leaves one capillary bed and then forms another","correct":true,"feedback":"Correct. It links glomerular filtration to peritubular exchange."},{"label":"It carries urine into the bladder","correct":false,"feedback":"Arterioles carry blood."},{"label":"It is the only vessel containing red blood cells","correct":false,"feedback":"Red blood cells normally remain throughout the blood vessels."}]}},{"id":"nephron-map-order","title":"Put it in order: Nephron route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]}},{"id":"nephron-map-match","title":"Match it: Blood–filtrate partnership","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins","Capsule → proximal tubule → loop → distal tubule → collecting duct","Reabsorption moves toward blood; secretion moves toward tubule"],"items":[{"label":"Blood path","category":0,"feedback":"Blood path: Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","category":1,"feedback":"Filtrate path: Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","category":2,"feedback":"Cross-talk: Reabsorption moves toward blood; secretion moves toward tubule"}]}},{"id":"l18-m5","chapter":"Transform filtrate into urine","chapterSummary":"Use three directional processes and regulated water handling to explain how kidneys preserve balance.","title":"Filtration, reabsorption, and secretion have different directions","highYield":"Filtration enters the nephron, reabsorption returns to blood, and secretion adds from blood to tubular fluid.","teach":["Glomerular filtration uses blood pressure to move water and small solutes across the filtration barrier into capsular space. Cells and most large plasma proteins normally remain in the circulation. The resulting filtrate contains many useful substances as well as wastes, so filtration alone cannot produce an appropriate final urine.","Tubular reabsorption moves selected substances from tubular fluid through the epithelium and back to blood; most filtered water and solutes are reclaimed. Tubular secretion moves substances from peritubular blood into tubular fluid. Together, the three processes can be summarized as excretion equals filtration minus reabsorption plus secretion."],"keyPoints":["Filtration: blood → capsular space.","Reabsorption: tubule → blood.","Secretion: blood → tubule.","Excretion = filtered − reabsorbed + secreted."],"visual":{"title":"Three renal directions","kind":"equation","items":[{"label":"Filter","detail":"Glomerular blood → capsule"},{"label":"Reabsorb","detail":"Tubular fluid → peritubular blood"},{"label":"Secrete","detail":"Peritubular blood → tubular fluid"},{"label":"Excrete","detail":"What remains and leaves as urine"}]},"mnemonic":{"title":"F in, R return, S supplement","cue":"Filter in · Reabsorb returns · Secrete supplements","explanation":"Anchor each process to the direction relative to the nephron."},"goodToKnow":"A substance can be filtered and then partly reabsorbed, filtered and secreted, or handled differently along multiple nephron segments.","act":{"type":"choice","prompt":"Glucose moves from tubular fluid back into peritubular blood. What process is this?","options":[{"label":"Tubular reabsorption","correct":true,"feedback":"Correct. The substance returns from the tubule to blood."},{"label":"Glomerular filtration","correct":false,"feedback":"Filtration is the initial movement from glomerular blood to capsular space."},{"label":"Tubular secretion","correct":false,"feedback":"Secretion moves from blood into tubular fluid."}]}},{"id":"l18-m6","chapter":null,"chapterSummary":null,"title":"Hormones help match water and sodium output to need","highYield":"ADH primarily changes collecting-duct water permeability; aldosterone promotes sodium reabsorption and potassium secretion in distal segments.","teach":["The proximal tubule performs bulk reabsorption, while the nephron loop establishes a concentration gradient in the medulla. The descending limb is relatively water-permeable; the ascending limb moves salts but is much less permeable to water. This countercurrent organization allows later segments to vary how much water is recovered.","Antidiuretic hormone increases water permeability in the late distal tubule and collecting duct, conserving water when appropriate. Aldosterone supports sodium reabsorption and potassium secretion in distal segments; water may follow retained sodium. Renin-angiotensin-aldosterone signalling, natriuretic peptides, sympathetic input, thirst, and circulation all contribute to fluid and pressure regulation."],"keyPoints":["The nephron loop helps create a medullary gradient.","ADH promotes regulated water reabsorption.","Aldosterone supports sodium retention and potassium secretion.","Renal, endocrine, cardiovascular, and nervous systems coordinate fluid balance."],"visual":{"title":"Segment and signal","kind":"map","items":[{"label":"Proximal tubule","detail":"Bulk recovery of water and many solutes"},{"label":"Nephron loop","detail":"Builds medullary osmotic gradient"},{"label":"ADH","detail":"Raises late-nephron water permeability"},{"label":"Aldosterone","detail":"Promotes distal sodium reabsorption and potassium secretion"}]},"mnemonic":{"title":"ADH adds water doors","cue":"More ADH → more aquaporin-mediated water recovery","explanation":"A functional cue; ADH does not add water to the body, it changes renal retention."},"goodToKnow":"Thirst and urine concentration respond to many signals. A universal water target ignores body size, climate, activity, food moisture, pregnancy, lactation, and medical conditions.","act":{"type":"choice","prompt":"Which hormone most directly increases collecting-duct water permeability?","options":[{"label":"Antidiuretic hormone","correct":true,"feedback":"Correct. ADH promotes insertion of water channels in responsive cells."},{"label":"Erythropoietin","correct":false,"feedback":"Erythropoietin stimulates red-cell production."},{"label":"Insulin","correct":false,"feedback":"Insulin regulates fuel metabolism, not collecting-duct water permeability."}]}},{"id":"urine-formation-match","title":"Match it: Three renal directions","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Glomerular blood → capsule","Tubular fluid → peritubular blood","Peritubular blood → tubular fluid","What remains and leaves as urine"],"items":[{"label":"Excrete","category":3,"feedback":"Excrete: What remains and leaves as urine"},{"label":"Secrete","category":2,"feedback":"Secrete: Peritubular blood → tubular fluid"},{"label":"Reabsorb","category":1,"feedback":"Reabsorb: Tubular fluid → peritubular blood"},{"label":"Filter","category":0,"feedback":"Filter: Glomerular blood → capsule"}]}},{"id":"l18-m7","chapter":"Integrate regulation and elimination","chapterSummary":"Connect acid–base and endocrine roles to urine composition, transport, storage, and safe nutrition practice.","title":"Kidneys share regulation with lungs, blood, bone, and marrow","highYield":"Renal handling of hydrogen and bicarbonate supports pH; renin, erythropoietin, and vitamin D activation link kidneys to other systems.","teach":["Kidneys contribute to acid–base balance by secreting hydrogen ions, reclaiming filtered bicarbonate, and generating new bicarbonate. Their response is slower than respiratory changes but provides sustained control. This partnership explains why ventilation and renal function must be considered together when thinking about blood pH.","Renin participates in a cascade that supports blood-pressure and sodium regulation. Erythropoietin signals red bone marrow to increase red-cell production when renal oxygen sensing indicates need. The kidneys also complete a major activation step for vitamin D, linking renal function to calcium and phosphate balance and therefore to bone physiology."],"keyPoints":["Hydrogen secretion and bicarbonate handling support pH.","Renin participates in pressure and sodium regulation.","Erythropoietin links kidney oxygen sensing to marrow.","Vitamin D activation links kidneys to mineral and bone balance."],"visual":{"title":"Renal system links","kind":"network","items":[{"label":"Lungs","detail":"Rapid carbon-dioxide contribution to acid–base balance"},{"label":"Circulation","detail":"Renin-related pressure and perfusion regulation"},{"label":"Bone marrow","detail":"Erythropoietin supports erythrocyte production"},{"label":"Intestine/bone","detail":"Activated vitamin D supports calcium and phosphate handling"}]},"mnemonic":{"title":"R-E-D-A","cue":"Renin · Erythropoietin · vitamin D Activation · Acid–base","explanation":"Four kidney jobs beyond making urine."},"goodToKnow":"Renal disease can affect hemoglobin, minerals, and acid–base status; these are systemic effects, not separate coincidences.","act":{"type":"choice","prompt":"Which renal product stimulates red bone marrow to make more erythrocytes?","options":[{"label":"Erythropoietin","correct":true,"feedback":"Correct. It is produced largely by specialized cells in the kidney."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and supports lipid digestion."},{"label":"Surfactant","correct":false,"feedback":"Pulmonary surfactant is produced in the lungs."}]}},{"id":"l18-m8","chapter":null,"chapterSummary":null,"title":"Urine is propelled, stored, and released by coordinated muscle","highYield":"Ureteral peristalsis moves urine; bladder stretch initiates a spinal reflex; voluntary control acts mainly through the external urethral sphincter.","teach":["Urine moves from each renal pelvis through a ureter, propelled mainly by smooth-muscle peristalsis rather than gravity alone. Transitional epithelium lets the ureters and bladder stretch. The bladder's detrusor muscle expands during filling, while its trigone is defined by the two ureter openings and the urethral outlet.","As bladder stretch rises, sensory signals reach the spinal cord and higher centres. The micturition reflex contracts the detrusor and relaxes the involuntary internal sphincter, while learned control of the skeletal external sphincter helps delay or permit voiding. The urethra is shorter in typical female anatomy and longer in typical male anatomy, where it also serves the reproductive tract at different times."],"keyPoints":["Ureteral peristalsis moves urine to the bladder.","Transitional epithelium accommodates stretching.","Detrusor contraction supports voiding.","Internal sphincter is involuntary; external sphincter has voluntary control."],"visual":{"title":"Urine exit route","kind":"sequence","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]},"mnemonic":{"title":"Pelvis–Pipe–Pouch–Passage","cue":"Renal pelvis · ureter · bladder · urethra","explanation":"A plain-language route from kidney to exterior."},"goodToKnow":"Frequent urination can reflect fluid timing, caffeine, medicines, pregnancy, sleep patterns, infection, metabolic changes, and more; frequency alone does not identify the cause.","act":{"type":"choice","prompt":"Which muscle forms the main contractile wall of the bladder?","options":[{"label":"Detrusor muscle","correct":true,"feedback":"Correct. Its smooth-muscle layers contract during voiding."},{"label":"Diaphragm","correct":false,"feedback":"The diaphragm is the main inspiratory muscle."},{"label":"Myocardium","correct":false,"feedback":"Myocardium is cardiac muscle."}]}},{"id":"integration-elimination-order","title":"Put it in order: Urine exit route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]}},{"id":"integration-elimination-match","title":"Match it: Renal system links","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Rapid carbon-dioxide contribution to acid–base balance","Renin-related pressure and perfusion regulation","Erythropoietin supports erythrocyte production","Activated vitamin D supports calcium and phosphate handling"],"items":[{"label":"Intestine/bone","category":3,"feedback":"Intestine/bone: Activated vitamin D supports calcium and phosphate handling"},{"label":"Bone marrow","category":2,"feedback":"Bone marrow: Erythropoietin supports erythrocyte production"},{"label":"Circulation","category":1,"feedback":"Circulation: Renin-related pressure and perfusion regulation"},{"label":"Lungs","category":0,"feedback":"Lungs: Rapid carbon-dioxide contribution to acid–base balance"}]}}],"flashcards":[{"front":"Urinary system organs","back":"Two kidneys, two ureters, urinary bladder, and urethra."},{"front":"Hilum","back":"Medial kidney gateway where vessels, nerves, lymphatics, and ureter enter or leave."},{"front":"Renal cortex","back":"Outer kidney region containing renal corpuscles and portions of tubules."},{"front":"Renal medulla","back":"Inner region organized into pyramids containing loops and collecting ducts."},{"front":"Renal corpuscle","back":"Glomerulus plus glomerular capsule; site where filtrate first forms."},{"front":"Afferent arteriole","back":"Vessel carrying blood into the glomerulus."},{"front":"Tubular reabsorption","back":"Movement of substances from tubular fluid back to blood."},{"front":"Tubular secretion","back":"Movement of substances from peritubular blood into tubular fluid."},{"front":"ADH","back":"Hormone that increases regulated water permeability in the late nephron."},{"front":"Erythropoietin","back":"Renal hormone that stimulates erythrocyte production in red bone marrow."},{"front":"Detrusor muscle","back":"Smooth muscle in the bladder wall that contracts during voiding."},{"front":"Micturition","back":"Coordinated process of emptying the urinary bladder."}],"quiz":[],"caseStudy":{"title":"A hydration shortcut that ignores the whole picture","scenario":"A client has started forcing several extra litres of water daily after seeing a fixed online target. They now wake repeatedly to urinate and feel light-headed at times. They also mention a recent change in medication and assume that completely clear urine always proves ideal hydration.","prompts":["Which kidney and bladder processes explain the change in urine volume and frequency?","What information about body size, activity, climate, diet, medicines, health conditions, thirst, and symptoms is missing?","Why is urine colour an imperfect standalone hydration measure?","Which symptoms or medication concerns should be referred rather than managed through a generic fluid prescription?"],"takeaway":"Fluid needs are contextual, and the kidneys continuously adjust water output. Support practical observation and clinical coordination instead of treating one intake number or urine colour as a universal target."}},{"n":19,"title":"The Reproductive System","kicker":"Map the major male and female reproductive organs and explain how structure supports each organ's role.","duration":"75–95 minutes","steps":[{"id":"l19-m1","chapter":"Male reproductive organization","chapterSummary":"Follow sperm production from the testis through maturation, transport, and seminal-fluid formation.","title":"The testes have paired exocrine and endocrine jobs","highYield":"Seminiferous tubules make sperm, while interstitial cells between the tubules make testosterone.","teach":["Each testis is wrapped by a fibrous capsule that sends partitions inward, forming lobules. Inside those lobules, tightly coiled seminiferous tubules provide the site of sperm formation. The scrotum holds the testes outside the pelvic cavity, where muscular adjustments help maintain a temperature suited to sperm production.","Two cell populations clarify the testis's dual role. Developing germ cells and their supporting Sertoli cells occupy the tubules, while interstitial Leydig cells lie in the tissue between tubules and secrete testosterone. The organ therefore sends sperm through ducts and hormones into blood."],"keyPoints":["Tunica albuginea and internal septa organize the testis into lobules.","Spermatogenesis occurs in seminiferous tubules.","Sertoli cells support developing sperm cells.","Leydig cells secrete testosterone into the circulation."],"visual":{"title":"Inside a testis","kind":"layers","items":[{"label":"Capsule","detail":"Tunica albuginea forms a durable outer coat."},{"label":"Lobules","detail":"Septa divide the organ into compartments."},{"label":"Tubules","detail":"Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Between tubules","detail":"Leydig cells produce testosterone."}]},"mnemonic":{"title":"S inside, L between","cue":"Sertoli supports sperm in Seminiferous tubules; Leydig lies between Loops.","explanation":"The repeated initials anchor the location and role of the two important support cells."},"goodToKnow":"The testes are both exocrine and endocrine: sperm travel through ducts, whereas testosterone enters the bloodstream.","act":{"type":"choice","prompt":"Which pairing correctly identifies a testicular cell and its main role?","options":[{"label":"Leydig cell — testosterone secretion","correct":true,"feedback":"Correct. Leydig cells are interstitial endocrine cells."},{"label":"Sertoli cell — carrying urine to the bladder","correct":false,"feedback":"Sertoli cells support developing sperm within seminiferous tubules."},{"label":"Spermatogonium — producing seminal-vesicle fluid","correct":false,"feedback":"A spermatogonium is an early germ cell, not an accessory gland."}]}},{"id":"l19-m2","chapter":null,"chapterSummary":null,"title":"Spermatogenesis reduces chromosome number, then reshapes the cell","highYield":"Mitosis preserves the germ-cell line; meiosis produces haploid spermatids; maturation creates a streamlined sperm cell.","teach":["Spermatogonia near the outer wall of a seminiferous tubule divide by mitosis. Some remain as a renewing cell population, while others become primary spermatocytes. A primary spermatocyte completes meiosis I to form two secondary spermatocytes, and meiosis II produces four haploid spermatids.","Spermatids are not yet fully shaped sperm. During maturation, the nucleus becomes compact, an enzyme-containing acrosome forms over the head, mitochondria concentrate in the midpiece, and a flagellum develops for movement. This is a change in form and function after the chromosome-reduction divisions."],"keyPoints":["Mitosis replenishes spermatogonia and supplies cells for development.","Meiosis I and II reduce a diploid primary spermatocyte to haploid spermatids.","One primary spermatocyte can yield four spermatids.","Head, midpiece, and tail are specialized for genetic delivery, energy, and movement."],"visual":{"title":"From germ cell to sperm","kind":"flow","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]},"mnemonic":{"title":"Grow, halve, halve, shape","cue":"Mitosis grows the line; meiosis halves twice; maturation shapes.","explanation":"This separates cell-number maintenance, chromosome reduction, and structural specialization."},"goodToKnow":"A mature sperm cell's midpiece is rich in mitochondria, but the cell's purpose is transport of paternal genetic material rather than general nutrient storage.","act":{"type":"choice","prompt":"What is produced directly by meiosis II during spermatogenesis?","options":[{"label":"Haploid spermatids","correct":true,"feedback":"Correct. Secondary spermatocytes complete meiosis II to form spermatids."},{"label":"Diploid spermatogonia","correct":false,"feedback":"Spermatogonia are maintained through mitosis."},{"label":"Seminal fluid","correct":false,"feedback":"Accessory glands contribute most seminal fluid."}]}},{"id":"l19-mod1-order","title":"Put it in order: From germ cell to sperm","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]}},{"id":"l19-mod1-match","title":"Match it: Inside a testis","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tunica albuginea forms a durable outer coat.","Septa divide the organ into compartments.","Seminiferous tubules contain developing sperm and Sertoli cells.","Leydig cells produce testosterone."],"items":[{"label":"Between tubules","category":3,"feedback":"Between tubules: Leydig cells produce testosterone."},{"label":"Tubules","category":2,"feedback":"Tubules: Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Lobules","category":1,"feedback":"Lobules: Septa divide the organ into compartments."},{"label":"Capsule","category":0,"feedback":"Capsule: Tunica albuginea forms a durable outer coat."}]}},{"id":"l19-m3","chapter":"Male transport and seminal fluid","chapterSummary":"Trace sperm through the ducts and identify how accessory glands assemble the transport medium.","title":"Sperm follow a continuous transport route","highYield":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra.","teach":["Newly formed sperm leave the convoluted seminiferous tubules, pass into straight tubules, cross the rete testis, and exit through efferent ductules. They then enter the epididymis, whose long coiled duct supports further maturation and storage while sperm gain motility.","During ejaculation, smooth-muscle contractions propel sperm into the ductus deferens, through an ejaculatory duct, and then into the urethra. The male urethra has prostatic, membranous, and spongy regions. Route questions become much easier when each segment is linked to its landmark."],"keyPoints":["The epididymis is a maturation and storage site, not the production site.","The ductus deferens carries sperm from the epididymis toward the pelvic cavity.","Ejaculatory ducts empty into the prostatic urethra.","The urethra provides the final passage to the exterior."],"visual":{"title":"Sperm route map","kind":"route","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]},"mnemonic":{"title":"Sperm Take Roads, Exit, Drive, Enter, Use","cue":"Seminiferous → straight → rete → efferent → ductus epididymis → ductus deferens → ejaculatory → urethra.","explanation":"The phrase cues the major route in order; add details only after the sequence is secure."},"goodToKnow":"After a vasectomy, sperm production and testosterone secretion can continue; the procedure interrupts the ductus deferens rather than removing the testes.","act":{"type":"choice","prompt":"Where do sperm normally mature and develop motility after leaving the testis?","options":[{"label":"Epididymis","correct":true,"feedback":"Correct. The coiled epididymal duct supports maturation and storage."},{"label":"Seminal vesicle","correct":false,"feedback":"The seminal vesicle adds fluid but is not a sperm-maturation site."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine, not sperm."}]}},{"id":"l19-m4","chapter":null,"chapterSummary":null,"title":"Accessory glands build the transport medium","highYield":"Semen combines sperm with secretions from seminal vesicles, prostate, and bulbourethral glands.","teach":["Sperm make up only part of semen. Seminal vesicles contribute much of the fluid and include fructose that can support sperm movement. The prostate adds fluid around the first portion of the urethra, and bulbourethral glands add a mucus-like secretion that lubricates the urethral passage.","Together, these secretions provide a liquid transport medium and help buffer conditions encountered during passage. This is a useful structure–function example: glands placed along the route add components before the mixture leaves through the urethra."],"keyPoints":["Semen is sperm plus accessory-gland secretions.","Seminal-vesicle fluid contributes energy substrate and volume.","Prostatic fluid joins the ejaculatory-duct contents in the prostatic urethra.","Bulbourethral secretion lubricates the urethra before ejaculation."],"visual":{"title":"What enters semen?","kind":"contributions","items":[{"label":"Testes/epididymides","detail":"Sperm cells."},{"label":"Seminal vesicles","detail":"Large fluid contribution with fructose."},{"label":"Prostate","detail":"Additional glandular fluid around the urethral route."},{"label":"Bulbourethral glands","detail":"Lubricating mucus-like secretion."}]},"mnemonic":{"title":"Cells plus three secretions","cue":"Sperm + seminal vesicle + prostate + bulbourethral.","explanation":"Think of semen as a mixture assembled along a route, not a product made in one organ."},"goodToKnow":"Fructose in seminal fluid is a local energy substrate for sperm movement; it does not mean that eating more sugar predictably improves fertility.","act":{"type":"choice","prompt":"Which statement best describes semen?","options":[{"label":"A mixture of sperm and several accessory-gland secretions","correct":true,"feedback":"Correct. Multiple structures contribute to the final fluid."},{"label":"A hormone made only by Leydig cells","correct":false,"feedback":"Leydig cells make testosterone, not semen."},{"label":"Fluid stored in the urinary bladder","correct":false,"feedback":"The urinary bladder stores urine."}]}},{"id":"l19-mod2-order","title":"Put it in order: Sperm route map","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]}},{"id":"l19-mod2-match","title":"Match it: What enters semen?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sperm cells.","Large fluid contribution with fructose.","Additional glandular fluid around the urethral route.","Lubricating mucus-like secretion."],"items":[{"label":"Bulbourethral glands","category":3,"feedback":"Bulbourethral glands: Lubricating mucus-like secretion."},{"label":"Prostate","category":2,"feedback":"Prostate: Additional glandular fluid around the urethral route."},{"label":"Seminal vesicles","category":1,"feedback":"Seminal vesicles: Large fluid contribution with fructose."},{"label":"Testes/epididymides","category":0,"feedback":"Testes/epididymides: Sperm cells."}]}},{"id":"l19-m5","chapter":"Female reproductive organization and cycles","chapterSummary":"Connect ovarian events, oocyte development, uterine anatomy, and endometrial change across a cycle.","title":"Oogenesis produces one large functional cell","highYield":"Unequal meiotic divisions preserve cytoplasm in one oocyte while small polar bodies receive little cytoplasm.","teach":["Oogonia form primary oocytes before birth, and those primary oocytes remain arrested until later reproductive cycles. When a selected oocyte resumes meiosis, the first division produces a large secondary oocyte and a small polar body rather than two equal cells.","The secondary oocyte is released at ovulation. In the usual sequence, meiosis II completes only if fertilization occurs, producing an ovum and another polar body. The unequal allocation retains organelles and cytoplasm in the cell that could support the first divisions after fertilization."],"keyPoints":["Primary oocytes form before birth and later resume development.","Meiosis I yields a secondary oocyte plus a polar body.","The secondary oocyte is the cell released at ovulation.","Meiosis II usually completes in association with fertilization."],"visual":{"title":"Unequal meiotic divisions","kind":"flow","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]},"mnemonic":{"title":"One keeps the kitchen","cue":"One oocyte keeps most cytoplasm; polar bodies carry chromosomes with little cytoplasm.","explanation":"The image explains why the divisions are genetically ordered but physically unequal."},"goodToKnow":"Oogenesis and spermatogenesis both use meiosis, but they differ in timing, equality of cell division, and the number of functional gametes produced.","act":{"type":"choice","prompt":"Why is a secondary oocyte much larger than its polar body?","options":[{"label":"Meiosis divides chromosomes but allocates most cytoplasm to the oocyte","correct":true,"feedback":"Correct. The divisions are unequal in cytoplasmic volume."},{"label":"The polar body contains twice as many chromosomes","correct":false,"feedback":"Both products are haploid after meiosis I; size reflects cytoplasmic allocation."},{"label":"The oocyte has already implanted","correct":false,"feedback":"Implantation occurs after fertilization and early cell divisions."}]}},{"id":"l19-m6","chapter":null,"chapterSummary":null,"title":"The ovarian and uterine cycles are synchronized","highYield":"Follicle growth and ovulation in the ovary align with menstrual, proliferative, and secretory changes in the endometrium.","teach":["During the follicular portion of the ovarian cycle, follicles develop and one usually becomes dominant. Rising estrogen is associated with repair and growth of the uterine endometrium. Ovulation releases the secondary oocyte, which is guided toward a uterine tube by the fimbriae and ciliary movement.","After ovulation, the emptied follicle becomes the corpus luteum and secretes progesterone as well as estrogen. These hormones support a secretory endometrium prepared for possible implantation. If implantation does not occur, the corpus luteum regresses, hormone support falls, and another menstrual phase begins."],"keyPoints":["Menstrual phase sheds the functional endometrial lining.","Proliferative phase rebuilds the lining as a follicle matures.","Ovulation separates the preovulatory and postovulatory portions of the cycle.","Secretory phase is supported by corpus-luteum hormones.","Cycle length and timing vary among individuals and across life stages."],"visual":{"title":"Two cycles, one timeline","kind":"timeline","items":[{"label":"Menstrual / early follicular","detail":"Endometrium sheds while follicles begin developing."},{"label":"Proliferative / follicular","detail":"Estrogen rises and the lining rebuilds."},{"label":"Ovulation","detail":"Secondary oocyte leaves the mature follicle."},{"label":"Secretory / luteal","detail":"Corpus luteum hormones support a receptive lining."},{"label":"No implantation","detail":"Corpus luteum regresses and the cycle resets."}]},"mnemonic":{"title":"Shed, spread, secrete","cue":"Menstrual sheds · proliferative spreads new lining · secretory enriches it.","explanation":"This anchors the three uterine phases without assuming an identical day count for everyone."},"goodToKnow":"The textbook's day numbers are a teaching model; real cycles vary. Phase relationships are more reliable than memorizing one universal calendar.","act":{"type":"choice","prompt":"Which ovarian structure chiefly supports the postovulatory secretory phase?","options":[{"label":"Corpus luteum","correct":true,"feedback":"Correct. It secretes progesterone and estrogen after ovulation."},{"label":"Fimbria","correct":false,"feedback":"Fimbriae help guide the oocyte toward the uterine tube."},{"label":"Polar body","correct":false,"feedback":"A polar body is a small meiotic product, not a hormone-secreting ovarian structure."}]}},{"id":"l19-mod3-order","title":"Put it in order: Unequal meiotic divisions","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]}},{"id":"l19-m7","chapter":"Fertilization, development, birth, and lactation","chapterSummary":"Follow the biological sequence from gamete union through implantation, placental exchange, labor, and milk delivery.","title":"Fertilization starts a sequence of transport and implantation","highYield":"Fertilization usually occurs in a uterine tube; the dividing conceptus reaches the uterus and implants in the endometrium.","teach":["The uterine tubes receive the ovulated secondary oocyte through the infundibulum and fimbriae. Cilia and smooth-muscle contractions move it toward the uterus. When fertilization occurs, sperm and oocyte genetic material combine to restore the diploid chromosome number in the zygote.","The zygote undergoes repeated mitotic divisions while traveling toward the uterine cavity, developing into a blastocyst. Its outer cells participate in implantation and formation of chorionic villi, while the inner cell mass gives rise to the embryo. Ectoderm, mesoderm, and endoderm then provide the foundational tissue layers."],"keyPoints":["Fertilization most often occurs in the uterine tube, not the uterus.","A zygote divides by mitosis while moving toward the uterine cavity.","Implantation occurs in the endometrium.","The inner cell mass forms the embryo; trophoblast-related tissues support implantation and placenta formation.","Three germ layers give rise to the body's tissues and organs."],"visual":{"title":"Early development route","kind":"route","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]},"mnemonic":{"title":"Tube, travel, touch down","cue":"Fertilize in the tube · divide while traveling · implant in the uterus.","explanation":"The phrase distinguishes the usual sites of fertilization, early transport, and implantation."},"goodToKnow":"Placental and maternal blood normally remain in separate circulations; exchange occurs across a thin interface rather than by directly mixing the two blood supplies.","act":{"type":"choice","prompt":"Which sequence is anatomically correct?","options":[{"label":"Fertilization in uterine tube → mitotic divisions → implantation in endometrium","correct":true,"feedback":"Correct. The early conceptus divides while moving to the uterus."},{"label":"Implantation in ovary → fertilization in cervix → cleavage in vagina","correct":false,"feedback":"Those locations reverse the normal pathway."},{"label":"Fertilization in bladder → implantation in ureter","correct":false,"feedback":"Those are urinary, not reproductive, structures."}]}},{"id":"l19-m8","chapter":null,"chapterSummary":null,"title":"Placenta, labor, and mammary glands support the transition to birth","highYield":"The placenta supports exchange during pregnancy; labor progresses through dilation, expulsion, and placental stages; mammary lobules produce milk.","teach":["Chorionic villi and uterine tissue contribute to the placenta, which supports exchange of oxygen, nutrients, and wastes between maternal and fetal circulations. The amnion surrounds the developing embryo or fetus with fluid, and the umbilical cord links fetal circulation to the placenta. These are coordinated support structures, not interchangeable names for one organ.","Labor is commonly organized into cervical dilation, expulsion of the baby, and delivery of the placenta. After birth, milk is produced by secretory alveoli grouped within mammary lobules. Milk moves through branching ducts toward widened regions and then through lactiferous ducts that open at the nipple."],"keyPoints":["The placenta is an exchange and endocrine interface during pregnancy.","The amnion encloses the developing fetus in fluid.","The umbilical cord connects fetal vessels to the placenta.","Labor progresses through dilation, expulsion, and placental stages.","Mammary alveoli make milk; ducts carry it toward the nipple."],"visual":{"title":"Support before and after birth","kind":"paired-flow","items":[{"label":"Pregnancy","detail":"Placenta exchanges; amnion cushions; cord connects."},{"label":"Dilation","detail":"Cervix opens as uterine contractions progress."},{"label":"Expulsion","detail":"Baby passes through the birth canal."},{"label":"Placental stage","detail":"Placenta separates and is delivered."},{"label":"Lactation","detail":"Alveoli produce milk and ducts convey it outward."}]},"mnemonic":{"title":"Open, out, after","cue":"Dilation opens · expulsion moves baby out · placental stage delivers afterbirth.","explanation":"A three-word cue for the major stages of labor."},"goodToKnow":"The mammary glands are organized into lobes, lobules, secretory alveoli, and ducts. Breast size mostly reflects adipose tissue and does not by itself indicate milk-making capacity.","act":{"type":"choice","prompt":"Where is milk produced within a lactating mammary gland?","options":[{"label":"Secretory alveoli in lobules","correct":true,"feedback":"Correct. Alveolar cells produce milk, which then enters the duct system."},{"label":"Placental villi","correct":false,"feedback":"Placental villi support exchange during pregnancy, not milk production."},{"label":"Uterine endometrium","correct":false,"feedback":"The endometrium lines the uterus and supports implantation."}]}},{"id":"l19-mod4-order","title":"Put it in order: Early development route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]}}],"flashcards":[{"front":"Seminiferous tubule","back":"Coiled testicular tubule where spermatogenesis occurs."},{"front":"Sertoli cell","back":"Support cell within seminiferous tubules that nourishes and regulates developing sperm."},{"front":"Leydig cell","back":"Interstitial testicular cell that secretes testosterone."},{"front":"Epididymis","back":"Coiled duct where sperm mature, gain motility, and are stored."},{"front":"Sperm route","back":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra."},{"front":"Semen","back":"Sperm combined with secretions from the seminal vesicles, prostate, and bulbourethral glands."},{"front":"Oogenesis","back":"Formation and maturation of the female gamete through unequal meiotic divisions."},{"front":"Ovulation","back":"Release of a secondary oocyte from a mature ovarian follicle."},{"front":"Corpus luteum","back":"Postovulatory ovarian structure that secretes progesterone and estrogen."},{"front":"Endometrium","back":"Inner uterine layer that changes across the cycle and receives an implanting conceptus."},{"front":"Blastocyst","back":"Early hollow-stage conceptus with an outer trophoblast and inner cell mass."},{"front":"Placenta","back":"Temporary maternal–fetal interface for exchange and hormone production during pregnancy."},{"front":"Three labor stages","back":"Dilation, expulsion, and placental stages."},{"front":"Mammary alveoli","back":"Secretory structures in lobules that produce milk."}],"quiz":[],"caseStudy":{"title":"A cycle change is not a one-nutrient diagnosis","scenario":"A physically active client reports that menstrual cycles have become less regular while training volume increased and meals became more restrictive. They ask for one supplement to restore fertility immediately and want reassurance that no medical assessment is needed.","prompts":["Which ovarian and uterine events must coordinate for a typical cycle?","What intake, training, stress, medication, reproductive, and health-history questions are relevant without assuming a cause?","Why would one supplement be unable to guarantee ovulation, implantation, or fertility?","Which scope and referral language would support the client without diagnosing them?"],"takeaway":"Cycle changes can reflect many interacting reproductive, endocrine, energy-availability, medication, stress, and health factors. A nutrition professional can assess intake patterns and support adequacy while recommending timely clinical evaluation rather than assigning a cause or promising a fertility outcome."}}]};
